1	//! The auth decision policy (CLAUDE.md §1, §7): what a GitHub OIDC token
2	//! must prove to write, and how long a validated GitHub user token stays
3	//! believed for reads. These functions are total and clock-injected; the
4	//! worker's edge adapts headers and JWKS bytes into the values they
5	//! decide over.
6	//!
7	//! The boundaries, stated once: writes are OIDC-only; laptops are
8	//! read-only; an OIDC token's `repository_owner` must be one of the
9	//! configured orgs; lease renewal additionally requires the configured
10	//! default branch and a project equal to the token's `repository` claim.
11	
12	use crate::constants::{
13	    ACCEPTED_ORGS_MAX, JWKS_CACHE_TTL_MS, OAUTH_STATE_TTL_MS, OIDC_CLOCK_TOLERANCE_MS,
14	    SESSION_TTL_MS, VERDICT_ALLOW_TTL_MS, VERDICT_DENY_TTL_MS,
15	};
16	use crate::error::{ClientError, Result};
17	use crate::types::{ProjectName, UnixMillis};
18	
19	/// The OIDC issuer URL every token must carry exactly.
20	pub const OIDC_ISSUER: &str = "https://token.actions.githubusercontent.com";
21	
22	/// The deployment configuration the policy checks against. Vars in the
23	/// stack supply it; production code never hardcodes identity.
24	#[derive(Debug, Clone, PartialEq, Eq)]
25	pub struct OidcConfig {
26	    /// The GitHub orgs whose OIDC tokens may write.
27	    pub orgs: Vec<String>,
28	    /// The exact audience a token must name, one string, never a match
29	    /// against a list inside the token.
30	    pub audience: String,
31	    /// The default-branch ref lease renewal is pinned to.
32	    pub default_branch_ref: String,
33	}
34	
35	/// A GitHub login, organisation slug, or repository name, folded to the
36	/// one spelling this deployment compares.
37	///
38	/// GitHub treats all three case-insensitively and returns them
39	/// case-preserving, so `NoxSystems` and `nox-systems` are one
40	/// organisation and an operator may have typed either into the deploy
41	/// config. Comparing them as bytes makes access depend on which spelling
42	/// somebody happened to use, which fails closed in a way nobody can see
43	/// from the outside: a correct admin list that refuses its admin. Every
44	/// one of these values is folded on the way in, so nothing downstream
45	/// compares anything else.
46	///
47	/// ASCII lowercase, because GitHub logins and slugs are ASCII letters,
48	/// digits, and hyphens, and a Unicode fold would be a different function
49	/// answering a question nobody asked here.
50	#[must_use]
51	pub fn fold_identifier(raw: &str) -> String {
52	    raw.trim().to_ascii_lowercase()
53	}
54	
55	impl OidcConfig {
56	    /// Validate the configuration itself: an empty org list, an org entry
57	    /// with whitespace, an empty audience, or more orgs than the cap is a
58	    /// deployment mistake, and the request path refuses it with
59	    /// `auth_unavailable` by construction because no token can pass the
60	    /// empty list. Validating here is cheaper than correcting a security
61	    /// boundary in production.
62	    pub fn validate(&self) -> Result<()> {
63	        if self.orgs.is_empty() || self.orgs.len() > ACCEPTED_ORGS_MAX {
64	            return Err(ClientError::AuthUnavailable);
65	        }
66	        if self
67	            .orgs
68	            .iter()
69	            .any(|org| org.is_empty() || org.bytes().any(|b| b.is_ascii_whitespace()))
70	        {
71	            return Err(ClientError::AuthUnavailable);
72	        }
73	        if self.audience.is_empty() || self.default_branch_ref.is_empty() {
74	            return Err(ClientError::AuthUnavailable);
75	        }
76	        Ok(())
77	    }
78	}
79	
80	/// The claims a verified OIDC token proves, extracted for the rest of the
81	/// system.
82	#[derive(Debug, Clone, PartialEq, Eq)]
83	pub struct OidcIdentity {
84	    /// `owner/repo` of the workflow run.
85	    pub repository: String,
86	    /// The owner half of `repository`.
87	    pub repository_owner: String,
