() => {
  const svg = document.querySelector('svg[role="img"][tabindex="0"]');
  if (!svg) return { error: "no focusable chart" };
  const box = svg.getBoundingClientRect();
  // Hover a third of the way across the plot.
  const x = box.left + box.width * 0.34;
  const y = box.top + box.height / 2;
  svg.dispatchEvent(new PointerEvent("pointermove", { clientX: x, clientY: y, bubbles: true }));
  return { dispatched: true, x: Math.round(x), y: Math.round(y) };
}

() => {
  const svg = document.querySelector('svg[role="img"][tabindex="0"]');
  svg.focus();
  return {
    focused: document.activeElement === svg,
    crosshair: !!document.querySelector('svg[role="img"] line + line + line + line'),
    tipText: document.querySelector('[aria-live="polite"]')?.textContent ?? "",
  };
}

() => {
  const mark = document.querySelector('a[aria-label="cachet, by nox"]');
  const layers = [...mark.querySelectorAll(':scope > span')].map((s) => ({
    svgWidth: s.querySelector('svg')?.getAttribute('width'),
    opacity: getComputedStyle(s).opacity,
    transform: getComputedStyle(s).transform,
  }));
  return { layers, transition: getComputedStyle(mark.firstElementChild).transitionDuration };
}

