        let next = walker.next_read().expect("the root is queued");
        assert_eq!(next, hash);
        walker.answer(hash, read);
        walker.into_outcome()
    }

    #[test]
    fn an_absent_root_is_counted_rather_than_refused() {
        // A lease naming a path whose narinfo is gone describes something
        // this cache no longer holds: no client can substitute it, so
        // refusing protects nothing. Refusing was also permanent, because
        // the lease keeps naming it and the narinfo stays gone.
        let outcome = walk_root(Err(WalkReadError::Absent));
        assert_eq!(outcome.gate, None);
        assert_eq!(outcome.unreadable_deep, 1);
    }

    #[test]
    fn an_unparseable_root_still_refuses() {
        // This one is present and servable with references nobody can
        // enumerate, so continuing would sweep a closure a client can
        // still reach the top of.
        let outcome = walk_root(Err(WalkReadError::Unparseable));
        assert!(matches!(
            outcome.gate,
            Some(GateTrip::UnreadableRootNarinfo { .. })
        ));
        assert_eq!(outcome.unreadable_deep, 0);
    }

    #[test]
    fn a_root_is_marked_whichever_way_its_read_failed() {
        // Marking is what keeps the sweep off it. A gate decides whether
        // the walk goes on, never whether the path survives.
        for read in [WalkReadError::Absent, WalkReadError::Unparseable] {
            let outcome = walk_root(Err(read));
            assert_eq!(outcome.marked.len(), 1, "{read:?}");
        }
    }
}
