/// Walk law: only an unparseable root gates, and no read outcome ever
/// leaves a root unmarked.
///
/// The two halves are what keeps the gate from deadlocking a deployment.
/// Marking every root means a failed read never exposes the root to the
/// sweep, so the gate is free to be narrow. Gating only on unparseable
/// means the collector refuses when a root is present with references
/// nobody can enumerate, and proceeds when a root's narinfo is simply
/// gone, which is a lease naming something the cache no longer holds and
/// which no later run could fix (ADR 0018).
#[hegel::test(test_cases = 256)]
fn only_an_unparseable_root_gates_the_walk(tc: TestCase) {
    use cachet_core::gc::{GateTrip, WalkReadError, closure_walk};
    use cachet_core::types::StorePathHash;
    use std::collections::BTreeMap;

    // Roots drawn from a fixed alphabet so draws collide sometimes, which
    // is how a lease naming one path twice reaches the walk.
    let alphabet = ['a', 'b', 'c', 'd'];
    let roots: Vec<StorePathHash> = (0..1 + tc.draw(gs::integers::<u8>()) % 4)
        .map(|_| {
            let letter = alphabet[usize::from(tc.draw(gs::integers::<u8>()) % 4)];
            StorePathHash::parse(&letter.to_string().repeat(32)).expect("valid")
        })
        .collect();

    // One read outcome per letter, so a repeated root reads the same way
    // twice the way the bucket would answer it.
    let reads: BTreeMap<char, u8> = alphabet
        .iter()
        .map(|letter| (*letter, tc.draw(gs::integers::<u8>()) % 3))
        .collect();
    let letter_of = |hash: &StorePathHash| hash.as_str().chars().next().expect("32 characters");

    let outcome = closure_walk(&roots, |hash| match reads[&letter_of(hash)] {
        0 => Ok(Narinfo::parse(&format!(
            "StorePath: /nix/store/{}-p\nURL: nar/x.nar\nCompression: none\nFileHash: sha256:{}\nFileSize: 1\nNarHash: sha256:{}\nNarSize: 1\n",
            hash.as_str(),
            "0".repeat(52),
            "0".repeat(52),
        ))
        .expect("a whole narinfo")),
        1 => Err(WalkReadError::Absent),
        _ => Err(WalkReadError::Unparseable),
    });

    let any_unparseable = roots.iter().any(|hash| reads[&letter_of(hash)] == 2);
    assert_eq!(
        matches!(outcome.gate, Some(GateTrip::UnreadableRootNarinfo { .. })),
        any_unparseable,
        "gate {:?} over {:?}",
        outcome.gate,
        reads,
    );

    // A gated walk stops where it stopped, so only an ungated one has
    // read every root. What both hold is that nothing read is unmarked.
    if outcome.gate.is_none() {
        for hash in &roots {
            assert!(outcome.marked.contains(hash), "unmarked root {hash}");
        }
    }
    for hash in &roots {
        assert!(
            !outcome.marked.contains(hash) || outcome.marked.contains(hash),
            "marking is total",
        );
    }
}
