        bucket.delete_multiple(batch).await?;
        sweep.bytes_freed += sweep.nar_deletes[nars_done..end]
            .iter()
            .map(|key| sweep.bytes_by_key.get(key).copied().unwrap_or(0))
            .sum::<u64>();
        nars_done = end;
    }
