//! The plan: what `plan(instance, stage, env)` answers, and the one
//! function that answers it.
//!
//! A plan is secret-free by construction. It carries names, URLs, and
//! policy numbers, and it carries no value the env map holds under a
//! secret binding. That is what makes a plan safe to print, paste into a
//! pull request, and read, and the property lane asserts it over
//! arbitrary maps rather than trusting the shape.
//!
//! Pure: `plan` reads its argument and nothing else. Two runs on two
//! machines with the same inputs produce byte-identical output, which the
//! golden lane pins.

use serde::Serialize;

use crate::env::{self, EnvMap};
use crate::error::DeployError;
use crate::name::{Deployment, Stage};
use crate::roster::{self, BindingKind, Requirement};

/// The compatibility date every deployment pins. A protocol constant
/// rather than a policy value: it decides which platform semantics the
/// worker gets, and two deployments on two dates are two different
/// runtimes.
pub const COMPATIBILITY_DATE: &str = "2026-05-28";

/// The collector's schedule. Hourly, and the same everywhere: the sweep
/// is idempotent and its work is bounded, so no stage wants its own.
pub const COLLECTOR_CRON: &str = "0 * * * *";

/// The widest CPU ceiling this grammar will render. Well past anything
/// an auth request needs, and there only so a typo answers a refusal
/// rather than a number nobody meant.
const MAX_CPU_MS: u32 = 300_000;

/// The database half of a plan.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct DatabasePlan {
    /// The database's name. Referenced, never created by a deploy: no
    /// stage owns it, so no `destroy` can delete an auth service's users.
    pub name: String,
    /// The branch this stage deploys against, which the stage creates and
    /// destroys.
    pub branch: String,
    /// The parent every branch forks from.
    pub parent_branch: String,
    /// The Hyperdrive configuration's name.
    pub hyperdrive: String,
    /// Whether Hyperdrive caching is on. Always true: CLAUDE.md §4 makes
    /// it a deployment invariant, because prepared statements depend on
    /// it, and no knob turns it off.
    pub caching: bool,
    /// The direct Postgres port. Hyperdrive replaces the pooler, so it
    /// wants the direct port rather than the vendor's pooled one.
    pub port: u16,
}

/// The worker half.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct WorkerPlan {
    /// The worker's name.
    pub name: String,
    /// The custom domain, taken from the origin's host, when this stage
    /// claims one.
