    /// why a preview claims none: a custom domain is a DNS record and a
    /// certificate, and two workers cannot answer on one hostname. A
    /// preview is destroyed when its pull request closes, so claiming
    /// production's domain would take it away from production, and
    /// claiming a per-preview subdomain would want a wildcard
    /// certificate this grammar has no way to provision. A preview
    /// answers on its own worker subdomain instead, which is the URL its
    /// `SESAME_DEPLOY_ORIGIN` should name.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub domain: Option<String>,
    /// The platform semantics this deployment pins.
    pub compatibility_date: String,
    /// The collector's schedule.
    pub cron: String,
    /// The CPU-millisecond ceiling, when the deployment named one.

