#[must_use]
pub fn binding(name: &str) -> Option<&'static Binding> {
    BINDINGS.iter().find(|candidate| candidate.name == name)
}

/// Every binding of one kind, in roster order.
pub fn of_kind(kind: BindingKind) -> impl Iterator<Item = &'static Binding> {
    BINDINGS.iter().filter(move |binding| binding.kind == kind)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_name_appears_once() {
        let mut names: Vec<&str> = BINDINGS.iter().map(|binding| binding.name).collect();
        let total = names.len();
