//! The deploy grammar's pure laws over arbitrary inputs
//! (docs/testing/property.md). The grammar is a function of its two
//! arguments, every derived name hangs off the deployment id, and no
//! rendered error or plan ever carries a value out of the environment
//! map.

use hegel::generators as gs;
use hegel::TestCase;

use sesame_deploy::env::{EnvMap, CPU_MS, MAIL_SENDERS, ORIGIN};
use sesame_deploy::{plan, Deployment, Stage};

/// The names a plan reads, plus names it ignores, so a sweep reaches both
/// halves of a map.
const NAMES: [&str; 8] = [
    ORIGIN,
    CPU_MS,
    MAIL_SENDERS,
    "SESAME_PRODUCT_URL",
    "SESAME_MAIL_FROM",
    "SESAME_ENVELOPE_KEK",
    "SESAME_PEPPER",
    "SESAME_OAUTH_GITHUB_CLIENT_ID",
];

/// A lowercase word, drawn so the instance half is usually valid and
/// sometimes not.
fn draw_word(tc: &TestCase, alphabet: &[u8], max: usize) -> String {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(max));
    bytes
        .iter()
        .map(|byte| alphabet[usize::from(*byte) % alphabet.len()] as char)
        .collect()
}

#[hegel::test(test_cases = 256)]
fn no_error_ever_renders_a_value_from_the_environment(tc: TestCase) {
    // The law CLAUDE.md §5 states and this crate has to keep. The map
    // holds a database password and two 32-byte secrets, and an error
    // that could carry a value would eventually print one into a CI log.
    // Every value here is marked, so a leak is unmistakable.
    let count = tc.draw(gs::integers::<u8>()) % 8;
    let mut marked: Vec<(String, String)> = Vec::new();
    for index in 0..count {
        let slot = usize::from(tc.draw(gs::integers::<u8>())) % NAMES.len();
        let tail = draw_word(&tc, b"abcXYZ019:/._@-", 20);
        marked.push((NAMES[slot].to_owned(), format!("zz{index}zz{tail}")));
    }
    let instance = draw_word(&tc, b"abcz019-_. ", 30);
    let stage = draw_word(&tc, b"presvingtaduo-019", 14);

    let env = EnvMap::from_pairs(marked.clone());
    let Err(error) = plan(&instance, &stage, &env) else {
        return;
    };
    let rendered = error.to_string();
    for (name, value) in &marked {
        assert!(
            !rendered.contains(value.as_str()),
            "the error rendered {name}'s value: {rendered}"
        );
    }
}

