fn a_plan_never_carries_a_secret_value(tc: TestCase) {
    let kek = format!("kek{}", draw_word(&tc, b"abcXYZ019", 20));
    let pepper = format!("pep{}", draw_word(&tc, b"abcXYZ019", 20));
    let instance = format!("a{}", draw_word(&tc, b"abcz019", 12));
    let env = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.com"),
        ("SESAME_PRODUCT_URL", "https://acme.com"),
        ("SESAME_MAIL_FROM", "no-reply@acme.com"),
        ("SESAME_ENVELOPE_KEK", kek.as_str()),
        ("SESAME_PEPPER", pepper.as_str()),
    ]);
    let Ok(built) = plan(&instance, "production", &env) else {
        return;
    };
    // The plan names its secrets and carries none of their values, which
    // is what makes `sesame deploy plan` printable into a pull request,
    // and the rendered toml lands in a git repository.
    let json = serde_json::to_string(&built).expect("a plan serializes");
    let toml = sesame_deploy::render::wrangler::render(&built);
    assert!(json.contains("SESAME_PEPPER"), "the name is expected");
    for (label, value) in [("the KEK", &kek), ("the pepper", &pepper)] {
        assert!(!json.contains(value.as_str()), "{label} reached the plan");
        assert!(!toml.contains(value.as_str()), "{label} reached the toml");
    }
}

