    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
    let raw = String::from_utf8_lossy(&bytes).into_owned();
    let _ = Deployment::new(&raw, "production");
    let _ = Stage::parse(&raw);
    if let Ok(deployment) = Deployment::new(&raw, "production") {
        // Anything accepted names a worker Cloudflare will take.
        let name = deployment.worker_name();
        assert!(name.len() <= 63, "{name} is longer than a worker name");
        assert!(
