#[test]
fn only_a_stage_that_outlives_a_pull_request_claims_a_domain() {
    // Two workers cannot answer on one hostname, and a preview is
    // destroyed when its pull request closes. A preview that claimed the
    // production domain would take it away from production, which is an
    // outage rather than a test deployment.
    let live = plan("acme", "production", &full_env()).expect("plans");
    let staging = plan("acme", "staging", &full_env()).expect("plans");
    assert_eq!(live.worker.domain.as_deref(), Some("auth.acme.example"));
    assert_eq!(staging.worker.domain.as_deref(), Some("auth.acme.example"));

    for number in [1u32, 42, 9999] {
        let preview = plan("acme", &format!("preview-{number}"), &full_env()).expect("plans");
        assert_eq!(preview.worker.domain, None, "preview-{number}");
        assert!(preview.ephemeral);
        let rendered = render::wrangler::render(&preview);
        assert!(
            !rendered.contains("custom_domain"),
            "preview-{number} rendered a route"
        );
        assert!(
            !rendered.contains("auth.acme.example\", custom_domain"),
            "preview-{number} claimed the production hostname"
        );
    }
}

