#[test]
fn every_refusal_names_a_field_and_nothing_else() {
    // The rendered wordings are a contract too: an operator reads them
    // out of a CI log, and each must say which name to fix.
    let minimum = || {
        EnvMap::from_pairs([
            (ORIGIN, "https://auth.acme.example"),
            ("SESAME_PRODUCT_URL", "https://acme.example"),
            ("SESAME_MAIL_FROM", "no-reply@acme.example"),
        ])
    };
    let mut wordings = Vec::new();
    for (label, error) in [
        (
            "bad instance",
            plan("A", "production", &minimum()).unwrap_err(),
        ),
        (
            "prefixed instance",
            plan("sesame-acme", "production", &minimum()).unwrap_err(),
        ),
        (
            "unknown stage",
            plan("acme", "prod", &minimum()).unwrap_err(),
        ),
        (
            "absent origin",
            plan("acme", "production", &EnvMap::default()).unwrap_err(),
        ),
    ] {
        wordings.push(format!("{label}: {error}"));
    }
    // The derived-var refusal: setting one is overriding a derivation,
    // and preferring one silently is how a deployment issues tokens under
    // an issuer nobody chose. It fires ahead of the missing-var checks
    // because the derivation is read first, so a minimal map is enough.
    let overridden = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.example"),
        ("SESAME_ISSUER", "https://somewhere.else.example"),
    ]);
    let refusal = plan("acme", "production", &overridden).unwrap_err();
    assert!(
        matches!(refusal, DeployError::Derived(_)),
        "the derivation is what refuses here: {refusal}"
    );
    wordings.push(format!("derived override: {refusal}"));
    // Half a both-or-neither pair. It needs the full environment: with
    // required vars missing, one of those refuses first, and a snapshot
    // that recorded THAT would say nothing about the pair law at all.
    let mut half_pairs: Vec<(String, String)> = full_env()
        .names()
        .map(|name| {
            (
                name.to_owned(),
                full_env().get(name).unwrap_or_default().to_owned(),
            )
        })
        .filter(|(name, _)| name != "SESAME_OAUTH_GITHUB_CLIENT_SECRET")
        .collect();
    half_pairs.retain(|(name, _)| name != "SESAME_OAUTH_GITHUB_CLIENT_SECRET");
    let half = EnvMap::from_pairs(half_pairs);
    let refusal = plan("acme", "production", &half).unwrap_err();
    assert!(
        matches!(refusal, DeployError::HalfPair(_)),
        "the pair law is what refuses here, not a missing var: {refusal}"
    );
    wordings.push(format!("half pair: {refusal}"));
    insta::assert_snapshot!("refusal_wordings", wordings.join("\n"));
}

#[test]
fn a_required_secret_is_missing_by_name() {
    let env = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.example"),
        ("SESAME_PRODUCT_URL", "https://acme.example"),
        ("SESAME_MAIL_FROM", "no-reply@acme.example"),
    ]);
    // Every required var is absent, so the first refusal names one of
    // them rather than the secret. Fill the vars and the secret surfaces.
    assert!(matches!(
        plan("acme", "production", &env),
        Err(DeployError::Missing(_))
    ));
}

