/// One `[vars]` entry the plan decided.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PlannedVar {
    /// The binding's name.
    pub name: String,
    /// Its value. Secret-free: only `Var`-kind bindings appear here.
    pub value: String,
    /// Whether the grammar derived it or the operator supplied it.
    pub derived: bool,
}

/// A whole deployment plan.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct DeployPlan {
    /// The deployment id: the one name every other name hangs off, and
    /// the value a deploy program checks against the stage it was
    /// invoked with, so the acme plan cannot run in the globex stage.
    pub name: String,
    /// The instance half of the pair.
    pub instance: String,
    /// The stage half.
    pub stage: String,
    /// The alchemy stage.
    pub alchemy_stage: String,
    /// The GitHub environment, which carries production's reviewer gate.
    pub github_environment: String,
    /// Whether a closed pull request destroys this deployment.
    pub ephemeral: bool,
    /// The public origin every derived URL comes from.
    pub origin: String,
    /// The database.
    pub database: DatabasePlan,
    /// The worker.
    pub worker: WorkerPlan,
    /// Every `[vars]` entry, in roster order.
    pub vars: Vec<PlannedVar>,
    /// The secret bindings this deployment expects, by name only. The
    /// values are never here and never in the state store's plan output.
    pub secrets: Vec<String>,
    /// The addresses the send_email binding may send from.
    pub mail_senders: Vec<String>,
    /// Where this deployment's own files live, derived from the id.
    pub paths: PathPlan,
}

/// The paths one deployment owns, derived from its id so two deployments
/// can never share a file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PathPlan {
    /// The environment file a fleet deploy reads.
    pub fleet_env: String,
    /// The directory a self-hosted deployment keeps its rendered config
    /// and its drawn secrets in.
    pub self_host_dir: String,
}

/// Builds a plan.
///
/// # Errors
/// [`DeployError`], one variant per shape the operator got wrong. No
/// variant carries a value from `env`, only a name.
///
/// # Examples
/// ```
/// use sesame_deploy::env::{EnvMap, ORIGIN};
/// use sesame_deploy::plan;
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// # use sesame_deploy::roster::{self, BindingKind, Requirement};
/// # // Every required var, filled: a deployment names all of them, and
/// # // the plan refuses by name until it does.
/// # let mut pairs: Vec<(String, String)> = roster::of_kind(BindingKind::Var)
/// #     .filter(|binding| binding.requirement == Requirement::Required)
/// #     .map(|binding| (binding.name.to_owned(), "1000".to_owned()))
/// #     .collect();
/// # pairs.push((ORIGIN.to_owned(), "https://auth.acme.com".to_owned()));
/// # pairs.push(("SESAME_ENVELOPE_KEK".to_owned(), "kek".to_owned()));
/// # pairs.push(("SESAME_PEPPER".to_owned(), "pepper".to_owned()));
/// # let env = EnvMap::from_pairs(pairs);
/// let plan = plan("acme", "production", &env)?;
/// assert_eq!(plan.name, "sesame-acme-production");
/// assert_eq!(plan.worker.domain, "auth.acme.com");
/// // The issuer is derived, so no operator has to keep it in step.
/// let issuer = plan.vars.iter().find(|v| v.name == "SESAME_ISSUER").expect("derived");
/// assert_eq!(issuer.value, "https://auth.acme.com");
/// assert!(issuer.derived);
/// # Ok(())
/// # }
/// ```
pub fn plan(instance: &str, stage: &str, env: &EnvMap) -> Result<DeployPlan, DeployError> {
    let deployment = Deployment::new(instance, stage)?;
    let origin = required_origin(env)?;
    let host = origin_host(&origin)?;
    let vars = planned_vars(env, &origin)?;
    let secrets = planned_secrets(env)?;

    Ok(DeployPlan {
        name: deployment.id(),
        instance: deployment.instance().to_owned(),
        stage: deployment.stage().word(),
        alchemy_stage: deployment.alchemy_stage(),
        github_environment: deployment.stage().github_environment().to_owned(),
        ephemeral: deployment.stage().is_ephemeral(),
        origin: origin.clone(),
        database: DatabasePlan {
            name: deployment.database_name(),
            branch: deployment.database_branch(),
            parent_branch: Stage::Production.database_branch(),
            hyperdrive: deployment.hyperdrive_name(),
            caching: true,
            port: 5432,
        },
        worker: WorkerPlan {
            name: deployment.worker_name(),
            domain: (!deployment.stage().is_ephemeral()).then_some(host),
            compatibility_date: COMPATIBILITY_DATE.to_owned(),
            cron: COLLECTOR_CRON.to_owned(),
            cpu_ms: cpu_ms(env)?,
        },
        vars,
        secrets,
        mail_senders: mail_senders(env)?,
        paths: PathPlan {
            fleet_env: deployment.fleet_env_path(),
            self_host_dir: deployment.self_host_dir(),
        },
    })
}

/// The origin, required and shape-checked.
fn required_origin(env: &EnvMap) -> Result<String, DeployError> {
    let raw = env
        .get(env::ORIGIN)
        .ok_or(DeployError::Missing(env::ORIGIN))?;
    let rest = raw
        .strip_prefix("https://")
        .ok_or(DeployError::Malformed(env::ORIGIN))?;
    // Scheme, host, optional port, and nothing else. A trailing path
    // would make every derived callback URL wrong in a way that only
    // surfaces at the first dance.
    if rest.is_empty() || rest.contains('/') || rest.contains('?') || rest.contains('#') {
        return Err(DeployError::Malformed(env::ORIGIN));
    }
    Ok(raw.to_owned())
}

/// The origin's host, which becomes the worker's custom domain.
fn origin_host(origin: &str) -> Result<String, DeployError> {
    let rest = origin
        .strip_prefix("https://")
        .ok_or(DeployError::Malformed(env::ORIGIN))?;
    Ok(rest.split(':').next().unwrap_or(rest).to_owned())
}

/// The CPU ceiling, when the deployment named one.
fn cpu_ms(env: &EnvMap) -> Result<Option<u32>, DeployError> {
    let Some(raw) = env.get(env::CPU_MS) else {
        return Ok(None);
    };
    raw.parse::<u32>()
        .ok()
        .filter(|value| (1..=MAX_CPU_MS).contains(value))
        .map(Some)
        .ok_or(DeployError::Malformed(env::CPU_MS))
}

/// The send_email allow-list, comma-joined and shape-checked.
///
/// The check is deliberately shallow: an address with no `@` is a typo
/// the platform would refuse at deploy time with a worse message, and
/// anything beyond that is Cloudflare's own validation to run.
fn mail_senders(env: &EnvMap) -> Result<Vec<String>, DeployError> {
    let mut senders = Vec::new();
    for address in env.get(env::MAIL_SENDERS).unwrap_or("").split(',') {
        let address = address.trim();
        if address.is_empty() {
            continue;
        }
        let (local, domain) = address
            .split_once('@')
            .ok_or(DeployError::Malformed(env::MAIL_SENDERS))?;
        if local.is_empty() || domain.is_empty() || domain.contains('@') {
            return Err(DeployError::Malformed(env::MAIL_SENDERS));
        }
        senders.push(address.to_owned());
    }
    Ok(senders)
}

/// Every `[vars]` entry the plan decided, in roster order.
///
/// Three rules, and each refuses rather than guesses. A required var that
/// is absent fails. A derived var that the operator set fails, because
/// preferring one of the two silently is how a deployment ends up issuing
/// tokens under an issuer nobody chose. A both-or-neither pair with one
/// half fails.
fn planned_vars(env: &EnvMap, origin: &str) -> Result<Vec<PlannedVar>, DeployError> {
    let mut planned = Vec::new();
    for binding in roster::of_kind(BindingKind::Var) {
        let derived = derived_value(binding.name, origin);
        if let Some(value) = derived {
            if env.has(binding.name) {
                return Err(DeployError::Derived(binding.name));
            }
            planned.push(PlannedVar {
                name: binding.name.to_owned(),
                value,
                derived: true,
            });
            continue;
        }
        match (env.get(binding.name), binding.requirement) {
            (Some(value), _) => planned.push(PlannedVar {
                name: binding.name.to_owned(),
                value: value.to_owned(),
                derived: false,
            }),
            (None, Requirement::Required) => return Err(DeployError::Missing(binding.name)),
            (None, _) => {}
        }
    }
    check_pairs(env)?;
    Ok(planned)
}

/// What the grammar computes rather than reads.
fn derived_value(name: &str, origin: &str) -> Option<String> {
    match name {
        roster::vars::ISSUER | roster::vars::OAUTH_CALLBACK_URL => Some(origin.to_owned()),
        _ => None,
    }
}

/// The both-or-neither pairs. One half present is an operator typo, and a
/// silently disabled provider is the wrong failure mode (ADR 0006).
fn check_pairs(env: &EnvMap) -> Result<(), DeployError> {
    for (id, secret) in [
        (
            "SESAME_OAUTH_GITHUB_CLIENT_ID",
            "SESAME_OAUTH_GITHUB_CLIENT_SECRET",
        ),
        (
            "SESAME_OAUTH_GOOGLE_CLIENT_ID",
            "SESAME_OAUTH_GOOGLE_CLIENT_SECRET",
        ),
    ] {
        match (env.has(id), env.has(secret)) {
            (true, false) => return Err(DeployError::HalfPair(secret)),
            (false, true) => return Err(DeployError::HalfPair(id)),
            _ => {}
        }
    }
    // The rotation slot without the live one is a rotation into nothing.
    if env.has("SESAME_BACKEND_KEY_PREVIOUS") && !env.has("SESAME_BACKEND_KEY") {
        return Err(DeployError::HalfPair("SESAME_BACKEND_KEY"));
    }
    Ok(())
}

/// The secret bindings this deployment expects, by name only.
fn planned_secrets(env: &EnvMap) -> Result<Vec<String>, DeployError> {
    let mut expected = Vec::new();
    for binding in roster::of_kind(BindingKind::Secret) {
        match (env.has(binding.name), binding.requirement) {
            (true, _) => expected.push(binding.name.to_owned()),
            (false, Requirement::Required) => return Err(DeployError::Missing(binding.name)),
            (false, _) => {}
        }
    }
    Ok(expected)
}

