//! The deploy grammar's pure laws over arbitrary inputs
//! (docs/testing/property.md). The grammar is a function of its two
//! arguments, every derived name hangs off the deployment id, and no
//! rendered error or plan ever carries a value out of the environment
//! map.

use hegel::generators as gs;
use hegel::TestCase;

use sesame_deploy::env::{EnvMap, CPU_MS, MAIL_SENDERS, ORIGIN};
use sesame_deploy::{plan, Deployment, Stage};

/// The names a plan reads, plus names it ignores, so a sweep reaches both
/// halves of a map.
const NAMES: [&str; 8] = [
    ORIGIN,
    CPU_MS,
    MAIL_SENDERS,
    "SESAME_PRODUCT_URL",
    "SESAME_MAIL_FROM",
    "SESAME_ENVELOPE_KEK",
    "SESAME_PEPPER",
    "SESAME_OAUTH_GITHUB_CLIENT_ID",
];

/// A lowercase word, drawn so the instance half is usually valid and
/// sometimes not.
fn draw_word(tc: &TestCase, alphabet: &[u8], max: usize) -> String {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(max));
    bytes
        .iter()
        .map(|byte| alphabet[usize::from(*byte) % alphabet.len()] as char)
        .collect()
}

#[hegel::test(test_cases = 256)]
fn no_error_ever_renders_a_value_from_the_environment(tc: TestCase) {
    // The law CLAUDE.md §5 states and this crate has to keep. The map
    // holds a database password and two 32-byte secrets, and an error
    // that could carry a value would eventually print one into a CI log.
    // Every value here is marked, so a leak is unmistakable.
    let count = tc.draw(gs::integers::<u8>()) % 8;
    let mut marked: Vec<(String, String)> = Vec::new();
    for index in 0..count {
        let slot = usize::from(tc.draw(gs::integers::<u8>())) % NAMES.len();
        let tail = draw_word(&tc, b"abcXYZ019:/._@-", 20);
        marked.push((NAMES[slot].to_owned(), format!("zz{index}zz{tail}")));
    }
    let instance = draw_word(&tc, b"abcz019-_. ", 30);
    let stage = draw_word(&tc, b"presvingtaduo-019", 14);

    let env = EnvMap::from_pairs(marked.clone());
    let Err(error) = plan(&instance, &stage, &env) else {
        return;
    };
    let rendered = error.to_string();
    for (name, value) in &marked {
        assert!(
            !rendered.contains(value.as_str()),
            "the error rendered {name}'s value: {rendered}"
        );
    }
}

#[hegel::test(test_cases = 256)]
fn a_plan_never_carries_a_secret_value(tc: TestCase) {
    let kek = format!("kek{}", draw_word(&tc, b"abcXYZ019", 20));
    let pepper = format!("pep{}", draw_word(&tc, b"abcXYZ019", 20));
    let instance = format!("a{}", draw_word(&tc, b"abcz019", 12));
    let env = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.com"),
        ("SESAME_PRODUCT_URL", "https://acme.com"),
        ("SESAME_MAIL_FROM", "no-reply@acme.com"),
        ("SESAME_ENVELOPE_KEK", kek.as_str()),
        ("SESAME_PEPPER", pepper.as_str()),
    ]);
    let Ok(built) = plan(&instance, "production", &env) else {
        return;
    };
    // The plan names its secrets and carries none of their values, which
    // is what makes `sesame deploy plan` printable into a pull request,
    // and the rendered toml lands in a git repository.
    let json = serde_json::to_string(&built).expect("a plan serializes");
    let toml = sesame_deploy::render::wrangler::render(&built);
    assert!(json.contains("SESAME_PEPPER"), "the name is expected");
    for (label, value) in [("the KEK", &kek), ("the pepper", &pepper)] {
        assert!(!json.contains(value.as_str()), "{label} reached the plan");
        assert!(!toml.contains(value.as_str()), "{label} reached the toml");
    }
}

#[hegel::test(test_cases = 128)]
fn the_grammar_is_a_function_of_its_arguments(tc: TestCase) {
    // Pure means reproducible: the same pair and the same map answer the
    // same plan on any machine, which is what lets a plan be reviewed
    // before it runs.
    let instance = format!("a{}", draw_word(&tc, b"abcz019", 12));
    let preview = u32::from(tc.draw(gs::integers::<u8>()));
    let stage = if preview == 0 {
        "staging".to_owned()
    } else {
        format!("preview-{preview}")
    };
    let env = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.com"),
        ("SESAME_PRODUCT_URL", "https://acme.com"),
        ("SESAME_MAIL_FROM", "no-reply@acme.com"),
    ]);
    assert_eq!(plan(&instance, &stage, &env), plan(&instance, &stage, &env));
}

#[hegel::test(test_cases = 256)]
fn the_deployment_id_determines_every_other_name(tc: TestCase) {
    let instance = format!("a{}", draw_word(&tc, b"abcz019-", 20));
    let preview = 1 + u32::from(tc.draw(gs::integers::<u8>()));
    let Ok(live) = Deployment::new(&instance, "production") else {
        return;
    };
    let preview = Deployment::new(&instance, &format!("preview-{preview}"))
        .expect("a valid instance stays valid across stages");

    // Two stages of one instance share a database and differ in
    // everything a stage owns.
    assert_eq!(live.database_name(), preview.database_name());
    assert_ne!(live.id(), preview.id());
    assert_ne!(live.database_branch(), preview.database_branch());
    assert_ne!(live.hyperdrive_name(), preview.hyperdrive_name());

    for derived in [
        preview.worker_name(),
        preview.alchemy_stage(),
        preview.hyperdrive_name(),
        preview.fleet_env_path(),
        preview.self_host_dir(),
    ] {
        assert!(
            derived.contains(&preview.id()),
            "{derived} does not carry {}",
            preview.id()
        );
    }
}

#[hegel::test(test_cases = 256)]
fn a_stage_round_trips_through_its_own_word(tc: TestCase) {
    let preview = 1 + u32::from(tc.draw(gs::integers::<u16>()));
    for stage in [Stage::Production, Stage::Staging, Stage::Preview(preview)] {
        assert_eq!(Stage::parse(&stage.word()), Ok(stage));
    }
}

#[hegel::test(test_cases = 256)]
fn instance_validation_is_total(tc: TestCase) {
    // Any byte string in, a typed answer out, never a panic.
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
    let raw = String::from_utf8_lossy(&bytes).into_owned();
    let _ = Deployment::new(&raw, "production");
    let _ = Stage::parse(&raw);
    if let Ok(deployment) = Deployment::new(&raw, "production") {
        // Anything accepted names a worker Cloudflare will take.
        let name = deployment.worker_name();
        assert!(name.len() <= 63, "{name} is longer than a worker name");
        assert!(
            name.bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-'),
            "{name} carries a character a worker name cannot"
        );
    }
}

