//! The deploy grammar's wire contracts (docs/testing/golden.md).
//!
//! Three artifacts other things read: the plan's JSON, which a deploy
//! program consumes; the rendered `wrangler.toml`, which a self-hoster
//! deploys with; and the roster's own variable table. Each is pinned as
//! bytes, because a change to any of them changes what somebody's
//! deployment does.

use sesame_deploy::env::{EnvMap, CPU_MS, MAIL_SENDERS, ORIGIN};
use sesame_deploy::render;
use sesame_deploy::{plan, DeployError};

/// The values that are not plain numbers, by name. Everything else takes
/// a number, because the plan shape-checks only the origin and the mail
/// senders and passes the rest through.
const SHAPED: [(&str, &str); 9] = [
    (ORIGIN, "https://auth.acme.example"),
    (MAIL_SENDERS, "no-reply@acme.example, support@acme.example"),
    (CPU_MS, "120"),
    ("SESAME_PRODUCT_URL", "https://acme.example"),
    ("SESAME_MAIL_FROM", "no-reply@acme.example"),
    ("SESAME_PASSKEY_RP_ID", "auth.acme.example"),
    ("SESAME_PASSKEY_RP_NAME", "Acme"),
    ("SESAME_PASSKEY_ORIGINS", "https://acme.example"),
    ("SESAME_OAUTH_GITHUB_CLIENT_ID", "gh-client-id"),
];

/// A deployment's environment, built from the roster rather than typed
/// out.
///
/// why derived: a hand-written list here is the same drift the roster
/// exists to stop, one layer down. It went stale the first time a
/// binding landed, and the refusal-wording test caught it only because
/// that test asserts its error *variant* before snapshotting it.
///
/// `optional` decides whether the optional surfaces are configured, which
/// is the difference between the fullest deployment and the leanest one.
fn env_from_roster(optional: bool) -> EnvMap {
    let mut pairs: Vec<(String, String)> = Vec::new();
    for binding in sesame_deploy::roster::BINDINGS {
        let wanted = match binding.requirement {
            sesame_deploy::roster::Requirement::Required => true,
            sesame_deploy::roster::Requirement::Optional => optional,
            // The grammar computes these, and setting one is refused.
            sesame_deploy::roster::Requirement::Derived => false,
        };
        // A platform binding is wired rather than supplied as a value.
        if !wanted || binding.kind == sesame_deploy::roster::BindingKind::Platform {
            continue;
        }
        let value = SHAPED
            .iter()
            .find(|(name, _)| *name == binding.name)
            .map_or("1000", |(_, value)| *value);
        pairs.push((binding.name.to_owned(), value.to_owned()));
    }
    for (name, value) in SHAPED {
        // The deploy-time-only names are not bindings, so the walk above
        // never reaches them.
        if name.starts_with(sesame_deploy::env::DEPLOY_PREFIX) && (optional || name == ORIGIN) {
            pairs.push((name.to_owned(), value.to_owned()));
        }
    }
    EnvMap::from_pairs(pairs)
}

/// A fully configured deployment: every optional surface on, so the
/// snapshot shows the whole shape rather than the minimum.
fn full_env() -> EnvMap {
    env_from_roster(true)
}

/// A deployment that names only what it must: no providers, no passkey
/// relying party, no brokered channel, no CPU ceiling. This is the shape
/// most self-hosters render first, and the absent `[limits]` block is the
/// point: sesame does not know what that number should be, so the
/// platform's own default stands.
fn minimum_env() -> EnvMap {
    env_from_roster(false)
}

#[test]
fn the_production_plan_is_the_locked_shape() {
    let built = plan("acme", "production", &full_env()).expect("a full environment plans");
    insta::assert_json_snapshot!("plan_production", built);
}

#[test]
fn a_preview_plan_differs_only_where_a_stage_owns_the_fact() {
    let built = plan("acme", "preview-42", &full_env()).expect("a full environment plans");
    insta::assert_json_snapshot!("plan_preview", built);
}

#[test]
fn only_a_stage_that_outlives_a_pull_request_claims_a_domain() {
    // Two workers cannot answer on one hostname, and a preview is
    // destroyed when its pull request closes. A preview that claimed the
    // production domain would take it away from production, which is an
    // outage rather than a test deployment.
    let live = plan("acme", "production", &full_env()).expect("plans");
    let staging = plan("acme", "staging", &full_env()).expect("plans");
    assert_eq!(live.worker.domain.as_deref(), Some("auth.acme.example"));
    assert_eq!(staging.worker.domain.as_deref(), Some("auth.acme.example"));

    for number in [1u32, 42, 9999] {
        let preview = plan("acme", &format!("preview-{number}"), &full_env()).expect("plans");
        assert_eq!(preview.worker.domain, None, "preview-{number}");
        assert!(preview.ephemeral);
        let rendered = render::wrangler::render(&preview);
        assert!(
            !rendered.contains("custom_domain"),
            "preview-{number} rendered a route"
        );
        assert!(
            !rendered.contains("auth.acme.example\", custom_domain"),
            "preview-{number} claimed the production hostname"
        );
    }
}

#[test]
fn the_rendered_wrangler_toml_is_the_locked_bytes() {
    let built = plan("acme", "production", &full_env()).expect("a full environment plans");
    insta::assert_snapshot!("wrangler_production", render::wrangler::render(&built));
}

#[test]
fn the_minimum_deployment_renders_without_a_cpu_ceiling() {
    let built = plan("acme", "staging", &minimum_env()).expect("the minimum plans");
    assert_eq!(built.worker.cpu_ms, None);
    let rendered = render::wrangler::render(&built);
    assert!(
        !rendered.contains("[limits]"),
        "a deployment that named no ceiling takes the platform's own"
    );
    assert!(
        !rendered.contains("[[send_email]]"),
        "a deployment that named no senders wires no mail binding"
    );
    insta::assert_snapshot!("wrangler_minimum", rendered);
}

#[test]
fn a_malformed_mail_sender_refuses_by_name() {
    for bad in ["not-an-address", "@acme.example", "ada@", "a@b@c"] {
        let mut pairs: Vec<(String, String)> = minimum_env()
            .names()
            .map(|name| {
                (
                    name.to_owned(),
                    minimum_env().get(name).unwrap_or_default().to_owned(),
                )
            })
            .collect();
        pairs.push((MAIL_SENDERS.to_owned(), bad.to_owned()));
        let refusal = plan("acme", "staging", &EnvMap::from_pairs(pairs)).unwrap_err();
        assert_eq!(
            refusal,
            DeployError::Malformed(MAIL_SENDERS),
            "{bad} must refuse by name"
        );
    }
}

#[test]
fn the_variable_table_is_the_locked_bytes() {
    insta::assert_snapshot!("variable_table", render::table::render());
}

#[test]
fn every_refusal_names_a_field_and_nothing_else() {
    // The rendered wordings are a contract too: an operator reads them
    // out of a CI log, and each must say which name to fix.
    let minimum = || {
        EnvMap::from_pairs([
            (ORIGIN, "https://auth.acme.example"),
            ("SESAME_PRODUCT_URL", "https://acme.example"),
            ("SESAME_MAIL_FROM", "no-reply@acme.example"),
        ])
    };
    let mut wordings = Vec::new();
    for (label, error) in [
        (
            "bad instance",
            plan("A", "production", &minimum()).unwrap_err(),
        ),
        (
            "prefixed instance",
            plan("sesame-acme", "production", &minimum()).unwrap_err(),
        ),
        (
            "unknown stage",
            plan("acme", "prod", &minimum()).unwrap_err(),
        ),
        (
            "absent origin",
            plan("acme", "production", &EnvMap::default()).unwrap_err(),
        ),
    ] {
        wordings.push(format!("{label}: {error}"));
    }
    // The derived-var refusal: setting one is overriding a derivation,
    // and preferring one silently is how a deployment issues tokens under
    // an issuer nobody chose. It fires ahead of the missing-var checks
    // because the derivation is read first, so a minimal map is enough.
    let overridden = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.example"),
        ("SESAME_ISSUER", "https://somewhere.else.example"),
    ]);
    let refusal = plan("acme", "production", &overridden).unwrap_err();
    assert!(
        matches!(refusal, DeployError::Derived(_)),
        "the derivation is what refuses here: {refusal}"
    );
    wordings.push(format!("derived override: {refusal}"));
    // Half a both-or-neither pair. It needs the full environment: with
    // required vars missing, one of those refuses first, and a snapshot
    // that recorded THAT would say nothing about the pair law at all.
    let mut half_pairs: Vec<(String, String)> = full_env()
        .names()
        .map(|name| {
            (
                name.to_owned(),
                full_env().get(name).unwrap_or_default().to_owned(),
            )
        })
        .filter(|(name, _)| name != "SESAME_OAUTH_GITHUB_CLIENT_SECRET")
        .collect();
    half_pairs.retain(|(name, _)| name != "SESAME_OAUTH_GITHUB_CLIENT_SECRET");
    let half = EnvMap::from_pairs(half_pairs);
    let refusal = plan("acme", "production", &half).unwrap_err();
    assert!(
        matches!(refusal, DeployError::HalfPair(_)),
        "the pair law is what refuses here, not a missing var: {refusal}"
    );
    wordings.push(format!("half pair: {refusal}"));
    insta::assert_snapshot!("refusal_wordings", wordings.join("\n"));
}

#[test]
fn a_required_secret_is_missing_by_name() {
    let env = EnvMap::from_pairs([
        (ORIGIN, "https://auth.acme.example"),
        ("SESAME_PRODUCT_URL", "https://acme.example"),
        ("SESAME_MAIL_FROM", "no-reply@acme.example"),
    ]);
    // Every required var is absent, so the first refusal names one of
    // them rather than the secret. Fill the vars and the secret surfaces.
    assert!(matches!(
        plan("acme", "production", &env),
        Err(DeployError::Missing(_))
    ));
}

