//! The stage grammar: `(instance, stage)` in, every derived name out.
//!
//! Pure by construction. No I/O, no clock, no randomness, no ambient
//! environment read, which is CLAUDE.md §3's seam law applied to
//! deployment configuration: the same pair produces the same names on
//! any machine, so a plan is reviewable before it runs.
//!
//! No code path here compares a stage name to a literal outside
//! [`Stage::parse`]. Behavior derives from the env map; names derive from
//! the pair. That separation is what keeps "which stage is this" from
//! spreading into every derivation.

use crate::error::DeployError;

use core::fmt;

/// The instance name's shape: a lowercase word, two to twenty-five
/// characters. It is the only free-form half of the pair.
const INSTANCE_MIN: usize = 2;
const INSTANCE_MAX: usize = 25;

/// The stage vocabulary, parsed rather than pattern-matched.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Stage {
    /// The live deployment.
    Production,
    /// The proving ground main deploys to.
    Staging,
    /// One pull request's own deployment, destroyed when it closes.
    Preview(u32),
}

impl Stage {
    /// Parses a stage word.
    ///
    /// # Errors
    /// [`DeployError::UnknownStage`] for anything outside the vocabulary.
    /// The vocabulary is closed on purpose: a typo that produced a fourth
    /// stage would deploy a real worker under a name nothing sweeps.
    pub fn parse(raw: &str) -> Result<Self, DeployError> {
        match raw {
            "production" => Ok(Self::Production),
            "staging" => Ok(Self::Staging),
            other => {
                let number = other
                    .strip_prefix("preview-")
                    .and_then(|digits| digits.parse::<u32>().ok())
                    .filter(|number| *number > 0);
                number.map(Self::Preview).ok_or(DeployError::UnknownStage)
            }
        }
    }

    /// The stage's own word, which is also its suffix.
    ///
    /// why every stage carries a suffix, production included: the
    /// deployment id joins the instance and the stage, and without a
    /// suffix on production the join stops being injective. With one,
    /// (`acme`, `production`) gives `sesame-acme-production` and
    /// (`acme-production`, anything) can only ever be longer.
    #[must_use]
    pub fn word(self) -> String {
        match self {
            Self::Production => "production".to_owned(),
            Self::Staging => "staging".to_owned(),
            Self::Preview(number) => format!("preview-{number}"),
        }
    }

    /// The GitHub environment this stage deploys under, which is what
    /// carries production's reviewer gate.
    #[must_use]
    pub const fn github_environment(self) -> &'static str {
        match self {
            Self::Production => "production",
            Self::Staging => "staging",
            Self::Preview(_) => "preview",
        }
    }

    /// The database branch.
    ///
    /// Production maps to `main`, and that is the vendor's name rather
    /// than sesame's: PlanetScale fixes its default branch's name, so
    /// production is the one stage whose branch is not named after it.
    #[must_use]
    pub fn database_branch(self) -> String {
        match self {
            Self::Production => "main".to_owned(),
            other => other.word(),
        }
    }

    /// Whether this stage is torn down when its pull request closes.
    #[must_use]
    pub const fn is_ephemeral(self) -> bool {
        matches!(self, Self::Preview(_))
    }
}

impl fmt::Display for Stage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.word())
    }
}

/// One deployment's identity: the pair, and everything it names.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Deployment {
    instance: String,
    stage: Stage,
}

impl Deployment {
    /// Validates the pair.
    ///
    /// # Errors
    /// [`DeployError::BadInstance`] when the instance is outside its
    /// shape, and [`DeployError::UnknownStage`] for a stage outside the
    /// vocabulary.
    pub fn new(instance: &str, stage: &str) -> Result<Self, DeployError> {
        let stage = Stage::parse(stage)?;
        if !(INSTANCE_MIN..=INSTANCE_MAX).contains(&instance.len()) {
            return Err(DeployError::BadInstance);
        }
        let mut bytes = instance.bytes();
        let Some(first) = bytes.next() else {
            return Err(DeployError::BadInstance);
        };
        if !first.is_ascii_lowercase() {
            return Err(DeployError::BadInstance);
        }
        if !bytes.all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-') {
            return Err(DeployError::BadInstance);
        }
        if instance.ends_with('-') || instance.contains("--") {
            return Err(DeployError::BadInstance);
        }
        // why this one refusal by name: an operator who writes
        // `sesame-acme` gets `sesame-sesame-acme-production`, which
        // works, deploys, and reads as a mistake forever after. Refusing
        // it here costs one line and saves a rename.
        if instance.starts_with("sesame-") || instance == "sesame" {
            return Err(DeployError::InstanceIsPrefixed);
        }
        Ok(Self {
            instance: instance.to_owned(),
            stage,
        })
    }

    /// The instance half.
    #[must_use]
    pub fn instance(&self) -> &str {
        &self.instance
    }

    /// The stage half.
    #[must_use]
    pub const fn stage(&self) -> Stage {
        self.stage
    }

    /// The deployment id: the one name everything else hangs off.
    #[must_use]
    pub fn id(&self) -> String {
        format!("sesame-{}-{}", self.instance, self.stage.word())
    }

    /// The worker's name, which is the deployment id.
    #[must_use]
    pub fn worker_name(&self) -> String {
        self.id()
    }

    /// The alchemy stage, which is the deployment id.
    #[must_use]
    pub fn alchemy_stage(&self) -> String {
        self.id()
    }

    /// The database's name, derived from the instance alone.
    ///
    /// why not the pair: one database holds every stage as a branch, so
    /// staging and production share a database and differ by branch. The
    /// database itself is referenced by name and created once by hand,
    /// so no stage's teardown can delete it.
    #[must_use]
    pub fn database_name(&self) -> String {
        format!("sesame-{}", self.instance)
    }

    /// The database branch this stage deploys against.
    #[must_use]
    pub fn database_branch(&self) -> String {
        self.stage.database_branch()
    }

    /// The Hyperdrive configuration's name.
    #[must_use]
    pub fn hyperdrive_name(&self) -> String {
        format!("{}-db", self.id())
    }

    /// The environment file this deployment's own configuration lives
    /// in. Derived from the id so two deployments can never share one.
    #[must_use]
    pub fn fleet_env_path(&self) -> String {
        format!("infra/.env.{}", self.id())
    }

    /// The directory a self-hosted deployment keeps its rendered config
    /// and its drawn secrets in, derived from the id for the same reason.
    #[must_use]
    pub fn self_host_dir(&self) -> String {
        format!("deploy/{}/", self.id())
    }
}

impl fmt::Display for Deployment {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.id())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_stage_vocabulary_is_closed() {
        assert_eq!(Stage::parse("production"), Ok(Stage::Production));
        assert_eq!(Stage::parse("staging"), Ok(Stage::Staging));
        assert_eq!(Stage::parse("preview-42"), Ok(Stage::Preview(42)));
        for bad in [
            "prod",
            "PRODUCTION",
            "production ",
            "preview",
            "preview-",
            "preview-0",
            "preview--1",
            "preview-abc",
            "preview-99999999999",
            "dev",
            "",
        ] {
            assert_eq!(Stage::parse(bad), Err(DeployError::UnknownStage), "{bad}");
        }
    }

    #[test]
    fn the_join_is_injective() {
        // The reason every stage carries a suffix. Without one,
        // ("acme-production", "staging") and ("acme", "production")
        // would both have to be distinguishable from a shared id, and a
        // suffix-free production breaks that.
        let mut ids = Vec::new();
        for instance in ["acme", "acme-production", "acme-staging", "a"] {
            for stage in ["production", "staging", "preview-1", "preview-11"] {
                if let Ok(deployment) = Deployment::new(instance, stage) {
                    ids.push(deployment.id());
                }
            }
        }
        let total = ids.len();
        ids.sort();
        ids.dedup();
        assert_eq!(ids.len(), total, "two pairs must never share one id");
    }

    #[test]
    fn the_instance_shape_is_enforced() {
        assert!(Deployment::new("acme", "production").is_ok());
        assert!(Deployment::new("acme-corp", "staging").is_ok());
        assert!(Deployment::new("a1", "staging").is_ok());
        for bad in [
            "a",
            "",
            "Acme",
            "1acme",
            "-acme",
            "acme-",
            "acme--corp",
            "acme_corp",
            "acme.corp",
            "acme corp",
            "aaaaaaaaaaaaaaaaaaaaaaaaaa",
        ] {
            assert_eq!(
                Deployment::new(bad, "production").err(),
                Some(DeployError::BadInstance),
                "{bad}"
            );
        }
        // The prefixed instance refuses by its own name, so the message
        // can tell the operator what to write instead.
        assert_eq!(
            Deployment::new("sesame-acme", "production").err(),
            Some(DeployError::InstanceIsPrefixed)
        );
        assert_eq!(
            Deployment::new("sesame", "production").err(),
            Some(DeployError::InstanceIsPrefixed)
        );
    }

    #[test]
    fn every_derived_name_hangs_off_the_pair() {
        let acme = Deployment::new("acme", "production").expect("valid");
        assert_eq!(acme.id(), "sesame-acme-production");
        assert_eq!(acme.worker_name(), "sesame-acme-production");
        assert_eq!(acme.alchemy_stage(), "sesame-acme-production");
        assert_eq!(acme.hyperdrive_name(), "sesame-acme-production-db");
        assert_eq!(acme.fleet_env_path(), "infra/.env.sesame-acme-production");
        assert_eq!(acme.self_host_dir(), "deploy/sesame-acme-production/");
        // The database is per instance, so every stage of one product
        // shares it and differs by branch.
        assert_eq!(acme.database_name(), "sesame-acme");

        let preview = Deployment::new("acme", "preview-42").expect("valid");
        assert_eq!(preview.database_name(), acme.database_name());
        assert_ne!(preview.id(), acme.id());
    }

    #[test]
    fn production_is_the_one_branch_named_unlike_its_stage() {
        // The vendor fixes its default branch's name, so this is a fact
        // about PlanetScale rather than a choice sesame made.
        assert_eq!(
            Deployment::new("acme", "production")
                .expect("valid")
                .database_branch(),
            "main"
        );
        assert_eq!(
            Deployment::new("acme", "staging")
                .expect("valid")
                .database_branch(),
            "staging"
        );
        assert_eq!(
            Deployment::new("acme", "preview-7")
                .expect("valid")
                .database_branch(),
            "preview-7"
        );
    }

    #[test]
    fn only_a_preview_is_ephemeral() {
        assert!(Stage::Preview(1).is_ephemeral());
        assert!(!Stage::Staging.is_ephemeral());
        assert!(!Stage::Production.is_ephemeral());
        assert_eq!(Stage::Preview(1).github_environment(), "preview");
        assert_eq!(Stage::Production.github_environment(), "production");
    }
