//! The environment map: the small set of secrets and ids the grammar
//! reads, behind a type rather than an ambient `std::env` call.
//!
//! CLAUDE.md §3's seam law says the core reads no ambient environment,
//! and a deployment plan is exactly the kind of thing that should be
//! reproducible from stated inputs. The caller builds the map; the
//! grammar reads it. That is what makes a plan an artifact a reviewer can
//! read before anything runs, rather than something only reproducible on
//! the machine that produced it.

use alloc_free::BTreeMap;

mod alloc_free {
    pub use std::collections::BTreeMap;
}

/// The deploy-time-only prefix.
///
/// why `SESAME_DEPLOY_` rather than renaming across the boundary: a
/// value that becomes a worker binding keeps its binding name everywhere,
/// so `.dev.vars`, `image/serve.mjs`, `workerd/rig.ts`, and the fleet
/// environment all spell `SESAME_ENVELOPE_KEK` the same way. This prefix
/// marks the values that never become bindings at all.
pub const DEPLOY_PREFIX: &str = "SESAME_DEPLOY_";

/// The deployment's public origin. Every derived URL comes from it.
pub const ORIGIN: &str = "SESAME_DEPLOY_ORIGIN";

/// The addresses the send_email binding may send from.
pub const MAIL_SENDERS: &str = "SESAME_DEPLOY_MAIL_SENDERS";

/// The worker's CPU-millisecond ceiling.
pub const CPU_MS: &str = "SESAME_DEPLOY_CPU_MS";

/// A read-only view of the environment the plan derives from.
///
/// `BTreeMap` rather than a hash: the plan renders in a stable order, and
/// a stable order is what makes a plan diffable between two runs.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct EnvMap(BTreeMap<String, String>);

impl EnvMap {
    /// Builds a map from pairs.
    ///
    /// # Examples
    /// ```
    /// use sesame_deploy::env::{EnvMap, ORIGIN};
    /// let env = EnvMap::from_pairs([(ORIGIN, "https://auth.acme.com")]);
    /// assert_eq!(env.get(ORIGIN), Some("https://auth.acme.com"));
    /// ```
    #[must_use]
    pub fn from_pairs<K, V, I>(pairs: I) -> Self
    where
        I: IntoIterator<Item = (K, V)>,
        K: Into<String>,
        V: Into<String>,
    {
        Self(
            pairs
                .into_iter()
                .map(|(key, value)| (key.into(), value.into()))
                // An empty value is an absent value, matching the
                // worker's own optional reader: a blank binding is how
                // the lane turns a surface off, and the two halves must
                // agree on that or a rendered config would enable a
                // surface the worker then refuses.
                .filter(|(_, value): &(String, String)| !value.is_empty())
                .collect(),
        )
    }

    /// Reads one name.
    #[must_use]
    pub fn get(&self, name: &str) -> Option<&str> {
        self.0.get(name).map(String::as_str)
    }

    /// Whether a name is present.
    #[must_use]
    pub fn has(&self, name: &str) -> bool {
        self.0.contains_key(name)
    }

    /// Every name present, in stable order.
    pub fn names(&self) -> impl Iterator<Item = &str> {
        self.0.keys().map(String::as_str)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_empty_value_reads_as_absent() {
        // The worker's optional reader maps an empty binding to absent,
        // and the lane relies on that to turn surfaces off. If this map
        // disagreed, a rendered config would enable a surface the worker
        // then refuses to serve.
        let env = EnvMap::from_pairs([(ORIGIN, ""), (CPU_MS, "50")]);
        assert!(!env.has(ORIGIN));
        assert_eq!(env.get(CPU_MS), Some("50"));
    }

    #[test]
    fn the_names_read_in_a_stable_order() {
        let one = EnvMap::from_pairs([(CPU_MS, "50"), (ORIGIN, "https://a.example")]);
        let other = EnvMap::from_pairs([(ORIGIN, "https://a.example"), (CPU_MS, "50")]);
        assert_eq!(one, other, "insertion order is not part of the map");
        assert_eq!(
            one.names().collect::<Vec<_>>(),
            other.names().collect::<Vec<_>>()
        );
    }
}

