//! The deploy grammar's closed error taxonomy.
//!
//! Every variant names a shape the operator got wrong, and none of them
//! carries a value from the environment map. That is not politeness: the
//! env map holds a database password and two 32-byte secrets, and an
//! error type that could carry one would eventually print one into a CI
//! log. The property lane asserts it over arbitrary maps.

use core::fmt;

/// Why a deployment plan could not be built.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DeployError {
    /// The instance name is outside its shape.
    BadInstance,
    /// The instance name already carries the `sesame-` prefix the
    /// deployment id adds.
    InstanceIsPrefixed,
    /// The stage word is outside the closed vocabulary.
    UnknownStage,
    /// A required variable is absent. The field name is static text from
    /// the roster, never a value.
    Missing(&'static str),
    /// A present variable's shape is wrong. Again, the name only.
    Malformed(&'static str),
    /// A variable the grammar derives was set explicitly. Setting it is
    /// an operator overriding a derivation, which the plan refuses rather
    /// than silently preferring one of the two.
    Derived(&'static str),
    /// Half of a both-or-neither pair is present.
    HalfPair(&'static str),
}

impl fmt::Display for DeployError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BadInstance => f.write_str(
                "the instance is a lowercase word of 2 to 25 characters, \
                 starting with a letter, with single hyphens inside",
            ),
            Self::InstanceIsPrefixed => {
                f.write_str("the instance carries no sesame- prefix: the deployment id adds it")
            }
            Self::UnknownStage => {
                f.write_str("the stage is production, staging, or preview-<number>")
            }
            Self::Missing(name) => write!(f, "{name} is required and absent"),
            Self::Malformed(name) => write!(f, "{name} is present and malformed"),
            Self::Derived(name) => write!(
                f,
                "{name} is derived from the deployment's origin; remove it"
            ),
            Self::HalfPair(name) => write!(f, "{name} needs its other half"),
        }
    }
}

impl std::error::Error for DeployError {}

