//! Rendering the roster as a Markdown table an operator reads.
//!
//! Generated rather than written, because a hand-written table drifts
//! from the roster the moment a binding lands, and the drift stays
//! invisible until an operator follows the table and gets a deployment
//! that refuses at its first request. The golden lane pins these bytes,
//! so a roster change shows up as a table change in the same diff.

use core::fmt::Write as _;

use crate::roster::{Binding, BindingKind, Requirement, BINDINGS};

/// Renders every binding as one Markdown table.
///
/// # Examples
/// ```
/// let table = sesame_deploy::render::table::render();
/// assert!(table.starts_with("| Name | Kind |"));
/// assert!(table.contains("SESAME_ENVELOPE_KEK"));
/// ```
#[must_use]
pub fn render() -> String {
    let mut out = String::from("| Name | Kind | Required | What |\n|---|---|---|---|\n");
    for binding in BINDINGS {
        // why the ignored result: the sink is a String, which cannot fail
        // to accept bytes. `write!` over `push_str(&format!(..))` avoids
        // the intermediate allocation per row.
        let _ = writeln!(
            out,
            "| `{}` | {} | {} | {} |",
            binding.name,
            kind_word(binding),
            requirement_word(binding),
            binding.summary
        );
    }
    out
}

/// The kind's word for a reader rather than for a compiler.
fn kind_word(binding: &Binding) -> &'static str {
    match binding.kind {
        BindingKind::Var => "var",
        BindingKind::Secret => "secret",
        BindingKind::Platform => "platform",
    }
}

/// The requirement's word.
fn requirement_word(binding: &Binding) -> &'static str {
    match binding.requirement {
        Requirement::Required => "yes",
        Requirement::Optional => "no",
        Requirement::Derived => "derived",
    }
}

