//! Rendering a plan as `wrangler.toml`.
//!
//! This is the self-hoster's path. A deployment that runs on the fleet
//! goes through alchemy, which reads the plan's JSON; a deployment that
//! runs anywhere else needs a file `wrangler deploy` understands, and
//! this writes it from the same plan, so the two paths cannot drift into
//! different deployments of the same product.
//!
//! Secrets never appear. The rendered file names them in a comment so the
//! operator knows which `wrangler secret put` calls follow, and carries
//! none of their values: this file lands on disk and in a git repository.

use core::fmt::Write as _;

use crate::plan::DeployPlan;

/// Renders the plan.
///
/// # Examples
/// ```
/// # use sesame_deploy::env::{EnvMap, ORIGIN};
/// # use sesame_deploy::{plan, render::wrangler};
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// # use sesame_deploy::roster::{self, BindingKind, Requirement};
/// # // Every required var, filled: a deployment names all of them, and
/// # // the plan refuses by name until it does.
/// # let mut pairs: Vec<(String, String)> = roster::of_kind(BindingKind::Var)
/// #     .filter(|binding| binding.requirement == Requirement::Required)
/// #     .map(|binding| (binding.name.to_owned(), "1000".to_owned()))
/// #     .collect();
/// # pairs.push((ORIGIN.to_owned(), "https://auth.acme.com".to_owned()));
/// # pairs.push(("SESAME_ENVELOPE_KEK".to_owned(), "kek".to_owned()));
/// # pairs.push(("SESAME_PEPPER".to_owned(), "pepper".to_owned()));
/// # let env = EnvMap::from_pairs(pairs);
/// let rendered = wrangler::render(&plan("acme", "production", &env)?);
/// assert!(rendered.contains(r#"name = "sesame-acme-production""#));
/// // No secret value can be here, because the plan never carried one.
/// assert!(!rendered.contains("SESAME_PEPPER ="));
/// # Ok(())
/// # }
/// ```
#[must_use]
pub fn render(plan: &DeployPlan) -> String {
    // why every write's result is ignored: the sink is a String, which
    // cannot fail to accept bytes.
    let mut out = String::new();
    let _ = writeln!(
        out,
        "# Generated from the deployment pair ({}, {}) by sesame's own\n\
         # deployment grammar. Every value here derives from that pair and\n\
         # this deployment's environment; editing the file by hand puts it\n\
         # out of step with the grammar that renders it again.\n",
        plan.instance, plan.stage,
    );
    let _ = writeln!(out, "name = \"{}\"", plan.worker.name);
    out.push_str("main = \"build/worker/index.js\"\n");
    let _ = writeln!(
        out,
        "compatibility_date = \"{}\"",
        plan.worker.compatibility_date
    );
    out.push_str("compatibility_flags = [\"nodejs_compat\"]\n\n");

    match &plan.worker.domain {
        Some(domain) => {
            out.push_str(
                "# The custom domain, taken from the deployment's own origin. The zone\n\
                 # must already exist in this Cloudflare account.\n",
            );
            let _ = writeln!(
                out,
                "routes = [{{ pattern = \"{domain}\", custom_domain = true }}]\n"
            );
        }
        // A stage that claims no domain answers on its worker subdomain.
        // The plan's own field says why.
        None => out.push_str(
            "# This stage claims no custom domain: it is torn down with its\n\
             # pull request, and a hostname outlives that. It answers on its\n\
             # worker subdomain, which its own origin should name.\n\n",
        ),
    }

    // No block when the deployment named no ceiling: the platform's own
    // default is a better answer than one sesame invented.
    if let Some(cpu_ms) = plan.worker.cpu_ms {
        let _ = writeln!(out, "[limits]\ncpu_ms = {cpu_ms}\n");
    }

    out.push_str(
        "# The collector's schedule. Its work is idempotent and bounded, so\n\
         # every stage runs the same one.\n[triggers]\n",
    );
    let _ = writeln!(out, "crons = [\"{}\"]\n", plan.worker.cron);

    render_hyperdrive(&mut out, plan);
    render_mail(&mut out, plan);
    render_vars(&mut out, plan);
    render_secret_names(&mut out, plan);
    out
}

/// The database binding, with the placeholder an operator must replace.
fn render_hyperdrive(out: &mut String, plan: &DeployPlan) {
    out.push_str(
        "# Caching on is a deployment invariant (CLAUDE.md §4): prepared\n\
         # statements depend on it, and no knob turns it off.\n\
         #\n\
         # The id below is a placeholder, and `wrangler deploy` refuses it.\n\
         # Create or adopt the Hyperdrive configuration named in the comment\n\
         # (`wrangler hyperdrive create`) and paste the id it answers here.\n\
         [[hyperdrive]]\n\
         binding = \"SESAME_DB\"\n",
    );
    let _ = writeln!(
        out,
        "# the configuration to create or adopt: {}",
        plan.database.hyperdrive
    );
    out.push_str("id = \"REPLACE_WITH_HYPERDRIVE_ID\"\n\n");
}

/// The send_email binding, when the deployment named any senders.
fn render_mail(out: &mut String, plan: &DeployPlan) {
    if plan.mail_senders.is_empty() {
        return;
    }
    out.push_str("[[send_email]]\nname = \"MAIL\"\n");
    let addresses = plan
        .mail_senders
        .iter()
        .map(|address| format!("\"{address}\""))
        .collect::<Vec<_>>()
        .join(", ");
    let _ = writeln!(out, "allowed_destination_addresses = [{addresses}]\n");
}

/// Every `[vars]` entry, in roster order.
fn render_vars(out: &mut String, plan: &DeployPlan) {
    out.push_str("[vars]\n");
    for var in &plan.vars {
        if var.derived {
            out.push_str("# derived from the deployment's origin\n");
        }
        let _ = writeln!(out, "{} = \"{}\"", var.name, var.value);
    }
}

/// The secret names, and never their values.
fn render_secret_names(out: &mut String, plan: &DeployPlan) {
    if plan.secrets.is_empty() {
        return;
    }
    out.push_str(
        "\n# Secrets are pushed with `wrangler secret put`, never written\n\
         # here. This deployment expects:\n",
    );
    for secret in &plan.secrets {
        let _ = writeln!(out, "#   {secret}");
    }
}

