mod tests {
    use base64ct::{Base64, Encoding};

    /// The bijection between what this parser reads and what the deploy
    /// roster declares.
    ///
    /// CLAUDE.md §7 forbids hand-maintained lists, and the binding names
    /// are one: they live here, in `wrangler.toml`, in `image/serve.mjs`,
    /// and in `workerd/rig.ts`. Replacing all fifty-odd literals with
    /// imported constants would prove each name is *spelled* once and
    /// still let the two sets drift apart. This proves the sets agree,
    /// which is the law that matters, by reading this file's own source.
    ///
    /// A name added to the roster and never read here fails. A name read
    /// here and never rostered fails. Both directions, mechanically.
    #[test]
    fn every_binding_this_parser_reads_is_rostered() {
        const SOURCE: &str = include_str!("config.rs");
        let mut read: Vec<&str> = Vec::new();
        let mut rest = SOURCE;
        while let Some(at) = rest.find("\"SESAME_") {
            let after = &rest[at + 1..];
            let end = after.find('"').unwrap_or(after.len());
            let name = &after[..end];
            // The scan reads its own source, so the search literal above
            // matches too and yields a bare prefix with nothing behind
            // it. A real binding has a name after the namespace.
            let named = name.len() > "SESAME_".len()
                && name
                    .bytes()
                    .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || byte == b'_');
            if named {
                read.push(name);
            }
            rest = &after[end..];
        }
        read.sort_unstable();
        read.dedup();
        // The bindings this parser reads through a roster constant rather
        // than a literal, so the scan above cannot see them.
        let named = [
            sesame_deploy::roster::vars::ISSUER,
            sesame_deploy::roster::vars::OAUTH_CALLBACK_URL,
        ];

        for name in read.iter().copied().chain(named) {
            // The test scaffold's own stand-in name is not a binding.
            if name == "SESAME_X" {
                continue;
            }
            assert!(
                sesame_deploy::roster::binding(name).is_some(),
                "{name} is read here and missing from the deploy roster"
            );
        }
        for binding in sesame_deploy::roster::BINDINGS {
            if binding.kind == sesame_deploy::roster::BindingKind::Platform {
                // A platform binding is wired by the deploy tooling and
                // reached through `env.hyperdrive`/`env.send_email`, not
                // read as a var.
                continue;
            }
            assert!(
                read.contains(&binding.name) || named.contains(&binding.name),
                "{} is rostered and never read by the config parser",
                binding.name
            );
        }
    }

    use super::bounded::*;

    #[test]
    fn secret_decode_round_trips_and_bounds() {
        let encoded = Base64::encode_string(&[0x42; 32]);
        let decoded = decode_secret_32(&encoded, "SESAME_ENVELOPE_KEK").expect("32 bytes parse");
        assert_eq!(decoded.expose(), &[0x42; 32]);
        assert!(decode_secret_32("not base64!!", "SESAME_ENVELOPE_KEK").is_err());
        assert!(
            decode_secret_32(&Base64::encode_string(&[0x42; 16]), "SESAME_ENVELOPE_KEK").is_err()
        );
    }

    #[test]
    fn bounded_knobs_reject_zero_overflow_and_text() {
        assert_eq!(
            millis_bounded("600000", "X", MAX_DAY_MS).expect("in range"),
            600_000
        );
        for bad in ["0", "86400001", "six hundred thousand", "-1"] {
            assert!(millis_bounded(bad, "X", MAX_DAY_MS).is_err(), "{bad}");
        }
        assert!(count_bounded("1025", "X", MAX_FEED_PAGE_LIMIT).is_err());
        assert_eq!(
            count_bounded("1024", "X", MAX_FEED_PAGE_LIMIT).expect("at the cap"),
            1024
        );
        // The parse-side ceilings answer the same rule.
        assert!(millis_bounded("31536000001", "X", MAX_SESSION_TTL_MS).is_err());
        assert!(millis_bounded("604800001", "X", MAX_IDEMPOTENCY_TTL_MS).is_err());
        assert!(count_bounded("101", "X", MAX_MAGIC_SEND_MAX).is_err());
        assert!(count_bounded("1000001", "X", MAX_MAGIC_SEND_GLOBAL_MAX).is_err());
        assert!(count_bounded("101", "X", MAX_ORG_INVITE_MAX).is_err());
        assert!(count_bounded("1000001", "X", MAX_ORG_INVITE_GLOBAL_MAX).is_err());
        assert!(count_bounded("101", "X", MAX_ORG_INVITE_ADDRESS_MAX).is_err());
        assert!(count_bounded("101", "X", MAX_ORG_CREATE_USER_MAX).is_err());
