        for binding in BINDINGS {
            let computed = binding.requirement == Requirement::Derived
                || matches!(binding.kind, BindingKind::Platform(_));
            if computed {
                assert!(binding.env.is_none(), "{}: nothing supplies it", binding.name);
                assert!(binding.default.is_none(), "{}: nothing defaults it", binding.name);
            }
        }
    }

