            assert!(
                !binding.summary.is_empty() && binding.summary.len() <= 120,
                "{}: a summary is one readable line",
                binding.name
            );
        }
    }

    #[test]
    fn the_named_constants_are_in_the_roster() {
        for name in [
            names::CACHE_BUCKET,
            names::CACHET_KV,
            names::CACHET_EVENTS,
            names::ASSETS,
            names::CACHET_SIGNING_KEY,
