1	//! The deploy grammar's pure laws over arbitrary inputs
2	//! (docs/testing/property.md). The grammar is a function of its two
3	//! arguments, every derived name hangs off the deployment's name, and no
4	//! rendered error or plan ever carries a value out of the environment map.
5	
6	use hegel::TestCase;
7	use hegel::generators as gs;
8	
9	use cachet_deploy::env::{DOMAIN, EnvMap};
10	use cachet_deploy::roster::env as deploy;
11	use cachet_deploy::{Deployment, plan};
12	
13	/// The names a plan reads, plus names it ignores, so a sweep reaches both
14	/// halves of a map.
15	const NAMES: [&str; 10] = [
16	    deploy::HOST,
17	    deploy::ORGS,
18	    deploy::ADMINS,
19	    deploy::OAUTH_CLIENT_ID,
20	    deploy::SIGNING_KEY,
21	    deploy::OAUTH_CLIENT_SECRET,
22	    deploy::STATS_TOKEN,
23	    deploy::GC_GRACE_MS,
24	    DOMAIN,
25	    "CACHET_DEPLOY_UNKNOWN",
26	];
27	
28	/// A word drawn from an alphabet, so a name is usually valid and sometimes
29	/// not.
30	fn draw_word(tc: &TestCase, alphabet: &[u8], max: usize) -> String {
31	    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(max));
32	    bytes
33	        .iter()
34	        .map(|byte| alphabet[usize::from(*byte) % alphabet.len()] as char)
35	        .collect()
36	}
37	
38	#[hegel::test(test_cases = 256)]
39	fn name_validation_is_total(tc: TestCase) {
40	    // Any byte string in, a typed answer out, never a panic.
41	    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
42	    let raw = String::from_utf8_lossy(&bytes).into_owned();
43	    if let Ok(deployment) = Deployment::new(&raw) {
44	        // Anything accepted names resources the platform will take: a
45	        // worker or bucket name under 64 characters of lowercase,
46	        // digits, and dashes, and a dataset with no dash at all.
47	        let resource = deployment.resource_name();
48	        assert!(
49	            resource.len() <= 63,
50	            "{resource} is longer than a worker name"
51	        );
52	        assert!(
53	            resource
54	                .bytes()
55	                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-'),
56	            "{resource} carries a character a worker name cannot"
57	        );
58	        assert!(!deployment.dataset().contains('-'));
59	        // The prefix appears once, whether the operator wrote it or not.
60	        assert!(resource.starts_with("cachet-"));
61	        assert!(!resource.starts_with("cachet-cachet-"));
62	    }
63	}
64	
65	#[hegel::test(test_cases = 256)]
66	fn no_error_ever_renders_a_value_from_the_environment(tc: TestCase) {
67	    // The map holds the signing key, and an error that could carry a
68	    // value would eventually print one into a CI log. Every value here is
69	    // marked, so a leak is unmistakable.
70	    let count = tc.draw(gs::integers::<u8>()) % 10;
71	    let mut marked: Vec<(String, String)> = Vec::new();
72	    for index in 0..count {
73	        let slot = usize::from(tc.draw(gs::integers::<u8>())) % NAMES.len();
74	        let tail = draw_word(&tc, b"abcXYZ019:/._@-", 20);
75	        marked.push((NAMES[slot].to_owned(), format!("zz{index}zz{tail}")));
76	    }
77	    let name = draw_word(&tc, b"abcz019-_. ", 34);
78	
79	    let env = EnvMap::from_pairs(marked.clone());
80	    let Err(error) = plan(&name, &env) else {
81	        return;
82	    };
83	    let rendered = error.to_string();
84	    for (env_name, value) in &marked {
85	        assert!(
86	            !rendered.contains(value.as_str()),
87	            "the error rendered {env_name}'s value: {rendered}"
88	        );
89	    }
90	}
91	
92	#[hegel::test(test_cases = 256)]
93	fn a_plan_never_carries_a_secret_value(tc: TestCase) {
94	    // why the zz fences: a bare prefix with an empty drawn tail is a word
95	    // like "sec", which the JSON's own "secrets" key contains. The fences
96	    // make every marked value a string no field name can be.
97	    let key = format!("zzkey{}zz", draw_word(&tc, b"abcXYZ019+/=", 40));
98	    let secret = format!("zzsec{}zz", draw_word(&tc, b"abcXYZ019", 20));
99	    let token = format!("zztok{}zz", draw_word(&tc, b"abcXYZ019", 20));
100	    let name = format!("a{}", draw_word(&tc, b"abcz019", 12));
101	    let env = EnvMap::from_pairs([
102	        (deploy::HOST, "cache.example.com"),
103	        (deploy::ORGS, "acme"),
104	        (deploy::ADMINS, "ada"),
105	        (deploy::OAUTH_CLIENT_ID, "Iv1.abc"),
106	        (deploy::SIGNING_KEY, key.as_str()),
107	        (deploy::OAUTH_CLIENT_SECRET, secret.as_str()),
108	        (deploy::STATS_TOKEN, token.as_str()),
109	        (
110	            deploy::CLOUDFLARE_ACCOUNT_ID,
111	            "0123456789abcdef0123456789abcdef",
112	        ),
113	    ]);
114	    let Ok(built) = plan(&name, &env) else {
115	        return;
116	    };
117	    // The plan names its secrets and carries none of their values, which
118	    // is what makes `cachet plan` printable into a pull request.
119	    let json = serde_json::to_string(&built).expect("a plan serializes");
120	    assert!(json.contains("CACHET_SIGNING_KEY"), "the name is expected");
121	    for (label, value) in [
122	        ("the key", &key),
123	        ("the secret", &secret),
124	        ("the token", &token),
125	    ] {
126	        assert!(!json.contains(value.as_str()), "{label} reached the plan");
127	    }
128	}
