130	#[hegel::test(test_cases = 128)]
131	fn the_grammar_is_a_function_of_its_arguments(tc: TestCase) {
132	    // Pure means reproducible: the same name and the same map answer the
133	    // same plan on any machine, which is what lets a plan be reviewed
134	    // before it runs.
135	    let name = format!("a{}", draw_word(&tc, b"abcz019-", 12));
136	    let grace = u64::from(tc.draw(gs::integers::<u32>()));
137	    let env = EnvMap::from_pairs([
138	        (deploy::HOST, "cache.example.com".to_owned()),
139	        (deploy::ORGS, "acme, labs".to_owned()),
140	        (deploy::ADMINS, "ada".to_owned()),
141	        (deploy::OAUTH_CLIENT_ID, "Iv1.abc".to_owned()),
142	        (deploy::SIGNING_KEY, "k".to_owned()),
143	        (deploy::OAUTH_CLIENT_SECRET, "s".to_owned()),
144	        (deploy::GC_GRACE_MS, grace.to_string()),
145	    ]);
146	    assert_eq!(plan(&name, &env), plan(&name, &env));
147	}
148	
149	#[hegel::test(test_cases = 256)]
150	fn the_name_determines_every_other_name(tc: TestCase) {
151	    let name = format!("a{}", draw_word(&tc, b"abcz019-", 20));
152	    let Ok(deployment) = Deployment::new(&name) else {
153	        return;
154	    };
155	    let resource = deployment.resource_name();
156	    assert_eq!(deployment.worker_name(), resource);
157	    assert_eq!(deployment.bucket_name(), resource);
158	    assert_eq!(deployment.kv_title(), resource);
159	    assert_eq!(deployment.dataset(), resource.replace('-', "_"));
160	    assert!(deployment.env_file_path().ends_with(&name));
161	}

1	//! The binding bijection: the roster and the worker's reads are held to
2	//! each other.
3	//!
4	//! The binding names are one list that lived in several places, and a
5	//! name added to one and missed in another produces a worker that deploys
6	//! and then refuses at the first request that reads it. This test reads
7	//! `cachet-worker`'s source and `cachet-core/src/constants.rs` from disk,
8	//! the way cachet-api's test reads the committed OpenAPI document, and
9	//! asserts the two sets agree in both directions: a name read and never
10	//! rostered fails, and a name rostered and never read fails.
11	//!
12	//! It lives here rather than in the worker because the worker is wasm32
13	//! only and no lane runs its tests on a host (CLAUDE.md §4).
14	
15	use std::collections::BTreeSet;
16	use std::path::{Path, PathBuf};
17	
18	use cachet_deploy::roster::{self, BindingKind, names};
19	
20	/// The repository root, from this crate's own manifest directory.
21	fn root() -> PathBuf {
22	    PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../.."))
23	}
24	
25	/// Every `.rs` file under a directory, recursively. Panics when the
26	/// directory is absent: a gate that scanned nothing would pass while
27	/// holding nothing (CLAUDE.md §9).
28	fn sources(dir: &Path, out: &mut Vec<PathBuf>) {
29	    let entries = std::fs::read_dir(dir)
30	        .unwrap_or_else(|err| panic!("{} does not list: {err}", dir.display()));
31	    for entry in entries {
32	        let path = entry.expect("a directory entry reads").path();
33	        if path.is_dir() {
34	            sources(&path, out);
35	        } else if path.extension().is_some_and(|ext| ext == "rs") {
36	            out.push(path);
37	        }
38	    }
39	}
40	
41	/// The binding-shaped string literals in one source text: every quoted
42	/// `CACHET_*` or `CLOUDFLARE_*` word, plus the two platform names that
43	/// carry no prefix.
44	fn literals(source: &str, into: &mut BTreeSet<String>) {
45	    // why the naive split: these files quote no escaped double quotes, so
46	    // odd segments are the literals. A stricter tokenizer would be a
47	    // parser for a problem a split solves.
48	    for (index, segment) in source.split('"').enumerate() {
49	        if index % 2 == 0 {
50	            continue;
51	        }
52	        let shaped = segment.len() > 2
53	            && segment
54	                .bytes()
55	                .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || byte == b'_');
56	        if !shaped {
57	            continue;
58	        }
59	        let namespaced = segment.starts_with("CACHET_")
60	            || segment.starts_with("CLOUDFLARE_")
61	            || segment == names::CACHE_BUCKET
62	            || segment == names::ASSETS;
63	        if namespaced {
64	            into.insert(segment.to_owned());
65	        }
66	    }
67	}
68	
69	#[test]
70	fn every_binding_the_worker_reads_is_rostered_and_every_rostered_binding_is_read() {
71	    let mut files = Vec::new();
72	    sources(&root().join("crates/cachet-worker/src"), &mut files);
73	    files.push(root().join("crates/cachet-core/src/constants.rs"));
74	    assert!(files.len() > 10, "the worker's source tree is where it was");
75	
76	    let mut read = BTreeSet::new();
77	    for file in &files {
78	        let source = std::fs::read_to_string(file)
79	            .unwrap_or_else(|err| panic!("{} does not read: {err}", file.display()));
80	        literals(&source, &mut read);
81	    }
82	
83	    // What the worker reads through a roster constant rather than a
84	    // literal, so the scan above cannot see it.
85	    let named: BTreeSet<String> = [names::CACHE_BUCKET, names::CACHET_KV, names::ASSETS]
86	        .into_iter()
87	        .map(str::to_owned)
88	        .collect();
89	
90	    // A compile-time stamp, read with option_env! and never a binding.
91	    let stamps = ["CACHET_BUILD_SHA"];
92	
93	    for name in read.iter().filter(|name| !stamps.contains(&name.as_str())) {
94	        assert!(
95	            roster::binding(name).is_some(),
96	            "{name} is read by the worker and missing from the roster"
97	        );
98	    }
99	    for binding in roster::BINDINGS {
100	        let seen = read.contains(binding.name) || named.contains(binding.name);
101	        assert!(
102	            seen,
103	            "{} is rostered and never read by the worker ({:?})",
104	            binding.name, binding.kind
105	        );
106	    }
107	    // The platform bindings reach the worker through env.bucket, env.kv,
108	    // env.analytics_engine, and env.assets; every one is accounted for
109	    // above, so this is the count that would change if one were dropped.
110	    assert_eq!(roster::platform().count(), 4);
111	    assert!(roster::BINDINGS.iter().all(|binding| {
112	        !matches!(binding.kind, BindingKind::Platform(_)) || binding.env.is_none()
113	    }));
114	}

