//! The doctor probe: answers "is this machine wired to read" the way an
//! operator does, but mechanically. The load-bearing distinction is
//! 404-versus-401: the worker authenticates before it consults the
//! bucket, so a 404 proves the credential works (the probed hash is
//! simply absent) and a 401 proves it does not.

/// One check's outcome. `ok` answers the summary; `detail` explains the
/// failure to the human reading it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Probe {
    /// What was checked, one short clause.
    pub name: String,
    /// Whether it held.
    pub ok: bool,
    /// What the check answer meant, or what to do about it.
    pub detail: String,
}

impl Probe {
    fn pass(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: true,
            detail,
        }
    }

    fn fail(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: false,
            detail,
        }
    }
}

/// A hash that parses but cannot exist: all zero bits but the last.
const PROBE_NARINFO: &str = "0000000000000000000000000000000a.narinfo";

/// Run every probe against one deployment: the unauthenticated health
/// document, the public config, the refusal of an anonymous read, and —
/// when a token is stored — the authenticated read, GitHub identity,
/// and org membership. Absence of a stored token is itself a probe
/// outcome, not an error.
pub async fn run_doctor(
    client: &reqwest::Client,
    cache_url: &str,
    token: Option<&str>,
) -> Vec<Probe> {
    let mut probes = vec![probe_cache_info(client, cache_url).await];
    let (config_probe, config) = probe_config(client, cache_url).await;
    probes.push(config_probe);
    probes.push(probe_narinfo(client, cache_url, None, true).await);
    let Some(token) = token else {
        probes.push(Probe::fail(
            "a stored login exists",
            format!("no token for this host: run `cachet login --cache-url {cache_url}`"),
        ));
        return probes;
    };
    probes.push(Probe::pass(
        "a stored login exists",
        "the state directory holds a token".to_string(),
    ));
    probes.push(probe_narinfo(client, cache_url, Some(token), false).await);
    // why: no probe asks GitHub about this credential. The deployment
    // issued it, so GitHub has never seen it and answers 401 to any
    // question about it; a doctor that asked reported a revoked
    // credential on a machine whose reads were working. The read probe
    // above is the honest test, and it is a stronger one: it is the
    // deployment answering about the credential it issued, which is the
    // same check every real read makes.
    let _ = &config;
    probes
}

/// The health document: unauthenticated by design, and its body names
/// the store directory.
async fn probe_cache_info(client: &reqwest::Client, cache_url: &str) -> Probe {
    const NAME: &str = "the cache answers /nix-cache-info";
    match client
        .get(format!("{cache_url}/nix-cache-info"))
        .send()
        .await
    {
        Ok(answer) if answer.status().is_success() => {
            let body = answer.text().await.unwrap_or_default();
            if body.contains("StoreDir: /nix/store") {
                Probe::pass(NAME, format!("{cache_url} is serving"))
            } else {
                Probe::fail(
                    NAME,
                    "the body names no store dir: is this a cachet deployment?".to_string(),
                )
            }
        }
        Ok(answer) => Probe::fail(NAME, format!("answered {}", answer.status().as_u16())),
        Err(failure) => Probe::fail(NAME, format!("no answer: {failure}")),
    }
}

/// The config document: OAuth client id, orgs, host, and the public
/// key. The probe keeps the document for the membership checks.
async fn probe_config(
    client: &reqwest::Client,
    cache_url: &str,
) -> (Probe, Option<cachet_api::PublicConfig>) {
    match crate::login::fetch_public_config(client, cache_url).await {
        Ok(config) => {
            let probe = Probe::pass(
                "the public config serves",
                format!(
                    "host {}, orgs [{}], key {}",
                    config.host,
                    config.orgs.join(", "),
                    config.public_key.split(':').next().unwrap_or("?")
                ),
            );
            (probe, Some(config))
        }
        Err(failure) => (
            Probe::fail("the public config serves", failure.to_string()),
            None,
        ),
    }
}

/// The load-bearing probe, run twice: anonymous must refuse with 401
/// (auth before bucket work); the stored token must clear auth, which
/// the impossible hash then renders as a 404.
async fn probe_narinfo(
    client: &reqwest::Client,
    cache_url: &str,
    token: Option<&str>,
    anonymous: bool,
) -> Probe {
    let (name, refused_detail) = if anonymous {
        (
            "anonymous reads refuse",
            "401 before the bucket, as the auth order requires",
        )
    } else {
        (
            "the stored token reads",
            "404 means authenticated-and-absent: the wiring works",
        )
    };
    let mut request = client.get(format!("{cache_url}/{PROBE_NARINFO}"));
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let expect = if anonymous { 401 } else { 404 };
    match request.send().await {
        Ok(answer) if answer.status().as_u16() == expect => {
            Probe::pass(name, refused_detail.to_string())
        }
        Ok(answer) if !anonymous && answer.status().is_success() => Probe::pass(
            name,
            "the probe path unexpectedly exists, which still proves auth".to_string(),
        ),
        Ok(answer) => Probe::fail(
            name,
            if anonymous {
                format!(
                    "answered {} instead of 401: the read guard is misconfigured",
                    answer.status().as_u16()
                )
            } else {
                format!(
                    "answered {}: this machine's credential expired or was revoked; run `cachet login` again, then `cachet setup`",
                    answer.status().as_u16()
                )
            },
        ),
        Err(failure) => Probe::fail(name, format!("no answer: {failure}")),
    }
}

/// Render the probe list in the report's shape: an `ok`/`FAIL` line per
/// probe. Answers whether everything held.
#[must_use]
pub fn render(probes: &[Probe]) -> (Vec<String>, bool) {
    let mut all_ok = true;
    let mut lines = Vec::new();
    for probe in probes {
        if probe.ok {
            lines.push(format!("ok   {}: {}", probe.name, probe.detail));
        } else {
            all_ok = false;
            lines.push(format!("FAIL {}: {}", probe.name, probe.detail));
        }
    }
    (lines, all_ok)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_separates_ok_from_fail() {
        let probes = vec![
            Probe::pass("a", "fine".to_string()),
            Probe::fail("b", "broken".to_string()),
        ];
        let (lines, all_ok) = render(&probes);
        assert!(!all_ok);
        assert_eq!(lines[0], "ok   a: fine");
        assert_eq!(lines[1], "FAIL b: broken");
        let (happy, all_ok) = render(&[Probe::pass("a", "fine".to_string())]);
        assert!(all_ok);
        assert_eq!(happy.len(), 1);
    }
}

import { Schema } from "effect";

// The wire, decoded. Every response the console reads passes through one
// of these before any screen sees it, so a deployment that answers a
// shape this console does not understand fails at the boundary with the
// field named rather than three components later with `undefined`.
//
// The vocabularies below are the worker's own closed enums
// (cachet-core/src/stats.rs and stats_query.rs). They are written out
// rather than imported because the API is defined in Rust; the console
// lane decodes recorded worker answers with these schemas, which is what
// keeps the two in step.

export const Subject = Schema.Literals(["reads", "writes", "probes"]);
export type Subject = typeof Subject.Type;

export const Dimension = Schema.Literals([
  "kind",
  "outcome",
  "actor",
  "repository",
  "reference",
  "hour",
  "day",
]);
export type Dimension = typeof Dimension.Type;

export const Window = Schema.Literals(["day", "week", "month"]);
export type Window = typeof Window.Type;

export const Actor = Schema.Literals(["ci", "laptop", "browser", "anonymous"]);
export type Actor = typeof Actor.Type;

export const Kind = Schema.Literals([
  "narinfo",
  "nar",
  "part",
  "begin",
  "complete",
  "abort",
  "probe",
  "unknown",
]);
export type Kind = typeof Kind.Type;

export const PublicConfig = Schema.Struct({
  oauthClientId: Schema.String,
  orgs: Schema.Array(Schema.String),
  host: Schema.String,
  publicKey: Schema.String,
  deployment: Schema.String,
  version: Schema.String,
  buildSha: Schema.optional(Schema.String),
  fontCss: Schema.optional(Schema.String),
});
export type PublicConfig = typeof PublicConfig.Type;

export const WhoAmI = Schema.Struct({
  login: Schema.String,
  admin: Schema.Boolean,
  credential: Schema.Literals(["browser", "laptop", "ci"]),
  expiresAtMs: Schema.optional(Schema.Number),
});
export type WhoAmI = typeof WhoAmI.Type;

export const Health = Schema.Struct({
  status: Schema.Literals(["healthy", "degraded", "unknown"]),
  nextCollectionAtMs: Schema.optional(Schema.Number),
  latestRunId: Schema.optional(Schema.String),
  latestFinishedAtMs: Schema.optional(Schema.Number),
  gate: Schema.optional(Schema.String),
});
export type Health = typeof Health.Type;

export const StatsRow = Schema.Struct({
  dimension: Schema.String,
  count: Schema.Number,
  bytes: Schema.Number,
});
export type StatsRow = typeof StatsRow.Type;

export const StatsEvents = Schema.Struct({
  subject: Schema.String,
  dimension: Schema.String,
  window: Schema.String,
  filters: Schema.Struct({
    kind: Schema.optional(Schema.String),
    outcome: Schema.optional(Schema.String),
    actor: Schema.optional(Schema.String),
  }),
  rows: Schema.Array(StatsRow),
});
export type StatsEvents = typeof StatsEvents.Type;

export const GcRunList = Schema.Struct({
  runs: Schema.Array(Schema.String),
  nextCursor: Schema.optional(Schema.String),
});
export type GcRunList = typeof GcRunList.Type;

export const GcReport = Schema.Struct({
  runId: Schema.String,
  startedAtMs: Schema.Number,
  finishedAtMs: Schema.Number,
  inventoryPaths: Schema.Number,
  activeLeases: Schema.Number,
  markedPaths: Schema.Number,
  unreadableDeep: Schema.Number,
  narinfosDeleted: Schema.Number,
  narsDeleted: Schema.Number,
  bytesFreed: Schema.Number,
  uploadsAborted: Schema.Number,
  // why: nullable rather than optional. The worker streams this body
  // verbatim from the bucket and the stored document writes `gate: null`
  // on a run that finished, so a schema expecting an absent key would
  // refuse every clean run.
  gate: Schema.optional(Schema.NullOr(Schema.String)),
});
export type GcReport = typeof GcReport.Type;

export const Stats = Schema.Struct({
  basedOnRunId: Schema.String,
  inventoryPaths: Schema.Number,
  narinfosDeleted: Schema.Number,
  narsDeleted: Schema.Number,
  bytesFreed: Schema.Number,
  // Same null as the report this is projected from.
  gate: Schema.optional(Schema.NullOr(Schema.String)),
  finishedAtMs: Schema.Number,
});
export type Stats = typeof Stats.Type;

/// The worker's RFC 9457 refusal, which every route answers with.
export const Problem = Schema.Struct({
  status: Schema.Number,
  title: Schema.String,
  code: Schema.String,
});
export type Problem = typeof Problem.Type;

import { useQuery } from "@tanstack/react-query";
import * as stylex from "@stylexjs/stylex";
import { useState } from "react";

import * as api from "../api/client.ts";
import { Label, Panel } from "../components/ui/primitives.tsx";
import { CheckIcon, CopyIcon } from "../components/icons.tsx";
import { Failed, LoadingScreen } from "../components/ui/states.tsx";
import { color, font, leading, space, text } from "../styles/tokens.stylex.ts";

// Who can reach this deployment and how. The one screen an org member
// who is not an admin can read, because everything on it is either
// public configuration or a fact about the reader's own credential.

const styles = stylex.create({
  rows: { display: "flex", flexDirection: "column" },
  row: {
    display: "grid",
    gridTemplateColumns: "20ch 1fr auto",
    gap: space.s6,
    // why: centred. A label beside a one-line value reads as one row
    // only when the two share a centre line; aligning both to the top
    // left the label riding above its own value.
    alignItems: "center",
    paddingBlock: space.s4,
    borderBottomWidth: "1px",
    borderBottomStyle: "solid",
    borderBottomColor: color.line,
  },
  // The organizations row carries a second, explanatory line, so its
  // label belongs beside the first line rather than the block's middle.
  rowTop: { alignItems: "start" },
  value: {
    fontFamily: font.mono,
    fontSize: text.spec,
    lineHeight: leading.body,
    color: color.text,
    wordBreak: "break-all",
  },
  note: {
    fontFamily: font.ui,
    fontSize: text.spec,
    lineHeight: leading.body,
    color: color.muted,
    marginTop: space.s1,
  },
  copy: {
    fontFamily: font.ui,
    fontSize: text.label,
    letterSpacing: "0.08em",
    textTransform: "uppercase",
    color: { default: color.muted, ":hover": color.text },
    backgroundColor: "transparent",
    borderWidth: "1px",
    borderStyle: "solid",
    borderColor: color.line,
    paddingBlock: space.s2,
    paddingInline: space.s3,
    cursor: "pointer",
    flexShrink: 0,
  },
  columns: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(32ch, 1fr))",
    gap: space.s6,
    alignItems: "start",
  },
  code: {
    fontFamily: font.mono,
    fontSize: text.spec,
    lineHeight: leading.body,
    color: color.text,
    backgroundColor: color.ink,
    borderWidth: "1px",
    borderStyle: "solid",
    borderColor: color.line,
    padding: space.s4,
    margin: 0,
    overflowX: "auto",
    whiteSpace: "pre",
  },
  steps: {
    display: "flex",
    flexDirection: "column",
    gap: space.s4,
    listStyle: "none",
    padding: 0,
    margin: 0,
  },
  step: { display: "flex", gap: space.s3, alignItems: "baseline" },
  stepNumber: {
    fontFamily: font.ui,
    fontSize: text.label,
    lineHeight: leading.label,
    color: color.muted,
    borderWidth: "1px",
    borderStyle: "solid",
    borderColor: color.line,
