34	        crate::error::problem_response(ClientError::AuthUnavailable)
35	    };
36	    let client_id = match env.var("CACHET_OAUTH_CLIENT_ID") {
37	        Ok(client_id) => client_id.to_string(),
38	        Err(_) => return missing("CACHET_OAUTH_CLIENT_ID"),
39	    };
40	    let host = match env.var("CACHET_HOST") {
41	        Ok(host) => host.to_string(),
42	        Err(_) => return missing("CACHET_HOST"),
43	    };
44	    let public_key = match env.secret("CACHET_SIGNING_KEY") {
45	        Ok(secret) => match NixSecretKey::parse(&secret.to_string()) {
46	            Ok(key) => key.public_key_text(),
47	            Err(failure) => {
48	                crate::log::event(
49	                    "error",
50	                    "api.signing_key_corrupt",
51	                    &[("error", format!("{failure:?}"))],
52	                );
53	                return crate::error::problem_response(ClientError::AuthUnavailable);
54	            }
55	        },
56	        Err(_) => return missing("CACHET_SIGNING_KEY"),
57	    };
58	    // why each key parses before it is served: `cachet setup` writes every
59	    // key this document lists into the daemon's trusted keys, and nix
60	    // refuses a configuration holding a malformed one, so a typo in the
61	    // var would break a laptop's nix rather than one cache. The document
62	    // refuses instead, and the event names the var to fix.
63	    let mut previous_public_keys = Vec::new();
64	    if let Ok(listed) = env.var(PREVIOUS_PUBLIC_KEYS_VAR) {
65	        let listed = listed.to_string();
