74	                    "api.previous_key_malformed",
75	                    &[
76	                        ("name", PREVIOUS_PUBLIC_KEYS_VAR.to_string()),
77	                        ("error", format!("{failure:?}")),
78	                    ],
79	                );
80	                return crate::error::problem_response(ClientError::AuthUnavailable);
81	            }
82	            previous_public_keys.push(key.to_string());
83	        }
84	    }
85	    log::event("info", "api.public_config", &[]);
86	    // The body is cachet-api's shared type: the served wire and the
87	    // published OpenAPI schema cannot drift apart here.
88	    let body = serde_json::to_string(&cachet_api::PublicConfig {
89	        oauth_client_id: client_id,
90	        orgs: config.orgs,
91	        host,
92	        public_key,
93	        previous_public_keys,
94	        deployment: env
95	            .var(DEPLOY_NAME_VAR)
96	            .map_or_else(|_| "cachet".to_string(), |value| value.to_string()),
97	        version: env!("CARGO_PKG_VERSION").to_string(),
98	        // why: stamped by the build that produces the deployable bundle,
99	        // absent from any other build. A worker compiled outside that
