102	        build_sha: option_env!("CACHET_BUILD_SHA")
103	            .filter(|sha| !sha.is_empty())
104	            .map(ToString::to_string),
105	        font_css: env
106	            .var(FONT_CSS_VAR)
107	            .ok()
108	            .map(|value| value.to_string())
109	            .filter(|value| !value.is_empty()),
110	    })
111	    .expect("the config fields serialize");
112	    let headers = worker::Headers::new();
113	    headers.set("content-type", "application/json")?;
114	    headers.set("cache-control", "no-store")?;
