254	    vars: &[(String, String)],
255	) -> impl Fn(&[&str]) -> Result<(), String> + Send + Sync {
256	    let sudo = vars
257	        .iter()
258	        .find(|(key, _)| key == "CACHET_SUDO")
259	        .map_or_else(|| "sudo".to_string(), |(_, v)| v.clone());
260	    move |argv: &[&str]| -> Result<(), String> {
261	        let invocation: Vec<String> = if sudo.is_empty() {
262	            argv.iter().map(ToString::to_string).collect()
263	        } else {
264	            std::iter::once(sudo.clone())
265	                .chain(argv.iter().map(ToString::to_string))
266	                .collect()
267	        };
268	        // why: stdin inherits (sudo's password prompt lives on the tty),
269	        // but stdout/stderr are captured — the reload dance's probing
270	        // attempts fail routinely (no systemctl on macOS) and their
271	        // complaints read as cachet's own failure if inherited. The
272	        // error string keeps the detail for the surfaces that report it.
273	        let output = std::process::Command::new(&invocation[0])
274	            .args(&invocation[1..])
275	            .stdin(std::process::Stdio::inherit())
276	            .stdout(std::process::Stdio::null())
277	            .stderr(std::process::Stdio::piped())
278	            .output()
279	            .map_err(|failure| format!("could not run {}: {failure}", invocation[0]))?;
280	        let status = output.status;
281	        if status.success() {
282	            return Ok(());
283	        }
284	        let detail = String::from_utf8_lossy(&output.stderr);
285	        let detail = detail.trim();
286	        if detail.is_empty() {
287	            Err(format!("{} exited {status}", invocation.join(" ")))
288	        } else {
289	            Err(format!(
290	                "{} exited {status}: {detail}",
291	                invocation.join(" ")
292	            ))
293	        }
294	    }
295	}
