297	/// The system-file installer: compose fully at a scratch path, then
298	/// place through the privilege runner; a half-written system config is
299	/// worse than a stale one.
300	fn installer<'r>(
301	    run: &'r cachet_cli::setup::Privileged<'r>,
302	) -> impl Fn(&std::path::Path, &str, u32) -> Result<(), String> + 'r {
303	    move |path: &std::path::Path, contents: &str, mode: u32| -> Result<(), String> {
304	        let tmp = std::env::temp_dir().join(format!(
305	            "cachet-setup-{}-{}",
306	            std::process::id(),
307	            path.file_name().unwrap_or_default().to_string_lossy()
308	        ));
309	        std::fs::write(&tmp, contents)
310	            .map_err(|failure| format!("{}: {failure}", tmp.display()))?;
311	        #[cfg(unix)]
312	        {
313	            use std::os::unix::fs::PermissionsExt as _;
314	            std::fs::set_permissions(&tmp, std::fs::Permissions::from_mode(mode))
315	                .map_err(|failure| format!("chmod {}: {failure}", tmp.display()))?;
316	        }
317	        if let Some(parent) = path.parent() {
318	            run(&["mkdir", "-p", &parent.to_string_lossy()])?;
319	        }
320	        run(&["cp", &tmp.to_string_lossy(), &path.to_string_lossy()])?;
321	        run(&["chmod", &format!("{mode:o}"), &path.to_string_lossy()])?;
322	        let _ = std::fs::remove_file(&tmp);
323	        Ok(())
324	    }
325	}
