327	/// The closing report: every write, then how the daemon restart went.
328	fn print_setup_report(host: &str, report: &cachet_cli::setup::SetupReport) {
329	    // Name the install. The two are wired differently (Determinate reads
330	    // the netrc it synthesizes from additionalNetrcSources, plain nix
331	    // reads netrc-file), so a reader chasing a 401 needs to know which
332	    // machine they are on before any of the paths below mean anything.
333	    if report.determinate {
334	        println!("cachet: Determinate Nix detected; wiring it the way it expects");
335	    } else {
336	        println!("cachet: nix detected");
337	    }
338	    let mut wrote = report.wrote.iter();
339	    if let Some(first) = wrote.next() {
340	        println!("cachet: {host} configured in {}", first.display());
341	    }
342	    for path in wrote {
343	        println!("cachet: wrote {}", path.display());
344	    }
345	    match &report.reload {
346	        cachet_cli::setup::ReloadOutcome::Systemd => {
347	            println!(
348	                "cachet: nix-daemon restarted with systemctl, so the new configuration is live"
349	            );
350	        }
351	        cachet_cli::setup::ReloadOutcome::Launchctl(label) => {
352	            println!("cachet: nix-daemon restarted ({label}), so the new configuration is live");
353	        }
354	        cachet_cli::setup::ReloadOutcome::DeterminateInit => {
355	            println!("cachet: determinate-nixd re-initialized, so the new configuration is live");
356	        }
357	        cachet_cli::setup::ReloadOutcome::Failed => {
358	            eprintln!(
359	                "cachet: could NOT restart nix-daemon, so the settings above are not in effect yet."
360	            );
361	            eprintln!("  Substitution will keep returning 401 until it reloads. Restart it with:");
362	            eprintln!(
363	                "    sudo launchctl kickstart -k system/systems.determinate.nix-daemon   # macOS, Determinate"
364	            );
365	            eprintln!(
366	                "    sudo launchctl kickstart -k system/org.nixos.nix-daemon              # macOS, upstream"
367	            );
368	            eprintln!(
369	                "    sudo systemctl restart nix-daemon                                    # linux"
370	            );
371	        }
372	    }
373	}
