411	/// The probe run, printing every line; the exit code answers the
412	/// aggregate.
413	async fn doctor(vars: Vec<(String, String)>, cache_url: Option<String>) -> ExitCode {
414	    let outcome = async {
415	        let dir = config::state_dir(&vars)?;
416	        let url = config::resolve_cache_url(cache_url.as_deref(), &dir)?;
417	        let host = config::host_of(&url)?;
418	        let client = cachet_cli::http_client()?;
419	        let token = config::read_token(&dir, &host)?;
420	        // The account is a fact this machine already holds, not a
421	        // question for anyone: the deployment named it at login.
422	        let login = config::read_login(&dir, &host).unwrap_or_default();
423	        Ok::<_, cachet_cli::CliError>((url, client, token, login))
424	    }
425	    .await;
426	    match outcome {
427	        Ok((url, client, token, login)) => {
428	            let probes = cachet_cli::doctor::run_doctor(&client, &url, token.as_deref()).await;
429	            let (lines, all_ok) = cachet_cli::doctor::render(&probes);
430	            for line in lines {
431	                println!("{line}");
432	            }
433	            if let Some(login) = login {
434	                println!("cachet: this machine's credential belongs to {login}");
435	            }
436	            if all_ok {
437	                ExitCode::SUCCESS
438	            } else {
439	                ExitCode::FAILURE
440	            }
441	        }
442	        Err(failure) => {
443	            eprintln!("cachet: {failure}");
444	            ExitCode::FAILURE
445	        }
446	    }
447	}
