508	/// Resolve the state directory: the explicit override, then XDG, then
509	/// the home fallback. The override exists so tests and unusual layouts
510	/// stay first-class.
511	///
512	/// # Errors
513	///
514	/// [`CliError`] when no home directory is discoverable.
515	pub fn state_dir(vars: &[(String, String)]) -> Result<PathBuf, CliError> {
516	    let value = |name: &str| {
517	        vars.iter()
518	            .find(|(key, _)| key == name)
519	            .map(|(_, v)| v.clone())
520	            .filter(|v| !v.is_empty())
521	    };
522	    if let Some(explicit) = value("CACHET_CONFIG_DIR") {
523	        return Ok(PathBuf::from(explicit));
524	    }
525	    if let Some(xdg) = value("XDG_CONFIG_HOME") {
526	        return Ok(PathBuf::from(xdg).join("cachet"));
527	    }
528	    value("HOME")
529	        .map(|home| PathBuf::from(home).join(".config").join("cachet"))
530	        .ok_or_else(|| CliError("no home directory: set CACHET_CONFIG_DIR explicitly".to_string()))
531	}
