544	/// Persist a login: the token at 0600 under its host, and the base URL
545	/// as the new default. Re-login overwrites both, so rotation is just
546	/// logging in again.
547	///
548	/// # Errors
549	///
550	/// [`CliError`] on any write or permission failure.
551	pub fn store_login(
552	    dir: &Path,
553	    host: &str,
554	    base_url: &str,
555	    token: &str,
556	    login: &str,
557	) -> Result<(), CliError> {
558	    let tokens = dir.join("tokens");
559	    std::fs::create_dir_all(&tokens)
560	        .map_err(|failure| CliError(format!("could not create {}: {failure}", tokens.display())))?;
561	    let path = token_path(dir, host);
562	    std::fs::write(&path, format!("{token}\n"))
563	        .map_err(|failure| CliError(format!("could not write {}: {failure}", path.display())))?;
564	    #[cfg(unix)]
565	    {
566	        use std::os::unix::fs::PermissionsExt as _;
567	        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).map_err(
568	            |failure| CliError(format!("could not chmod {}: {failure}", path.display())),
569	        )?;
570	    }
571	    // why: the login is remembered rather than looked up. The credential
572	    // is this deployment's, so GitHub cannot say who holds it, and the
573	    // deployment already said at the exchange. A diagnostic that named
574	    // the account by asking GitHub about a token GitHub never issued
575	    // reported a revoked credential on a perfectly working machine.
576	    let login_path = tokens.join(format!("{host}.login"));
577	    std::fs::write(&login_path, format!("{login}\n")).map_err(|failure| {
578	        CliError(format!(
579	            "could not write {}: {failure}",
580	            login_path.display()
581	        ))
582	    })?;
583	    std::fs::write(default_url_path(dir), format!("{base_url}\n")).map_err(|failure| {
584	        CliError(format!(
585	            "could not write {}: {failure}",
586	            default_url_path(dir).display()
587	        ))
588	    })?;
589	    Ok(())
590	}
