653	/// The host a base URL names, for netrc and token filenames. A URL
654	/// whose host cannot be told from its path is a configuration bug, so
655	/// this fails loudly rather than guessing.
656	///
657	/// # Errors
658	///
659	/// [`CliError`] on a shape that names no host.
660	pub fn host_of(base_url: &str) -> Result<String, CliError> {
661	    let stripped = base_url
662	        .trim_end_matches('/')
663	        .strip_prefix("https://")
664	        .or_else(|| base_url.trim_end_matches('/').strip_prefix("http://"))
665	        .ok_or_else(|| {
666	            CliError(format!(
667	                "the cache URL {base_url:?} must start with https://"
668	            ))
669	        })?;
670	    let host = stripped
671	        .split(['/', ':', '?', '#'])
672	        .next()
673	        .filter(|h| !h.is_empty())
674	        .ok_or_else(|| CliError(format!("the cache URL {base_url:?} names no host")))?;
675	    if !host
676	        .chars()
677	        .all(|ch| ch.is_ascii_alphanumeric() || ch == '.' || ch == '-')
678	    {
679	        return Err(CliError(format!("{host:?} is not a plausible hostname")));
680	    }
681	    Ok(host.to_string())
682	}
