688	///
689	/// [`CliError`] naming the fix when neither exists.
690	pub fn resolve_cache_url(flag: Option<&str>, dir: &Path) -> Result<String, CliError> {
691	    if let Some(url) = flag {
692	        return Ok(url.trim_end_matches('/').to_string());
693	    }
