768	/// `default` keyword to the next one, across as many lines as it
769	/// occupies: dropping whole blocks is what keeps orphaned `password`
770	/// lines from leaking a credential for a machine the file no longer
771	/// names.
772	#[must_use]
773	pub fn netrc_replace_block(existing: &str, host: &str, token: &str) -> String {
774	    #[derive(Debug, PartialEq)]
775	    enum Kind {
776	        Preamble,
777	        Machine(String),
778	        Default,
779	    }
780	
781	    let mut spans: Vec<(Kind, &str)> = Vec::new();
782	    let mut start = 0_usize;
783	    let mut kind = Kind::Preamble;
784	    // The scanner walks whole tokens but keeps byte offsets, so kept
785	    // spans survive with their original spacing.
786	    let bytes = existing.as_bytes();
787	    let mut cursor = 0_usize;
788	    while cursor < existing.len() {
789	        while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
790	            cursor += 1;
791	        }
792	        let token_start = cursor;
793	        while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
794	            cursor += 1;
795	        }
796	        let token = &existing[token_start..cursor];
797	        if token == "machine" || token == "default" {
798	            if token_start > start {
799	                spans.push((kind, &existing[start..token_start]));
800	            }
801	            if token == "machine" {
802	                while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
803	                    cursor += 1;
804	                }
805	                let name_start = cursor;
806	                while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
807	                    cursor += 1;
808	                }
809	                kind = Kind::Machine(existing[name_start..cursor].to_string());
810	            } else {
811	                kind = Kind::Default;
812	            }
813	            start = token_start;
814	        }
815	    }
816	    if existing.len() > start {
817	        spans.push((kind, &existing[start..]));
818	    }
819	
