90	    let mut cursor = 0_usize;
91	    while cursor < existing.len() {
92	        while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
93	            cursor += 1;
94	        }
95	        let token_start = cursor;
96	        while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
97	            cursor += 1;
98	        }
99	        let token = &existing[token_start..cursor];
100	        if token == "machine" || token == "default" {
101	            if token_start > start {
102	                spans.push((kind, &existing[start..token_start]));
103	            }
104	            if token == "machine" {
105	                while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
106	                    cursor += 1;
107	                }
108	                let name_start = cursor;
109	                while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
110	                    cursor += 1;
111	                }
112	                kind = Kind::Machine(existing[name_start..cursor].to_string());
113	            } else {
114	                kind = Kind::Default;
115	            }
116	            start = token_start;
117	        }
118	    }
119	    if existing.len() > start {
