  onSignOut: () => void;
  children: ReactNode;
}) => {
  const pathname = useRouterState({
    select: (state) => state.location.pathname,
  });
  const edge = useEdge();
  const here = SCREENS.find((screen) => screen.to === pathname) ?? SCREENS[0];
