input.content:
//! The placeholder grammar: the closed set of `$` tokens a manifest may
//! carry, and the two renderers.
//!
//! The set is closed on purpose. A renderer that guessed at an unknown
//! token would deploy a binding whose value nobody chose, so every `$`
//! followed by an uppercase letter must name one of these, or the whole
//! render refuses:
//!
//! | Token | Meaning |
//! | --- | --- |
//! | `$NAME` | the instance's name as the operator wrote it |
//! | `$RESOURCE_NAME` | the name every account resource is created under |
//! | `$RESOURCE_NAME_UNDERSCORED` | the same with dashes as underscores |
//! | `$HOST` | the instance's host |
//! | `$VERSION` | the release's version |
//! | `$VAR(<binding>)` | the operator's value for a var |
//! | `$SECRET(<binding>)` | the operator's value for a secret |
//! | `$GENERATED_PUBLIC(<secret>)` | the public half of a key the deployer generated for a secret |
//!
//! A `$` followed by anything else is a literal dollar sign, so a JSON
//! path like `$.version` in a probe passes through untouched.
//!
//! Two renderers, because a secret's value must never reach a printable
//! place. [`render_public`] refuses a template that names one;
//! [`render_secret`] is what a `secret_text` binding renders through, and
//! its output goes into a request body and nowhere else.

use std::collections::BTreeMap;

/// One piece of a parsed template.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Segment {
    /// Text carried verbatim.
    Literal(String),
    /// `$NAME`.
    Name,
    /// `$RESOURCE_NAME`.
    ResourceName,
    /// `$RESOURCE_NAME_UNDERSCORED`.
    ResourceNameUnderscored,
    /// `$HOST`.
    Host,
    /// `$VERSION`.
    Version,
    /// `$VAR(<binding>)`.
    Var(String),
    /// `$SECRET(<binding>)`.
    Secret(String),
    /// `$GENERATED_PUBLIC(<secret>)`.
    GeneratedPublic(String),
}

/// Why a template did not parse.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PlaceholderError {
    /// A `$` token outside the closed set.
    Unknown(String),
    /// A token that takes an argument had none, or an unclosed one.
    MissingArgument(String),
}

impl core::fmt::Display for PlaceholderError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Unknown(token) => write!(f, "${token} is not a placeholder this deployer knows"),
            Self::MissingArgument(token) => {
                write!(f, "${token} names a binding in parentheses, and none followed")
            }
        }
    }
}

impl std::error::Error for PlaceholderError {}

/// Parse a template into segments.
///
/// # Errors
/// [`PlaceholderError`] on a `$` token outside the set, or an argument
/// form with no argument.
///
/// # Examples
/// ```
/// use deployer_manifest::placeholder::{parse, Segment};
/// let parsed = parse("https://$HOST-1")?;
/// assert_eq!(parsed, vec![
///     Segment::Literal("https://".to_owned()),
///     Segment::Host,
///     Segment::Literal("-1".to_owned()),
/// ]);
/// // A dollar sign that starts no token is a dollar sign.
/// assert_eq!(parse("$.version")?, vec![Segment::Literal("$.version".to_owned())]);
/// assert!(parse("$NOPE").is_err());
/// # Ok::<(), deployer_manifest::placeholder::PlaceholderError>(())
/// ```
pub fn parse(template: &str) -> Result<Vec<Segment>, PlaceholderError> {
    let mut segments = Vec::new();
    let mut literal = String::new();
    let mut rest = template;
    while let Some(at) = rest.find('$') {
        let (before, tail) = rest.split_at(at);
        literal.push_str(before);
        let after = &tail[1..];
        let word_len = after
            .bytes()
            .take_while(|byte| byte.is_ascii_uppercase() || *byte == b'_')
            .count();
        if word_len == 0 || !after.as_bytes()[0].is_ascii_uppercase() {
            literal.push('$');
            rest = after;
            continue;
        }
        let word = &after[..word_len];
        let mut consumed = 1 + word_len;
        let segment = match word {
            "NAME" => Segment::Name,
            "RESOURCE_NAME" => Segment::ResourceName,
            "RESOURCE_NAME_UNDERSCORED" => Segment::ResourceNameUnderscored,
            "HOST" => Segment::Host,
            "VERSION" => Segment::Version,
            "VAR" | "SECRET" | "GENERATED_PUBLIC" => {
                let argument = &after[word_len..];
                let Some(inner) = argument.strip_prefix('(') else {
                    return Err(PlaceholderError::MissingArgument(word.to_owned()));
                };
                let Some(close) = inner.find(')') else {
                    return Err(PlaceholderError::MissingArgument(word.to_owned()));
                };
                let name = &inner[..close];
                if name.is_empty() {
                    return Err(PlaceholderError::MissingArgument(word.to_owned()));
                }
                consumed += 1 + close + 1;
                match word {
                    "VAR" => Segment::Var(name.to_owned()),
                    "SECRET" => Segment::Secret(name.to_owned()),
                    _ => Segment::GeneratedPublic(name.to_owned()),
                }
            }
            other => return Err(PlaceholderError::Unknown(other.to_owned())),
        };
        if !literal.is_empty() {
            segments.push(Segment::Literal(std::mem::take(&mut literal)));
        }
        segments.push(segment);
        rest = &tail[consumed..];
    }
    literal.push_str(rest);
    if !literal.is_empty() {
