//! The manifest's types and their validation.
//!
//! The shape is cachet's `cachet-deploy` manifest, generalized where a
//! second product needs it: a resource may be a Hyperdrive configuration,
//! a D1 database, or a queue; a worker may bind `send_email`; the asset
//! layer and the console are optional. A manifest cachet emits round-trips
//! through these types byte for byte, which the golden lane pins.
//!
//! Validation is structural and closed. Every binding names a declared
//! resource, every `$` parses, secrets appear only where a secret may, and
//! the artifacts, when present, cover every module. A manifest that fails
//! any of these never reaches a renderer.

use std::collections::{BTreeMap, BTreeSet};

use serde::{Deserialize, Serialize};

use crate::placeholder::{self, PlaceholderError};
use crate::MANIFEST_VERSION;

/// Whether a deployment must carry a var or secret.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Requirement {
    /// The worker refuses to serve without it. One with a default may be
    /// omitted by the operator, because the deployer supplies the default.
    Required,
    /// The worker runs without it, and omitting it turns one surface off.
    Optional,
    /// The deployer computes it; no operator supplies it.
    Derived,
}

/// The whole manifest.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Manifest {
    /// The schema version, which must equal [`MANIFEST_VERSION`].
    pub manifest_version: u32,
    /// The product, which is also the prefix its resources carry.
    pub product: String,
    /// The release's version.
    pub version: String,
    /// The worker.
    pub worker: WorkerSpec,
    /// The account resources an install creates, each with a key the
    /// bindings reference.
    pub resources: Vec<Resource>,
    /// The worker's bindings.
    pub bindings: Vec<BindingSpec>,
    /// The vars a deployment carries.
    pub vars: Vec<VarSpec>,
    /// The secrets a deployment carries.
    pub secrets: Vec<SecretSpec>,
    /// The cron triggers.
    pub crons: Vec<CronSpec>,
    /// How the worker is reached.
    pub route: RouteSpec,
    /// The asset layer, for a product that serves one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assets: Option<AssetsSpec>,
    /// What an install checks after it applies, in order.
    pub verify: Vec<Probe>,
    /// The console, for a product that serves one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub console: Option<ConsoleSpec>,
    /// The measured artifacts. Absent on a product's committed template;
    /// its release workflow fills it, and the deployer refuses to install
    /// a manifest without it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub artifacts: Option<Artifacts>,
}

/// The worker's release-level facts.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WorkerSpec {
    /// The entry module's name within `modules`.
    pub main_module: String,
    /// Every module the bundle uploads.
    pub modules: Vec<ModuleDecl>,
    /// The platform semantics.
    pub compatibility_date: String,
    /// The compatibility flags, stated rather than inherited.
    pub compatibility_flags: Vec<String>,
    /// Whether observability is on.
    pub observability: bool,
    /// The limits.
    pub limits: Limits,
}

/// One module, by name and kind; its hash lives in [`Artifacts`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModuleDecl {
    /// A POSIX path relative to the entry.
    pub name: String,
    /// What it is.
    pub kind: ModuleKind,
}

/// What a module is, which decides the content type it uploads under.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum ModuleKind {
    /// An ES module: `application/javascript+module`.
    EsModule,
    /// A compiled wasm module: `application/wasm`.
    CompiledWasm,
    /// A text module: `text/plain`.
    Text,
    /// A data module: `application/octet-stream`.
    Data,
}

impl ModuleKind {
    /// The content type the Workers API takes for this kind.
    #[must_use]
    pub const fn content_type(self) -> &'static str {
        match self {
            Self::EsModule => "application/javascript+module",
            Self::CompiledWasm => "application/wasm",
            Self::Text => "text/plain",
            Self::Data => "application/octet-stream",
        }
    }
}

/// The worker's limits.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Limits {
    /// The CPU ceiling in milliseconds.
    pub cpu_ms: u32,
}

/// An account resource an install creates.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Resource {
    /// An R2 bucket.
    R2Bucket {
        /// The key bindings reference.
        key: String,
        /// The bucket's name, as a template.
        name: String,
    },
    /// A KV namespace.
    KvNamespace {
        /// The key bindings reference.
        key: String,
        /// The namespace's title, as a template.
        title: String,
    },
    /// An Analytics Engine dataset. Configuration only: nothing is created
    /// and nothing is destroyed with the deployment.
    AnalyticsEngine {
        /// The key bindings reference.
        key: String,
        /// The dataset's name, as a template.
        dataset: String,
    },
    /// A Hyperdrive configuration in front of a database the operator
    /// supplies, whose connection string is a secret.
    Hyperdrive {
        /// The key bindings reference.
        key: String,
        /// The configuration's name, as a template.
        name: String,
        /// The origin connection string, as a `$SECRET(...)` template.
        origin: String,
    },
    /// A D1 database.
    D1 {
        /// The key bindings reference.
        key: String,
        /// The database's name, as a template.
        name: String,
    },
    /// A queue.
    Queue {
        /// The key bindings reference.
        key: String,
        /// The queue's name, as a template.
        name: String,
    },
}

impl Resource {
    /// The key bindings reference this resource by.
    #[must_use]
    pub fn key(&self) -> &str {
        match self {
            Self::R2Bucket { key, .. }
            | Self::KvNamespace { key, .. }
            | Self::AnalyticsEngine { key, .. }
            | Self::Hyperdrive { key, .. }
            | Self::D1 { key, .. }
            | Self::Queue { key, .. } => key,
        }
    }

    /// The templates this resource carries that a public render fills.
    fn public_templates(&self) -> Vec<(&'static str, &str)> {
        match self {
            Self::R2Bucket { name, .. }
            | Self::Hyperdrive { name, .. }
            | Self::D1 { name, .. }
            | Self::Queue { name, .. } => vec![("name", name)],
            Self::KvNamespace { title, .. } => vec![("title", title)],
            Self::AnalyticsEngine { dataset, .. } => vec![("dataset", dataset)],
        }
    }
}

/// One worker binding.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BindingSpec {
    /// The Workers API binding type: `r2_bucket`, `kv_namespace`,
    /// `analytics_engine`, `assets`, `hyperdrive`, `d1`, `queue`,
    /// `send_email`.
    #[serde(rename = "type")]
    pub kind: String,
    /// The binding's name.
    pub name: String,
    /// The resource it binds, for a binding that binds one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource: Option<String>,
}

/// One var a deployment carries.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VarSpec {
    /// The binding's name.
    pub name: String,
    /// Whether a deployment must carry it.
    pub requirement: Requirement,
    /// Its value as a template or a literal.
    pub value: String,
    /// The deploy-time environment variable that supplies it, for a CLI
    /// reading an env file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub env: Option<String>,
    /// The value it takes when the operator omits it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default: Option<String>,
    /// One line an operator reads beside the name.
    pub summary: String,
    /// How a wizard asks for it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub wizard: Option<Wizard>,
}

/// One secret a deployment carries.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SecretSpec {
    /// The binding's name.
    pub name: String,
    /// Whether a deployment must carry it.
    pub requirement: Requirement,
    /// Its value as a `$SECRET(...)` template.
    pub value: String,
    /// The deploy-time environment variable that supplies it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub env: Option<String>,
    /// One line an operator reads beside the name.
    pub summary: String,
    /// How a wizard asks for it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub wizard: Option<Wizard>,
    /// How a deployer generates it where the customer is, when it does.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub generated: Option<Generated>,
}

/// How a wizard collects a value.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Wizard {
    /// The field's label.
    pub label: String,
    /// One or two sentences under the field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub help: Option<String>,
    /// The third-party console page where the value is made.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub console_url: Option<String>,
    /// Ordered setup steps shown beside the field.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub setup_steps: Vec<String>,
    /// A redirect URI to show the user, as a template.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub redirect_uri_template: Option<String>,
}

/// A secret a deployer generates rather than asks for.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum Generated {
    /// An ed25519 key in nix's `<name>:<base64(seed ‖ public)>` form, the
    /// shape cachet's signing key takes.
    Ed25519NixKey {
        /// The key's name, as a template.
        key_name: String,
    },
    /// Random bytes, base64.
    RandomBase64 {
        /// How many bytes.
        bytes: u32,
    },
}

/// One cron trigger.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CronSpec {
    /// The expression.
    pub expression: String,
    /// The var that must carry the same expression, when one does.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub var: Option<String>,
}

/// Whether a custom domain is wanted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CustomDomain {
    /// Every instance has one.
    Required,
    /// An instance may have one or answer on workers.dev.
    Optional,
    /// The product never takes one.
    None,
}

/// How the worker is reached.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RouteSpec {
    /// Whether a custom domain is wanted.
    pub custom_domain: CustomDomain,
    /// Whether an instance may answer on workers.dev.
    pub workers_dev: bool,
    /// Whether the host is the instance's identity, so that moving it
    /// later is a rotation rather than a setting.
    pub host_is_identity: bool,
}

/// The asset layer.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AssetsSpec {
    /// Where the build lands, relative to the product's repository root.
    pub directory: String,
    /// The path the assets are served under.
    pub base: String,
    /// The layer's HTML handling mode.
    pub html_handling: String,
    /// The layer's not-found handling mode.
    pub not_found_handling: String,
}

/// One post-apply check.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Probe {
    /// The path to GET on the instance's host.
    pub get: String,
    /// The status it must answer.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status: Option<u16>,
    /// A JSON path into the answer, of the `$.field` shape.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub json_path: Option<String>,
    /// What the path must equal, as a template or a literal.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub equals: Option<String>,
}

/// The console.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ConsoleSpec {
    /// The path it is served under.
    pub path: String,
}

/// The measured artifacts of one release.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Artifacts {
    /// Every module's hash and size, in `modules` order.
    pub modules: Vec<ModuleArtifact>,
    /// Every asset by served path.
    pub assets: BTreeMap<String, AssetArtifact>,
}

/// One module's measurement.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModuleArtifact {
    /// The module's name.
    pub name: String,
    /// Its SHA-256, hex.
    pub sha256: String,
    /// Its size in bytes.
    pub size: u64,
}

/// One asset's measurement.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AssetArtifact {
    /// The hash the asset upload API takes: the first 32 hex characters of
    /// the file's SHA-256.
    pub hash: String,
    /// Its size in bytes.
    pub size: u64,
}

/// Why a manifest was refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SchemaError {
    /// The text is not the JSON this schema reads.
    Json(String),
    /// The schema version is another one.
    Version {
        /// What the manifest named.
        found: u32,
    },
    /// The manifest parsed and does not hold together.
    Invalid(Vec<Violation>),
}

impl core::fmt::Display for SchemaError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Json(detail) => write!(f, "the manifest is not readable JSON: {detail}"),
            Self::Version { found } => write!(
                f,
                "the manifest is schema version {found}; this deployer reads {MANIFEST_VERSION}"
            ),
            Self::Invalid(violations) => {
                write!(f, "the manifest does not hold together:")?;
                for violation in violations {
                    write!(f, " {violation}.")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for SchemaError {}

/// One way a manifest does not hold together.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Violation {
    /// A binding references a resource key nothing declares.
    UnknownResource {
        /// The binding.
        binding: String,
        /// The key it named.
        key: String,
    },
    /// Two resources share a key.
    DuplicateResourceKey(String),
    /// Two vars, or two secrets, or a var and a secret share a name.
    DuplicateName(String),
    /// The entry module is not in the module list.
    MainModuleMissing(String),
    /// A cron names a var whose value is another expression.
    CronVarDisagrees(String),
    /// A cron names a var nothing declares.
    CronVarMissing(String),
    /// A template did not parse.
    Placeholder {
        /// Where.
        field: String,
        /// Why.
        error: PlaceholderError,
    },
    /// A secret appears in a template rendered for a printable place.
    SecretInPublicField(String),
    /// A secret's value is not a secret template.
    SecretValueNotSecret(String),
    /// The artifacts list a module the worker does not declare, or miss
    /// one it does.
    ArtifactsDisagree(String),
}

impl core::fmt::Display for Violation {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::UnknownResource { binding, key } => {
                write!(f, "binding {binding} names the resource {key}, which nothing declares")
            }
            Self::DuplicateResourceKey(key) => write!(f, "two resources carry the key {key}"),
            Self::DuplicateName(name) => write!(f, "two bindings carry the name {name}"),
            Self::MainModuleMissing(name) => {
                write!(f, "the entry module {name} is not among the modules")
            }
            Self::CronVarDisagrees(var) => {
                write!(f, "the cron and the var {var} carry different expressions")
            }
            Self::CronVarMissing(var) => write!(f, "the cron names the var {var}, which nothing declares"),
            Self::Placeholder { field, error } => write!(f, "{field}: {error}"),
            Self::SecretInPublicField(field) => {
                write!(f, "{field} names a secret where a value could be printed")
            }
            Self::SecretValueNotSecret(name) => {
                write!(f, "the secret {name} has a value that is not a $SECRET template")
            }
            Self::ArtifactsDisagree(name) => {
                write!(f, "the artifacts and the modules disagree about {name}")
            }
        }
    }
}

impl Manifest {
    /// Read a manifest from its JSON, refusing another schema version or a
    /// manifest that does not hold together.
    ///
    /// # Errors
    /// [`SchemaError`].
    ///
    /// # Examples
    /// ```
    /// let text = include_str!("../../../fixtures/cachet/deploy-manifest.json");
    /// let manifest = deployer_manifest::Manifest::from_json(text)?;
    /// assert_eq!(manifest.product, "cachet");
    /// # Ok::<(), deployer_manifest::SchemaError>(())
    /// ```
    pub fn from_json(text: &str) -> Result<Self, SchemaError> {
        let manifest: Self =
            serde_json::from_str(text).map_err(|failure| SchemaError::Json(failure.to_string()))?;
        if manifest.manifest_version != MANIFEST_VERSION {
            return Err(SchemaError::Version {
                found: manifest.manifest_version,
            });
        }
        let violations = manifest.validate();
        if violations.is_empty() {
            Ok(manifest)
        } else {
            Err(SchemaError::Invalid(violations))
        }
    }

    /// The manifest as pretty JSON with a trailing newline: the bytes a
    /// product's emitter writes, so a parse and a write round-trip.
    #[must_use]
    pub fn to_json(&self) -> String {
        let mut text = serde_json::to_string_pretty(self).expect("a manifest serializes");
        text.push('\n');
        text
    }

    /// Every way this manifest does not hold together. Empty means it does.
    #[must_use]
    pub fn validate(&self) -> Vec<Violation> {
        let mut violations = Vec::new();

        let mut keys = BTreeSet::new();
        for resource in &self.resources {
            if !keys.insert(resource.key().to_owned()) {
                violations.push(Violation::DuplicateResourceKey(resource.key().to_owned()));
            }
            for (field, template) in resource.public_templates() {
                check_public(
                    &format!("resource {} {field}", resource.key()),
                    template,
                    &mut violations,
                );
            }
            if let Resource::Hyperdrive { key, origin, .. } = resource {
                check_secret_template(&format!("resource {key} origin"), origin, &mut violations);
            }
        }

        for binding in &self.bindings {
            if let Some(key) = &binding.resource {
                if !keys.contains(key) {
                    violations.push(Violation::UnknownResource {
                        binding: binding.name.clone(),
                        key: key.clone(),
                    });
                }
            }
        }

        let mut names = BTreeSet::new();
        for var in &self.vars {
            if !names.insert(var.name.clone()) {
                violations.push(Violation::DuplicateName(var.name.clone()));
            }
            check_public(&format!("var {}", var.name), &var.value, &mut violations);
        }
        for secret in &self.secrets {
            if !names.insert(secret.name.clone()) {
                violations.push(Violation::DuplicateName(secret.name.clone()));
            }
            check_secret_template(
                &format!("secret {}", secret.name),
                &secret.value,
                &mut violations,
            );
            if let Some(Generated::Ed25519NixKey { key_name }) = &secret.generated {
                check_public(
                    &format!("secret {} key name", secret.name),
                    key_name,
                    &mut violations,
                );
            }
        }

        if !self
            .worker
            .modules
            .iter()
            .any(|module| module.name == self.worker.main_module)
        {
            violations.push(Violation::MainModuleMissing(
                self.worker.main_module.clone(),
            ));
        }

        for cron in &self.crons {
            if let Some(var) = &cron.var {
                match self.vars.iter().find(|candidate| &candidate.name == var) {
                    None => violations.push(Violation::CronVarMissing(var.clone())),
                    Some(found) if found.value != cron.expression => {
                        violations.push(Violation::CronVarDisagrees(var.clone()));
                    }
                    Some(_) => {}
                }
            }
        }

        for (index, probe) in self.verify.iter().enumerate() {
            if let Some(equals) = &probe.equals {
                check_public(&format!("probe {index} equals"), equals, &mut violations);
            }
        }

        if let Some(artifacts) = &self.artifacts {
            let declared: BTreeSet<&str> = self
                .worker
                .modules
                .iter()
                .map(|module| module.name.as_str())
                .collect();
            let measured: BTreeSet<&str> = artifacts
                .modules
                .iter()
                .map(|module| module.name.as_str())
                .collect();
            for name in declared.symmetric_difference(&measured) {
                violations.push(Violation::ArtifactsDisagree((*name).to_owned()));
            }
        }

        violations
    }
}

/// A template for a printable place parses and names no secret.
fn check_public(field: &str, template: &str, violations: &mut Vec<Violation>) {
    match placeholder::mentions_secret(template) {
        Ok(true) => violations.push(Violation::SecretInPublicField(field.to_owned())),
        Ok(false) => {}
        Err(error) => violations.push(Violation::Placeholder {
            field: field.to_owned(),
            error,
        }),
    }
}

/// A template for a secret place parses and names a secret.
fn check_secret_template(field: &str, template: &str, violations: &mut Vec<Violation>) {
    match placeholder::mentions_secret(template) {
        Ok(true) => {}
        Ok(false) => violations.push(Violation::SecretValueNotSecret(field.to_owned())),
        Err(error) => violations.push(Violation::Placeholder {
            field: field.to_owned(),
            error,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const CACHET: &str = include_str!("../../../fixtures/cachet/deploy-manifest.json");

    #[test]
    fn cachets_manifest_reads_and_holds_together() {
        let manifest = Manifest::from_json(CACHET).expect("cachet's manifest is readable");
        assert_eq!(manifest.product, "cachet");
        assert_eq!(manifest.manifest_version, MANIFEST_VERSION);
        assert_eq!(manifest.resources.len(), 3);
        assert_eq!(manifest.bindings.len(), 4);
        assert!(manifest.assets.is_some());
        assert!(manifest.artifacts.is_none(), "a committed template is unmeasured");
    }

    #[test]
    fn another_schema_version_is_refused_before_its_fields_are_read() {
        let text = CACHET.replacen("\"manifestVersion\": 1", "\"manifestVersion\": 2", 1);
        assert_eq!(
            Manifest::from_json(&text),
            Err(SchemaError::Version { found: 2 })
        );
    }

    #[test]
    fn a_binding_naming_no_resource_is_a_violation() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.bindings[0].resource = Some("nowhere".to_owned());
        assert!(manifest.validate().contains(&Violation::UnknownResource {
            binding: manifest.bindings[0].name.clone(),
            key: "nowhere".to_owned(),
        }));
    }

    #[test]
    fn a_secret_in_a_var_is_a_violation_and_a_var_in_a_secret_is_too() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.vars[0].value = "$SECRET(CACHET_SIGNING_KEY)".to_owned();
        manifest.secrets[0].value = "$VAR(CACHET_HOST)".to_owned();
        let violations = manifest.validate();
        assert!(violations.contains(&Violation::SecretInPublicField(format!(
            "var {}",
            manifest.vars[0].name
        ))));
        assert!(violations.contains(&Violation::SecretValueNotSecret(format!(
            "secret {}",
            manifest.secrets[0].name
        ))));
    }

    #[test]
    fn the_cron_and_its_var_must_agree() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.crons[0].expression = "30 * * * *".to_owned();
        assert!(manifest
            .validate()
            .contains(&Violation::CronVarDisagrees("CACHET_GC_CRON".to_owned())));
    }

    #[test]
    fn artifacts_must_cover_the_modules_exactly() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.artifacts = Some(Artifacts {
            modules: vec![ModuleArtifact {
                name: "index.js".to_owned(),
                sha256: "00".repeat(32),
                size: 1,
            }],
            assets: BTreeMap::new(),
        });
        let violations = manifest.validate();
        assert!(violations.contains(&Violation::ArtifactsDisagree("index_bg.wasm".to_owned())));
        assert!(violations.contains(&Violation::ArtifactsDisagree("worker/shim.mjs".to_owned())));
    }

    #[test]
    fn module_kinds_name_their_content_types() {
        assert_eq!(ModuleKind::EsModule.content_type(), "application/javascript+module");
        assert_eq!(ModuleKind::CompiledWasm.content_type(), "application/wasm");
    }
}

