/// Why a manifest was refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SchemaError {
    /// The text is not the JSON this schema reads.
    Json(String),
    /// The schema version is another one.
    Version {
        /// What the manifest named.
        found: u32,
    },
    /// The manifest parsed and does not hold together.
    Invalid(Vec<Violation>),
}

impl core::fmt::Display for SchemaError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Json(detail) => write!(f, "the manifest is not readable JSON: {detail}"),
            Self::Version { found } => write!(
                f,
                "the manifest is schema version {found}; this deployer reads {MANIFEST_VERSION}"
            ),
            Self::Invalid(violations) => {
                write!(f, "the manifest does not hold together:")?;
                for violation in violations {
                    write!(f, " {violation}.")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for SchemaError {}

/// One way a manifest does not hold together.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Violation {
    /// A binding references a resource key nothing declares.
    UnknownResource {
        /// The binding.
        binding: String,
        /// The key it named.
        key: String,
    },
    /// Two resources share a key.
    DuplicateResourceKey(String),
    /// Two vars, or two secrets, or a var and a secret share a name.
    DuplicateName(String),
    /// The entry module is not in the module list.
    MainModuleMissing(String),
    /// A cron names a var whose value is another expression.
    CronVarDisagrees(String),
    /// A cron names a var nothing declares.
    CronVarMissing(String),
    /// A template did not parse.
    Placeholder {
        /// Where.
        field: String,
        /// Why.
        error: PlaceholderError,
    },
    /// A secret appears in a template rendered for a printable place.
    SecretInPublicField(String),
    /// A secret's value is not a secret template.
    SecretValueNotSecret(String),
    /// The artifacts list a module the worker does not declare, or miss
    /// one it does.
    ArtifactsDisagree(String),
}

impl core::fmt::Display for Violation {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::UnknownResource { binding, key } => {
                write!(f, "binding {binding} names the resource {key}, which nothing declares")
            }
            Self::DuplicateResourceKey(key) => write!(f, "two resources carry the key {key}"),
            Self::DuplicateName(name) => write!(f, "two bindings carry the name {name}"),
            Self::MainModuleMissing(name) => {
                write!(f, "the entry module {name} is not among the modules")
            }
            Self::CronVarDisagrees(var) => {
                write!(f, "the cron and the var {var} carry different expressions")
            }
            Self::CronVarMissing(var) => write!(f, "the cron names the var {var}, which nothing declares"),
            Self::Placeholder { field, error } => write!(f, "{field}: {error}"),
            Self::SecretInPublicField(field) => {
                write!(f, "{field} names a secret where a value could be printed")
            }
            Self::SecretValueNotSecret(name) => {
                write!(f, "the secret {name} has a value that is not a $SECRET template")
            }
            Self::ArtifactsDisagree(name) => {
                write!(f, "the artifacts and the modules disagree about {name}")
            }
        }
    }
}

impl Manifest {
    /// Read a manifest from its JSON, refusing another schema version or a
    /// manifest that does not hold together.
    ///
    /// # Errors
    /// [`SchemaError`].
    ///
    /// # Examples
    /// ```
    /// let text = include_str!("../../../fixtures/cachet/deploy-manifest.json");
    /// let manifest = deployer_manifest::Manifest::from_json(text)?;
    /// assert_eq!(manifest.product, "cachet");
    /// # Ok::<(), deployer_manifest::SchemaError>(())
    /// ```
    pub fn from_json(text: &str) -> Result<Self, SchemaError> {
        let manifest: Self =
            serde_json::from_str(text).map_err(|failure| SchemaError::Json(failure.to_string()))?;
        if manifest.manifest_version != MANIFEST_VERSION {
            return Err(SchemaError::Version {
                found: manifest.manifest_version,
            });
        }
        let violations = manifest.validate();
        if violations.is_empty() {
            Ok(manifest)
        } else {
            Err(SchemaError::Invalid(violations))
        }
    }

    /// The manifest as pretty JSON with a trailing newline: the bytes a
    /// product's emitter writes, so a parse and a write round-trip.
    #[must_use]
    pub fn to_json(&self) -> String {
        let mut text = serde_json::to_string_pretty(self).expect("a manifest serializes");
        text.push('\n');
        text
    }

    /// Every way this manifest does not hold together. Empty means it does.
    #[must_use]
    pub fn validate(&self) -> Vec<Violation> {
        let mut violations = Vec::new();

        let mut keys = BTreeSet::new();
        for resource in &self.resources {
            if !keys.insert(resource.key().to_owned()) {
                violations.push(Violation::DuplicateResourceKey(resource.key().to_owned()));
            }
            for (field, template) in resource.public_templates() {
                check_public(
                    &format!("resource {} {field}", resource.key()),
                    template,
                    &mut violations,
                );
            }
            if let Resource::Hyperdrive { key, origin, .. } = resource {
                check_secret_template(&format!("resource {key} origin"), origin, &mut violations);
            }
        }

        for binding in &self.bindings {
            if let Some(key) = &binding.resource {
                if !keys.contains(key) {
                    violations.push(Violation::UnknownResource {
                        binding: binding.name.clone(),
                        key: key.clone(),
                    });
                }
            }
        }

        let mut names = BTreeSet::new();
        for var in &self.vars {
            if !names.insert(var.name.clone()) {
                violations.push(Violation::DuplicateName(var.name.clone()));
            }
            check_public(&format!("var {}", var.name), &var.value, &mut violations);
        }
        for secret in &self.secrets {
            if !names.insert(secret.name.clone()) {
                violations.push(Violation::DuplicateName(secret.name.clone()));
            }
            check_secret_template(
                &format!("secret {}", secret.name),
                &secret.value,
                &mut violations,
            );
            if let Some(Generated::Ed25519NixKey { key_name }) = &secret.generated {
                check_public(
                    &format!("secret {} key name", secret.name),
                    key_name,
                    &mut violations,
                );
            }
        }

        if !self
            .worker
            .modules
            .iter()
            .any(|module| module.name == self.worker.main_module)
        {
            violations.push(Violation::MainModuleMissing(
                self.worker.main_module.clone(),
            ));
        }

        for cron in &self.crons {
            if let Some(var) = &cron.var {
                match self.vars.iter().find(|candidate| &candidate.name == var) {
                    None => violations.push(Violation::CronVarMissing(var.clone())),
                    Some(found) if found.value != cron.expression => {
                        violations.push(Violation::CronVarDisagrees(var.clone()));
                    }
                    Some(_) => {}
                }
            }
        }

        for (index, probe) in self.verify.iter().enumerate() {
            if let Some(equals) = &probe.equals {
                check_public(&format!("probe {index} equals"), equals, &mut violations);
            }
        }

        if let Some(artifacts) = &self.artifacts {
            let declared: BTreeSet<&str> = self
                .worker
                .modules
                .iter()
                .map(|module| module.name.as_str())
                .collect();
            let measured: BTreeSet<&str> = artifacts
                .modules
                .iter()
                .map(|module| module.name.as_str())
                .collect();
            for name in declared.symmetric_difference(&measured) {
                violations.push(Violation::ArtifactsDisagree((*name).to_owned()));
            }
        }

        violations
    }
}

/// A template for a printable place parses and names no secret.
fn check_public(field: &str, template: &str, violations: &mut Vec<Violation>) {
    match placeholder::mentions_secret(template) {
        Ok(true) => violations.push(Violation::SecretInPublicField(field.to_owned())),
        Ok(false) => {}
        Err(error) => violations.push(Violation::Placeholder {
            field: field.to_owned(),
            error,
        }),
    }
}

/// A template for a secret place parses and names a secret.
fn check_secret_template(field: &str, template: &str, violations: &mut Vec<Violation>) {
    match placeholder::mentions_secret(template) {
        Ok(true) => {}
        Ok(false) => violations.push(Violation::SecretValueNotSecret(field.to_owned())),
        Err(error) => violations.push(Violation::Placeholder {
            field: field.to_owned(),
            error,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const CACHET: &str = include_str!("../../../fixtures/cachet/deploy-manifest.json");

    #[test]
    fn cachets_manifest_reads_and_holds_together() {
        let manifest = Manifest::from_json(CACHET).expect("cachet's manifest is readable");
        assert_eq!(manifest.product, "cachet");
        assert_eq!(manifest.manifest_version, MANIFEST_VERSION);
        assert_eq!(manifest.resources.len(), 3);
        assert_eq!(manifest.bindings.len(), 4);
        assert!(manifest.assets.is_some());
        assert!(manifest.artifacts.is_none(), "a committed template is unmeasured");
    }

    #[test]
    fn another_schema_version_is_refused_before_its_fields_are_read() {
        let text = CACHET.replacen("\"manifestVersion\": 1", "\"manifestVersion\": 2", 1);
        assert_eq!(
            Manifest::from_json(&text),
            Err(SchemaError::Version { found: 2 })
        );
    }

    #[test]
    fn a_binding_naming_no_resource_is_a_violation() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.bindings[0].resource = Some("nowhere".to_owned());
        assert!(manifest.validate().contains(&Violation::UnknownResource {
            binding: manifest.bindings[0].name.clone(),
            key: "nowhere".to_owned(),
        }));
    }

    #[test]
    fn a_secret_in_a_var_is_a_violation_and_a_var_in_a_secret_is_too() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.vars[0].value = "$SECRET(CACHET_SIGNING_KEY)".to_owned();
        manifest.secrets[0].value = "$VAR(CACHET_HOST)".to_owned();
        let violations = manifest.validate();
        assert!(violations.contains(&Violation::SecretInPublicField(format!(
            "var {}",
            manifest.vars[0].name
        ))));
        assert!(violations.contains(&Violation::SecretValueNotSecret(format!(
            "secret {}",
            manifest.secrets[0].name
        ))));
    }

    #[test]
    fn the_cron_and_its_var_must_agree() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.crons[0].expression = "30 * * * *".to_owned();
        assert!(manifest
            .validate()
            .contains(&Violation::CronVarDisagrees("CACHET_GC_CRON".to_owned())));
    }

    #[test]
    fn artifacts_must_cover_the_modules_exactly() {
        let mut manifest = Manifest::from_json(CACHET).expect("readable");
        manifest.artifacts = Some(Artifacts {
            modules: vec![ModuleArtifact {
