//! The manifest's pure laws over arbitrary inputs (docs/testing/property.md):
//! the placeholder grammar is total, a public render never carries a
//! secret's value, and a manifest round-trips through its own JSON.

use std::collections::BTreeMap;

use hegel::generators as gs;
use hegel::TestCase;

use deployer_manifest::placeholder::{parse, render_public, render_secret, Inputs, Segment};
use deployer_manifest::Manifest;

const CACHET: &str = include_str!("../../../fixtures/cachet/deploy-manifest.json");

fn draw_word(tc: &TestCase, alphabet: &[u8], max: usize) -> String {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(max));
    bytes
        .iter()
        .map(|byte| alphabet[usize::from(*byte) % alphabet.len()] as char)
        .collect()
}

#[hegel::test(test_cases = 512)]
fn the_grammar_is_total(tc: TestCase) {
    // Any byte string in, a parse or a typed refusal out, never a panic.
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(64));
    let raw = String::from_utf8_lossy(&bytes).into_owned();
    if let Ok(segments) = parse(&raw) {
        // Literals reassemble to the text they came from, and a segment
        // that is not a literal came from a `$` token that is now gone.
        let literal_text: String = segments
            .iter()
            .filter_map(|segment| match segment {
                Segment::Literal(text) => Some(text.as_str()),
                _ => None,
            })
            .collect();
        assert!(literal_text.len() <= raw.len());
    }
}

#[hegel::test(test_cases = 256)]
fn a_public_render_never_carries_a_secret_value(tc: TestCase) {
    let secret_value = format!("zz{}zz", draw_word(&tc, b"abcXYZ019", 20));
    let template = format!(
        "{}$SECRET(K){}",
        draw_word(&tc, b"abc/.-", 8),
        draw_word(&tc, b"abc/.-", 8)
    );
    let vars = BTreeMap::new();
    let generated = BTreeMap::new();
    let secrets = BTreeMap::from([("K".to_owned(), secret_value.clone())]);
    let inputs = Inputs {
        name: "n",
        resource_name: "p-n",
        host: "h.example",
        version: "0.0.1",
        vars: &vars,
        generated_public: &generated,
    };
    // The public renderer refuses, and its error names the binding and
    // never the value.
    let refused = render_public(&template, &inputs).unwrap_err();
    assert!(!refused.to_string().contains(&secret_value));
    // The secret renderer carries it, which is its one job.
    assert!(render_secret(&template, &inputs, &secrets)
        .unwrap()
        .contains(&secret_value));
}

#[hegel::test(test_cases = 64)]
fn the_manifest_round_trips_through_its_json(tc: TestCase) {
    let mut manifest = Manifest::from_json(CACHET).expect("readable");
    // Perturb the parts an emitter varies between releases, then check
    // the round trip holds for the perturbed document too.
    manifest.version = format!("{}.{}.{}", tc.draw(gs::integers::<u8>()), 0, 1);
    let text = manifest.to_json();
    let back = Manifest::from_json(&text).expect("what we wrote reads");
    assert_eq!(back, manifest);
    assert_eq!(back.to_json(), text);
}

