//! The manifest crate's wire contracts (docs/testing/golden.md): cachet's
//! committed manifest is readable here and reads back to the same bytes,
//! which is the cross-repository contract this crate exists to hold.

use deployer_manifest::placeholder::parse;
use deployer_manifest::Manifest;

const CACHET: &str = include_str!("../../../fixtures/cachet/deploy-manifest.json");

#[test]
fn cachets_manifest_reads_back_to_the_bytes_cachet_wrote() {
    // cachet's emitter and this crate's writer are two serializers of one
    // shape. Byte equality here is what lets a manifest be signed as a
    // file and read as a document without the two ever disagreeing.
    let manifest = Manifest::from_json(CACHET).expect("readable");
    assert_eq!(manifest.to_json(), CACHET);
}

#[test]
fn every_placeholder_cachet_uses_is_one_this_deployer_knows() {
    let manifest = Manifest::from_json(CACHET).expect("readable");
    let mut placeholders = Vec::new();
    let mut templates: Vec<String> = Vec::new();
    templates.extend(manifest.vars.iter().map(|var| var.value.clone()));
    templates.extend(manifest.secrets.iter().map(|secret| secret.value.clone()));
    templates.extend(
        manifest
            .verify
            .iter()
            .filter_map(|probe| probe.equals.clone()),
    );
    for template in templates {
        for segment in parse(&template).expect("validated") {
            let rendered = format!("{segment:?}");
            if !rendered.starts_with("Literal") && !placeholders.contains(&rendered) {
                placeholders.push(rendered);
            }
        }
    }
    placeholders.sort();
    insta::assert_snapshot!("cachet_placeholders", placeholders.join("\n"));
}

