//! What one instance is: the facts a render reads that no manifest can
//! know, because they belong to the customer.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

/// How the instance is reached.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum Route {
    /// A hostname in a zone the account holds.
    CustomDomain {
        /// The hostname.
        hostname: String,
        /// The zone's id.
        zone_id: String,
    },
    /// The account's workers.dev subdomain.
    WorkersDev,
}

/// One instance's facts.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct InstanceSpec {
    /// The instance's id in the control plane, which every worker the
    /// engine uploads carries as a tag.
    pub id: String,
    /// The name the operator chose.
    pub name: String,
    /// The Cloudflare account.
    pub account_id: String,
    /// The host the product answers on: the custom domain's hostname, or
    /// the workers.dev address.
    pub host: String,
    /// How the worker is reached.
    pub route: Route,
    /// The operator's values for the manifest's vars, by binding name.
    /// Defaults the manifest carries are filled in by [`crate::plan`].
    pub vars: BTreeMap<String, String>,
}

/// The name grammar every product's resources share: a lowercase word of
/// 2 to 32 characters, a letter first, then letters, digits, and dashes.
/// It is the strictest of the grammars the name becomes (a bucket's).
#[must_use]
pub fn name_is_valid(name: &str) -> bool {
    (2..=32).contains(&name.len())
        && name.as_bytes()[0].is_ascii_lowercase()
        && name
            .bytes()
