}

/// The name every account resource is created under: `<product>-<name>`,
/// or the name as it is when it already carries the prefix, so no
/// customer ever reads `cachet-cachet-*` in their account.
///
/// # Examples
/// ```
/// use deployer_engine::spec::resource_name;
