/// assert_eq!(resource_name("cachet", "cachet-staging"), "cachet-staging");
/// ```
#[must_use]
pub fn resource_name(product: &str, name: &str) -> String {
    let prefix = format!("{product}-");
    if name.starts_with(&prefix) {
        name.to_owned()
    } else {
        format!("{prefix}{name}")
    }
}

/// The tags every worker the engine uploads carries, so a later pre-flight
/// can tell its own work from a customer's.
