    pub const PRODUCT: &str = "deployer:product=";
    /// `deployer:version=<version>`.
    pub const VERSION: &str = "deployer:version=";
    /// `deployer:schema=<manifest version>`.
    pub const SCHEMA: &str = "deployer:schema=";
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_grammar_is_the_bucket_grammar() {
        for good in ["production", "a1", "prod-acme", "cachet-staging"] {
            assert!(name_is_valid(good), "{good}");
        }
