            assert!(!name_is_valid(bad), "{bad}");
        }
    }

    #[test]
    fn the_prefix_appears_once() {
        assert_eq!(resource_name("sesame", "acme"), "sesame-acme");
        assert_eq!(resource_name("sesame", "sesame-acme"), "sesame-acme");
    }
}

