    pub probes: Vec<PlannedProbe>,
    /// The ownership tags the worker carries.
    pub tags: Vec<String>,
}

/// Why a plan could not be built.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PlanError {
    /// The instance's name is outside the grammar.
    BadName,
    /// A required var with no default has no value.
    MissingVar(String),
    /// A template did not render.
    Render {
        /// Where.
        field: String,
        /// Why, naming no value.
        error: RenderError,
    },
}

impl core::fmt::Display for PlanError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::BadName => f.write_str(
                "the instance name is a lowercase word of 2 to 32 characters: a letter, then letters, digits, and dashes",
            ),
            Self::MissingVar(name) => write!(f, "{name} is required and has no value"),
            Self::Render { field, error } => write!(f, "{field}: {error}"),
        }
    }
}

impl std::error::Error for PlanError {}

/// The vars a render reads: the operator's values with the manifest's
/// defaults filled in, and every derived var computed.
///
/// # Errors
/// [`PlanError::MissingVar`] for a required var with no default and no
/// value.
pub fn effective_vars(
    manifest: &Manifest,
    spec: &InstanceSpec,
) -> Result<BTreeMap<String, String>, PlanError> {
    let mut vars = BTreeMap::new();
    for var in &manifest.vars {
        if var.requirement == Requirement::Derived {
            continue;
        }
        match (spec.vars.get(&var.name), &var.default, var.requirement) {
            (Some(value), _, _) => {
                vars.insert(var.name.clone(), value.clone());
            }
            (None, Some(default), _) => {
                vars.insert(var.name.clone(), default.clone());
            }
            (None, None, Requirement::Required) => {
                return Err(PlanError::MissingVar(var.name.clone()));
            }
            (None, None, _) => {}
        }
    }
    Ok(vars)
}

/// Build the plan.
///
/// # Errors
/// [`PlanError`], naming a field or a var and never a value.
///
/// # Examples
/// ```
/// use std::collections::BTreeMap;
/// use deployer_engine::{plan::plan, InstanceSpec, Route};
/// use deployer_manifest::Manifest;
/// let manifest = Manifest::from_json(include_str!("../../../fixtures/cachet/deploy-manifest.json"))?;
/// let spec = InstanceSpec {
///     id: "inst-1".to_owned(),
///     name: "production".to_owned(),
///     account_id: "0123456789abcdef0123456789abcdef".to_owned(),
///     host: "cache.acme.example".to_owned(),
///     route: Route::CustomDomain { hostname: "cache.acme.example".to_owned(), zone_id: "zone".to_owned() },
///     vars: BTreeMap::from([
///         ("CACHET_HOST".to_owned(), "cache.acme.example".to_owned()),
///         ("CACHET_ORGS".to_owned(), "acme".to_owned()),
///         ("CACHET_ADMINS".to_owned(), "ada".to_owned()),
///         ("CACHET_OAUTH_CLIENT_ID".to_owned(), "Iv1.abc".to_owned()),
///     ]),
/// };
/// let plan = plan(&manifest, &spec, &BTreeMap::new())?;
/// assert_eq!(plan.resource_name, "cachet-production");
/// assert!(plan.vars.iter().any(|(name, value)| name == "CACHET_STATS_DATASET" && value == "cachet_production"));
/// assert!(plan.secrets.contains(&"CACHET_SIGNING_KEY".to_owned()));
/// # Ok::<(), Box<dyn std::error::Error>>(())
/// ```
pub fn plan(
    manifest: &Manifest,
    spec: &InstanceSpec,
    generated_public: &BTreeMap<String, String>,
) -> Result<Plan, PlanError> {
    if !spec::name_is_valid(&spec.name) {
        return Err(PlanError::BadName);
    }
    let resource_name = spec::resource_name(&manifest.product, &spec.name);
    let supplied = effective_vars(manifest, spec)?;
    let inputs = Inputs {
        name: &spec.name,
        resource_name: &resource_name,
        host: &spec.host,
        version: &manifest.version,
        vars: &supplied,
        generated_public,
    };
    let render = |field: String, template: &str| {
        placeholder::render_public(template, &inputs)
            .map_err(|error| PlanError::Render { field, error })
    };

    let mut resources = Vec::new();
    for resource in &manifest.resources {
        let key = resource.key().to_owned();
        resources.push(match resource {
            Resource::R2Bucket { name, .. } => PlannedResource::R2Bucket {
                name: render(format!("resource {key}"), name)?,
                key,
            },
            Resource::KvNamespace { title, .. } => PlannedResource::KvNamespace {
                title: render(format!("resource {key}"), title)?,
                key,
            },
            Resource::AnalyticsEngine { dataset, .. } => PlannedResource::AnalyticsEngine {
                dataset: render(format!("resource {key}"), dataset)?,
                key,
            },
            Resource::Hyperdrive { name, origin, .. } => PlannedResource::Hyperdrive {
                name: render(format!("resource {key}"), name)?,
                origin_secret: secret_named(origin).unwrap_or_default(),
                key,
            },
            Resource::D1 { name, .. } => PlannedResource::D1 {
                name: render(format!("resource {key}"), name)?,
                key,
            },
            Resource::Queue { name, .. } => PlannedResource::Queue {
                name: render(format!("resource {key}"), name)?,
                key,
            },
        });
    }

    let mut vars = Vec::new();
    for var in &manifest.vars {
        let value = match var.requirement {
            // A derived var's template computes from the instance alone.
            Requirement::Derived => render(format!("var {}", var.name), &var.value)?,
            // An optional var the operator left unset is not carried.
            _ if !supplied.contains_key(&var.name) => continue,
            _ => render(format!("var {}", var.name), &var.value)?,
        };
        vars.push((var.name.clone(), value));
    }

    let secrets = manifest
        .secrets
        .iter()
        .map(|secret| secret.name.clone())
        .collect();

    let probes = manifest
        .verify
        .iter()
        .enumerate()
        .map(|(index, probe)| planned_probe(index, probe, &spec.host, &render))
        .collect::<Result<Vec<_>, _>>()?;

    let tags = vec![
        format!("{}{}", spec::tags::INSTANCE, spec.id),
        format!("{}{}", spec::tags::PRODUCT, manifest.product),
        format!("{}{}", spec::tags::VERSION, manifest.version),
        format!("{}{}", spec::tags::SCHEMA, manifest.manifest_version),
    ];

    Ok(Plan {
        product: manifest.product.clone(),
        version: manifest.version.clone(),
        name: spec.name.clone(),
        resource_name,
        host: spec.host.clone(),
        route: spec.route.clone(),
        resources,
        vars,
        secrets,
        crons: manifest.crons.iter().map(|cron| cron.expression.clone()).collect(),
        probes,
        tags,
    })
}

/// The secret a `$SECRET(...)` template names, for a plan that carries the
/// name and never the value.
fn secret_named(template: &str) -> Option<String> {
    placeholder::parse(template)
        .ok()?
        .into_iter()
        .find_map(|segment| match segment {
            placeholder::Segment::Secret(name) => Some(name),
            _ => None,
        })
}

fn planned_probe(
    index: usize,
    probe: &Probe,
    host: &str,
    render: &dyn Fn(String, &str) -> Result<String, PlanError>,
) -> Result<PlannedProbe, PlanError> {
    Ok(PlannedProbe {
        url: format!("https://{host}{}", probe.get),
        status: probe.status,
        json_path: probe.json_path.clone(),
        equals: match &probe.equals {
            Some(template) => Some(render(format!("probe {index}"), template)?),
            None => None,
        },
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cachet() -> Manifest {
        Manifest::from_json(include_str!(
            "../../../fixtures/cachet/deploy-manifest.json"
        ))
        .expect("readable")
    }

    fn spec(vars: &[(&str, &str)]) -> InstanceSpec {
        InstanceSpec {
            id: "inst-1".to_owned(),
            name: "production".to_owned(),
            account_id: "0123456789abcdef0123456789abcdef".to_owned(),
            host: "cache.acme.example".to_owned(),
            route: Route::WorkersDev,
            vars: vars
                .iter()
                .map(|(name, value)| ((*name).to_owned(), (*value).to_owned()))
                .collect(),
        }
    }

    const REQUIRED: [(&str, &str); 4] = [
        ("CACHET_HOST", "cache.acme.example"),
        ("CACHET_ORGS", "acme"),
        ("CACHET_ADMINS", "ada"),
        ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
    ];

    #[test]
    fn a_required_var_without_a_default_refuses_by_name() {
        let mut vars = REQUIRED.to_vec();
        vars.retain(|(name, _)| *name != "CACHET_ORGS");
        assert_eq!(
            plan(&cachet(), &spec(&vars), &BTreeMap::new()),
            Err(PlanError::MissingVar("CACHET_ORGS".to_owned()))
        );
    }

    #[test]
    fn defaults_fill_in_and_optionals_stay_out_and_derived_compute() {
        let built = plan(&cachet(), &spec(&REQUIRED), &BTreeMap::new()).expect("plans");
        let value = |name: &str| {
            built
                .vars
                .iter()
                .find(|(candidate, _)| candidate == name)
                .map(|(_, value)| value.as_str())
        };
        assert_eq!(value("CACHET_AUDIENCE"), Some("cachet"));
        assert_eq!(value("CACHET_DEFAULT_BRANCH_REF"), Some("refs/heads/main"));
        assert_eq!(value("CACHET_GC_GRACE_MS"), None);
        assert_eq!(value("CACHET_DEPLOY_NAME"), Some("production"));
        assert_eq!(value("CACHET_STATS_DATASET"), Some("cachet_production"));
        assert_eq!(value("CACHET_GC_CRON"), Some("0 * * * *"));
        assert_eq!(built.crons, vec!["0 * * * *".to_owned()]);
    }

    #[test]
    fn the_probes_render_against_the_host_and_the_generated_key() {
        let generated = BTreeMap::from([(
            "CACHET_SIGNING_KEY".to_owned(),
            "cache.acme.example-1:AAAA".to_owned(),
        )]);
        let built = plan(&cachet(), &spec(&REQUIRED), &generated).expect("plans");
        assert_eq!(built.probes[0].url, "https://cache.acme.example/nix-cache-info");
        assert_eq!(built.probes[0].status, Some(200));
        let key_probe = built
            .probes
            .iter()
            .find(|probe| probe.json_path.as_deref() == Some("$.publicKey"))
            .expect("the key probe");
        assert_eq!(key_probe.equals.as_deref(), Some("cache.acme.example-1:AAAA"));
    }

    #[test]
    fn a_bad_name_refuses_before_anything_renders() {
        let mut bad = spec(&REQUIRED);
        bad.name = "Prod".to_owned();
        assert_eq!(
            plan(&cachet(), &bad, &BTreeMap::new()),
            Err(PlanError::BadName)
        );
    }
}

