//! The render: a plan plus the ids an account answered, turned into the
//! script metadata the Workers API takes.
//!
//! Metadata is rendered twice in an instance's life. A first install
//! carries every secret as a `secret_text` binding, which is the one
//! request body a secret's value ever enters. Every later upload omits
//! the secrets and sets `keep_bindings`, so the platform keeps what it
//! has and the engine never needs to hold a value it does not have.

use std::collections::BTreeMap;

use deployer_manifest::placeholder::{self, Inputs, RenderError};
use deployer_manifest::schema::Manifest;
use serde::Serialize;

use crate::plan::{Plan, PlannedResource};
use crate::spec::InstanceSpec;

/// One binding as the Workers API's `metadata.bindings` names it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Binding {
    /// An R2 bucket.
    R2Bucket {
        /// The binding's name.
        name: String,
        /// The bucket.
        bucket_name: String,
    },
    /// A KV namespace.
    KvNamespace {
        /// The binding's name.
        name: String,
        /// The namespace's id.
        namespace_id: String,
    },
    /// An Analytics Engine dataset.
    AnalyticsEngine {
        /// The binding's name.
        name: String,
        /// The dataset.
        dataset: String,
    },
    /// The asset layer.
    Assets {
        /// The binding's name.
        name: String,
    },
    /// A Hyperdrive configuration.
    Hyperdrive {
        /// The binding's name.
        name: String,
        /// The configuration's id.
        id: String,
    },
    /// A D1 database.
    D1 {
        /// The binding's name.
        name: String,
        /// The database's id.
        id: String,
    },
    /// A queue.
    Queue {
        /// The binding's name.
        name: String,
        /// The queue.
        queue_name: String,
    },
    /// The send_email binding.
    SendEmail {
        /// The binding's name.
        name: String,
    },
    /// A plain-text var.
    PlainText {
        /// The binding's name.
        name: String,
        /// The value.
        text: String,
    },
    /// A secret. Present only on a first install or a rotation.
    SecretText {
        /// The binding's name.
        name: String,
        /// The value. This is the one place a secret's value appears.
        text: String,
    },
}

/// The observability block.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Observability {
    /// Whether it is on.
    pub enabled: bool,
}

/// The limits block.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Limits {
    /// The CPU ceiling in milliseconds.
    pub cpu_ms: u32,
}

/// The assets block: the upload session's completion token and the
/// layer's handling modes.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AssetsMetadata {
    /// The completion token the upload session answered.
    pub jwt: String,
    /// The handling modes.
    pub config: AssetsConfig,
}

/// The asset layer's modes.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AssetsConfig {
    /// HTML handling.
    pub html_handling: String,
    /// Not-found handling.
    pub not_found_handling: String,
}

/// The `metadata` part of a script upload.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ScriptMetadata {
    /// The entry module's name.
    pub main_module: String,
    /// Every binding.
    pub bindings: Vec<Binding>,
    /// The compatibility date.
    pub compatibility_date: String,
    /// The compatibility flags.
    pub compatibility_flags: Vec<String>,
    /// Observability.
    pub observability: Observability,
    /// Limits.
    pub limits: Limits,
    /// The ownership tags.
    pub tags: Vec<String>,
    /// The binding types to keep from the previous upload. Set to
    /// `["secret_text"]` on every upload after the first.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub keep_bindings: Option<Vec<String>>,
    /// The asset layer, when the product serves one and this upload
    /// carries a completion token.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub assets: Option<AssetsMetadata>,
}

/// The ids an account answered for the resources a plan created, by the
/// manifest's key. Buckets, datasets, and queues are addressed by name and
/// need none.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ResourceIds {
    /// KV namespace ids by key.
    pub kv_namespaces: BTreeMap<String, String>,
    /// Hyperdrive configuration ids by key.
    pub hyperdrives: BTreeMap<String, String>,
    /// D1 database ids by key.
    pub d1_databases: BTreeMap<String, String>,
}

/// Where the secrets for this upload come from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Secrets<'a> {
    /// A first install or a rotation: every secret's value, rendered into
    /// its binding.
    Values(&'a BTreeMap<String, String>),
    /// An update or a reconfiguration: keep what the platform holds.
    Keep,
}

/// Why a render refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MetadataError {
    /// A binding names a resource kind the render does not place.
    UnplaceableBinding(String),
    /// A resource the bindings need has no id yet.
    MissingId(String),
    /// A secret's template did not render.
    Secret {
        /// Which.
        name: String,
        /// Why, naming no value.
        error: RenderError,
    },
}

impl core::fmt::Display for MetadataError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::UnplaceableBinding(name) => {
                write!(f, "the binding {name} has a type this engine does not place")
            }
            Self::MissingId(key) => write!(f, "the resource {key} has no id to bind"),
            Self::Secret { name, error } => write!(f, "secret {name}: {error}"),
        }
    }
}

impl std::error::Error for MetadataError {}

/// Render the script metadata for one upload.
///
/// # Errors
/// [`MetadataError`], naming a binding or a resource and never a value.
pub fn metadata(
    manifest: &Manifest,
    spec: &InstanceSpec,
    plan: &Plan,
    ids: &ResourceIds,
    secrets: Secrets<'_>,
    assets_jwt: Option<String>,
) -> Result<ScriptMetadata, MetadataError> {
    let mut bindings = Vec::new();
    let resources: BTreeMap<&str, &PlannedResource> = plan
        .resources
        .iter()
        .map(|resource| (resource.key(), resource))
        .collect();

    for binding in &manifest.bindings {
        let resource = binding
            .resource
            .as_deref()
            .and_then(|key| resources.get(key).copied());
        bindings.push(match (binding.kind.as_str(), resource) {
            ("r2_bucket", Some(PlannedResource::R2Bucket { name, .. })) => Binding::R2Bucket {
                name: binding.name.clone(),
                bucket_name: name.clone(),
            },
            ("kv_namespace", Some(PlannedResource::KvNamespace { key, .. })) => {
                Binding::KvNamespace {
                    name: binding.name.clone(),
                    namespace_id: ids
                        .kv_namespaces
                        .get(key)
                        .cloned()
                        .ok_or_else(|| MetadataError::MissingId(key.clone()))?,
                }
            }
            ("analytics_engine", Some(PlannedResource::AnalyticsEngine { dataset, .. })) => {
                Binding::AnalyticsEngine {
                    name: binding.name.clone(),
                    dataset: dataset.clone(),
                }
            }
            ("hyperdrive", Some(PlannedResource::Hyperdrive { key, .. })) => Binding::Hyperdrive {
                name: binding.name.clone(),
                id: ids
                    .hyperdrives
                    .get(key)
                    .cloned()
                    .ok_or_else(|| MetadataError::MissingId(key.clone()))?,
            },
            ("d1", Some(PlannedResource::D1 { key, .. })) => Binding::D1 {
                name: binding.name.clone(),
                id: ids
                    .d1_databases
                    .get(key)
                    .cloned()
                    .ok_or_else(|| MetadataError::MissingId(key.clone()))?,
            },
            ("queue", Some(PlannedResource::Queue { name, .. })) => Binding::Queue {
                name: binding.name.clone(),
                queue_name: name.clone(),
            },
            ("assets", None) => Binding::Assets {
                name: binding.name.clone(),
            },
            ("send_email", None) => Binding::SendEmail {
                name: binding.name.clone(),
            },
            _ => return Err(MetadataError::UnplaceableBinding(binding.name.clone())),
        });
    }

    for (name, value) in &plan.vars {
        bindings.push(Binding::PlainText {
            name: name.clone(),
            text: value.clone(),
        });
    }

    let keep_bindings = match secrets {
        Secrets::Values(values) => {
            let supplied = crate::plan::effective_vars(manifest, spec).unwrap_or_default();
            let generated = BTreeMap::new();
            let inputs = Inputs {
                name: &spec.name,
                resource_name: &plan.resource_name,
                host: &spec.host,
                version: &manifest.version,
                vars: &supplied,
                generated_public: &generated,
            };
            for secret in &manifest.secrets {
                // An optional secret the operator did not supply is not
                // carried, the way an optional var is not.
                let named = secret_named(&secret.value);
                if secret.requirement == deployer_manifest::schema::Requirement::Optional
                    && !named.as_deref().is_some_and(|name| values.contains_key(name))
                {
                    continue;
                }
                let text = placeholder::render_secret(&secret.value, &inputs, values).map_err(
                    |error| MetadataError::Secret {
                        name: secret.name.clone(),
                        error,
                    },
                )?;
                bindings.push(Binding::SecretText {
                    name: secret.name.clone(),
                    text,
                });
            }
            None
        }
        Secrets::Keep => Some(vec!["secret_text".to_owned()]),
    };

    let assets = match (assets_jwt, &manifest.assets) {
        (Some(jwt), Some(spec)) => Some(AssetsMetadata {
            jwt,
            config: AssetsConfig {
                html_handling: spec.html_handling.clone(),
                not_found_handling: spec.not_found_handling.clone(),
            },
        }),
        _ => None,
    };

    Ok(ScriptMetadata {
        main_module: manifest.worker.main_module.clone(),
        bindings,
        compatibility_date: manifest.worker.compatibility_date.clone(),
        compatibility_flags: manifest.worker.compatibility_flags.clone(),
        observability: Observability {
            enabled: manifest.worker.observability,
        },
        limits: Limits {
            cpu_ms: manifest.worker.limits.cpu_ms,
        },
        tags: plan.tags.clone(),
        keep_bindings,
        assets,
    })
}

fn secret_named(template: &str) -> Option<String> {
    placeholder::parse(template)
        .ok()?
        .into_iter()
        .find_map(|segment| match segment {
            placeholder::Segment::Secret(name) => Some(name),
            _ => None,
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::spec::Route;

    fn cachet() -> Manifest {
        Manifest::from_json(include_str!(
            "../../../fixtures/cachet/deploy-manifest.json"
        ))
        .expect("readable")
    }

    fn spec() -> InstanceSpec {
        InstanceSpec {
            id: "inst-1".to_owned(),
            name: "production".to_owned(),
            account_id: "0123456789abcdef0123456789abcdef".to_owned(),
            host: "cache.acme.example".to_owned(),
            route: Route::WorkersDev,
            vars: [
                ("CACHET_HOST", "cache.acme.example"),
                ("CACHET_ORGS", "acme"),
                ("CACHET_ADMINS", "ada"),
                ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
            ]
            .into_iter()
            .map(|(name, value)| (name.to_owned(), value.to_owned()))
            .collect(),
        }
    }

    fn ids() -> ResourceIds {
        ResourceIds {
            kv_namespaces: BTreeMap::from([("kv".to_owned(), "kv-id".to_owned())]),
            ..ResourceIds::default()
        }
    }

    #[test]
    fn a_first_install_carries_secrets_and_an_update_keeps_them() {
        let manifest = cachet();
        let spec = spec();
        let plan = crate::plan::plan(&manifest, &spec, &BTreeMap::new()).expect("plans");
        let values = BTreeMap::from([
            ("CACHET_SIGNING_KEY".to_owned(), "zzkeyzz".to_owned()),
            ("CACHET_OAUTH_CLIENT_SECRET".to_owned(), "zzsecretzz".to_owned()),
        ]);
        let first = metadata(&manifest, &spec, &plan, &ids(), Secrets::Values(&values), None)
            .expect("renders");
        assert!(first.keep_bindings.is_none());
        let secret_names: Vec<&str> = first
            .bindings
            .iter()
            .filter_map(|binding| match binding {
                Binding::SecretText { name, .. } => Some(name.as_str()),
                _ => None,
            })
            .collect();
        assert_eq!(
            secret_names,
            ["CACHET_SIGNING_KEY", "CACHET_OAUTH_CLIENT_SECRET"],
            "the optional stats token was not supplied, so it is not carried"
        );

        let later = metadata(&manifest, &spec, &plan, &ids(), Secrets::Keep, None).expect("renders");
        assert_eq!(later.keep_bindings, Some(vec!["secret_text".to_owned()]));
        assert!(!later
            .bindings
            .iter()
            .any(|binding| matches!(binding, Binding::SecretText { .. })));
        let json = serde_json::to_string(&later).expect("serializes");
        assert!(!json.contains("zzkeyzz"));
    }

    #[test]
    fn a_missing_namespace_id_refuses_by_key() {
        let manifest = cachet();
        let spec = spec();
        let plan = crate::plan::plan(&manifest, &spec, &BTreeMap::new()).expect("plans");
        assert_eq!(
            metadata(&manifest, &spec, &plan, &ResourceIds::default(), Secrets::Keep, None),
            Err(MetadataError::MissingId("kv".to_owned()))
        );
    }

    #[test]
    fn the_binding_types_are_the_workers_api_words() {
        let manifest = cachet();
        let spec = spec();
        let plan = crate::plan::plan(&manifest, &spec, &BTreeMap::new()).expect("plans");
        let rendered = metadata(&manifest, &spec, &plan, &ids(), Secrets::Keep, Some("jwt".to_owned()))
            .expect("renders");
        let json = serde_json::to_value(&rendered).expect("serializes");
        let types: Vec<&str> = json["bindings"]
            .as_array()
            .expect("list")
            .iter()
            .map(|binding| binding["type"].as_str().expect("typed"))
            .collect();
        assert!(types.starts_with(&["r2_bucket", "kv_namespace", "analytics_engine", "assets"]));
        assert!(types[4..].iter().all(|kind| *kind == "plain_text"));
        assert_eq!(json["assets"]["jwt"], "jwt");
        assert_eq!(json["assets"]["config"]["not_found_handling"], "none");
        assert_eq!(json["compatibility_flags"][0], "nodejs_compat");
    }
}

