//! module parts, a secret is set on its own without a code upload, a
//! schedules PUT replaces the set, a domain attaches to a service in a
//! zone. Nothing here interprets: the trait moves bytes and ids, and
//! [`crate::apply`] decides.

use std::collections::BTreeMap;

use deployer_manifest::schema::ModuleKind;
use serde::{Deserialize, Serialize};

use crate::render::ScriptMetadata;

/// A platform refusal or a transport failure.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ApiError {
    /// The HTTP status, or 0 when the request never got an answer.
    pub status: u16,
    /// The platform's error code when it named one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub code: Option<u32>,
    /// One line, never carrying a request body.
    pub message: String,
}

impl ApiError {
    /// A failure with no platform behind it.
    #[must_use]
    pub fn transport(message: impl Into<String>) -> Self {
        Self {
            status: 0,
            code: None,
            message: message.into(),
        }
    }

    /// Whether the platform answered "already exists", which every
    /// create-if-absent step reads as success.
    #[must_use]
    pub fn is_conflict(&self) -> bool {
        self.status == 409 || self.code == Some(10_014) || self.code == Some(10_004)
    }

    /// Whether the platform answered "no such thing".
    #[must_use]
    pub fn is_not_found(&self) -> bool {
        self.status == 404
    }
}

impl core::fmt::Display for ApiError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self.code {
            Some(code) => write!(f, "{} (code {code}): {}", self.status, self.message),
            None => write!(f, "{}: {}", self.status, self.message),
        }
    }
}

impl std::error::Error for ApiError {}

/// One module part of a script upload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModulePart {
    /// The module's name, a POSIX path relative to the entry.
    pub name: String,
    /// What it is.
    pub kind: ModuleKind,
    /// The bytes.
    pub bytes: Vec<u8>,
}

/// What the platform says about a script that exists.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ScriptInfo {
    /// The script's tags.
    pub tags: Vec<String>,
}

/// A KV namespace.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct KvNamespace {
    /// The id bindings use.
    pub id: String,
    /// The title the deployer names it by.
    pub title: String,
}

/// A zone.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Zone {
    /// The zone's id.
    pub id: String,
    /// The zone's name.
    pub name: String,
}

/// A custom domain attached to a worker.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Domain {
    /// The attachment's id.
    pub id: String,
    /// The hostname.
    pub hostname: String,
    /// The worker it routes to.
    pub service: String,
}

/// One page of an R2 listing.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ObjectPage {
    /// The keys on this page.
    pub keys: Vec<String>,
    /// Where the next page starts, when there is one.
    pub cursor: Option<String>,
}

/// An asset upload session the platform opened.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetsSession {
    /// The token uploads present.
    pub jwt: String,
    /// The hashes to upload, grouped as the platform wants them uploaded
    /// together. Empty when every asset is already known, in which case
    /// `jwt` is already the completion token.
    pub buckets: Vec<Vec<String>>,
}

/// What a probe answered.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProbeAnswer {
    /// The status.
    pub status: u16,
    /// The body, for a JSON path to read.
    pub body: String,
}

/// The Cloudflare API, as the engine calls it.
pub trait CloudflareApi {
    /// The script's info when it exists, `None` when it does not.
    async fn get_script(&self, account: &str, name: &str) -> Result<Option<ScriptInfo>, ApiError>;
    /// Upload a script: the metadata part and every module part.
    async fn upload_script(
        &self,
        account: &str,
        name: &str,
        metadata: &ScriptMetadata,
        modules: &[ModulePart],
    ) -> Result<(), ApiError>;
    /// Delete a script.
    async fn delete_script(&self, account: &str, name: &str) -> Result<(), ApiError>;
    /// Set one secret without uploading code.
    async fn put_secret(
        &self,
        account: &str,
        script: &str,
        name: &str,
        value: &str,
    ) -> Result<(), ApiError>;
    /// Replace the cron triggers.
    async fn put_schedules(&self, account: &str, script: &str, crons: &[String]) -> Result<(), ApiError>;

    /// Every KV namespace in the account.
    async fn list_kv_namespaces(&self, account: &str) -> Result<Vec<KvNamespace>, ApiError>;
    /// Create a KV namespace.
    async fn create_kv_namespace(&self, account: &str, title: &str) -> Result<KvNamespace, ApiError>;
    /// Delete a KV namespace.
    async fn delete_kv_namespace(&self, account: &str, id: &str) -> Result<(), ApiError>;

    /// Every R2 bucket's name.
    async fn list_r2_buckets(&self, account: &str) -> Result<Vec<String>, ApiError>;
    /// Create an R2 bucket.
    async fn create_r2_bucket(&self, account: &str, name: &str) -> Result<(), ApiError>;
    /// Delete an R2 bucket, which the platform refuses while it holds
    /// objects.
    async fn delete_r2_bucket(&self, account: &str, name: &str) -> Result<(), ApiError>;
    /// One page of a bucket's keys.
    async fn list_r2_objects(
        &self,
        account: &str,
        bucket: &str,
        cursor: Option<&str>,
    ) -> Result<ObjectPage, ApiError>;
    /// Delete objects by key.
    async fn delete_r2_objects(&self, account: &str, bucket: &str, keys: &[String]) -> Result<(), ApiError>;

    /// Create a Hyperdrive configuration, answering its id.
    async fn create_hyperdrive(&self, account: &str, name: &str, origin: &str) -> Result<String, ApiError>;
    /// Every Hyperdrive configuration's (id, name).
    async fn list_hyperdrives(&self, account: &str) -> Result<Vec<(String, String)>, ApiError>;
    /// Delete a Hyperdrive configuration.
    async fn delete_hyperdrive(&self, account: &str, id: &str) -> Result<(), ApiError>;

    /// The zones matching a name.
    async fn list_zones(&self, name: &str) -> Result<Vec<Zone>, ApiError>;
    /// The domains routing to a worker.
    async fn list_domains(&self, account: &str, service: &str) -> Result<Vec<Domain>, ApiError>;
    /// Attach a hostname in a zone to a worker.
    async fn attach_domain(
        &self,
        account: &str,
        hostname: &str,
        service: &str,
        zone_id: &str,
    ) -> Result<Domain, ApiError>;
    /// Detach a domain.
    async fn detach_domain(&self, account: &str, domain_id: &str) -> Result<(), ApiError>;
    /// The account's workers.dev subdomain, when it has one.
    async fn get_subdomain(&self, account: &str) -> Result<Option<String>, ApiError>;
    /// Enable or disable a worker on workers.dev.
    async fn set_workers_dev(&self, account: &str, script: &str, enabled: bool) -> Result<(), ApiError>;

    /// Open an asset upload session for a script.
    async fn assets_upload_session(
        &self,
        account: &str,
        script: &str,
        manifest: &BTreeMap<String, (String, u64)>,
    ) -> Result<AssetsSession, ApiError>;
    /// Upload one bucket of assets under a session token, answering the
    /// completion token once the last bucket lands.
    async fn upload_assets(
        &self,
        jwt: &str,
        files: &[(String, Vec<u8>)],
    ) -> Result<Option<String>, ApiError>;

    /// GET a URL on the instance's host, for a verify probe.
    async fn probe(&self, url: &str) -> Result<ProbeAnswer, ApiError>;
}

/// Where module and asset bytes come from: a release's blob store,
/// addressed by hash. The engine verifies the hash of what comes back.
pub trait BlobSource {
    /// The bytes for one SHA-256, hex.
    async fn fetch(&self, sha256: &str) -> Result<Vec<u8>, ApiError>;
}

