//! What changes between two releases of a product, as the update screen
//! shows it before anyone clicks.

use std::collections::BTreeSet;

use deployer_manifest::schema::Manifest;
use serde::{Deserialize, Serialize};

/// The differences between the installed manifest and a target.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BindingDiff {
    /// Vars the target adds.
    pub vars_added: Vec<String>,
    /// Vars the target drops.
    pub vars_removed: Vec<String>,
    /// Secrets the target adds, which an update must ask for.
    pub secrets_added: Vec<String>,
    /// Secrets the target drops.
    pub secrets_removed: Vec<String>,
    /// Bindings the target adds.
    pub bindings_added: Vec<String>,
    /// Bindings the target drops.
    pub bindings_removed: Vec<String>,
    /// Resources the target adds, which an update must create.
    pub resources_added: Vec<String>,
    /// Resources the target drops. The engine never deletes these on an
    /// update; they are listed so a person can.
    pub resources_removed: Vec<String>,
    /// Whether the compatibility date or flags change.
    pub compatibility_changed: bool,
    /// Whether the cron set changes.
    pub crons_changed: bool,
}

impl BindingDiff {
    /// Whether anything changes at all.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.vars_added.is_empty()
            && self.vars_removed.is_empty()
            && self.secrets_added.is_empty()
            && self.secrets_removed.is_empty()
            && self.bindings_added.is_empty()
            && self.bindings_removed.is_empty()
            && self.resources_added.is_empty()
            && self.resources_removed.is_empty()
            && !self.compatibility_changed
            && !self.crons_changed
    }
}

/// The differences between two manifests.
///
/// # Examples
/// ```
/// use deployer_engine::diff::diff;
/// use deployer_manifest::Manifest;
/// let a = Manifest::from_json(include_str!("../../../fixtures/cachet/deploy-manifest.json"))?;
/// let mut b = a.clone();
/// b.vars.retain(|var| var.name != "CACHET_FONT_CSS");
/// let changes = diff(&a, &b);
/// assert_eq!(changes.vars_removed, vec!["CACHET_FONT_CSS".to_owned()]);
/// assert!(diff(&a, &a).is_empty());
/// # Ok::<(), deployer_manifest::SchemaError>(())
/// ```
#[must_use]
pub fn diff(installed: &Manifest, target: &Manifest) -> BindingDiff {
    let names = |items: &[String]| -> BTreeSet<String> { items.iter().cloned().collect() };
    let vars_a = names(&installed.vars.iter().map(|var| var.name.clone()).collect::<Vec<_>>());
    let vars_b = names(&target.vars.iter().map(|var| var.name.clone()).collect::<Vec<_>>());
    let secrets_a = names(
        &installed
            .secrets
            .iter()
            .map(|secret| secret.name.clone())
            .collect::<Vec<_>>(),
    );
    let secrets_b = names(
        &target
            .secrets
            .iter()
            .map(|secret| secret.name.clone())
            .collect::<Vec<_>>(),
    );
    let bindings_a = names(
        &installed
            .bindings
            .iter()
            .map(|binding| binding.name.clone())
            .collect::<Vec<_>>(),
    );
    let bindings_b = names(
        &target
            .bindings
            .iter()
            .map(|binding| binding.name.clone())
            .collect::<Vec<_>>(),
    );
    let resources_a = names(
        &installed
            .resources
            .iter()
            .map(|resource| resource.key().to_owned())
            .collect::<Vec<_>>(),
    );
    let resources_b = names(
        &target
            .resources
            .iter()
            .map(|resource| resource.key().to_owned())
            .collect::<Vec<_>>(),
    );
    let crons_a: BTreeSet<&str> = installed
        .crons
        .iter()
        .map(|cron| cron.expression.as_str())
        .collect();
    let crons_b: BTreeSet<&str> = target
        .crons
        .iter()
        .map(|cron| cron.expression.as_str())
        .collect();
    BindingDiff {
        vars_added: vars_b.difference(&vars_a).cloned().collect(),
        vars_removed: vars_a.difference(&vars_b).cloned().collect(),
        secrets_added: secrets_b.difference(&secrets_a).cloned().collect(),
        secrets_removed: secrets_a.difference(&secrets_b).cloned().collect(),
        bindings_added: bindings_b.difference(&bindings_a).cloned().collect(),
        bindings_removed: bindings_a.difference(&bindings_b).cloned().collect(),
        resources_added: resources_b.difference(&resources_a).cloned().collect(),
        resources_removed: resources_a.difference(&resources_b).cloned().collect(),
        compatibility_changed: installed.worker.compatibility_date != target.worker.compatibility_date
            || installed.worker.compatibility_flags != target.worker.compatibility_flags,
        crons_changed: crons_a != crons_b,
    }
}

