//! The operations: converge, rotate, uninstall, each a sequence of
//! idempotent steps against the API, reporting every step as an event.
//!
//! Every step is create-if-absent against a name the plan decided, so a
//! run interrupted anywhere resumes by running again and a second run
//! after a clean first one creates nothing. Every worker uploaded carries
//! the plan's ownership tags, and pre-flight reads them before anything
//! else, so a name that belongs to someone else is refused rather than
//! overwritten.
//!
//! Secrets enter exactly one request: the first script upload, or a
//! rotation's `put_secret`. No event, no error, and no returned value
//! carries one.

use std::collections::BTreeMap;

use deployer_manifest::schema::Manifest;
use deployer_manifest::MANIFEST_VERSION;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::api::{ApiError, BlobSource, CloudflareApi, ModulePart, Zone};
use crate::plan::{Plan, PlanError, PlannedProbe, PlannedResource};
use crate::render::{self, MetadataError, ResourceIds, Secrets};
use crate::spec::{tags, InstanceSpec, Route};

/// Which operation a run is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Operation {
    /// A first install.
    Install,
    /// A release change.
    Update,
    /// A var change on the installed release.
    Configure,
    /// A secret change.
    Rotate,
    /// A teardown.
    Uninstall,
}

/// One step of an operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum Step {
    /// Reading what the account already holds under the plan's names.
    Preflight,
    /// Creating an R2 bucket.
    Bucket {
        /// Its name.
        name: String,
    },
    /// Creating a KV namespace.
    Namespace {
        /// Its title.
        title: String,
    },
    /// Creating a Hyperdrive configuration.
    Hyperdrive {
        /// Its name.
        name: String,
    },
    /// Uploading the asset layer.
    Assets,
    /// Uploading the worker.
    Worker,
    /// Setting one secret.
    Secret {
        /// Its binding name.
        name: String,
    },
    /// Setting the cron triggers.
    Schedules,
    /// Attaching the route.
    Route,
    /// Waiting for the route to resolve, then checking one probe.
    Verify {
        /// Which probe.
        url: String,
    },
    /// Detaching the route.
    DetachRoute,
    /// Deleting the worker.
    DeleteWorker,
    /// Deleting a KV namespace.
    DeleteNamespace {
        /// Its title.
        title: String,
    },
    /// Deleting a Hyperdrive configuration.
    DeleteHyperdrive {
        /// Its name.
        name: String,
    },
    /// Emptying a bucket, page by page.
    EmptyBucket {
        /// Its name.
        name: String,
    },
    /// Deleting a bucket.
    DeleteBucket {
        /// Its name.
        name: String,
    },
}

impl Step {
    /// The step's name as a person reads it in a progress list.
    #[must_use]
    pub fn label(&self) -> String {
        match self {
            Self::Preflight => "Checking the account".to_owned(),
            Self::Bucket { name } => format!("Creating bucket {name}"),
            Self::Namespace { title } => format!("Creating namespace {title}"),
            Self::Hyperdrive { name } => format!("Creating Hyperdrive {name}"),
            Self::Assets => "Uploading the console".to_owned(),
            Self::Worker => "Uploading the worker".to_owned(),
            Self::Secret { name } => format!("Setting {name}"),
            Self::Schedules => "Setting the schedule".to_owned(),
            Self::Route => "Attaching the address".to_owned(),
            Self::Verify { url } => format!("Verifying {url}"),
            Self::DetachRoute => "Detaching the address".to_owned(),
            Self::DeleteWorker => "Deleting the worker".to_owned(),
            Self::DeleteNamespace { title } => format!("Deleting namespace {title}"),
            Self::DeleteHyperdrive { name } => format!("Deleting Hyperdrive {name}"),
            Self::EmptyBucket { name } => format!("Emptying bucket {name}"),
            Self::DeleteBucket { name } => format!("Deleting bucket {name}"),
        }
    }
}

/// What happened to a step.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum EventKind {
    /// The step began.
    Started,
    /// The step finished.
    Done,
    /// The step found nothing to do.
    Unchanged,
    /// The step failed, and this is what to do about it.
    Failed {
        /// One sentence a person acts on.
        remedy: String,
    },
}

/// One entry in an operation's log.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Event {
    /// Its position, so a client that missed some asks for the rest.
    pub seq: u64,
    /// The operation.
    pub operation: Operation,
    /// The step.
    pub step: Step,
    /// What happened.
    pub kind: EventKind,
    /// One line of detail, never a value from a secret.
    pub detail: String,
}

/// How pre-flight classified the worker's name in the account.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum Classification {
    /// Nothing there.
    Absent,
    /// This instance's own worker.
    Ours,
    /// Another instance of this deployer.
    OtherInstance {
        /// Its id.
        instance: String,
    },
    /// A worker nobody here deployed.
    NotOurs,
    /// A worker a newer deployer schema deployed, which this one cannot
    /// safely rewrite.
    NewerSchema {
        /// The schema it carries.
        schema: u32,
    },
}

/// What pre-flight learned.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Preflight {
    /// The worker's name.
    pub worker: Classification,
    /// The zone the custom domain lives in, when the route is one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub zone: Option<Zone>,
    /// The account's workers.dev subdomain, when the route is that.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub subdomain: Option<String>,
}

/// Why a step failed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Failure {
    /// The platform refused or did not answer.
    Api(ApiError),
    /// Pre-flight found a name that is not ours to write.
    Refused(Classification),
    /// The plan or the metadata did not render.
    Render(String),
    /// A blob's bytes did not hash to the name that fetched them.
    Blob {
        /// Which.
        name: String,
    },
    /// A probe did not answer as the manifest says it must.
    Verify {
        /// Which.
        url: String,
        /// What was wrong, without the body.
        detail: String,
    },
    /// A resource kind this engine does not create yet.
    Unsupported(String),
    /// A secret a step needed was not supplied.
    MissingSecret(String),
    /// The custom domain's zone is not in the account.
    ZoneMissing(String),
    /// The account has no workers.dev subdomain.
    NoSubdomain,
}

impl Failure {
    /// One sentence a person acts on.
    #[must_use]
    pub fn remedy(&self) -> String {
        match self {
            Self::Api(error) if error.status == 0 => {
                "Cloudflare did not answer; retry.".to_owned()
            }
            Self::Api(error) if error.status == 401 || error.status == 403 => {
                "The account credential was refused; reconnect the account and retry.".to_owned()
            }
            Self::Api(_) => "Cloudflare refused the request; retry, and check the account's limits if it refuses again.".to_owned(),
            Self::Refused(Classification::NotOurs) => {
                "A worker with this name exists and was not deployed here; pick another instance name.".to_owned()
            }
            Self::Refused(Classification::OtherInstance { .. }) => {
                "This name belongs to another instance of yours; pick another name or remove that instance first.".to_owned()
            }
            Self::Refused(Classification::NewerSchema { .. }) => {
                "A newer deployer manages this worker; it cannot be downgraded from here.".to_owned()
            }
            Self::Refused(_) => "Retry.".to_owned(),
            Self::Render(_) => "The release's manifest and this instance disagree; report it.".to_owned(),
            Self::Blob { .. } => "A release file did not match its hash; the release store is corrupt, so refuse and report it.".to_owned(),
            Self::Verify { .. } => "The address may still be propagating; the agent retries on its own.".to_owned(),
            Self::Unsupported(_) => "This release needs a resource kind this deployer does not create yet.".to_owned(),
            Self::MissingSecret(name) => format!("Supply {name} and retry."),
            Self::ZoneMissing(name) => format!("Add {name} to this Cloudflare account, or choose workers.dev."),
            Self::NoSubdomain => "Pick a workers.dev subdomain for the account in the dashboard, or choose a custom domain.".to_owned(),
        }
    }
}

impl core::fmt::Display for Failure {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Api(error) => write!(f, "Cloudflare answered {error}"),
            Self::Refused(classification) => write!(f, "refused: {classification:?}"),
            Self::Render(detail) => write!(f, "render: {detail}"),
            Self::Blob { name } => write!(f, "{name} did not hash to its name"),
            Self::Verify { url, detail } => write!(f, "{url}: {detail}"),
            Self::Unsupported(kind) => write!(f, "{kind} is not created by this engine"),
            Self::MissingSecret(name) => write!(f, "no value for {name}"),
            Self::ZoneMissing(name) => write!(f, "no zone named {name}"),
            Self::NoSubdomain => f.write_str("the account has no workers.dev subdomain"),
        }
    }
}

/// A failed operation: which step, and why.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ApplyError {
    /// The step that failed.
    pub step: Step,
    /// Why.
    pub failure: Failure,
}

impl core::fmt::Display for ApplyError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "{}: {}", self.step.label(), self.failure)
    }
}

impl std::error::Error for ApplyError {}

impl From<PlanError> for Failure {
    fn from(error: PlanError) -> Self {
        Self::Render(error.to_string())
    }
}

impl From<MetadataError> for Failure {
    fn from(error: MetadataError) -> Self {
        Self::Render(error.to_string())
    }
}

impl From<ApiError> for Failure {
    fn from(error: ApiError) -> Self {
        Self::Api(error)
    }
}

/// The event sink with its sequence counter.
struct Emitter<'a> {
    seq: u64,
    operation: Operation,
    sink: &'a mut dyn FnMut(Event),
}

impl Emitter<'_> {
    fn emit(&mut self, step: &Step, kind: EventKind, detail: impl Into<String>) {
        self.seq += 1;
        (self.sink)(Event {
            seq: self.seq,
            operation: self.operation,
            step: step.clone(),
            kind,
            detail: detail.into(),
        });
    }

    fn started(&mut self, step: &Step) {
        self.emit(step, EventKind::Started, "");
    }

    fn done(&mut self, step: &Step, detail: impl Into<String>) {
        self.emit(step, EventKind::Done, detail);
    }

    fn unchanged(&mut self, step: &Step, detail: impl Into<String>) {
        self.emit(step, EventKind::Unchanged, detail);
    }

    fn failed(&mut self, step: &Step, failure: Failure) -> ApplyError {
        self.emit(
            step,
            EventKind::Failed {
                remedy: failure.remedy(),
            },
            failure.to_string(),
        );
        ApplyError { step: step.clone(), failure }
    }
}

/// Classify what the account holds under the plan's worker name, and
/// resolve the route's zone or subdomain.
///
/// # Errors
/// [`ApplyError`] when the platform cannot be read.
pub async fn preflight<A: CloudflareApi>(
    api: &A,
    spec: &InstanceSpec,
    plan: &Plan,
) -> Result<Preflight, ApplyError> {
    let step = Step::Preflight;
    let wrap = |failure: Failure| ApplyError {
        step: step.clone(),
        failure,
    };
    let worker = match api
        .get_script(&spec.account_id, &plan.resource_name)
        .await
        .map_err(|error| wrap(error.into()))?
    {
        None => Classification::Absent,
        Some(info) => classify(&info.tags, &spec.id),
    };
    let (zone, subdomain) = match &spec.route {
        Route::CustomDomain { hostname, .. } => {
            let zones = api
                .list_zones(&zone_of(hostname))
                .await
                .map_err(|error| wrap(error.into()))?;
            let zone = zones
                .into_iter()
                .find(|zone| hostname == &zone.name || hostname.ends_with(&format!(".{}", zone.name)))
                .ok_or_else(|| wrap(Failure::ZoneMissing(zone_of(hostname))))?;
            (Some(zone), None)
        }
        Route::WorkersDev => {
            let subdomain = api
                .get_subdomain(&spec.account_id)
                .await
                .map_err(|error| wrap(error.into()))?
                .ok_or_else(|| wrap(Failure::NoSubdomain))?;
            (None, Some(subdomain))
        }
    };
    Ok(Preflight {
        worker,
        zone,
        subdomain,
    })
}

/// The registrable zone a hostname most likely lives in: its last two
/// labels. A deeper zone is found because the platform's zone listing
/// matches by name and the caller accepts any zone the hostname ends in.
fn zone_of(hostname: &str) -> String {
    let labels: Vec<&str> = hostname.split('.').collect();
    if labels.len() <= 2 {
        hostname.to_owned()
    } else {
        labels[labels.len() - 2..].join(".")
    }
}

/// Read ownership off a script's tags.
fn classify(script_tags: &[String], instance: &str) -> Classification {
    let value = |prefix: &str| {
        script_tags
            .iter()
            .find_map(|tag| tag.strip_prefix(prefix))
            .map(str::to_owned)
    };
    let Some(owner) = value(tags::INSTANCE) else {
        return Classification::NotOurs;
    };
    if owner != instance {
        return Classification::OtherInstance { instance: owner };
    }
    match value(tags::SCHEMA).and_then(|schema| schema.parse::<u32>().ok()) {
        Some(schema) if schema > MANIFEST_VERSION => Classification::NewerSchema { schema },
        _ => Classification::Ours,
    }
}

/// Converge the account on the plan: an install, an update, or a
/// reconfiguration, which differ only in which secrets the upload carries
/// and in the label the events wear.
///
/// # Errors
/// [`ApplyError`], after emitting the failed step's event.
pub async fn converge<A: CloudflareApi, B: BlobSource>(
    api: &A,
    blobs: &B,
    operation: Operation,
    manifest: &Manifest,
    spec: &InstanceSpec,
    plan: &Plan,
    secrets: Secrets<'_>,
    sink: &mut dyn FnMut(Event),
) -> Result<(), ApplyError> {
    let mut emit = Emitter {
        seq: 0,
        operation,
        sink,
    };
    let account = spec.account_id.as_str();
    let service = plan.resource_name.as_str();

    let step = Step::Preflight;
    emit.started(&step);
    let flight = preflight(api, spec, plan).await.map_err(|error| {
        emit.emit(
            &step,
            EventKind::Failed {
                remedy: error.failure.remedy(),
            },
            error.failure.to_string(),
        );
        error
    })?;
    match &flight.worker {
        Classification::Absent | Classification::Ours => {
            emit.done(&step, format!("{:?}", flight.worker));
        }
        other => return Err(emit.failed(&step, Failure::Refused(other.clone()))),
    }

    let mut ids = ResourceIds::default();
    for resource in &plan.resources {
        match resource {
            PlannedResource::R2Bucket { name, .. } => {
                let step = Step::Bucket { name: name.clone() };
                emit.started(&step);
                let existing = api
                    .list_r2_buckets(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                if existing.iter().any(|bucket| bucket == name) {
                    emit.unchanged(&step, "already there");
                } else {
                    match api.create_r2_bucket(account, name).await {
                        Ok(()) => emit.done(&step, "created"),
                        Err(error) if error.is_conflict() => emit.unchanged(&step, "already there"),
                        Err(error) => return Err(emit.failed(&step, error.into())),
                    }
                }
            }
            PlannedResource::KvNamespace { key, title } => {
                let step = Step::Namespace {
                    title: title.clone(),
                };
                emit.started(&step);
                let existing = api
                    .list_kv_namespaces(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                let id = match existing.into_iter().find(|namespace| &namespace.title == title) {
                    Some(found) => {
                        emit.unchanged(&step, "already there");
                        found.id
                    }
                    None => {
                        let created = api
                            .create_kv_namespace(account, title)
                            .await
                            .map_err(|error| emit.failed(&step, error.into()))?;
                        emit.done(&step, "created");
                        created.id
                    }
                };
                ids.kv_namespaces.insert(key.clone(), id);
            }
            PlannedResource::AnalyticsEngine { .. } => {}
            PlannedResource::Hyperdrive {
                key,
                name,
                origin_secret,
            } => {
                let step = Step::Hyperdrive { name: name.clone() };
                emit.started(&step);
                let existing = api
                    .list_hyperdrives(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                let id = match existing.into_iter().find(|(_, candidate)| candidate == name) {
                    Some((id, _)) => {
                        emit.unchanged(&step, "already there");
                        id
                    }
                    None => {
                        let Secrets::Values(values) = secrets else {
                            return Err(emit.failed(&step, Failure::MissingSecret(origin_secret.clone())));
                        };
                        let origin = values
                            .get(origin_secret)
                            .ok_or_else(|| emit.failed(&step, Failure::MissingSecret(origin_secret.clone())))?;
                        let id = api
                            .create_hyperdrive(account, name, origin)
                            .await
                            .map_err(|error| emit.failed(&step, error.into()))?;
                        emit.done(&step, "created");
                        id
                    }
                };
                ids.hyperdrives.insert(key.clone(), id);
            }
            PlannedResource::D1 { .. } => {
                let step = Step::Worker;
                return Err(emit.failed(&step, Failure::Unsupported("d1".to_owned())));
            }
            PlannedResource::Queue { .. } => {
                let step = Step::Worker;
                return Err(emit.failed(&step, Failure::Unsupported("queue".to_owned())));
            }
        }
    }

    let assets_jwt = match (&manifest.assets, &manifest.artifacts) {
        (Some(_), Some(artifacts)) if !artifacts.assets.is_empty() => {
            let step = Step::Assets;
            emit.started(&step);
            let listing: BTreeMap<String, (String, u64)> = artifacts
                .assets
                .iter()
                .map(|(path, asset)| (path.clone(), (asset.hash.clone(), asset.size)))
                .collect();
            let session = api
                .assets_upload_session(account, service, &listing)
                .await
                .map_err(|error| emit.failed(&step, error.into()))?;
            let mut completion = if session.buckets.is_empty() {
                Some(session.jwt.clone())
            } else {
                None
            };
            let mut uploaded = 0_usize;
            for bucket in &session.buckets {
                let mut files = Vec::new();
                for hash in bucket {
                    let bytes = blobs
                        .fetch(hash)
                        .await
                        .map_err(|error| emit.failed(&step, error.into()))?;
                    files.push((hash.clone(), bytes));
                    uploaded += 1;
                }
                completion = api
                    .upload_assets(&session.jwt, &files)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
            }
            let Some(jwt) = completion else {
                return Err(emit.failed(
                    &step,
                    Failure::Api(ApiError::transport("the asset upload ended without a completion token")),
                ));
            };
            emit.done(&step, format!("{uploaded} files uploaded"));
            Some(jwt)
        }
        _ => None,
    };

    let step = Step::Worker;
    emit.started(&step);
    let Some(artifacts) = &manifest.artifacts else {
        return Err(emit.failed(&step, Failure::Render("the manifest carries no artifacts".to_owned())));
    };
    let mut modules = Vec::new();
    for module in &manifest.worker.modules {
        let measured = artifacts
            .modules
            .iter()
            .find(|candidate| candidate.name == module.name)
            .ok_or_else(|| emit.failed(&step, Failure::Blob { name: module.name.clone() }))?;
        let bytes = blobs
            .fetch(&measured.sha256)
            .await
            .map_err(|error| emit.failed(&step, error.into()))?;
        if sha256_hex(&bytes) != measured.sha256 {
            return Err(emit.failed(&step, Failure::Blob { name: module.name.clone() }));
        }
        modules.push(ModulePart {
            name: module.name.clone(),
            kind: module.kind,
            bytes,
        });
    }
    let metadata = render::metadata(manifest, spec, plan, &ids, secrets, assets_jwt)
        .map_err(|error| emit.failed(&step, error.into()))?;
    api.upload_script(account, service, &metadata, &modules)
        .await
        .map_err(|error| emit.failed(&step, error.into()))?;
    emit.done(&step, format!("{} modules", modules.len()));

    let step = Step::Schedules;
    emit.started(&step);
    api.put_schedules(account, service, &plan.crons)
        .await
        .map_err(|error| emit.failed(&step, error.into()))?;
    emit.done(&step, plan.crons.join(", "));

    let step = Step::Route;
    emit.started(&step);
    match (&spec.route, &flight.zone) {
        (Route::CustomDomain { hostname, .. }, Some(zone)) => {
            let existing = api
                .list_domains(account, service)
                .await
                .map_err(|error| emit.failed(&step, error.into()))?;
            if existing.iter().any(|domain| &domain.hostname == hostname) {
                emit.unchanged(&step, hostname.clone());
            } else {
                api.attach_domain(account, hostname, service, &zone.id)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                emit.done(&step, hostname.clone());
            }
        }
        (Route::WorkersDev, _) => {
            api.set_workers_dev(account, service, true)
                .await
                .map_err(|error| emit.failed(&step, error.into()))?;
            emit.done(&step, spec.host.clone());
        }
        (Route::CustomDomain { .. }, None) => {
            return Err(emit.failed(&step, Failure::ZoneMissing(spec.host.clone())));
        }
    }

    verify_with(api, plan, &mut emit).await
}

/// Run the plan's probes against the host.
///
/// # Errors
/// [`ApplyError`] on the first probe that does not answer as required.
pub async fn verify<A: CloudflareApi>(
    api: &A,
    operation: Operation,
    plan: &Plan,
    sink: &mut dyn FnMut(Event),
) -> Result<(), ApplyError> {
    let mut emit = Emitter {
        seq: 0,
        operation,
        sink,
    };
    verify_with(api, plan, &mut emit).await
}

async fn verify_with<A: CloudflareApi>(
    api: &A,
    plan: &Plan,
    emit: &mut Emitter<'_>,
) -> Result<(), ApplyError> {
    for probe in &plan.probes {
        let step = Step::Verify {
            url: probe.url.clone(),
        };
        emit.started(&step);
        let answer = api
            .probe(&probe.url)
            .await
            .map_err(|error| emit.failed(&step, error.into()))?;
        if let Err(detail) = judge(probe, answer.status, &answer.body) {
            return Err(emit.failed(
                &step,
                Failure::Verify {
                    url: probe.url.clone(),
                    detail,
                },
            ));
        }
        emit.done(&step, format!("{}", answer.status));
    }
    Ok(())
}

/// Whether a probe's answer satisfies it, naming what was wrong when not.
/// The detail names the path and the expectation, never the body.
fn judge(probe: &PlannedProbe, status: u16, body: &str) -> Result<(), String> {
    if let Some(wanted) = probe.status {
        if status != wanted {
            return Err(format!("answered {status}, expected {wanted}"));
        }
    }
    if let (Some(path), Some(expected)) = (&probe.json_path, &probe.equals) {
        if !(200..300).contains(&status) {
            return Err(format!("answered {status}"));
        }
        let found = read_json_path(body, path).ok_or_else(|| format!("{path} is absent"))?;
        if &found != expected {
            return Err(format!("{path} differs from the expected value"));
        }
    }
    Ok(())
}

/// Read a `$.a.b` path out of a JSON body as text. Strings answer their
/// text; numbers and booleans answer their JSON form.
#[must_use]
pub fn read_json_path(body: &str, path: &str) -> Option<String> {
    let value: serde_json::Value = serde_json::from_str(body).ok()?;
    let mut cursor = &value;
    for segment in path.strip_prefix("$.")?.split('.') {
        cursor = cursor.get(segment)?;
    }
    match cursor {
        serde_json::Value::String(text) => Some(text.clone()),
        serde_json::Value::Null => None,
        other => Some(other.to_string()),
    }
}

/// Set one secret on the installed worker without uploading code.
///
/// # Errors
/// [`ApplyError`].
pub async fn rotate_secret<A: CloudflareApi>(
    api: &A,
    spec: &InstanceSpec,
    plan: &Plan,
    name: &str,
    value: &str,
    sink: &mut dyn FnMut(Event),
) -> Result<(), ApplyError> {
    let mut emit = Emitter {
        seq: 0,
        operation: Operation::Rotate,
        sink,
    };
    let step = Step::Secret {
        name: name.to_owned(),
    };
    emit.started(&step);
    api.put_secret(&spec.account_id, &plan.resource_name, name, value)
        .await
        .map_err(|error| emit.failed(&step, error.into()))?;
    emit.done(&step, "set");
    Ok(())
}

/// Tear an instance down. The bucket stays unless asked, because it is the
/// product's data; everything else goes.
///
/// # Errors
/// [`ApplyError`], after emitting the failed step's event.
pub async fn uninstall<A: CloudflareApi>(
    api: &A,
    spec: &InstanceSpec,
    plan: &Plan,
    delete_buckets: bool,
    sink: &mut dyn FnMut(Event),
) -> Result<(), ApplyError> {
    let mut emit = Emitter {
        seq: 0,
        operation: Operation::Uninstall,
        sink,
    };
    let account = spec.account_id.as_str();
    let service = plan.resource_name.as_str();

    let step = Step::Preflight;
    emit.started(&step);
    let existing = api
        .get_script(account, service)
        .await
        .map_err(|error| emit.failed(&step, error.into()))?;
    let worker_present = match existing {
        None => {
            emit.unchanged(&step, "no worker");
            false
        }
        Some(info) => match classify(&info.tags, &spec.id) {
            Classification::Ours => {
                emit.done(&step, "ours");
                true
            }
            other => return Err(emit.failed(&step, Failure::Refused(other))),
        },
    };

    if worker_present {
        let step = Step::DetachRoute;
        emit.started(&step);
        let domains = api
            .list_domains(account, service)
            .await
            .map_err(|error| emit.failed(&step, error.into()))?;
        for domain in &domains {
            api.detach_domain(account, &domain.id)
                .await
                .map_err(|error| emit.failed(&step, error.into()))?;
        }
        if let Err(error) = api.set_workers_dev(account, service, false).await {
            if !error.is_not_found() {
                return Err(emit.failed(&step, error.into()));
            }
        }
        emit.done(&step, format!("{} detached", domains.len()));

        let step = Step::DeleteWorker;
        emit.started(&step);
        if let Err(error) = api.put_schedules(account, service, &[]).await {
            if !error.is_not_found() {
                return Err(emit.failed(&step, error.into()));
            }
        }
        match api.delete_script(account, service).await {
            Ok(()) => emit.done(&step, "deleted"),
            Err(error) if error.is_not_found() => emit.unchanged(&step, "already gone"),
            Err(error) => return Err(emit.failed(&step, error.into())),
        }
    }

    for resource in &plan.resources {
        match resource {
            PlannedResource::KvNamespace { title, .. } => {
                let step = Step::DeleteNamespace {
                    title: title.clone(),
                };
                emit.started(&step);
                let namespaces = api
                    .list_kv_namespaces(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                match namespaces.into_iter().find(|namespace| &namespace.title == title) {
                    Some(found) => {
                        api.delete_kv_namespace(account, &found.id)
                            .await
                            .map_err(|error| emit.failed(&step, error.into()))?;
                        emit.done(&step, "deleted");
                    }
                    None => emit.unchanged(&step, "already gone"),
                }
            }
            PlannedResource::Hyperdrive { name, .. } => {
                let step = Step::DeleteHyperdrive { name: name.clone() };
                emit.started(&step);
                let configs = api
                    .list_hyperdrives(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                match configs.into_iter().find(|(_, candidate)| candidate == name) {
                    Some((id, _)) => {
                        api.delete_hyperdrive(account, &id)
                            .await
                            .map_err(|error| emit.failed(&step, error.into()))?;
                        emit.done(&step, "deleted");
                    }
                    None => emit.unchanged(&step, "already gone"),
                }
            }
            PlannedResource::R2Bucket { name, .. } => {
                if !delete_buckets {
                    let step = Step::DeleteBucket { name: name.clone() };
                    emit.unchanged(&step, "kept");
                    continue;
                }
                let step = Step::EmptyBucket { name: name.clone() };
                emit.started(&step);
                let buckets = api
                    .list_r2_buckets(account)
                    .await
                    .map_err(|error| emit.failed(&step, error.into()))?;
                if !buckets.iter().any(|bucket| bucket == name) {
                    emit.unchanged(&step, "already gone");
                    continue;
                }
                let mut deleted = 0_usize;
                let mut cursor: Option<String> = None;
                loop {
                    let page = api
                        .list_r2_objects(account, name, cursor.as_deref())
                        .await
                        .map_err(|error| emit.failed(&step, error.into()))?;
                    if !page.keys.is_empty() {
                        deleted += page.keys.len();
                        api.delete_r2_objects(account, name, &page.keys)
                            .await
                            .map_err(|error| emit.failed(&step, error.into()))?;
                    }
                    match page.cursor {
                        Some(next) => cursor = Some(next),
                        None => break,
                    }
                }
                emit.done(&step, format!("{deleted} objects deleted"));
                let step = Step::DeleteBucket { name: name.clone() };
                emit.started(&step);
                match api.delete_r2_bucket(account, name).await {
                    Ok(()) => emit.done(&step, "deleted"),
                    Err(error) if error.is_not_found() => emit.unchanged(&step, "already gone"),
                    Err(error) => return Err(emit.failed(&step, error.into())),
                }
            }
            PlannedResource::AnalyticsEngine { .. }
            | PlannedResource::D1 { .. }
            | PlannedResource::Queue { .. } => {}
        }
    }
    Ok(())
}

/// The hex SHA-256 of bytes, the way the manifest records a module.
#[must_use]
pub fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    let mut out = String::with_capacity(64);
    for byte in digest {
        out.push_str(&format!("{byte:02x}"));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ownership_reads_off_the_tags() {
        let ours = vec![
            "deployer:instance=i-1".to_owned(),
            "deployer:schema=1".to_owned(),
        ];
        assert_eq!(classify(&ours, "i-1"), Classification::Ours);
        assert_eq!(
            classify(&ours, "i-2"),
            Classification::OtherInstance {
                instance: "i-1".to_owned()
            }
        );
        assert_eq!(classify(&[], "i-1"), Classification::NotOurs);
        assert_eq!(
            classify(&["deployer:instance=i-1".to_owned(), "deployer:schema=7".to_owned()], "i-1"),
            Classification::NewerSchema { schema: 7 }
        );
    }

    #[test]
    fn a_zone_is_the_last_two_labels_unless_the_host_is_shorter() {
        assert_eq!(zone_of("cache.acme.example"), "acme.example");
        assert_eq!(zone_of("a.b.c.d"), "c.d");
        assert_eq!(zone_of("example.com"), "example.com");
    }

    #[test]
    fn a_json_path_reads_strings_as_text_and_the_rest_as_json() {
        let body = r#"{"version":"0.1.2","nested":{"n":3,"on":true},"gone":null}"#;
        assert_eq!(read_json_path(body, "$.version").as_deref(), Some("0.1.2"));
        assert_eq!(read_json_path(body, "$.nested.n").as_deref(), Some("3"));
        assert_eq!(read_json_path(body, "$.nested.on").as_deref(), Some("true"));
        assert_eq!(read_json_path(body, "$.gone"), None);
        assert_eq!(read_json_path(body, "$.missing"), None);
        assert_eq!(read_json_path(body, "version"), None, "a path starts at the root");
        assert_eq!(read_json_path("not json", "$.x"), None);
    }

    #[test]
    fn a_probe_is_judged_on_status_then_path_and_the_detail_names_no_body() {
        let probe = PlannedProbe {
            url: "https://h/x".to_owned(),
            status: Some(200),
            json_path: Some("$.k".to_owned()),
            equals: Some("v".to_owned()),
        };
        assert_eq!(judge(&probe, 200, r#"{"k":"v"}"#), Ok(()));
        assert_eq!(
            judge(&probe, 503, r#"{"k":"v"}"#),
            Err("answered 503, expected 200".to_owned())
        );
        let wrong = judge(&probe, 200, r#"{"k":"zzsecretzz"}"#).unwrap_err();
        assert!(!wrong.contains("zzsecretzz"));
    }

    #[test]
    fn the_hash_is_hex_sha256() {
        assert_eq!(
            sha256_hex(b""),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
    }
}

