//! An in-memory Cloudflare, for the lanes.
//!
//! It models the parts of the platform the engine's decisions depend on:
//! that a create-if-absent sees what an earlier create made, that a
//! script upload with `keep_bindings` keeps the secrets it had, that a
//! bucket lists in pages and refuses to delete while it holds objects, and
//! that ownership rides on tags. Every call is logged by name, so a test
//! can assert that a second run created nothing.

use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet};

use crate::api::{
    ApiError, AssetsSession, BlobSource, CloudflareApi, Domain, KvNamespace, ModulePart,
    ObjectPage, ProbeAnswer, ScriptInfo, Zone,
};
use crate::render::{Binding, ScriptMetadata};

/// How many keys one listing page carries, small so a test exercises
/// paging with a few thousand objects.
pub const PAGE: usize = 1_000;

/// One uploaded script as the fake remembers it.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct FakeScript {
    /// The last metadata, as JSON.
    pub metadata: serde_json::Value,
    /// The module names and sizes.
    pub modules: Vec<(String, usize)>,
    /// The secrets the platform holds, by name.
    pub secrets: BTreeMap<String, String>,
    /// The cron triggers.
    pub schedules: Vec<String>,
    /// Whether it answers on workers.dev.
    pub workers_dev: bool,
    /// The tags.
    pub tags: Vec<String>,
}

#[derive(Debug, Default)]
struct State {
    scripts: BTreeMap<(String, String), FakeScript>,
    namespaces: BTreeMap<String, Vec<KvNamespace>>,
    buckets: BTreeMap<(String, String), BTreeSet<String>>,
    hyperdrives: BTreeMap<String, Vec<(String, String, String)>>,
    zones: Vec<Zone>,
    domains: Vec<(String, Domain)>,
    subdomains: BTreeMap<String, String>,
    probes: BTreeMap<String, ProbeAnswer>,
    known_assets: BTreeSet<String>,
    next_id: u64,
    calls: Vec<String>,
}

/// The fake.
#[derive(Debug, Default)]
pub struct FakeCloudflare {
    state: RefCell<State>,
}

impl FakeCloudflare {
    /// An empty account.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// A zone the account holds.
    pub fn with_zone(self, id: &str, name: &str) -> Self {
        self.state.borrow_mut().zones.push(Zone {
            id: id.to_owned(),
            name: name.to_owned(),
        });
        self
    }

    /// The account's workers.dev subdomain.
    pub fn with_subdomain(self, account: &str, subdomain: &str) -> Self {
        self.state
            .borrow_mut()
            .subdomains
            .insert(account.to_owned(), subdomain.to_owned());
        self
    }

    /// What a URL answers when probed.
    pub fn answer_probe(&self, url: &str, status: u16, body: &str) {
        self.state.borrow_mut().probes.insert(
            url.to_owned(),
            ProbeAnswer {
                status,
                body: body.to_owned(),
            },
        );
    }

    /// A script that already exists, with tags.
    pub fn seed_script(&self, account: &str, name: &str, tags: &[&str]) {
        self.state.borrow_mut().scripts.insert(
            (account.to_owned(), name.to_owned()),
            FakeScript {
                tags: tags.iter().map(|tag| (*tag).to_owned()).collect(),
                ..FakeScript::default()
            },
        );
    }

    /// Objects a bucket already holds.
    pub fn seed_objects(&self, account: &str, bucket: &str, keys: impl IntoIterator<Item = String>) {
        self.state
            .borrow_mut()
            .buckets
            .entry((account.to_owned(), bucket.to_owned()))
            .or_default()
            .extend(keys);
    }

    /// The script as the fake remembers it.
    #[must_use]
    pub fn script(&self, account: &str, name: &str) -> Option<FakeScript> {
        self.state
            .borrow()
            .scripts
            .get(&(account.to_owned(), name.to_owned()))
            .cloned()
    }

    /// Whether a bucket exists, and how many objects it holds.
    #[must_use]
    pub fn bucket(&self, account: &str, name: &str) -> Option<usize> {
        self.state
            .borrow()
            .buckets
            .get(&(account.to_owned(), name.to_owned()))
            .map(BTreeSet::len)
    }

    /// The namespaces in an account.
    #[must_use]
    pub fn namespaces(&self, account: &str) -> Vec<KvNamespace> {
        self.state
            .borrow()
            .namespaces
            .get(account)
            .cloned()
            .unwrap_or_default()
    }

    /// The domains attached to a service.
    #[must_use]
    pub fn domains(&self, account: &str, service: &str) -> Vec<Domain> {
        self.state
            .borrow()
            .domains
            .iter()
            .filter(|(owner, domain)| owner == account && domain.service == service)
            .map(|(_, domain)| domain.clone())
            .collect()
    }

    /// Every call so far, by name and first argument.
    #[must_use]
    pub fn calls(&self) -> Vec<String> {
        self.state.borrow().calls.clone()
    }

    /// Forget the call log, so a test can watch one run alone.
    pub fn clear_calls(&self) {
        self.state.borrow_mut().calls.clear();
    }

    fn log(&self, call: impl Into<String>) {
        self.state.borrow_mut().calls.push(call.into());
    }

    fn fresh_id(&self, prefix: &str) -> String {
        let mut state = self.state.borrow_mut();
        state.next_id += 1;
        format!("{prefix}-{}", state.next_id)
    }
}

fn not_found(what: &str) -> ApiError {
    ApiError {
        status: 404,
        code: Some(10_007),
        message: format!("{what} not found"),
    }
}

impl CloudflareApi for FakeCloudflare {
    async fn get_script(&self, account: &str, name: &str) -> Result<Option<ScriptInfo>, ApiError> {
        self.log(format!("get_script {name}"));
        Ok(self
            .script(account, name)
            .map(|script| ScriptInfo { tags: script.tags }))
    }

    async fn upload_script(
        &self,
        account: &str,
        name: &str,
        metadata: &ScriptMetadata,
        modules: &[ModulePart],
    ) -> Result<(), ApiError> {
        self.log(format!("upload_script {name}"));
        let mut state = self.state.borrow_mut();
        let entry = state
            .scripts
            .entry((account.to_owned(), name.to_owned()))
            .or_default();
        let keep_secrets = metadata
            .keep_bindings
            .as_ref()
            .is_some_and(|kept| kept.iter().any(|kind| kind == "secret_text"));
        if !keep_secrets {
            entry.secrets.clear();
        }
        for binding in &metadata.bindings {
            if let Binding::SecretText { name, text } = binding {
                entry.secrets.insert(name.clone(), text.clone());
            }
        }
        entry.metadata = serde_json::to_value(metadata).expect("metadata serializes");
        entry.modules = modules
            .iter()
            .map(|module| (module.name.clone(), module.bytes.len()))
            .collect();
        entry.tags = metadata.tags.clone();
        Ok(())
    }

    async fn delete_script(&self, account: &str, name: &str) -> Result<(), ApiError> {
        self.log(format!("delete_script {name}"));
        self.state
            .borrow_mut()
            .scripts
            .remove(&(account.to_owned(), name.to_owned()))
            .map(|_| ())
            .ok_or_else(|| not_found("script"))
    }

    async fn put_secret(&self, account: &str, script: &str, name: &str, value: &str) -> Result<(), ApiError> {
        self.log(format!("put_secret {name}"));
        let mut state = self.state.borrow_mut();
        let entry = state
            .scripts
            .get_mut(&(account.to_owned(), script.to_owned()))
            .ok_or_else(|| not_found("script"))?;
        entry.secrets.insert(name.to_owned(), value.to_owned());
        Ok(())
    }

    async fn put_schedules(&self, account: &str, script: &str, crons: &[String]) -> Result<(), ApiError> {
        self.log(format!("put_schedules {script}"));
        let mut state = self.state.borrow_mut();
        let entry = state
            .scripts
            .get_mut(&(account.to_owned(), script.to_owned()))
            .ok_or_else(|| not_found("script"))?;
        entry.schedules = crons.to_vec();
        Ok(())
    }

    async fn list_kv_namespaces(&self, account: &str) -> Result<Vec<KvNamespace>, ApiError> {
        self.log("list_kv_namespaces");
        Ok(self.namespaces(account))
    }

    async fn create_kv_namespace(&self, account: &str, title: &str) -> Result<KvNamespace, ApiError> {
        self.log(format!("create_kv_namespace {title}"));
        let namespace = KvNamespace {
            id: self.fresh_id("kv"),
            title: title.to_owned(),
        };
        self.state
            .borrow_mut()
            .namespaces
            .entry(account.to_owned())
            .or_default()
            .push(namespace.clone());
        Ok(namespace)
    }

    async fn delete_kv_namespace(&self, account: &str, id: &str) -> Result<(), ApiError> {
        self.log(format!("delete_kv_namespace {id}"));
        let mut state = self.state.borrow_mut();
        let list = state.namespaces.entry(account.to_owned()).or_default();
        let before = list.len();
        list.retain(|namespace| namespace.id != id);
        if list.len() == before {
            return Err(not_found("namespace"));
        }
        Ok(())
    }

    async fn list_r2_buckets(&self, account: &str) -> Result<Vec<String>, ApiError> {
        self.log("list_r2_buckets");
        Ok(self
            .state
            .borrow()
            .buckets
            .keys()
            .filter(|(owner, _)| owner == account)
            .map(|(_, name)| name.clone())
            .collect())
    }

    async fn create_r2_bucket(&self, account: &str, name: &str) -> Result<(), ApiError> {
        self.log(format!("create_r2_bucket {name}"));
        let mut state = self.state.borrow_mut();
        let key = (account.to_owned(), name.to_owned());
        if state.buckets.contains_key(&key) {
            return Err(ApiError {
                status: 409,
                code: Some(10_004),
                message: "bucket exists".to_owned(),
            });
        }
        state.buckets.insert(key, BTreeSet::new());
        Ok(())
    }

    async fn delete_r2_bucket(&self, account: &str, name: &str) -> Result<(), ApiError> {
        self.log(format!("delete_r2_bucket {name}"));
        let mut state = self.state.borrow_mut();
        let key = (account.to_owned(), name.to_owned());
        match state.buckets.get(&key) {
            None => Err(not_found("bucket")),
            Some(objects) if !objects.is_empty() => Err(ApiError {
                status: 409,
                code: Some(10_008),
                message: "the bucket is not empty".to_owned(),
            }),
            Some(_) => {
                state.buckets.remove(&key);
                Ok(())
            }
        }
    }

    async fn list_r2_objects(
        &self,
        account: &str,
        bucket: &str,
        cursor: Option<&str>,
    ) -> Result<ObjectPage, ApiError> {
        self.log(format!("list_r2_objects {bucket}"));
        let state = self.state.borrow();
        let objects = state
            .buckets
            .get(&(account.to_owned(), bucket.to_owned()))
            .ok_or_else(|| not_found("bucket"))?;
        let start: usize = cursor.and_then(|text| text.parse().ok()).unwrap_or(0);
        let keys: Vec<String> = objects.iter().skip(start).take(PAGE).cloned().collect();
        let next = start + keys.len();
        Ok(ObjectPage {
            keys,
            cursor: (next < objects.len()).then(|| next.to_string()),
        })
    }

    async fn delete_r2_objects(&self, account: &str, bucket: &str, keys: &[String]) -> Result<(), ApiError> {
        self.log(format!("delete_r2_objects {bucket} {}", keys.len()));
        let mut state = self.state.borrow_mut();
        let objects = state
            .buckets
            .get_mut(&(account.to_owned(), bucket.to_owned()))
            .ok_or_else(|| not_found("bucket"))?;
        for key in keys {
            objects.remove(key);
        }
        Ok(())
    }

    async fn create_hyperdrive(&self, account: &str, name: &str, origin: &str) -> Result<String, ApiError> {
        self.log(format!("create_hyperdrive {name}"));
        let id = self.fresh_id("hd");
        self.state
            .borrow_mut()
            .hyperdrives
            .entry(account.to_owned())
            .or_default()
            .push((id.clone(), name.to_owned(), origin.to_owned()));
        Ok(id)
    }

    async fn list_hyperdrives(&self, account: &str) -> Result<Vec<(String, String)>, ApiError> {
        self.log("list_hyperdrives");
        Ok(self
            .state
            .borrow()
            .hyperdrives
            .get(account)
            .map(|list| {
                list.iter()
                    .map(|(id, name, _)| (id.clone(), name.clone()))
                    .collect()
            })
            .unwrap_or_default())
    }

    async fn delete_hyperdrive(&self, account: &str, id: &str) -> Result<(), ApiError> {
        self.log(format!("delete_hyperdrive {id}"));
        let mut state = self.state.borrow_mut();
        let list = state.hyperdrives.entry(account.to_owned()).or_default();
        let before = list.len();
        list.retain(|(candidate, _, _)| candidate != id);
        if list.len() == before {
            return Err(not_found("hyperdrive"));
        }
        Ok(())
    }

    async fn list_zones(&self, name: &str) -> Result<Vec<Zone>, ApiError> {
        self.log(format!("list_zones {name}"));
        Ok(self
            .state
            .borrow()
            .zones
            .iter()
            .filter(|zone| zone.name == name)
            .cloned()
            .collect())
    }

    async fn list_domains(&self, account: &str, service: &str) -> Result<Vec<Domain>, ApiError> {
        self.log(format!("list_domains {service}"));
        Ok(self.domains(account, service))
    }

    async fn attach_domain(&self, account: &str, hostname: &str, service: &str, zone_id: &str) -> Result<Domain, ApiError> {
        self.log(format!("attach_domain {hostname}"));
        if !self.state.borrow().zones.iter().any(|zone| zone.id == zone_id) {
            return Err(not_found("zone"));
        }
        let domain = Domain {
            id: self.fresh_id("domain"),
            hostname: hostname.to_owned(),
            service: service.to_owned(),
        };
        self.state
            .borrow_mut()
            .domains
            .push((account.to_owned(), domain.clone()));
        Ok(domain)
    }

    async fn detach_domain(&self, account: &str, domain_id: &str) -> Result<(), ApiError> {
        self.log(format!("detach_domain {domain_id}"));
        let mut state = self.state.borrow_mut();
        let before = state.domains.len();
        state
            .domains
            .retain(|(owner, domain)| !(owner == account && domain.id == domain_id));
        if state.domains.len() == before {
            return Err(not_found("domain"));
        }
        Ok(())
    }

    async fn get_subdomain(&self, account: &str) -> Result<Option<String>, ApiError> {
        self.log("get_subdomain");
        Ok(self.state.borrow().subdomains.get(account).cloned())
    }

    async fn set_workers_dev(&self, account: &str, script: &str, enabled: bool) -> Result<(), ApiError> {
        self.log(format!("set_workers_dev {script} {enabled}"));
        let mut state = self.state.borrow_mut();
        let entry = state
            .scripts
            .get_mut(&(account.to_owned(), script.to_owned()))
            .ok_or_else(|| not_found("script"))?;
        entry.workers_dev = enabled;
        Ok(())
    }

    async fn assets_upload_session(
        &self,
        _account: &str,
        script: &str,
        manifest: &BTreeMap<String, (String, u64)>,
    ) -> Result<AssetsSession, ApiError> {
        self.log(format!("assets_upload_session {script}"));
        let state = self.state.borrow();
        let missing: Vec<String> = manifest
            .values()
            .map(|(hash, _)| hash.clone())
            .filter(|hash| !state.known_assets.contains(hash))
            .collect();
        Ok(AssetsSession {
            jwt: format!("session-{script}"),
            buckets: if missing.is_empty() {
                Vec::new()
            } else {
                vec![missing]
            },
        })
    }

    async fn upload_assets(&self, jwt: &str, files: &[(String, Vec<u8>)]) -> Result<Option<String>, ApiError> {
        self.log(format!("upload_assets {}", files.len()));
        let mut state = self.state.borrow_mut();
        for (hash, _) in files {
            state.known_assets.insert(hash.clone());
        }
        Ok(Some(format!("completion-{jwt}")))
    }

    async fn probe(&self, url: &str) -> Result<ProbeAnswer, ApiError> {
        self.log(format!("probe {url}"));
        self.state
            .borrow()
            .probes
            .get(url)
            .cloned()
            .ok_or_else(|| ApiError::transport(format!("{url} did not answer")))
    }
}

/// Blobs by hash, in memory.
#[derive(Debug, Default)]
pub struct FakeBlobs {
    blobs: BTreeMap<String, Vec<u8>>,
}

impl FakeBlobs {
    /// Store bytes under their SHA-256, answering the hash.
    pub fn insert(&mut self, bytes: Vec<u8>) -> String {
        let hash = crate::apply::sha256_hex(&bytes);
        self.blobs.insert(hash.clone(), bytes);
        hash
    }

    /// Store bytes under an arbitrary key, the way assets are keyed by a
    /// 32-character prefix rather than a full digest.
    pub fn insert_keyed(&mut self, key: &str, bytes: Vec<u8>) {
        self.blobs.insert(key.to_owned(), bytes);
    }
}

impl BlobSource for FakeBlobs {
    async fn fetch(&self, sha256: &str) -> Result<Vec<u8>, ApiError> {
        self.blobs
            .get(sha256)
            .cloned()
            .ok_or_else(|| ApiError::transport(format!("no blob {sha256}")))
    }
}

