//! The operations against the in-memory Cloudflare (docs/testing/unit.md):
//! an install creates everything and a second run creates nothing; pre-
//! flight classifies every kind of collision; an update keeps secrets; an
//! uninstall keeps the bucket unless told otherwise, and empties it in
//! pages when told.

use std::collections::BTreeMap;

use deployer_engine::api::CloudflareApi as _;
use deployer_engine::apply::{self, Classification, EventKind, Failure, Operation, Step};
use deployer_engine::fake::{FakeBlobs, FakeCloudflare};
use deployer_engine::plan::plan;
use deployer_engine::render::Secrets;
use deployer_engine::{Event, InstanceSpec, Route};
use deployer_manifest::schema::{Artifacts, AssetArtifact, ModuleArtifact};
use deployer_manifest::Manifest;

const ACCOUNT: &str = "0123456789abcdef0123456789abcdef";

/// cachet's manifest with artifacts measured against the fake blob store.
fn release() -> (Manifest, FakeBlobs) {
    let mut manifest = Manifest::from_json(include_str!(
        "../../../fixtures/cachet/deploy-manifest.json"
    ))
    .expect("readable");
    let mut blobs = FakeBlobs::default();
    let modules = manifest
        .worker
        .modules
        .iter()
        .map(|module| {
            let bytes = format!("bytes of {}", module.name).into_bytes();
            let size = bytes.len() as u64;
            let sha256 = blobs.insert(bytes);
            ModuleArtifact {
                name: module.name.clone(),
                sha256,
                size,
            }
        })
        .collect();
    blobs.insert_keyed("0123456789abcdef0123456789abcdef", b"<html>".to_vec());
    manifest.artifacts = Some(Artifacts {
        modules,
        assets: BTreeMap::from([(
            "/console/index.html".to_owned(),
            AssetArtifact {
                hash: "0123456789abcdef0123456789abcdef".to_owned(),
                size: 6,
            },
        )]),
    });
    (manifest, blobs)
}

fn spec(route: Route) -> InstanceSpec {
    InstanceSpec {
        id: "inst-1".to_owned(),
        name: "production".to_owned(),
        account_id: ACCOUNT.to_owned(),
        host: "cache.acme.example".to_owned(),
        route,
        vars: [
            ("CACHET_HOST", "cache.acme.example"),
            ("CACHET_ORGS", "acme"),
            ("CACHET_ADMINS", "ada"),
            ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
        ]
        .into_iter()
        .map(|(name, value)| (name.to_owned(), value.to_owned()))
        .collect(),
    }
}

fn custom_domain() -> Route {
    Route::CustomDomain {
        hostname: "cache.acme.example".to_owned(),
        zone_id: "zone-1".to_owned(),
    }
}

fn generated() -> BTreeMap<String, String> {
    BTreeMap::from([(
        "CACHET_SIGNING_KEY".to_owned(),
        "cache.acme.example-1:AAAA".to_owned(),
    )])
}

fn secrets() -> BTreeMap<String, String> {
    BTreeMap::from([
        ("CACHET_SIGNING_KEY".to_owned(), "zzkeyzz".to_owned()),
        ("CACHET_OAUTH_CLIENT_SECRET".to_owned(), "zzsecretzz".to_owned()),
    ])
}

fn healthy_answers(api: &FakeCloudflare, version: &str) {
    api.answer_probe("https://cache.acme.example/nix-cache-info", 200, "StoreDir: /nix/store\n");
    api.answer_probe(
        "https://cache.acme.example/api/public/config",
        200,
        &format!(
            r#"{{"version":"{version}","publicKey":"cache.acme.example-1:AAAA","deployment":"production"}}"#
        ),
    );
}

fn run<F: std::future::Future>(future: F) -> F::Output {
    // The fake never awaits anything real, so one poll completes it.
    let mut future = Box::pin(future);
    let waker = std::task::Waker::noop();
    let mut context = std::task::Context::from_waker(waker);
    match future.as_mut().poll(&mut context) {
        std::task::Poll::Ready(output) => output,
        std::task::Poll::Pending => panic!("the fake never pends"),
    }
}

#[test]
fn an_install_creates_everything_and_a_second_run_creates_nothing() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_zone("zone-1", "acme.example");
    healthy_answers(&api, &manifest.version);
    let spec = spec(custom_domain());
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();

    let mut events: Vec<Event> = Vec::new();
    run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |event| events.push(event),
    ))
    .expect("installs");

    // Every step ran, in order, and none failed.
    let steps: Vec<String> = events
        .iter()
        .filter(|event| matches!(event.kind, EventKind::Done | EventKind::Unchanged))
        .map(|event| event.step.label())
        .collect();
    assert_eq!(
        steps,
        [
            "Checking the account",
            "Creating bucket cachet-production",
            "Creating namespace cachet-production",
            "Uploading the console",
            "Uploading the worker",
            "Setting the schedule",
            "Attaching the address",
            "Verifying https://cache.acme.example/nix-cache-info",
            "Verifying https://cache.acme.example/api/public/config",
            "Verifying https://cache.acme.example/api/public/config",
            "Verifying https://cache.acme.example/api/public/config",
        ]
    );
    assert!(events.iter().enumerate().all(|(index, event)| event.seq == index as u64 + 1));

    let script = api.script(ACCOUNT, "cachet-production").expect("uploaded");
    assert_eq!(script.secrets, values, "the first upload carried every secret");
    assert_eq!(script.schedules, vec!["0 * * * *".to_owned()]);
    assert_eq!(script.modules.len(), 3);
    assert!(script.tags.contains(&"deployer:instance=inst-1".to_owned()));
    assert_eq!(api.bucket(ACCOUNT, "cachet-production"), Some(0));
    assert_eq!(api.namespaces(ACCOUNT).len(), 1);
    assert_eq!(api.domains(ACCOUNT, "cachet-production").len(), 1);
    let json = serde_json::to_string(&events).expect("serializes");
    assert!(!json.contains("zzkeyzz"), "no event carries a secret");

    // The same run again: nothing is created, the upload keeps the secrets.
    api.clear_calls();
    let mut again: Vec<Event> = Vec::new();
    run(apply::converge(
        &api,
        &blobs,
        Operation::Update,
        &manifest,
        &spec,
        &plan,
        Secrets::Keep,
        &mut |event| again.push(event),
    ))
    .expect("updates");
    let creates: Vec<String> = api
        .calls()
        .into_iter()
        .filter(|call| call.starts_with("create_") || call.starts_with("attach_"))
        .collect();
    assert!(creates.is_empty(), "a second run created {creates:?}");
    let script = api.script(ACCOUNT, "cachet-production").expect("still there");
    assert_eq!(script.secrets, values, "keep_bindings kept the platform's secrets");
    assert_eq!(
        script.metadata["keep_bindings"],
        serde_json::json!(["secret_text"])
    );
    assert!(again
        .iter()
        .any(|event| matches!(event.kind, EventKind::Unchanged)));
}

#[test]
fn preflight_classifies_every_kind_of_collision() {
    let (manifest, _) = release();
    let api = FakeCloudflare::new().with_subdomain(ACCOUNT, "acme");
    let spec = spec(Route::WorkersDev);
    let plan = plan(&manifest, &spec, &generated()).expect("plans");

    let absent = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(absent.worker, Classification::Absent);
    assert_eq!(absent.subdomain.as_deref(), Some("acme"));

    api.seed_script(ACCOUNT, "cachet-production", &[]);
    let not_ours = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(not_ours.worker, Classification::NotOurs);

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-9", "deployer:schema=1"],
    );
    let other = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(
        other.worker,
        Classification::OtherInstance {
            instance: "inst-9".to_owned()
        }
    );

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-1", "deployer:schema=9"],
    );
    let newer = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(newer.worker, Classification::NewerSchema { schema: 9 });

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-1", "deployer:schema=1"],
    );
    let ours = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(ours.worker, Classification::Ours);
}

#[test]
fn a_collision_refuses_before_anything_is_created() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_subdomain(ACCOUNT, "acme");
    api.seed_script(ACCOUNT, "cachet-production", &[]);
    let spec = spec(Route::WorkersDev);
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    let mut events = Vec::new();
    let refused = run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |event| events.push(event),
    ))
    .unwrap_err();
    assert_eq!(refused.step, Step::Preflight);
    assert_eq!(refused.failure, Failure::Refused(Classification::NotOurs));
    assert!(api.bucket(ACCOUNT, "cachet-production").is_none());
    let failed = events
        .iter()
        .find(|event| matches!(event.kind, EventKind::Failed { .. }))
        .expect("a failed event");
    let EventKind::Failed { remedy } = &failed.kind else {
        unreachable!()
    };
    assert!(remedy.contains("pick another instance name"), "{remedy}");
}

#[test]
fn a_missing_zone_and_a_missing_subdomain_are_named() {
    let (manifest, _) = release();
    let api = FakeCloudflare::new();
    let plan_domain = plan(&manifest, &spec(custom_domain()), &generated()).expect("plans");
    let refused = run(apply::preflight(&api, &spec(custom_domain()), &plan_domain)).unwrap_err();
    assert_eq!(refused.failure, Failure::ZoneMissing("acme.example".to_owned()));
    let plan_dev = plan(&manifest, &spec(Route::WorkersDev), &generated()).expect("plans");
    let refused = run(apply::preflight(&api, &spec(Route::WorkersDev), &plan_dev)).unwrap_err();
    assert_eq!(refused.failure, Failure::NoSubdomain);
}

#[test]
fn a_probe_that_disagrees_fails_the_verify_and_names_no_body() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_zone("zone-1", "acme.example");
    api.answer_probe("https://cache.acme.example/nix-cache-info", 200, "");
    api.answer_probe(
        "https://cache.acme.example/api/public/config",
        200,
        r#"{"version":"0.1.2","publicKey":"someone-else-1:BBBB","deployment":"production"}"#,
    );
    let spec = spec(custom_domain());
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    let mut events = Vec::new();
    let failed = run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |event| events.push(event),
    ))
    .unwrap_err();
    assert!(matches!(failed.step, Step::Verify { .. }));
    let Failure::Verify { detail, .. } = &failed.failure else {
        panic!("{failed:?}")
    };
    assert!(detail.contains("$.publicKey"), "{detail}");
    assert!(!detail.contains("BBBB"), "the detail names the path, not the body");
}

#[test]
fn a_blob_that_does_not_hash_to_its_name_is_refused() {
    let (manifest, mut blobs) = release();
    // Corrupt the entry module's bytes under its recorded hash.
    let recorded = manifest.artifacts.as_ref().expect("measured").modules[0]
        .sha256
        .clone();
    blobs.insert_keyed(&recorded, b"tampered".to_vec());
    let api = FakeCloudflare::new().with_zone("zone-1", "acme.example");
    let spec = spec(custom_domain());
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    let failed = run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |_| {},
    ))
    .unwrap_err();
    assert_eq!(failed.step, Step::Worker);
    assert_eq!(
        failed.failure,
        Failure::Blob {
            name: "index.js".to_owned()
        }
    );
    assert!(api.script(ACCOUNT, "cachet-production").is_none(), "nothing was uploaded");
}

#[test]
fn a_rotation_sets_one_secret_and_uploads_no_code() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_zone("zone-1", "acme.example");
    healthy_answers(&api, &manifest.version);
    let spec = spec(custom_domain());
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |_| {},
    ))
    .expect("installs");
    api.clear_calls();
    run(apply::rotate_secret(
        &api,
        &spec,
        &plan,
        "CACHET_SIGNING_KEY",
        "zznewzz",
        &mut |_| {},
    ))
    .expect("rotates");
    assert_eq!(api.calls(), vec!["put_secret CACHET_SIGNING_KEY".to_owned()]);
    assert_eq!(
        api.script(ACCOUNT, "cachet-production")
            .expect("there")
            .secrets["CACHET_SIGNING_KEY"],
        "zznewzz"
    );
}

#[test]
fn uninstall_keeps_the_bucket_unless_asked_and_empties_it_in_pages_when_asked() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_zone("zone-1", "acme.example");
    healthy_answers(&api, &manifest.version);
    let spec = spec(custom_domain());
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |_| {},
    ))
    .expect("installs");
    api.seed_objects(
        ACCOUNT,
        "cachet-production",
        (0..2_500).map(|index| format!("{index:032}.narinfo")),
    );

    let mut events = Vec::new();
    run(apply::uninstall(&api, &spec, &plan, false, &mut |event| {
        events.push(event);
    }))
    .expect("uninstalls");
    assert!(api.script(ACCOUNT, "cachet-production").is_none());
    assert!(api.namespaces(ACCOUNT).is_empty());
    assert!(api.domains(ACCOUNT, "cachet-production").is_empty());
    assert_eq!(api.bucket(ACCOUNT, "cachet-production"), Some(2_500), "kept, with its objects");
    assert!(events.iter().any(|event| {
        matches!(&event.step, Step::DeleteBucket { .. })
            && matches!(event.kind, EventKind::Unchanged)
            && event.detail == "kept"
    }));

    // Running it again with the bucket condemned: the worker is already
    // gone, so nothing refuses, and the bucket empties page by page.
    api.clear_calls();
    run(apply::uninstall(&api, &spec, &plan, true, &mut |_| {})).expect("uninstalls");
    assert!(api.bucket(ACCOUNT, "cachet-production").is_none());
    let deletes = api
        .calls()
        .iter()
        .filter(|call| call.starts_with("delete_r2_objects"))
        .count();
    assert_eq!(deletes, 3, "2,500 objects at 1,000 a page is three pages");
}

#[test]
fn the_fake_refuses_to_delete_a_bucket_that_holds_objects() {
    let api = FakeCloudflare::new();
    run(api.create_r2_bucket(ACCOUNT, "b")).expect("creates");
    api.seed_objects(ACCOUNT, "b", ["k".to_owned()]);
    assert!(run(api.delete_r2_bucket(ACCOUNT, "b")).is_err());
}

