        .any(|event| matches!(event.kind, EventKind::Unchanged)));
}

#[test]
fn preflight_classifies_every_kind_of_collision() {
    let (manifest, _) = release();
    let api = FakeCloudflare::new().with_subdomain(ACCOUNT, "acme");
    let spec = spec(Route::WorkersDev);
    let plan = plan(&manifest, &spec, &generated()).expect("plans");

    let absent = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(absent.worker, Classification::Absent);
    assert_eq!(absent.subdomain.as_deref(), Some("acme"));

    api.seed_script(ACCOUNT, "cachet-production", &[]);
    let not_ours = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(not_ours.worker, Classification::NotOurs);

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-9", "deployer:schema=1"],
    );
    let other = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(
        other.worker,
        Classification::OtherInstance {
            instance: "inst-9".to_owned()
        }
    );

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-1", "deployer:schema=9"],
    );
    let newer = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(newer.worker, Classification::NewerSchema { schema: 9 });

    api.seed_script(
        ACCOUNT,
        "cachet-production",
        &["deployer:instance=inst-1", "deployer:schema=1"],
    );
    let ours = run(apply::preflight(&api, &spec, &plan)).expect("reads");
    assert_eq!(ours.worker, Classification::Ours);
}

#[test]
fn a_collision_refuses_before_anything_is_created() {
    let (manifest, blobs) = release();
    let api = FakeCloudflare::new().with_subdomain(ACCOUNT, "acme");
    api.seed_script(ACCOUNT, "cachet-production", &[]);
    let spec = spec(Route::WorkersDev);
    let plan = plan(&manifest, &spec, &generated()).expect("plans");
    let values = secrets();
    let mut events = Vec::new();
    let refused = run(apply::converge(
        &api,
        &blobs,
        Operation::Install,
        &manifest,
        &spec,
        &plan,
        Secrets::Values(&values),
        &mut |event| events.push(event),
    ))
    .unwrap_err();
    assert_eq!(refused.step, Step::Preflight);
    assert_eq!(refused.failure, Failure::Refused(Classification::NotOurs));
    assert!(api.bucket(ACCOUNT, "cachet-production").is_none());
