    let refused = run(apply::preflight(&api, &spec(custom_domain()), &plan_domain)).unwrap_err();
    assert_eq!(refused.failure, Failure::ZoneMissing("acme.example".to_owned()));
    let plan_dev = plan(&manifest, &spec(Route::WorkersDev), &generated()).expect("plans");
    let refused = run(apply::preflight(&api, &spec(Route::WorkersDev), &plan_dev)).unwrap_err();
