            ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
            ("CACHET_GC_GRACE_MS", "0"),
            ("CACHET_FONT_CSS", "https://fonts.acme.example/cachet.css"),
            ("CLOUDFLARE_ACCOUNT_ID", "0123456789abcdef0123456789abcdef"),
            ("CACHET_PREVIOUS_PUBLIC_KEYS", "cache.acme.example-1:AAAA"),
            ("CACHET_MANAGED_BY", "https://deployer.example/instances/inst-1"),
        ]
        .into_iter()
        .map(|(name, value)| (name.to_owned(), value.to_owned()))
        .collect(),
    }
