}

#[test]
fn the_kept_secrets_metadata_is_the_locked_shape() {
    // The upload every update sends: no secret values, keep_bindings set,
    // the asset layer's completion token in place.
    let manifest = cachet();
    let spec = spec(Route::WorkersDev);
    let built = plan(&manifest, &spec, &generated()).expect("plans");
    let ids = ResourceIds {
        kv_namespaces: BTreeMap::from([("kv".to_owned(), "kv-0123".to_owned())]),
