//! The engine's wire contracts (docs/testing/golden.md): the plan a client
//! shows as "what will be created", and the script metadata the Workers
//! API receives, both pinned as bytes for cachet's manifest.

use std::collections::BTreeMap;

use deployer_engine::plan::plan;
use deployer_engine::render::{metadata, ResourceIds, Secrets};
use deployer_engine::{InstanceSpec, Route};
use deployer_manifest::Manifest;

fn cachet() -> Manifest {
    Manifest::from_json(include_str!(
        "../../../fixtures/cachet/deploy-manifest.json"
    ))
    .expect("readable")
}

fn spec(route: Route) -> InstanceSpec {
    InstanceSpec {
        id: "inst-1".to_owned(),
        name: "production".to_owned(),
        account_id: "0123456789abcdef0123456789abcdef".to_owned(),
        host: "cache.acme.example".to_owned(),
        route,
        vars: [
            ("CACHET_HOST", "cache.acme.example"),
            ("CACHET_ORGS", "acme, acme-labs"),
            ("CACHET_ADMINS", "ada,grace"),
            ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
            ("CACHET_GC_GRACE_MS", "0"),
            ("CACHET_FONT_CSS", "https://fonts.acme.example/cachet.css"),
            ("CLOUDFLARE_ACCOUNT_ID", "0123456789abcdef0123456789abcdef"),
            ("CACHET_PREVIOUS_PUBLIC_KEYS", "cache.acme.example-1:AAAA"),
            ("CACHET_MANAGED_BY", "https://deployer.example/instances/inst-1"),
        ]
        .into_iter()
        .map(|(name, value)| (name.to_owned(), value.to_owned()))
        .collect(),
    }
}

fn generated() -> BTreeMap<String, String> {
    BTreeMap::from([(
        "CACHET_SIGNING_KEY".to_owned(),
        "cache.acme.example-2:BBBB".to_owned(),
    )])
}

#[test]
fn the_full_plan_is_the_locked_shape() {
    let built = plan(
        &cachet(),
        &spec(Route::CustomDomain {
            hostname: "cache.acme.example".to_owned(),
            zone_id: "zone-1".to_owned(),
        }),
        &generated(),
    )
    .expect("plans");
    insta::assert_json_snapshot!("plan_full", built);
}

#[test]
fn the_kept_secrets_metadata_is_the_locked_shape() {
