}

//! The engine's pure laws over arbitrary inputs (docs/testing/property.md):
//! the plan is a function of its arguments, no secret's value ever reaches
//! a plan or a kept-secrets render, and every accepted name derives
//! resource names the platform takes with the product prefix exactly once.

use std::collections::BTreeMap;

use hegel::generators as gs;
use hegel::TestCase;

use deployer_engine::plan::plan;
use deployer_engine::render::{metadata, ResourceIds, Secrets};
use deployer_engine::spec::{name_is_valid, resource_name};
use deployer_engine::{InstanceSpec, Route};
use deployer_manifest::Manifest;

fn cachet() -> Manifest {
    Manifest::from_json(include_str!(
        "../../../fixtures/cachet/deploy-manifest.json"
    ))
    .expect("readable")
}

fn draw_word(tc: &TestCase, alphabet: &[u8], max: usize) -> String {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(max));
    bytes
        .iter()
        .map(|byte| alphabet[usize::from(*byte) % alphabet.len()] as char)
        .collect()
}

fn spec(name: &str, extra: &[(String, String)]) -> InstanceSpec {
    let mut vars: BTreeMap<String, String> = [
        ("CACHET_HOST", "cache.acme.example"),
        ("CACHET_ORGS", "acme"),
        ("CACHET_ADMINS", "ada"),
        ("CACHET_OAUTH_CLIENT_ID", "Iv1.abc"),
    ]
    .into_iter()
    .map(|(key, value)| (key.to_owned(), value.to_owned()))
    .collect();
    for (key, value) in extra {
        vars.insert(key.clone(), value.clone());
    }
    InstanceSpec {
        id: "inst-1".to_owned(),
        name: name.to_owned(),
        account_id: "0123456789abcdef0123456789abcdef".to_owned(),
        host: "cache.acme.example".to_owned(),
        route: Route::WorkersDev,
        vars,
    }
}

#[hegel::test(test_cases = 512)]
fn name_validation_is_total_and_the_prefix_appears_once(tc: TestCase) {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(40));
    let raw = String::from_utf8_lossy(&bytes).into_owned();
    if name_is_valid(&raw) {
        let resource = resource_name("cachet", &raw);
        assert!(resource.starts_with("cachet-"));
        assert!(!resource.starts_with("cachet-cachet-"));
        assert!(resource.len() <= 63);
        assert!(resource
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-'));
    }
}

#[hegel::test(test_cases = 256)]
fn a_plan_and_a_kept_render_never_carry_a_secret_value(tc: TestCase) {
    // Every value here is fenced, so a leak is unmistakable: a bare word
    // could coincide with a field name.
    let key = format!("zzkey{}zz", draw_word(&tc, b"abcXYZ019+/=", 40));
    let secret = format!("zzsec{}zz", draw_word(&tc, b"abcXYZ019", 20));
    let grace = u64::from(tc.draw(gs::integers::<u16>()));
    let spec = spec(
        "production",
        &[("CACHET_GC_GRACE_MS".to_owned(), grace.to_string())],
    );
    let manifest = cachet();
    let secrets = BTreeMap::from([
        ("CACHET_SIGNING_KEY".to_owned(), key.clone()),
        ("CACHET_OAUTH_CLIENT_SECRET".to_owned(), secret.clone()),
    ]);
    let built = plan(&manifest, &spec, &BTreeMap::new()).expect("plans");
    let plan_json = serde_json::to_string(&built).expect("serializes");
    let ids = ResourceIds {
        kv_namespaces: BTreeMap::from([("kv".to_owned(), "kv-1".to_owned())]),
        ..ResourceIds::default()
    };
    let kept = metadata(&manifest, &spec, &built, &ids, Secrets::Keep, None).expect("renders");
    let kept_json = serde_json::to_string(&kept).expect("serializes");
    for (label, value) in [("the key", &key), ("the secret", &secret)] {
        assert!(!plan_json.contains(value.as_str()), "{label} reached the plan");
        assert!(!kept_json.contains(value.as_str()), "{label} reached a kept render");
    }
    // The one render that may carry them does, and only there.
    let first = metadata(&manifest, &spec, &built, &ids, Secrets::Values(&secrets), None)
        .expect("renders");
    let first_json = serde_json::to_string(&first).expect("serializes");
    assert!(first_json.contains(key.as_str()));
}

#[hegel::test(test_cases = 128)]
fn the_plan_is_a_function_of_its_arguments(tc: TestCase) {
    let name = format!("a{}", draw_word(&tc, b"abcz019-", 12));
    let grace = u64::from(tc.draw(gs::integers::<u32>()));
    let spec = spec(&name, &[("CACHET_GC_GRACE_MS".to_owned(), grace.to_string())]);
    let manifest = cachet();
    assert_eq!(
        plan(&manifest, &spec, &BTreeMap::new()),
        plan(&manifest, &spec, &BTreeMap::new())
    );
}

