//! The release signature.
//!
//! A product's CI signs the published manifest bytes with the product's
//! release key, and the agent in a customer's account verifies the
//! signature before it applies anything. The signature is over the bytes
//! as published, never over a re-serialization, so the two sides need
//! agree on nothing but the file.
//!
//! This is what draws the trust boundary the design rests on: a control
//! plane can choose among published releases and cannot push code, because
//! the agent carries the release public keys and the control plane does
//! not hold the secret halves.

use base64ct::{Base64, Encoding};
use ed25519_dalek::{Signature, Signer as _, SigningKey, Verifier as _, VerifyingKey};

/// Why a signature did not verify.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SignatureError {
    /// The public key text is not 32 bytes of standard base64.
    PublicKey,
    /// The signature text is not 64 bytes of standard base64.
    Signature,
    /// The signature does not verify under any of the keys.
    Rejected,
}

impl core::fmt::Display for SignatureError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            Self::PublicKey => "the release public key is not 32 bytes of base64",
            Self::Signature => "the signature is not 64 bytes of base64",
            Self::Rejected => "the signature does not verify under any release key",
        })
    }
}

impl std::error::Error for SignatureError {}

/// The public half of a seed, as the base64 text an agent carries.
///
/// # Examples
/// ```
/// use deployer_manifest::signature::{public_key_text, sign, verify};
/// let seed = [7_u8; 32];
/// let public = public_key_text(&seed);
/// let signature = sign(&seed, b"manifest bytes");
/// assert!(verify(&[public.clone()], b"manifest bytes", &signature).is_ok());
/// assert!(verify(&[public], b"other bytes", &signature).is_err());
/// ```
#[must_use]
pub fn public_key_text(seed: &[u8; 32]) -> String {
    let key = SigningKey::from_bytes(seed);
    Base64::encode_string(key.verifying_key().as_bytes())
}

/// Sign bytes with a seed, answering the signature as base64.
#[must_use]
pub fn sign(seed: &[u8; 32], bytes: &[u8]) -> String {
    let key = SigningKey::from_bytes(seed);
    Base64::encode_string(&key.sign(bytes).to_bytes())
}

/// Verify a signature over bytes under any of the given public keys.
///
/// Several keys, because a product rotates its release key the way it
/// rotates anything: the new one joins, the old one stays until every
/// release signed under it has aged out.
///
/// # Errors
/// [`SignatureError`].
pub fn verify(
    public_keys: &[String],
    bytes: &[u8],
    signature_text: &str,
) -> Result<(), SignatureError> {
    let signature_bytes =
        Base64::decode_vec(signature_text.trim()).map_err(|_| SignatureError::Signature)?;
    let signature_array: [u8; 64] = signature_bytes
        .as_slice()
        .try_into()
        .map_err(|_| SignatureError::Signature)?;
    let signature = Signature::from_bytes(&signature_array);
    let mut any_key = false;
    for text in public_keys {
        let key_bytes = Base64::decode_vec(text.trim()).map_err(|_| SignatureError::PublicKey)?;
        let key_array: [u8; 32] = key_bytes
            .as_slice()
            .try_into()
            .map_err(|_| SignatureError::PublicKey)?;
        let key = VerifyingKey::from_bytes(&key_array).map_err(|_| SignatureError::PublicKey)?;
        any_key = true;
        if key.verify(bytes, &signature).is_ok() {
            return Ok(());
        }
    }
    debug_assert!(any_key || public_keys.is_empty());
    Err(SignatureError::Rejected)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_signature_verifies_under_its_key_and_no_other() {
        let seed_a = [1_u8; 32];
        let seed_b = [2_u8; 32];
        let signature = sign(&seed_a, b"release");
        assert_eq!(
            verify(&[public_key_text(&seed_a)], b"release", &signature),
            Ok(())
        );
        assert_eq!(
            verify(&[public_key_text(&seed_b)], b"release", &signature),
            Err(SignatureError::Rejected)
        );
        // A rotation keeps the old key beside the new one.
        assert_eq!(
            verify(
                &[public_key_text(&seed_b), public_key_text(&seed_a)],
                b"release",
                &signature
            ),
            Ok(())
        );
        assert_eq!(
            verify(&[], b"release", &signature),
            Err(SignatureError::Rejected),
            "no keys verify nothing"
        );
    }

    #[test]
    fn malformed_texts_are_named_for_what_they_are() {
        let seed = [3_u8; 32];
        let signature = sign(&seed, b"x");
        assert_eq!(
            verify(&["not base64!".to_owned()], b"x", &signature),
            Err(SignatureError::PublicKey)
        );
        assert_eq!(
            verify(&[Base64::encode_string(&[0_u8; 16])], b"x", &signature),
            Err(SignatureError::PublicKey)
        );
        assert_eq!(
            verify(&[public_key_text(&seed)], b"x", "short"),
            Err(SignatureError::Signature)
        );
    }
}

