            None,
            "a path starts at the root"
        );
        assert_eq!(read_json_path("not json", "$.x"), None);
    }

    #[test]
    fn a_probe_is_judged_on_status_then_path_and_the_detail_names_no_body() {
        let probe = PlannedProbe {
            url: "https://h/x".to_owned(),
            status: Some(200),
            json_path: Some("$.k".to_owned()),
            equals: Some("v".to_owned()),
        };
        assert_eq!(judge(&probe, 200, r#"{"k":"v"}"#), Ok(()));
        assert_eq!(
            judge(&probe, 503, r#"{"k":"v"}"#),
            Err("answered 503, expected 200".to_owned())
        );
        let wrong = judge(&probe, 200, r#"{"k":"zzsecretzz"}"#).unwrap_err();
        assert!(!wrong.contains("zzsecretzz"));
    }

    #[test]
    fn the_hash_is_hex_sha256() {
        assert_eq!(
            sha256_hex(b""),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
    }
