/// One manifest binding as the API takes it, with the id the account
/// answered where the kind needs one.
fn resource_binding(
    binding: &BindingSpec,
    resources: &BTreeMap<&str, &PlannedResource>,
    ids: &ResourceIds,
) -> Result<Binding, MetadataError> {
    let resource = binding
        .resource
        .as_deref()
        .and_then(|key| resources.get(key).copied());
    let id_for = |map: &BTreeMap<String, String>, key: &str| {
        map.get(key)
            .cloned()
            .ok_or_else(|| MetadataError::MissingId(key.to_owned()))
    };
    let name = binding.name.clone();
    Ok(match (binding.kind.as_str(), resource) {
        ("r2_bucket", Some(PlannedResource::R2Bucket { name: bucket, .. })) => Binding::R2Bucket {
            name,
            bucket_name: bucket.clone(),
        },
        ("kv_namespace", Some(PlannedResource::KvNamespace { key, .. })) => Binding::KvNamespace {
            name,
            namespace_id: id_for(&ids.kv_namespaces, key)?,
        },
        ("analytics_engine", Some(PlannedResource::AnalyticsEngine { dataset, .. })) => {
            Binding::AnalyticsEngine {
                name,
                dataset: dataset.clone(),
            }
        }
        ("hyperdrive", Some(PlannedResource::Hyperdrive { key, .. })) => Binding::Hyperdrive {
            name,
            id: id_for(&ids.hyperdrives, key)?,
        },
        ("d1", Some(PlannedResource::D1 { key, .. })) => Binding::D1 {
            name,
            id: id_for(&ids.d1_databases, key)?,
        },
        ("queue", Some(PlannedResource::Queue { name: queue, .. })) => Binding::Queue {
            name,
            queue_name: queue.clone(),
        },
        ("assets", None) => Binding::Assets { name },
        ("send_email", None) => Binding::SendEmail { name },
        _ => return Err(MetadataError::UnplaceableBinding(name)),
    })
}

/// The `secret_text` bindings of a first install or a rotation. An
/// optional secret the operator did not supply is not carried, the way an
/// optional var is not.
fn secret_bindings(
    manifest: &Manifest,
    spec: &InstanceSpec,
    plan: &Plan,
    values: &BTreeMap<String, String>,
) -> Result<Vec<Binding>, MetadataError> {
    let supplied = crate::plan::effective_vars(manifest, spec).unwrap_or_default();
    let generated = BTreeMap::new();
    let inputs = Inputs {
        name: &spec.name,
        resource_name: &plan.resource_name,
        host: &spec.host,
        version: &manifest.version,
        vars: &supplied,
        generated_public: &generated,
    };
    let mut bindings = Vec::new();
    for secret in &manifest.secrets {
        let named = secret_named(&secret.value);
        if secret.requirement == Requirement::Optional
            && !named
                .as_deref()
                .is_some_and(|name| values.contains_key(name))
        {
            continue;
        }
        let text = placeholder::render_secret(&secret.value, &inputs, values).map_err(|error| {
            MetadataError::Secret {
                name: secret.name.clone(),
                error,
            }
        })?;
        bindings.push(Binding::SecretText {
            name: secret.name.clone(),
            text,
        });
    }
    Ok(bindings)
}

