[package]
name = "cachet-api"
description = "The cachet HTTP surface as typed route handlers. The OpenAPI document is generated from this code by derive macros; the code is the truth, the yaml is committed and drift-checked."
edition.workspace = true
version.workspace = true
publish.workspace = true
license.workspace = true

[lints]
workspace = true

[features]
# why: the yaml feature pulls a C yaml backend into the build graph; it is
# needed only by the openapi generation binary, so the worker's build never
# enables it and the wasm-hygiene gate never has to look at it.
yaml-export = ["utoipa/yaml"]

[dependencies]
serde.workspace = true
serde_json.workspace = true
# why: the OpenAPI document is generated from the route descriptors below
# and committed; an exact pin keeps the generated bytes stable across
# regenerations (CLAUDE.md §6).
utoipa = "=5.5.0"

# why: the two verbatim-served bodies are mirrored here so the generated
# document describes them. The test that keeps the mirrors honest decodes
# the core type's own bytes, which needs the core type; nothing in the
# shipped crate depends on it, so the direction in CLAUDE.md §4 holds.
[dev-dependencies]
cachet-core = { path = "../cachet-core" }

# why: regenerating the committed document is a maintenance action with its
# own binary, available only when the yaml-export feature is on.
[[bin]]
name = "openapi"
path = "src/bin/openapi.rs"
required-features = ["yaml-export"]
