/// `GET /api/self/gc-runs`: one page of run ids, oldest first.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize, utoipa::ToSchema)]
pub struct GcRunList {
    /// The run ids in chronological order.
    pub runs: Vec<String>,
