//! The content type an asset is served with, from its path.
//!
//! The asset upload API takes a content type per file and the layer
//! serves each file with the type it was uploaded under, so a stylesheet
//! uploaded as octet-stream is a stylesheet no browser applies. The
//! manifest records paths and hashes; this table turns the path into the
//! type, and anything it does not know ships as octet-stream.

/// The content type for a served path, by extension.
///
/// # Examples
/// ```
/// use deployer_engine::assets::content_type_for;
/// assert_eq!(content_type_for("/console/index.html"), "text/html; charset=utf-8");
/// assert_eq!(content_type_for("/console/assets/app-3f2a.js"), "text/javascript; charset=utf-8");
/// assert_eq!(content_type_for("/console/fonts/geist.woff2"), "font/woff2");
/// assert_eq!(content_type_for("/console/mystery.bin"), "application/octet-stream");
/// ```
#[must_use]
pub fn content_type_for(path: &str) -> &'static str {
    let extension = path
        .rsplit('/')
        .next()
        .and_then(|file| file.rsplit_once('.'))
        .map(|(_, extension)| extension.to_ascii_lowercase());
    match extension.as_deref() {
        Some("html") => "text/html; charset=utf-8",
        Some("js" | "mjs") => "text/javascript; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("json" | "map") => "application/json; charset=utf-8",
        Some("svg") => "image/svg+xml",
        Some("png") => "image/png",
        Some("ico") => "image/x-icon",
        Some("webp") => "image/webp",
        Some("woff2") => "font/woff2",
        Some("woff") => "font/woff",
        Some("txt") => "text/plain; charset=utf-8",
        Some("wasm") => "application/wasm",
        Some("webmanifest") => "application/manifest+json",
        _ => "application/octet-stream",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_extension_is_read_case_insensitively_from_the_last_segment() {
        assert_eq!(content_type_for("/A.B/index.HTML"), "text/html; charset=utf-8");
        assert_eq!(content_type_for("/dir.with.dots/file"), "application/octet-stream");
        assert_eq!(content_type_for(""), "application/octet-stream");
        assert_eq!(content_type_for("/app.js.map"), "application/json; charset=utf-8");
    }
}
