//! The two multipart bodies the Workers API takes, assembled as bytes.
//!
//! A script upload is one `metadata` part and one part per module; an
//! asset upload is one part per file, base64. Both are built here rather
//! than through a browser FormData object because bytes built in Rust are
//! bytes the unit lane can pin, and because the boundary is then a
//! function of the content, so the same upload encodes the same way
//! everywhere.

use base64ct::{Base64, Encoding};

use crate::api::{AssetFile, ModulePart};
use crate::apply::sha256_hex;

/// An encoded body with the header that names its boundary.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Encoded {
    /// The `Content-Type` header value.
    pub content_type: String,
    /// The body.
    pub body: Vec<u8>,
}

/// One part before encoding.
struct Part<'a> {
    name: &'a str,
    filename: Option<&'a str>,
    content_type: &'a str,
    bytes: &'a [u8],
}

/// A boundary no part contains: a prefix plus a digest of every part,
/// which no part can contain without changing the digest.
fn boundary(parts: &[Part<'_>]) -> String {
    let mut all = Vec::new();
    for part in parts {
        all.extend_from_slice(part.name.as_bytes());
        all.push(0);
        all.extend_from_slice(part.bytes);
        all.push(0);
    }
    format!("deployer-{}", &sha256_hex(&all)[..32])
}

fn encode(parts: &[Part<'_>]) -> Encoded {
    let boundary = boundary(parts);
    let mut body = Vec::new();
    for part in parts {
        body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
        match part.filename {
            Some(filename) => body.extend_from_slice(
                format!(
                    "Content-Disposition: form-data; name=\"{}\"; filename=\"{filename}\"\r\n",
                    part.name
                )
                .as_bytes(),
            ),
            None => body.extend_from_slice(
                format!("Content-Disposition: form-data; name=\"{}\"\r\n", part.name).as_bytes(),
            ),
        }
        body.extend_from_slice(format!("Content-Type: {}\r\n\r\n", part.content_type).as_bytes());
        body.extend_from_slice(part.bytes);
        body.extend_from_slice(b"\r\n");
    }
    body.extend_from_slice(format!("--{boundary}--\r\n").as_bytes());
    Encoded {
        content_type: format!("multipart/form-data; boundary={boundary}"),
        body,
    }
}

/// The body of `PUT /accounts/{a}/workers/scripts/{s}`: the metadata as
/// JSON, then every module under its own name and content type.
///
/// # Examples
/// ```
/// use deployer_engine::api::ModulePart;
/// use deployer_engine::multipart::script_upload;
/// use deployer_manifest::schema::ModuleKind;
/// let encoded = script_upload(
///     br#"{"main_module":"index.js"}"#,
///     &[ModulePart { name: "index.js".to_owned(), kind: ModuleKind::EsModule, bytes: b"export default {}".to_vec() }],
/// );
/// assert!(encoded.content_type.starts_with("multipart/form-data; boundary=deployer-"));
/// let text = String::from_utf8(encoded.body).unwrap();
/// assert!(text.contains("name=\"metadata\""));
/// assert!(text.contains("name=\"index.js\"; filename=\"index.js\""));
/// assert!(text.contains("Content-Type: application/javascript+module"));
/// ```
#[must_use]
pub fn script_upload(metadata_json: &[u8], modules: &[ModulePart]) -> Encoded {
    let mut parts = vec![Part {
        name: "metadata",
        filename: None,
        content_type: "application/json",
        bytes: metadata_json,
    }];
    for module in modules {
        parts.push(Part {
            name: &module.name,
            filename: Some(&module.name),
            content_type: module.kind.content_type(),
            bytes: &module.bytes,
        });
    }
    encode(&parts)
}

/// The body of `POST /accounts/{a}/workers/assets/upload?base64=true`:
/// every file under its hash, base64, with the type the layer will serve
/// it as.
#[must_use]
pub fn assets_upload(files: &[AssetFile]) -> Encoded {
    let encoded: Vec<String> = files
        .iter()
        .map(|file| Base64::encode_string(&file.bytes))
        .collect();
    let parts: Vec<Part<'_>> = files
        .iter()
        .zip(&encoded)
        .map(|(file, text)| Part {
            name: &file.hash,
            filename: Some(&file.hash),
            content_type: &file.content_type,
            bytes: text.as_bytes(),
        })
        .collect();
    encode(&parts)
}

