//! Grants: what lets a browser speak to an agent directly.
//!
//! A secret goes browser to agent and never through the control plane,
//! so the agent needs a way to know the browser is the instance's owner
//! acting now. The control plane signs a short-lived grant naming the
//! instance, the purpose, and for a secrets grant the names it may set;
//! the agent verifies it against the control plane's public key. The same
//! shape carries the wake the control plane sends after a configuration
//! change and the confirmation a bucket deletion needs.
//!
//! A grant carries no secret and names no value. Its text is
//! `base64(json) "." base64(signature)`, both standard padded base64.

use base64ct::{Base64, Encoding};
use deployer_manifest::signature::{self, SignatureError};
use serde::{Deserialize, Serialize};

/// What a grant permits.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Purpose {
    /// Setting the named secrets.
    Secrets,
    /// Deleting the instance's bucket, with the typed name beside it.
    DeleteBucket,
    /// Reconciling now rather than at the next tick.
    Reconcile,
}

/// A grant's claims.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Grant {
    /// The instance the grant is for.
    pub instance_id: String,
    /// What it permits.
    pub purpose: Purpose,
    /// For a secrets grant, the binding names it may set.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub secret_names: Vec<String>,
    /// When it was issued, epoch milliseconds.
    pub issued_at_ms: u64,
    /// When it stops working, epoch milliseconds.
    pub expires_at_ms: u64,
    /// A value the issuer never repeats, so two grants for one purpose are
    /// two grants.
    pub nonce: String,
}

/// Why a grant was refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GrantError {
    /// The text is not two base64 halves with JSON in the first.
    Malformed,
    /// The signature does not verify under the control plane's key.
    Signature(SignatureError),
    /// The grant has expired.
    Expired,
    /// The grant is for another instance.
    WrongInstance,
    /// The grant is for another purpose.
    WrongPurpose,
}

impl core::fmt::Display for GrantError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::Malformed => f.write_str("the grant is not readable"),
            Self::Signature(inner) => write!(f, "the grant's signature was refused: {inner}"),
            Self::Expired => f.write_str("the grant has expired"),
            Self::WrongInstance => f.write_str("the grant is for another instance"),
            Self::WrongPurpose => f.write_str("the grant is for another purpose"),
        }
    }
}

impl std::error::Error for GrantError {}

/// Sign a grant into its text.
///
/// # Examples
/// ```
/// use deployer_engine::grant::{issue, verify, Grant, Purpose};
/// use deployer_manifest::signature::public_key_text;
/// let seed = [9_u8; 32];
/// let grant = Grant {
///     instance_id: "inst-1".to_owned(),
///     purpose: Purpose::Secrets,
///     secret_names: vec!["CACHET_SIGNING_KEY".to_owned()],
///     issued_at_ms: 1_000,
///     expires_at_ms: 61_000,
///     nonce: "n1".to_owned(),
/// };
/// let token = issue(&seed, &grant);
/// let keys = [public_key_text(&seed)];
/// let verified = verify(&keys, &token, "inst-1", Purpose::Secrets, 30_000).unwrap();
/// assert_eq!(verified, grant);
/// assert!(verify(&keys, &token, "inst-1", Purpose::Secrets, 61_001).is_err());
/// assert!(verify(&keys, &token, "inst-2", Purpose::Secrets, 30_000).is_err());
/// ```
#[must_use]
pub fn issue(seed: &[u8; 32], grant: &Grant) -> String {
    let json = serde_json::to_vec(grant).expect("a grant serializes");
    let signature = signature::sign(seed, &json);
    format!("{}.{signature}", Base64::encode_string(&json))
}

/// Verify a grant's text for one instance and one purpose at one moment.
///
/// # Errors
/// [`GrantError`].
pub fn verify(
    public_keys: &[String],
    token: &str,
    instance_id: &str,
    purpose: Purpose,
    now_ms: u64,
) -> Result<Grant, GrantError> {
    let (claims_text, signature_text) = token.split_once('.').ok_or(GrantError::Malformed)?;
    let json = Base64::decode_vec(claims_text).map_err(|_| GrantError::Malformed)?;
    signature::verify(public_keys, &json, signature_text).map_err(GrantError::Signature)?;
    let grant: Grant = serde_json::from_slice(&json).map_err(|_| GrantError::Malformed)?;
    if now_ms > grant.expires_at_ms {
        return Err(GrantError::Expired);
    }
    if grant.instance_id != instance_id {
        return Err(GrantError::WrongInstance);
    }
    if grant.purpose != purpose {
        return Err(GrantError::WrongPurpose);
    }
    Ok(grant)
}

#[cfg(test)]
mod tests {
    use super::*;
    use deployer_manifest::signature::public_key_text;

    fn grant(purpose: Purpose) -> Grant {
        Grant {
            instance_id: "inst-1".to_owned(),
            purpose,
            secret_names: Vec::new(),
            issued_at_ms: 0,
            expires_at_ms: 100,
            nonce: "n".to_owned(),
        }
    }

    #[test]
    fn a_tampered_claim_fails_the_signature_and_a_wrong_key_does_too() {
        let seed = [1_u8; 32];
        let keys = [public_key_text(&seed)];
        let token = issue(&seed, &grant(Purpose::Reconcile));
        let (claims, signature) = token.split_once('.').unwrap();
        let mut forged = serde_json::from_slice::<Grant>(&Base64::decode_vec(claims).unwrap()).unwrap();
        forged.instance_id = "inst-2".to_owned();
        let forged_token = format!(
            "{}.{signature}",
            Base64::encode_string(&serde_json::to_vec(&forged).unwrap())
        );
        assert!(matches!(
            verify(&keys, &forged_token, "inst-2", Purpose::Reconcile, 10),
            Err(GrantError::Signature(_))
        ));
        let other = [public_key_text(&[2_u8; 32])];
        assert!(matches!(
            verify(&other, &token, "inst-1", Purpose::Reconcile, 10),
            Err(GrantError::Signature(_))
        ));
        assert_eq!(
            verify(&keys, &token, "inst-1", Purpose::Secrets, 10),
            Err(GrantError::WrongPurpose)
        );
        assert_eq!(
            verify(&keys, "nodot", "inst-1", Purpose::Reconcile, 10),
            Err(GrantError::Malformed)
        );
    }
}
