//! The error table: every refusal either server sends, as a code the
//! client matches on and a problem+json body.

use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

/// The `application/problem+json` content type.
pub const PROBLEM_CONTENT_TYPE: &str = "application/problem+json";

/// Every refusal code.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "snake_case")]
pub enum ErrorCode {
    /// No session, or an agent key that is not one.
    Unauthorized,
    /// A session that does not own the instance.
    Forbidden,
    /// No such instance, release, or route.
    NotFound,
    /// A body or query that does not parse, or a field outside its set.
    MalformedBody,
    /// An instance name outside the grammar.
    BadName,
    /// The account already holds the name and it is not this instance's.
    NameTaken,
    /// The operation needs a fresh Cloudflare authorization first.
    AuthorizationRequired,
    /// An operation is already running for the instance.
    OperationRunning,
    /// The release is not published, or not for this product.
    ReleaseUnknown,
    /// A grant that did not verify, expired, or was for another purpose.
    GrantRefused,
    /// The typed name did not match the instance's.
    NameMismatch,
    /// Cloudflare or the release store did not answer usefully.
    UpstreamUnavailable,
    /// The record changed under the request; read it again.
    Conflict,
}

impl ErrorCode {
    /// The HTTP status the code answers with.
    #[must_use]
    pub const fn status(self) -> u16 {
        match self {
            Self::Unauthorized => 401,
            Self::Forbidden | Self::GrantRefused | Self::NameMismatch => 403,
            Self::NotFound | Self::ReleaseUnknown => 404,
            Self::MalformedBody | Self::BadName => 400,
            Self::NameTaken | Self::OperationRunning | Self::Conflict => 409,
            Self::AuthorizationRequired => 428,
            Self::UpstreamUnavailable => 503,
        }
    }

    /// The code's wire name.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Unauthorized => "unauthorized",
            Self::Forbidden => "forbidden",
            Self::NotFound => "not_found",
            Self::MalformedBody => "malformed_body",
            Self::BadName => "bad_name",
            Self::NameTaken => "name_taken",
            Self::AuthorizationRequired => "authorization_required",
            Self::OperationRunning => "operation_running",
            Self::ReleaseUnknown => "release_unknown",
            Self::GrantRefused => "grant_refused",
            Self::NameMismatch => "name_mismatch",
            Self::UpstreamUnavailable => "upstream_unavailable",
            Self::Conflict => "conflict",
        }
    }

    /// One sentence a person reads.
    #[must_use]
    pub const fn title(self) -> &'static str {
        match self {
            Self::Unauthorized => "Sign in to continue.",
            Self::Forbidden => "This instance belongs to another account.",
            Self::NotFound => "Nothing here.",
            Self::MalformedBody => "The request did not have the shape this route takes.",
            Self::BadName => {
                "An instance name is a lowercase word of 2 to 32 characters: a letter, then letters, digits, and dashes."
            }
            Self::NameTaken => "The account already holds a worker under this name.",
            Self::AuthorizationRequired => "Authorize this operation with Cloudflare first.",
            Self::OperationRunning => "An operation is already running for this instance.",
            Self::ReleaseUnknown => "No such release is published.",
            Self::GrantRefused => "The grant was refused.",
            Self::NameMismatch => "The name typed is not this instance's name.",
            Self::UpstreamUnavailable => "Cloudflare did not answer; try again.",
            Self::Conflict => "The instance changed while you were editing it; reload.",
        }
    }

    /// The problem body for this code.
    #[must_use]
    pub fn body(self) -> ProblemBody {
        ProblemBody {
            r#type: "about:blank".to_owned(),
            title: self.title().to_owned(),
            status: self.status(),
            code: self,
        }
    }
}

/// An RFC 9457 problem body.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
pub struct ProblemBody {
    /// Always `about:blank`; the code is the vocabulary.
    pub r#type: String,
    /// One sentence a person reads.
    pub title: String,
    /// The HTTP status, repeated.
    pub status: u16,
    /// The code the client matches on.
    pub code: ErrorCode,
}

impl ProblemBody {
    /// The body's bytes: compact JSON, so two refusals with one code are
    /// one byte string.
    #[must_use]
    pub fn to_json(&self) -> String {
        serde_json::to_string(self).expect("a problem body serializes")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_wire_name_and_the_serde_name_agree() {
        for code in [
            ErrorCode::Unauthorized,
            ErrorCode::AuthorizationRequired,
            ErrorCode::UpstreamUnavailable,
        ] {
            let serialized = serde_json::to_value(code).expect("serializes");
            assert_eq!(serialized, code.as_str());
        }
    }

    #[test]
    fn a_problem_body_carries_the_status_its_code_answers_with() {
        let body = ErrorCode::NameTaken.body();
        assert_eq!(body.status, 409);
        assert_eq!(
            body.to_json(),
            r#"{"type":"about:blank","title":"The account already holds a worker under this name.","status":409,"code":"name_taken"}"#
        );
    }
}
