//! The Cloudflare REST API, as the engine and the control plane call it
//! from inside a worker.
//!
//! [`CloudflareClient`] implements the engine's trait over `worker::Fetch`
//! with one credential, so the agent drives it with its account token and
//! the control plane drives it with a customer's operation token. The
//! account-level calls the control plane alone makes live in [`account`],
//! and the release store's blob fetch in [`blobs`].
//!
//! Every answer passes through the API's envelope, and a refusal becomes
//! the engine's [`ApiError`] with the platform's own code. No body a
//! request carried is ever logged or repeated.

#![forbid(unsafe_code)]
#![allow(async_fn_in_trait)]

pub mod account;
pub mod blobs;
pub mod client;

pub use client::CloudflareClient;

use deployer_engine::api::ApiError;
use serde::de::DeserializeOwned;
use serde::Deserialize;
use worker::{Fetch, Headers, Method, Request, RequestInit};

/// The production API base.
pub const API_BASE: &str = "https://api.cloudflare.com/client/v4";

/// The production OAuth base.
pub const OAUTH_BASE: &str = "https://dash.cloudflare.com/oauth2";

/// A request body.
pub enum Body {
    /// JSON text.
    Json(String),
    /// Raw bytes with their content type.
    Bytes {
        /// The `Content-Type` header value.
        content_type: String,
        /// The bytes.
        bytes: Vec<u8>,
    },
    /// A URL-encoded form.
    Form(String),
}

/// The platform's envelope.
#[derive(Debug, Deserialize)]
struct Envelope<T> {
    #[serde(default)]
    success: bool,
    #[serde(default)]
    errors: Vec<EnvelopeError>,
    result: Option<T>,
    #[serde(default)]
    result_info: Option<ResultInfo>,
}

#[derive(Debug, Deserialize)]
struct EnvelopeError {
    #[serde(default)]
    code: Option<u32>,
    #[serde(default)]
    message: String,
}

/// Paging facts the platform puts beside a list.
#[derive(Debug, Default, Deserialize)]
pub struct ResultInfo {
    /// The cursor for the next page, on cursor-paged listings.
    #[serde(default)]
    pub cursor: Option<String>,
    /// Whether more follows, on cursor-paged listings.
    #[serde(default)]
    pub is_truncated: Option<bool>,
    /// How many pages, on page-numbered listings.
    #[serde(default)]
    pub total_pages: Option<u32>,
}

/// A decoded answer: the result and its paging facts.
pub struct Answer<T> {
    /// The result.
    pub result: T,
    /// The paging facts, when the platform sent any.
    pub info: ResultInfo,
}

/// Send one request with a bearer credential and decode the envelope.
///
/// # Errors
/// [`ApiError`] for a transport failure, a non-success envelope, or an
/// unreadable body; a 404 is an error with status 404, which callers
/// that expect absence read as `None`.
pub async fn call<T: DeserializeOwned>(
    bearer: &str,
    method: Method,
    url: &str,
    body: Option<Body>,
) -> Result<Answer<T>, ApiError> {
    let (status, text) = send(Some(bearer), method, url, body).await?;
    decode(status, &text)
}

/// Send one request and answer the status and the body text.
///
/// # Errors
/// [`ApiError::transport`] when the request could not be made or
/// answered.
pub async fn send(
    bearer: Option<&str>,
    method: Method,
    url: &str,
    body: Option<Body>,
) -> Result<(u16, String), ApiError> {
    let headers = Headers::new();
    if let Some(token) = bearer {
        headers
            .set("authorization", &format!("Bearer {token}"))
            .map_err(|_| ApiError::transport("the authorization header could not be set"))?;
    }
    headers
        .set("accept", "application/json")
        .map_err(|_| ApiError::transport("the accept header could not be set"))?;
    let mut init = RequestInit::new();
    init.with_method(method);
    match body {
        Some(Body::Json(text)) => {
            headers
                .set("content-type", "application/json")
                .map_err(|_| ApiError::transport("the content-type header could not be set"))?;
            init.with_body(Some(worker::wasm_bindgen::JsValue::from_str(&text)));
        }
        Some(Body::Form(text)) => {
            headers
                .set("content-type", "application/x-www-form-urlencoded")
                .map_err(|_| ApiError::transport("the content-type header could not be set"))?;
            init.with_body(Some(worker::wasm_bindgen::JsValue::from_str(&text)));
        }
        Some(Body::Bytes {
            content_type,
            bytes,
        }) => {
            headers
                .set("content-type", &content_type)
                .map_err(|_| ApiError::transport("the content-type header could not be set"))?;
            let array = worker::js_sys::Uint8Array::from(bytes.as_slice());
            init.with_body(Some(array.into()));
        }
        None => {}
    }
    init.with_headers(headers);
    let request = Request::new_with_init(url, &init)
        .map_err(|_| ApiError::transport("the request could not be built"))?;
    let mut response = Fetch::Request(request)
        .send()
        .await
        .map_err(|_| ApiError::transport("Cloudflare did not answer"))?;
    let status = response.status_code();
    let text = response.text().await.unwrap_or_default();
    Ok((status, text))
}

/// Decode an envelope, turning a refusal into an [`ApiError`] that carries
/// the platform's first error code and message.
///
/// # Errors
/// [`ApiError`].
pub fn decode<T: DeserializeOwned>(status: u16, text: &str) -> Result<Answer<T>, ApiError> {
    let envelope: Envelope<T> = match serde_json::from_str(text) {
        Ok(envelope) => envelope,
        Err(_) if (200..300).contains(&status) => {
            return Err(ApiError {
                status,
                code: None,
                message: "the answer was not the envelope this client reads".to_owned(),
            })
        }
        Err(_) => {
            return Err(ApiError {
                status,
                code: None,
                message: format!("Cloudflare answered {status}"),
            })
        }
    };
    if !(200..300).contains(&status) || !envelope.success {
        let first = envelope.errors.first();
        return Err(ApiError {
            status,
            code: first.and_then(|error| error.code),
            message: first
                .map(|error| error.message.clone())
                .unwrap_or_else(|| format!("Cloudflare answered {status}")),
        });
    }
    let result = envelope.result.ok_or_else(|| ApiError {
        status,
        code: None,
        message: "the answer carried no result".to_owned(),
    })?;
    Ok(Answer {
        result,
        info: envelope.result_info.unwrap_or_default(),
    })
}

/// Percent-encode a path segment.
#[must_use]
pub fn segment(text: &str) -> String {
    worker::js_sys::encode_uri_component(text).into()
}
