//! The engine's trait, over the REST API.

use std::collections::BTreeMap;

use deployer_engine::api::{
    ApiError, AssetFile, AssetsSession, CloudflareApi, Domain, KvNamespace, ModulePart,
    ObjectPage, ProbeAnswer, ScriptInfo, Zone,
