use serde_json::json;
use worker::Method;

use crate::{call, decode, segment, send, Answer, Body};

/// One account's API, under one credential.
#[derive(Debug, Clone)]
pub struct CloudflareClient {
    /// The API base, without a trailing slash.
    pub base: String,
    /// The bearer credential: an account token or an operation's OAuth
    /// access token.
    token: String,
}

impl CloudflareClient {
    /// A client against a base with a credential.
    #[must_use]
    pub fn new(base: &str, token: &str) -> Self {
        Self {
            base: base.trim_end_matches('/').to_owned(),
            token: token.to_owned(),
        }
    }

    fn url(&self, path: &str) -> String {
        format!("{}{path}", self.base)
    }

    async fn get<T: serde::de::DeserializeOwned>(&self, path: &str) -> Result<Answer<T>, ApiError> {
        call(&self.token, Method::Get, &self.url(path), None).await
    }

    async fn json<T: serde::de::DeserializeOwned>(
        &self,
        method: Method,
        path: &str,
        body: serde_json::Value,
    ) -> Result<Answer<T>, ApiError> {
        call(
            &self.token,
            method,
            &self.url(path),
            Some(Body::Json(body.to_string())),
        )
        .await
    }

    /// A GET that reads a 404 as absence.
    async fn get_optional<T: serde::de::DeserializeOwned>(
        &self,
        path: &str,
    ) -> Result<Option<T>, ApiError> {
        match self.get::<T>(path).await {
            Ok(answer) => Ok(Some(answer.result)),
            Err(error) if error.is_not_found() => Ok(None),
            Err(error) => Err(error),
        }
    }

    /// A DELETE whose answer is not read beyond its status.
    async fn delete(&self, path: &str) -> Result<(), ApiError> {
        call::<serde_json::Value>(&self.token, Method::Delete, &self.url(path), None)
            .await
            .map(|_| ())
    }
}

