/// The parts of a Postgres URL Hyperdrive takes.
fn hyperdrive_origin(connection: &str) -> Result<serde_json::Value, ApiError> {
    let url = worker::Url::parse(connection)
        .map_err(|_| ApiError::transport("the database URL is not a URL"))?;
    let scheme = match url.scheme() {
        "postgres" | "postgresql" => "postgres",
        "mysql" => "mysql",
        _ => return Err(ApiError::transport("the database URL is not postgres or mysql")),
    };
    let host = url
        .host_str()
        .ok_or_else(|| ApiError::transport("the database URL names no host"))?;
    let database = url.path().trim_start_matches('/');
    if database.is_empty() {
        return Err(ApiError::transport("the database URL names no database"));
    }
    Ok(json!({
        "scheme": scheme,
        "host": host,
        "port": url.port().unwrap_or(if scheme == "mysql" { 3306 } else { 5432 }),
        "database": database,
        "user": url.username(),
        "password": url.password().unwrap_or(""),
    }))
}

impl CloudflareApi for CloudflareClient {
    async fn get_script(&self, account: &str, name: &str) -> Result<Option<ScriptInfo>, ApiError> {
        let path = format!(
            "/accounts/{account}/workers/scripts/{}/settings",
            segment(name)
        );
        Ok(self
            .get_optional::<SettingsAnswer>(&path)
            .await?
            .map(|settings| ScriptInfo {
                tags: settings.tags,
            }))
    }

    async fn upload_script(
        &self,
        account: &str,
        name: &str,
        metadata: &ScriptMetadata,
        modules: &[ModulePart],
    ) -> Result<(), ApiError> {
        let metadata_json = serde_json::to_vec(metadata)
            .map_err(|_| ApiError::transport("the metadata did not serialize"))?;
        let encoded = multipart::script_upload(&metadata_json, modules);
        let path = format!("/accounts/{account}/workers/scripts/{}", segment(name));
        call::<serde_json::Value>(
            &self.token,
            Method::Put,
            &self.url(&path),
            Some(Body::Bytes {
                content_type: encoded.content_type,
                bytes: encoded.body,
            }),
        )
        .await
        .map(|_| ())
    }

    async fn delete_script(&self, account: &str, name: &str) -> Result<(), ApiError> {
        self.delete(&format!(
            "/accounts/{account}/workers/scripts/{}?force=true",
            segment(name)
        ))
        .await
    }

    async fn put_secret(
        &self,
        account: &str,
        script: &str,
        name: &str,
        value: &str,
    ) -> Result<(), ApiError> {
        let path = format!(
            "/accounts/{account}/workers/scripts/{}/secrets",
            segment(script)
        );
        self.json::<serde_json::Value>(
            Method::Put,
            &path,
            json!({ "name": name, "text": value, "type": "secret_text" }),
        )
        .await
        .map(|_| ())
    }

    async fn put_schedules(&self, account: &str, script: &str, crons: &[String]) -> Result<(), ApiError> {
        let path = format!(
            "/accounts/{account}/workers/scripts/{}/schedules",
            segment(script)
        );
        let body: Vec<serde_json::Value> = crons.iter().map(|cron| json!({ "cron": cron })).collect();
        self.json::<serde_json::Value>(Method::Put, &path, serde_json::Value::Array(body))
            .await
            .map(|_| ())
    }

    async fn list_kv_namespaces(&self, account: &str) -> Result<Vec<KvNamespace>, ApiError> {
        let mut all = Vec::new();
        let mut page = 1_u32;
        loop {
            let answer: Answer<Vec<KvNamespace>> = self
                .get(&format!(
                    "/accounts/{account}/storage/kv/namespaces?per_page=100&page={page}"
                ))
                .await?;
            let count = answer.result.len();
            all.extend(answer.result);
            let total = answer.info.total_pages.unwrap_or(1);
            if page >= total || count == 0 {
                break;
            }
            page += 1;
        }
        Ok(all)
    }

