    }

    async fn list_r2_objects(
        &self,
        account: &str,
        bucket: &str,
        cursor: Option<&str>,
    ) -> Result<ObjectPage, ApiError> {
        let mut path = format!(
            "/accounts/{account}/r2/buckets/{}/objects?per_page=1000",
            segment(bucket)
        );
        if let Some(cursor) = cursor {
            path.push_str("&cursor=");
            path.push_str(&segment(cursor));
        }
        let answer: Answer<Vec<ObjectKey>> = self.get(&path).await?;
        let more = answer.info.is_truncated.unwrap_or(false);
        Ok(ObjectPage {
            keys: answer.result.into_iter().map(|object| object.key).collect(),
            cursor: if more { answer.info.cursor } else { None },
        })
    }

    async fn delete_r2_objects(&self, account: &str, bucket: &str, keys: &[String]) -> Result<(), ApiError> {
        // why one at a time: the REST API deletes objects singly; bulk
        // deletion is an S3-API feature that needs S3 credentials the
        // agent does not hold.
        for key in keys {
            let path = format!(
                "/accounts/{account}/r2/buckets/{}/objects/{}",
                segment(bucket),
                segment(key)
            );
            match self.delete(&path).await {
                Ok(()) => {}
                Err(error) if error.is_not_found() => {}
                Err(error) => return Err(error),
            }
        }
        Ok(())
    }

