            .collect())
    }

    async fn delete_hyperdrive(&self, account: &str, id: &str) -> Result<(), ApiError> {
        self.delete(&format!(
            "/accounts/{account}/hyperdrive/configs/{}",
            segment(id)
        ))
        .await
    }

    async fn list_zones(&self, name: &str) -> Result<Vec<Zone>, ApiError> {
        let answer: Answer<Vec<Zone>> = self
            .get(&format!("/zones?name={}&per_page=50", segment(name)))
            .await?;
        Ok(answer.result)
    }

    async fn list_domains(&self, account: &str, service: &str) -> Result<Vec<Domain>, ApiError> {
        let answer: Answer<Vec<Domain>> = self
            .get(&format!(
                "/accounts/{account}/workers/domains?service={}",
                segment(service)
            ))
            .await?;
        Ok(answer.result)
    }

    async fn attach_domain(
        &self,
        account: &str,
        hostname: &str,
        service: &str,
        zone_id: &str,
    ) -> Result<Domain, ApiError> {
        let answer: Answer<Domain> = self
            .json(
                Method::Put,
                &format!("/accounts/{account}/workers/domains"),
                json!({
                    "hostname": hostname,
                    "service": service,
                    "zone_id": zone_id,
                    "environment": "production",
                }),
            )
            .await?;
        Ok(answer.result)
    }

    async fn detach_domain(&self, account: &str, domain_id: &str) -> Result<(), ApiError> {
        self.delete(&format!(
            "/accounts/{account}/workers/domains/{}",
            segment(domain_id)
        ))
        .await
    }

    async fn get_subdomain(&self, account: &str) -> Result<Option<String>, ApiError> {
        match self
            .get::<SubdomainAnswer>(&format!("/accounts/{account}/workers/subdomain"))
            .await
        {
            Ok(answer) => Ok(answer.result.subdomain.filter(|name| !name.is_empty())),
            Err(error) if error.is_not_found() => Ok(None),
            Err(error) => Err(error),
        }
    }

    async fn set_workers_dev(&self, account: &str, script: &str, enabled: bool) -> Result<(), ApiError> {
        let path = format!(
            "/accounts/{account}/workers/scripts/{}/subdomain",
            segment(script)
        );
        self.json::<serde_json::Value>(
            Method::Post,
            &path,
            json!({ "enabled": enabled, "previews_enabled": false }),
        )
        .await
        .map(|_| ())
    }

    async fn assets_upload_session(
        &self,
        account: &str,
        script: &str,
        manifest: &BTreeMap<String, (String, u64)>,
    ) -> Result<AssetsSession, ApiError> {
        let listing: serde_json::Map<String, serde_json::Value> = manifest
            .iter()
            .map(|(path, (hash, size))| (path.clone(), json!({ "hash": hash, "size": size })))
            .collect();
        let path = format!(
            "/accounts/{account}/workers/scripts/{}/assets-upload-session",
            segment(script)
        );
        let answer: Answer<SessionAnswer> = self
            .json(Method::Post, &path, json!({ "manifest": listing }))
            .await?;
        Ok(AssetsSession {
            jwt: answer.result.jwt,
            buckets: answer.result.buckets,
        })
    }

    async fn upload_assets(&self, jwt: &str, files: &[AssetFile]) -> Result<Option<String>, ApiError> {
        let encoded = multipart::assets_upload(files);
        // why the session token: the upload authenticates with the jwt the
        // session answered, never with the account credential.
        let (status, text) = send(
            Some(jwt),
            Method::Post,
            &self.url("/workers/assets/upload?base64=true"),
            Some(Body::Bytes {
                content_type: encoded.content_type,
                bytes: encoded.body,
            }),
        )
        .await?;
        let answer: Answer<CompletionAnswer> = decode(status, &text)?;
        Ok(answer.result.jwt)
    }

    async fn probe(&self, url: &str) -> Result<ProbeAnswer, ApiError> {
        let (status, body) = send(None, Method::Get, url, None).await?;
        Ok(ProbeAnswer { status, body })
    }
}
