cat > crates/deployer-cloudflare/src/blobs.rs <<'EOF'
//! The release store's blobs, fetched by hash and verified by the engine.

use deployer_engine::api::{ApiError, BlobSource};
use worker::{Fetch, Method, Request};

/// Blobs under `<base>/<hash>`.
#[derive(Debug, Clone)]
pub struct HttpBlobSource {
    /// The base, ending in a slash or not.
    pub base: String,
}

impl BlobSource for HttpBlobSource {
    async fn fetch(&self, sha256: &str) -> Result<Vec<u8>, ApiError> {
        let url = format!("{}/{sha256}", self.base.trim_end_matches('/'));
        let request = Request::new(&url, Method::Get)
            .map_err(|_| ApiError::transport("the blob request could not be built"))?;
        let mut response = Fetch::Request(request)
            .send()
            .await
            .map_err(|_| ApiError::transport("the release store did not answer"))?;
        let status = response.status_code();
        if !(200..300).contains(&status) {
            return Err(ApiError {
                status,
                code: None,
                message: format!("the release store answered {status} for a blob"),
            });
        }
        response
            .bytes()
            .await
            .map_err(|_| ApiError::transport("the blob's bytes could not be read"))
    }
}
