cat > crates/deployer-cloudflare/src/account.rs <<'EOF'
//! The account-level calls only the control plane makes: the OAuth
//! exchange, who the user is, which accounts they hold, and minting and
//! revoking the account-owned token an agent runs under.

use deployer_engine::api::ApiError;
use serde::Deserialize;
use serde_json::json;
use worker::Method;

use crate::{call, decode, segment, send, Answer, Body};

/// What the token endpoint answers.
#[derive(Debug, Clone, Deserialize)]
pub struct TokenAnswer {
    /// The access token.
    pub access_token: String,
    /// Seconds until it expires.
    #[serde(default)]
    pub expires_in: Option<u64>,
    /// The scopes granted, space-separated.
    #[serde(default)]
    pub scope: Option<String>,
}

/// Exchange an authorization code for an access token, with PKCE.
///
/// # Errors
/// [`ApiError`].
pub async fn exchange_code(
    oauth_base: &str,
    client_id: &str,
    client_secret: &str,
    code: &str,
    verifier: &str,
    redirect_uri: &str,
) -> Result<TokenAnswer, ApiError> {
    let form = form_encode(&[
        ("grant_type", "authorization_code"),
        ("code", code),
        ("redirect_uri", redirect_uri),
        ("client_id", client_id),
        ("client_secret", client_secret),
        ("code_verifier", verifier),
    ]);
    let (status, text) = send(
        None,
        Method::Post,
        &format!("{}/token", oauth_base.trim_end_matches('/')),
        Some(Body::Form(form)),
    )
    .await?;
    if !(200..300).contains(&status) {
        return Err(ApiError {
            status,
            code: None,
            message: "the code exchange was refused".to_owned(),
        });
    }
    serde_json::from_str(&text).map_err(|_| ApiError::transport("the token answer was unreadable"))
}

/// Revoke an access token at the end of an operation.
///
/// # Errors
/// [`ApiError`].
pub async fn revoke_token(
    oauth_base: &str,
    client_id: &str,
    client_secret: &str,
    token: &str,
) -> Result<(), ApiError> {
    let form = form_encode(&[
        ("token", token),
        ("client_id", client_id),
        ("client_secret", client_secret),
    ]);
    let (status, _) = send(
        None,
        Method::Post,
        &format!("{}/revoke", oauth_base.trim_end_matches('/')),
        Some(Body::Form(form)),
    )
    .await?;
    if (200..300).contains(&status) || status == 404 {
        Ok(())
    } else {
        Err(ApiError {
            status,
            code: None,
            message: "the revocation was refused".to_owned(),
        })
    }
}

/// The user behind a token.
#[derive(Debug, Clone, Deserialize)]
pub struct UserAnswer {
    /// Cloudflare's user id.
    pub id: String,
    /// The email.
    #[serde(default)]
    pub email: String,
}

/// `GET /user`.
///
/// # Errors
/// [`ApiError`].
pub async fn user(api_base: &str, token: &str) -> Result<UserAnswer, ApiError> {
    let answer: Answer<UserAnswer> = call(
        token,
        Method::Get,
        &format!("{}/user", api_base.trim_end_matches('/')),
        None,
    )
    .await?;
    Ok(answer.result)
}

/// One account the token can see.
#[derive(Debug, Clone, Deserialize)]
pub struct AccountAnswer {
    /// The id.
    pub id: String,
    /// The name.
    pub name: String,
}

/// `GET /accounts`, every page.
///
/// # Errors
/// [`ApiError`].
pub async fn accounts(api_base: &str, token: &str) -> Result<Vec<AccountAnswer>, ApiError> {
    let mut all = Vec::new();
    let mut page = 1_u32;
    loop {
        let answer: Answer<Vec<AccountAnswer>> = call(
            token,
            Method::Get,
            &format!(
                "{}/accounts?per_page=50&page={page}",
                api_base.trim_end_matches('/')
            ),
            None,
        )
        .await?;
        let count = answer.result.len();
        all.extend(answer.result);
        if page >= answer.info.total_pages.unwrap_or(1) || count == 0 {
            break;
        }
        page += 1;
    }
    Ok(all)
}

/// A permission group the account token API names.
#[derive(Debug, Clone, Deserialize)]
pub struct PermissionGroup {
    /// The id policies reference.
    pub id: String,
    /// The name a person reads.
    pub name: String,
}

/// `GET /accounts/{a}/tokens/permission_groups`.
///
/// # Errors
/// [`ApiError`].
pub async fn permission_groups(
    api_base: &str,
    token: &str,
    account: &str,
) -> Result<Vec<PermissionGroup>, ApiError> {
    let answer: Answer<Vec<PermissionGroup>> = call(
        token,
        Method::Get,
        &format!(
            "{}/accounts/{account}/tokens/permission_groups",
            api_base.trim_end_matches('/')
        ),
        None,
    )
    .await?;
    Ok(answer.result)
}

/// An account-owned token, as minted: the value is answered once.
#[derive(Debug, Clone, Deserialize)]
pub struct MintedToken {
    /// The token's id, for revocation.
    pub id: String,
    /// The value. Never logged; written into the agent's secret binding
    /// and dropped.
    pub value: String,
}

/// `POST /accounts/{a}/tokens`: mint the agent's token with the named
/// permission groups on the account, and on one zone when given.
///
/// # Errors
/// [`ApiError`].
pub async fn mint_account_token(
    api_base: &str,
    token: &str,
    account: &str,
    name: &str,
    account_groups: &[String],
    zone: Option<(&str, &[String])>,
) -> Result<MintedToken, ApiError> {
    let group_list = |ids: &[String]| -> Vec<serde_json::Value> {
        ids.iter().map(|id| json!({ "id": id })).collect()
    };
    let mut policies = vec![json!({
        "effect": "allow",
        "permission_groups": group_list(account_groups),
        "resources": { format!("com.cloudflare.api.account.{account}"): "*" },
    })];
    if let Some((zone_id, groups)) = zone {
        policies.push(json!({
            "effect": "allow",
            "permission_groups": group_list(groups),
            "resources": { format!("com.cloudflare.api.account.zone.{zone_id}"): "*" },
        }));
    }
    let answer: Answer<MintedToken> = call(
        token,
        Method::Post,
        &format!("{}/accounts/{account}/tokens", api_base.trim_end_matches('/')),
        Some(Body::Json(
            json!({ "name": name, "policies": policies }).to_string(),
        )),
    )
    .await?;
    Ok(answer.result)
}

/// `DELETE /accounts/{a}/tokens/{id}`.
///
/// # Errors
/// [`ApiError`].
pub async fn delete_account_token(
    api_base: &str,
    token: &str,
    account: &str,
    token_id: &str,
) -> Result<(), ApiError> {
    let (status, text) = send(
        Some(token),
        Method::Delete,
        &format!(
            "{}/accounts/{account}/tokens/{}",
            api_base.trim_end_matches('/'),
            segment(token_id)
        ),
        None,
    )
    .await?;
    if status == 404 {
        return Ok(());
    }
    decode::<serde_json::Value>(status, &text).map(|_| ())
}

/// URL-encode a form.
fn form_encode(pairs: &[(&str, &str)]) -> String {
    pairs
        .iter()
        .map(|(key, value)| format!("{key}={}", segment(value)))
        .collect::<Vec<_>>()
        .join("&")
}
