//!
//! The agent worker imports the names below, so a binding it reads and a
//! binding its manifest declares are one constant. `agent-manifest` (this
//! crate's second binary) emits the manifest, the repository commits it
//! under `fixtures/deployer-agent/deploy-manifest.json`, and the
//! agent-manifest gate fails on drift (CLAUDE.md §8). CI measures the
//! built modules into it, signs it, and publishes it like any product's.

use deployer_manifest::schema::{
    BindingSpec, CronSpec, CustomDomain, Limits, Manifest, Migrations, ModuleDecl, ModuleKind,
    Probe, Requirement, RouteSpec, SecretSpec, VarSpec, WorkerSpec,
};
use deployer_manifest::MANIFEST_VERSION;

/// The product name in the release store.
pub const PRODUCT: &str = "deployer-agent";

/// The binding names the agent reads.
pub mod names {
