    pub const CONTROL_PLANE_URL: &str = "CONTROL_PLANE_URL";
    /// The instance this agent serves.
    pub const INSTANCE_ID: &str = "INSTANCE_ID";
    /// The control plane's ed25519 public key, base64, which grants verify
