    pub const CONTROL_PLANE_PUBLIC_KEY: &str = "CONTROL_PLANE_PUBLIC_KEY";
    /// The release public keys the agent accepts manifests under,
    /// comma-joined base64.
    pub const RELEASE_PUBLIC_KEYS: &str = "RELEASE_PUBLIC_KEYS";
    /// The Cloudflare API base, overridable for the lane.
    pub const CF_API_BASE_URL: &str = "CF_API_BASE_URL";
    /// The account-owned API token the agent acts with.
    pub const AGENT_TOKEN: &str = "AGENT_TOKEN";
    /// The bearer the control plane knows this agent by.
    pub const AGENT_KEY: &str = "AGENT_KEY";
    /// The Durable Object namespace holding the agent's state.
    pub const AGENT: &str = "AGENT";
    /// The Durable Object class.
    pub const AGENT_CLASS: &str = "Agent";
}

