pub const CRON: &str = "*/5 * * * *";

/// The agent's manifest template for one version: unmeasured, for CI to
/// measure and sign.
#[must_use]
pub fn manifest(version: &str) -> Manifest {
    let var = |name: &str, summary: &str| VarSpec {
