//! The agent worker's entry: routes the browser's and the control plane's
//! requests to the one Durable Object that holds this instance's state,
//! and turns the cron into a reconcile.
//!
//! The worker itself decides nothing. It answers CORS for the control
//! plane's origin, because the browser posts secrets here directly, and
//! hands every request to [`object::Agent`], whose single-threaded storage
//! is what keeps two reconciles from running at once.

#![forbid(unsafe_code)]

mod control;
mod log;
mod object;
mod problem;

use deployer_api::agent::names;
use deployer_api::ErrorCode;
use worker::{event, Context, Cors, Env, Method, Request, Response, Result};

pub use object::Agent;

/// The agent's version, which it reports and compares against desired
/// state to know when to update itself.
pub const AGENT_VERSION: &str = env!("CARGO_PKG_VERSION");

/// The commit the agent was built from, when the build stamped one.
pub const BUILD_SHA: Option<&str> = option_env!("DEPLOYER_BUILD_SHA");

/// The paths the browser posts to under a grant, and the control plane's
/// wake.
const BROWSER_PATHS: [&str; 3] = ["/secrets", "/delete-bucket", "/reconcile"];

/// The fetch entry. Every request the agent takes is forwarded to the
/// object; CORS is answered here because it is a property of the
/// worker's origin, not of the state.
#[event(fetch)]
async fn fetch(req: Request, env: Env, _ctx: Context) -> Result<Response> {
    console_error_panic_hook::set_once();
    let path = req.path();
    let method = req.method();
    let cors = cors(&env);
    if method == Method::Options {
        return Response::empty()?.with_status(204).with_cors(&cors);
    }
    let known = path == "/health" && method == Method::Get
        || BROWSER_PATHS.contains(&path.as_str()) && method == Method::Post;
    if !known {
        return problem::response(ErrorCode::NotFound);
    }
    let response = object_stub(&env)?.fetch_with_request(req).await?;
    response.with_cors(&cors)
}

/// The cron: reconcile now. The tick goes through the object so it
/// serializes with every other run.
#[event(scheduled)]
async fn scheduled(_event: worker::ScheduledEvent, env: Env, _ctx: worker::ScheduleContext) {
    console_error_panic_hook::set_once();
    let Ok(stub) = object_stub(&env) else {
        log::event("error", "agent.unbound", &[]);
        return;
    };
    if let Err(failure) = stub.fetch_with_str("https://agent.invalid/tick").await {
        log::event("error", "agent.tick_failed", &[("reason", failure.to_string())]);
    }
}

/// The object for this instance: one per agent, named by the instance id
/// so every request and every tick lands on the same state.
fn object_stub(env: &Env) -> Result<worker::Stub> {
    let instance_id = env.var(names::INSTANCE_ID)?.to_string();
    env.durable_object(names::AGENT)?
        .id_from_name(&instance_id)?
        .get_stub()
}

/// The control plane's origin is the only one a browser may post from.
fn cors(env: &Env) -> Cors {
    let origin = env
        .var(names::CONTROL_PLANE_URL)
        .map(|value| value.to_string())
        .unwrap_or_default();
    Cors::new()
        .with_origins([origin.trim_end_matches('/')])
        .with_methods([Method::Get, Method::Post, Method::Options])
        .with_allowed_headers(["content-type"])
        .with_max_age(600)
}
