//! The agent's event log: one JSON object per line on the console. Fields
//! carry step names, versions, and reasons, never a secret's value, a
//! grant, or a token.

use worker::console_log;

/// Emit one event line at the given level.
pub fn event(level: &str, name: &str, fields: &[(&str, String)]) {
    let mut document = serde_json::Map::new();
    document.insert("level".to_owned(), level.into());
    document.insert("event".to_owned(), name.into());
    for (key, value) in fields {
