    pub agent_token: String,
    /// The bearer the control plane knows this agent by.
    pub agent_key: String,
}

impl Settings {
    /// Read the settings off the environment.
    ///
    /// # Errors
    /// A missing binding, by name.
    pub fn read(env: &worker::Env) -> worker::Result<Self> {
        use deployer_api::agent::names;
        let var = |name: &str| env.var(name).map(|value| value.to_string());
        let secret = |name: &str| env.secret(name).map(|value| value.to_string());
        Ok(Self {
            control_plane_url: var(names::CONTROL_PLANE_URL)?
                .trim_end_matches('/')
                .to_owned(),
            instance_id: var(names::INSTANCE_ID)?,
            control_public_key: var(names::CONTROL_PLANE_PUBLIC_KEY)?,
            release_public_keys: var(names::RELEASE_PUBLIC_KEYS)?
                .split(',')
                .map(str::trim)
                .filter(|key| !key.is_empty())
                .map(str::to_owned)
                .collect(),
            api_base: var(names::CF_API_BASE_URL)
                .unwrap_or_else(|_| deployer_cloudflare::API_BASE.to_owned()),
            agent_token: secret(names::AGENT_TOKEN)?,
            agent_key: secret(names::AGENT_KEY)?,
        })
    }

    fn agent_url(&self, tail: &str) -> String {
        format!(
            "{}/agent/v1/instances/{}/{tail}",
            self.control_plane_url, self.instance_id
        )
    }
}

/// Read desired state.
///
/// # Errors
/// [`ApiError`].
pub async fn fetch_desired(settings: &Settings) -> Result<AgentDesired, ApiError> {
    let (status, text) = send(
        Some(&settings.agent_key),
        Method::Get,
        &settings.agent_url("desired"),
        None,
    )
    .await?;
    if !(200..300).contains(&status) {
        return Err(ApiError {
            status,
            code: None,
            message: format!("the control plane answered {status} for desired state"),
        });
    }
    serde_json::from_str(&text)
        .map_err(|_| ApiError::transport("desired state was not the shape this agent reads"))
}

/// Report events, and with `outcome` the end of the operation.
///
/// # Errors
/// [`ApiError`].
pub async fn post_events(
    settings: &Settings,
    operation_id: &str,
    events: Vec<Event>,
    outcome: Option<OperationOutcome>,
) -> Result<(), ApiError> {
    let body = AgentEvents {
        operation_id: operation_id.to_owned(),
        events,
        outcome,
    };
    let text = serde_json::to_string(&body)
        .map_err(|_| ApiError::transport("the events did not serialize"))?;
    let (status, _) = send(
        Some(&settings.agent_key),
        Method::Post,
        &settings.agent_url("events"),
        Some(Body::Json(text)),
    )
    .await?;
    if (200..300).contains(&status) {
        Ok(())
    } else {
        Err(ApiError {
            status,
            code: None,
            message: format!("the control plane answered {status} for events"),
        })
    }
}

/// Report the heartbeat.
///
/// # Errors
/// [`ApiError`].
pub async fn post_status(settings: &Settings, status_body: &AgentStatus) -> Result<(), ApiError> {
    let text = serde_json::to_string(status_body)
        .map_err(|_| ApiError::transport("the status did not serialize"))?;
    let (status, _) = send(
        Some(&settings.agent_key),
        Method::Post,
        &settings.agent_url("status"),
        Some(Body::Json(text)),
    )
    .await?;
    if (200..300).contains(&status) {
        Ok(())
    } else {
        Err(ApiError {
            status,
            code: None,
            message: format!("the control plane answered {status} for status"),
        })
    }
}

/// Fetch a manifest and its signature, verify the signature under the
/// release keys, and read the manifest. Nothing unsigned is ever parsed
/// into a plan.
///
/// # Errors
/// [`ApiError`] naming the refusal and never the bytes.
pub async fn fetch_manifest(
    settings: &Settings,
    manifest_url: &str,
    signature_url: &str,
) -> Result<Manifest, ApiError> {
    let (status, manifest_text) = send(None, Method::Get, manifest_url, None).await?;
    if !(200..300).contains(&status) {
        return Err(ApiError {
            status,
            code: None,
            message: format!("the release store answered {status} for the manifest"),
        });
    }
    let (status, signature_text) = send(None, Method::Get, signature_url, None).await?;
    if !(200..300).contains(&status) {
        return Err(ApiError {
            status,
            code: None,
            message: format!("the release store answered {status} for the signature"),
        });
    }
    signature::verify(
        &settings.release_public_keys,
        manifest_text.as_bytes(),
        &signature_text,
    )
    .map_err(|refusal| ApiError::transport(format!("the release signature was refused: {refusal}")))?;
    let manifest = Manifest::from_json(&manifest_text)
        .map_err(|refusal| ApiError::transport(format!("the manifest was refused: {refusal}")))?;
    if manifest.artifacts.is_none() {
        return Err(ApiError::transport(
            "the manifest carries no artifacts, so it was never measured",
        ));
    }
    Ok(manifest)
}
