use std::collections::BTreeMap;
use std::rc::Rc;
use std::time::Duration;

use deployer_api::agent::names;
use deployer_api::{
    AgentDesired, AgentHealth, AgentStatus, DeleteBucketBody, ErrorCode, OperationOutcome,
