use deployer_engine::grant::{self, Purpose};
use deployer_engine::plan::plan;
use deployer_engine::render::Secrets;
use deployer_engine::{Event, EventKind, Operation};
use deployer_manifest::schema::Requirement;
use serde::{Deserialize, Serialize};
use worker::{durable_object, DurableObject, Env, Request, Response, Result, State};

use crate::control::{self, Settings};
use crate::{log, problem, AGENT_VERSION};

/// The revision the agent last applied in full.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Applied {
    revision: u64,
    version: String,
    operation_id: String,
}

const KEY_APPLIED: &str = "applied";
const KEY_PENDING_SECRETS: &str = "pending_secrets";
const KEY_DELETE_CONFIRMED: &str = "delete_confirmed";
const KEY_RETRIES: &str = "retries";
const KEY_DESIRED: &str = "desired";
const KEY_AGENT_UPDATE_TRIED: &str = "agent_update_tried";

/// How many times a failed operation retries on its own before waiting for
/// the next tick or a nudge.
const MAX_RETRIES: u32 = 6;

/// The object.
#[durable_object]
pub struct Agent {
    state: State,
    env: Env,
}

impl DurableObject for Agent {
    fn new(state: State, env: Env) -> Self {
        Self { state, env }
    }

    async fn fetch(&self, mut req: Request) -> Result<Response> {
        let path = req.path();
        match path.as_str() {
            "/health" => problem::json(200, &self.health().await?),
            "/tick" => {
                self.wake().await?;
                Response::empty().map(|response| response.with_status(204))
            }
            "/secrets" => {
                let Ok(body) = req.json::<SecretsBody>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                self.take_secrets(body).await
            }
            "/delete-bucket" => {
                let Ok(body) = req.json::<DeleteBucketBody>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                self.confirm_delete(body).await
            }
            "/reconcile" => {
                let Ok(body) = req.json::<ReconcileBody>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                let settings = Settings::read(&self.env)?;
                if let Err(refusal) = grant::verify(
                    &[settings.control_public_key.clone()],
                    &body.grant,
                    &settings.instance_id,
                    Purpose::Reconcile,
                    now_ms(),
                ) {
                    log::event("warn", "agent.grant_refused", &[("reason", refusal.to_string())]);
                    return problem::response(ErrorCode::GrantRefused);
                }
                self.wake().await?;
                problem::json(202, &self.health().await?)
            }
            _ => problem::response(ErrorCode::NotFound),
        }
    }

    async fn alarm(&self) -> Result<Response> {
        self.reconcile().await;
        Response::empty()
    }
}

impl Agent {
    async fn health(&self) -> Result<AgentHealth> {
        let applied: Option<Applied> = self.state.storage().get(KEY_APPLIED).await?;
        let pending: Option<BTreeMap<String, String>> =
            self.state.storage().get(KEY_PENDING_SECRETS).await?;
        Ok(AgentHealth {
            agent_version: AGENT_VERSION.to_owned(),
            instance_id: self
                .env
                .var(names::INSTANCE_ID)
                .map(|value| value.to_string())
                .unwrap_or_default(),
            revision_applied: applied.map(|applied| applied.revision),
            secrets_pending: pending.is_some_and(|map| !map.is_empty()),
        })
    }

    /// Reconcile as soon as this request returns.
    async fn wake(&self) -> Result<()> {
        self.state
            .storage()
            .set_alarm(Duration::from_millis(1))
            .await
    }

    /// Take the browser's secrets under a grant. Every name posted must be
    /// one the grant names; the values are held until the upload that
    /// carries them succeeds.
    async fn take_secrets(&self, body: SecretsBody) -> Result<Response> {
        let settings = Settings::read(&self.env)?;
        let verified = match grant::verify(
            &[settings.control_public_key.clone()],
            &body.grant,
            &settings.instance_id,
            Purpose::Secrets,
            now_ms(),
        ) {
            Ok(verified) => verified,
            Err(refusal) => {
                log::event("warn", "agent.grant_refused", &[("reason", refusal.to_string())]);
                return problem::response(ErrorCode::GrantRefused);
            }
        };
        if body
            .secrets
            .keys()
            .any(|name| !verified.secret_names.contains(name))
        {
            log::event("warn", "agent.grant_refused", &[("reason", "a name outside the grant".to_owned())]);
            return problem::response(ErrorCode::GrantRefused);
        }
        let storage = self.state.storage();
        let mut pending: BTreeMap<String, String> = storage
            .get(KEY_PENDING_SECRETS)
            .await?
            .unwrap_or_default();
        let names: Vec<String> = body.secrets.keys().cloned().collect();
        pending.extend(body.secrets);
        storage.put(KEY_PENDING_SECRETS, &pending).await?;
        storage.put(KEY_RETRIES, 0_u32).await?;
        log::event("info", "agent.secrets_taken", &[("names", names.join(","))]);
        self.wake().await?;
        problem::json(200, &self.health().await?)
    }

    /// Take the typed name under a grant, which is what lets the bucket go.
    async fn confirm_delete(&self, body: DeleteBucketBody) -> Result<Response> {
        let settings = Settings::read(&self.env)?;
        if let Err(refusal) = grant::verify(
            &[settings.control_public_key.clone()],
            &body.grant,
            &settings.instance_id,
            Purpose::DeleteBucket,
            now_ms(),
        ) {
            log::event("warn", "agent.grant_refused", &[("reason", refusal.to_string())]);
            return problem::response(ErrorCode::GrantRefused);
        }
        let desired: Option<AgentDesired> = self.state.storage().get(KEY_DESIRED).await?;
        let Some(desired) = desired else {
            return problem::response(ErrorCode::Conflict);
        };
        if desired.spec.name != body.name {
            return problem::response(ErrorCode::NameMismatch);
        }
        self.state.storage().put(KEY_DELETE_CONFIRMED, true).await?;
        log::event("info", "agent.delete_confirmed", &[]);
        self.wake().await?;
        problem::json(200, &self.health().await?)
    }

    /// One reconcile: read desired state, converge or tear down, report.
    /// Failures are logged and reported, never raised, because the alarm
    /// that runs this has nobody to raise to.
    async fn reconcile(&self) {
        let settings = match Settings::read(&self.env) {
            Ok(settings) => settings,
            Err(failure) => {
                log::event("error", "agent.settings_missing", &[("reason", failure.to_string())]);
                return;
            }
        };
        let desired = match control::fetch_desired(&settings).await {
            Ok(desired) => desired,
            Err(failure) => {
                log::event("error", "agent.desired_unreadable", &[("reason", failure.message)]);
                return;
            }
        };
        if let Err(failure) = self.state.storage().put(KEY_DESIRED, &desired).await {
            log::event("error", "agent.storage_failed", &[("reason", failure.to_string())]);
        }
        let outcome = if desired.desired.uninstall.is_some() {
            self.tear_down(&settings, &desired).await
        } else {
            self.converge(&settings, &desired).await
        };
        match outcome {
            Ok(()) => {
                let _ = self.state.storage().put(KEY_RETRIES, 0_u32).await;
                self.maybe_update_self(&settings, &desired).await;
            }
            Err(reason) => {
                log::event("warn", "agent.operation_failed", &[("reason", reason.clone())]);
                self.schedule_retry().await;
            }
