    /// Converge the account on desired state.
    async fn converge(&self, settings: &Settings, desired: &AgentDesired) -> std::result::Result<(), String> {
        let storage = self.state.storage();
        let applied: Option<Applied> = storage.get(KEY_APPLIED).await.map_err(|e| e.to_string())?;
        let pending: BTreeMap<String, String> = storage
            .get(KEY_PENDING_SECRETS)
            .await
            .map_err(|e| e.to_string())?
            .unwrap_or_default();
        let up_to_date = applied
            .as_ref()
            .is_some_and(|applied| applied.revision == desired.desired.revision);
        if up_to_date && pending.is_empty() {
            self.heartbeat(settings, applied.as_ref(), None, true).await;
            return Ok(());
        }
        let manifest = control::fetch_manifest(settings, &desired.manifest_url, &desired.signature_url)
            .await
            .map_err(|failure| failure.message)?;
        let built = plan(&manifest, &desired.spec, &desired.desired.generated_public)
            .map_err(|failure| failure.to_string())?;
        let operation = match &applied {
            None => Operation::Install,
            Some(applied) if applied.version != desired.desired.version => Operation::Update,
            Some(_) => Operation::Configure,
        };
        // A first install, and any run with secrets waiting, carries them;
        // every other upload keeps what the platform holds.
        let carrying = applied.is_none() || !pending.is_empty();
        if carrying {
            let missing: Vec<String> = manifest
                .secrets
                .iter()
                .filter(|secret| secret.requirement == Requirement::Required)
                .filter(|secret| !pending.contains_key(&secret.name))
                .map(|secret| secret.name.clone())
                .collect();
