                let event = Event {
                    seq: 1,
                    operation,
                    step: Step::Secret { name: name.clone() },
                    kind: EventKind::Failed {
                        remedy: format!("Supply {name} and retry."),
                    },
                    detail: "waiting for a secret the browser has not posted".to_owned(),
                };
                let _ = control::post_events(settings, &desired.operation_id, vec![event], None).await;
                self.heartbeat(settings, applied.as_ref(), Some(format!("waiting for {name}")), false)
                    .await;
                // Nothing to retry until the browser posts; the post wakes
                // the object.
                return Ok(());
            }
        }
        let secrets = if carrying {
            Secrets::Values(&pending)
        } else {
            Secrets::Keep
        };
        let api = CloudflareClient::new(&settings.api_base, &settings.agent_token);
        let blobs = HttpBlobSource {
            base: desired.blob_base_url.clone(),
        };
        let target = Target {
            manifest: &manifest,
            spec: &desired.spec,
            plan: &built,
        };
        let result = {
            let mut sink = live_sink(settings, &desired.operation_id);
            apply::converge(&api, &blobs, operation, target, secrets, &mut sink).await
        };
        match result {
            Ok(()) => {
                let applied = Applied {
                    revision: desired.desired.revision,
                    version: desired.desired.version.clone(),
                    operation_id: desired.operation_id.clone(),
                };
                storage.put(KEY_APPLIED, &applied).await.map_err(|e| e.to_string())?;
                // The one place secrets lived is cleared the moment the
                // upload that carried them succeeded.
                let _ = storage.delete(KEY_PENDING_SECRETS).await;
                let _ = control::post_events(
                    settings,
                    &desired.operation_id,
                    Vec::new(),
                    Some(OperationOutcome::Succeeded),
                )
                .await;
                self.heartbeat(settings, Some(&applied), None, true).await;
                log::event(
                    "info",
                    "agent.converged",
                    &[("version", applied.version.clone()), ("revision", applied.revision.to_string())],
                );
                Ok(())
            }
            Err(failure) => {
                let _ = control::post_events(
                    settings,
                    &desired.operation_id,
                    Vec::new(),
                    Some(OperationOutcome::Failed),
                )
                .await;
                self.heartbeat(settings, applied.as_ref(), Some(failure.to_string()), false)
                    .await;
                Err(failure.to_string())
            }
        }
    }

    /// Tear the instance down as desired state asks. The bucket goes only
    /// when desired state asks and the person confirmed here.
    async fn tear_down(&self, settings: &Settings, desired: &AgentDesired) -> std::result::Result<(), String> {
        let storage = self.state.storage();
        let applied: Option<Applied> = storage.get(KEY_APPLIED).await.map_err(|e| e.to_string())?;
        if applied
            .as_ref()
            .is_some_and(|applied| applied.revision == desired.desired.revision)
        {
            self.heartbeat(settings, applied.as_ref(), None, false).await;
            return Ok(());
        }
        let wants_delete = desired
            .desired
            .uninstall
            .as_ref()
            .is_some_and(|request| request.delete_bucket);
        let confirmed: bool = storage
            .get(KEY_DELETE_CONFIRMED)
            .await
            .map_err(|e| e.to_string())?
            .unwrap_or(false);
        let manifest = control::fetch_manifest(settings, &desired.manifest_url, &desired.signature_url)
            .await
            .map_err(|failure| failure.message)?;
        let built = plan(&manifest, &desired.spec, &desired.desired.generated_public)
            .map_err(|failure| failure.to_string())?;
        let api = CloudflareClient::new(&settings.api_base, &settings.agent_token);
        let result = {
            let mut sink = live_sink(settings, &desired.operation_id);
            apply::uninstall(&api, &desired.spec, &built, wants_delete && confirmed, &mut sink).await
        };
        match result {
            Ok(()) if wants_delete && !confirmed => {
                // The worker is gone and the bucket waits for the typed
                // name; the confirmation wakes this object again.
                self.heartbeat(
                    settings,
                    applied.as_ref(),
                    Some("waiting for the bucket deletion to be confirmed".to_owned()),
                    false,
                )
                .await;
                Ok(())
            }
            Ok(()) => {
                let applied = Applied {
                    revision: desired.desired.revision,
                    version: desired.desired.version.clone(),
                    operation_id: desired.operation_id.clone(),
                };
                storage.put(KEY_APPLIED, &applied).await.map_err(|e| e.to_string())?;
                let _ = storage.delete(KEY_PENDING_SECRETS).await;
                let _ = control::post_events(
                    settings,
                    &desired.operation_id,
                    Vec::new(),
                    Some(OperationOutcome::Succeeded),
                )
                .await;
                self.heartbeat(settings, None, None, false).await;
                log::event("info", "agent.uninstalled", &[]);
                Ok(())
            }
            Err(failure) => {
                let _ = control::post_events(
                    settings,
                    &desired.operation_id,
                    Vec::new(),
                    Some(OperationOutcome::Failed),
                )
                .await;
                self.heartbeat(settings, applied.as_ref(), Some(failure.to_string()), false)
                    .await;
                Err(failure.to_string())
            }
        }
    }

    /// Re-upload this agent when desired state names another version of
    /// it. Once per named version: a version the build stamps differently
    /// from the manifest would otherwise re-upload on every tick.
    async fn maybe_update_self(&self, settings: &Settings, desired: &AgentDesired) {
        let wanted = &desired.agent.version;
        if wanted == AGENT_VERSION {
            return;
        }
        let storage = self.state.storage();
        let tried: Option<String> = storage.get(KEY_AGENT_UPDATE_TRIED).await.ok().flatten();
        if tried.as_deref() == Some(wanted.as_str()) {
            return;
        }
        let _ = storage.put(KEY_AGENT_UPDATE_TRIED, wanted).await;
        let manifest = match control::fetch_manifest(
            settings,
            &desired.agent.manifest_url,
            &desired.agent.signature_url,
        )
        .await
        {
            Ok(manifest) => manifest,
            Err(failure) => {
                log::event("warn", "agent.self_update_refused", &[("reason", failure.message)]);
                return;
            }
        };
        let built = match plan(&manifest, &desired.agent.spec, &BTreeMap::new()) {
            Ok(built) => built,
            Err(failure) => {
                log::event("warn", "agent.self_update_refused", &[("reason", failure.to_string())]);
                return;
            }
        };
        let api = CloudflareClient::new(&settings.api_base, &settings.agent_token);
        let blobs = HttpBlobSource {
            base: desired.blob_base_url.clone(),
        };
        let operation_id = format!("{}-agent", desired.operation_id);
        let target = Target {
            manifest: &manifest,
            spec: &desired.agent.spec,
            plan: &built,
        };
        let result = {
            let mut sink = live_sink(settings, &operation_id);
            apply::converge(&api, &blobs, Operation::Update, target, Secrets::Keep, &mut sink).await
        };
        let outcome = match result {
            Ok(()) => {
                log::event("info", "agent.self_updated", &[("version", wanted.clone())]);
                OperationOutcome::Succeeded
            }
            Err(failure) => {
                log::event("warn", "agent.self_update_failed", &[("reason", failure.to_string())]);
                OperationOutcome::Failed
            }
        };
        let _ = control::post_events(settings, &operation_id, Vec::new(), Some(outcome)).await;
    }

    /// Report status.
    async fn heartbeat(
        &self,
        settings: &Settings,
        applied: Option<&Applied>,
        last_error: Option<String>,
        reachable: bool,
    ) {
        let body = AgentStatus {
            agent_version: AGENT_VERSION.to_owned(),
            revision_applied: applied.map(|applied| applied.revision),
            installed_version: applied.map(|applied| applied.version.clone()),
            served_version: None,
            public_key: None,
            reachable,
            last_reconcile_at_ms: now_ms(),
            last_error,
        };
        if let Err(failure) = control::post_status(settings, &body).await {
            log::event("warn", "agent.status_unreported", &[("reason", failure.message)]);
        }
    }

    /// Back off and try again, up to a bound; past it the next tick or
    /// nudge is what tries again.
    async fn schedule_retry(&self) {
        let storage = self.state.storage();
        let retries: u32 = storage.get(KEY_RETRIES).await.ok().flatten().unwrap_or(0);
        if retries >= MAX_RETRIES {
            log::event("warn", "agent.retries_exhausted", &[]);
            return;
        }
        let _ = storage.put(KEY_RETRIES, retries + 1).await;
        let delay = Duration::from_secs(60 * 2_u64.pow(retries));
        if let Err(failure) = storage.set_alarm(delay).await {
            log::event("error", "agent.alarm_failed", &[("reason", failure.to_string())]);
        }
    }
}

/// A sink that posts each event as it happens, so a person watching sees
/// the step list move rather than fill in at the end. Each post is its own
/// task; the control plane orders by the event's own sequence number.
fn live_sink(settings: &Settings, operation_id: &str) -> impl FnMut(Event) {
    let settings = Rc::new(settings.clone());
    let operation_id = Rc::new(operation_id.to_owned());
    let in_flight: Rc<RefCell<u32>> = Rc::new(RefCell::new(0));
    move |event: Event| {
        let settings = Rc::clone(&settings);
        let operation_id = Rc::clone(&operation_id);
        let in_flight = Rc::clone(&in_flight);
        *in_flight.borrow_mut() += 1;
        worker::wasm_bindgen_futures::spawn_local(async move {
            if let Err(failure) = control::post_events(&settings, &operation_id, vec![event], None).await
            {
                log::event("warn", "agent.event_unreported", &[("reason", failure.message)]);
            }
            *in_flight.borrow_mut() -= 1;
        });
    }
}

/// The clock, sampled where it is needed.
fn now_ms() -> u64 {
    worker::Date::now().as_millis()
}
