//! The control plane worker's entry.
//!
//! Four surfaces share the worker. `/v1` is the client's API, behind a
//! session cookie. `/agent/v1` is what agents in customers' accounts call,
//! behind each agent's own key. `/releases` and `/blobs` are the public,
//! immutable release store. Everything else is the client's static files.
//!
//! State lives in three Durable Object classes: one per user, one per
//! instance, one per product's release index. The worker authenticates,
//! routes, and forwards; the objects decide.

#![forbid(unsafe_code)]

mod instance;
mod internal;
mod log;
mod oauth;
mod problem;
mod rand;
mod releases;
mod routes;
mod session;
mod settings;
mod store;
mod user;

use worker::{event, Context, Env, Request, Response, Result};

pub use instance::InstanceObject;
pub use releases::ReleaseIndex;
pub use user::UserObject;

/// The control plane's version.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// The commit the control plane was built from, when the build stamped
/// one.
pub const BUILD_SHA: Option<&str> = option_env!("DEPLOYER_BUILD_SHA");

/// The fetch entry.
#[event(fetch)]
async fn fetch(req: Request, env: Env, _ctx: Context) -> Result<Response> {
    console_error_panic_hook::set_once();
    let path = req.path();
    if path.starts_with("/v1/") {
        return routes::client(req, &env).await;
    }
    if path.starts_with("/agent/v1/") {
        return routes::agent(req, &env).await;
    }
    if path.starts_with("/releases/") || path.starts_with("/blobs/") {
        return releases::serve(&env, &path).await;
    }
    routes::assets(&env, &req).await
}
