//! The error boundary: a typed [`ErrorCode`] leaves the control plane as
//! an RFC 9457 problem+json body with the error table's status.

use deployer_api::error::PROBLEM_CONTENT_TYPE;
use deployer_api::ErrorCode;
use worker::{Headers, Response, Result};

/// Render a code as a problem+json response.
pub fn response(code: ErrorCode) -> Result<Response> {
    let headers = Headers::new();
    headers.set("content-type", PROBLEM_CONTENT_TYPE)?;
    headers.set("cache-control", "no-store")?;
    Ok(Response::ok(code.body().to_json())?
        .with_status(code.status())
        .with_headers(headers))
}

/// Render a body as JSON with a status.
pub fn json<T: serde::Serialize>(status: u16, body: &T) -> Result<Response> {
    let headers = Headers::new();
    headers.set("content-type", "application/json")?;
    headers.set("cache-control", "no-store")?;
    let text = serde_json::to_string(body)?;
    Ok(Response::ok(text)?.with_status(status).with_headers(headers))
}

/// A 302 with its Location set in one piece.
pub fn redirect(location: &str) -> Result<Response> {
    let headers = Headers::new();
    headers.set("location", location)?;
    headers.set("cache-control", "no-store")?;
    Ok(Response::empty()?.with_status(302).with_headers(headers))
}
