//! Sessions: a random id in a cookie, a record in KV, fourteen days.

use serde::{Deserialize, Serialize};
use worker::{Env, Request};

use crate::settings::names;

/// The cookie's name.
pub const COOKIE: &str = "deployer_session";

/// How long a session lives.
pub const TTL_SECONDS: u64 = 14 * 24 * 3600;

/// What a session records.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Session {
    /// Cloudflare's user id.
    pub user_id: String,
    /// The email at sign-in.
    pub email: String,
    /// When it was made, epoch milliseconds.
    pub created_at_ms: u64,
}

fn key(id: &str) -> String {
    format!("session/{id}")
}

/// The session the request carries, when it carries a live one.
pub async fn current(env: &Env, req: &Request) -> Option<Session> {
    let cookie = req.headers().get("cookie").ok().flatten()?;
    let id = cookie
        .split(';')
        .map(str::trim)
        .find_map(|pair| pair.strip_prefix(&format!("{COOKIE}=")))?
        .to_owned();
    if id.is_empty() || id.len() > 128 {
        return None;
    }
    let kv = env.kv(names::SESSIONS).ok()?;
    kv.get(&key(&id)).json::<Session>().await.ok().flatten()
}

/// Make a session, answering the cookie header value to set.
pub async fn create(env: &Env, session: &Session) -> worker::Result<String> {
    let id = crate::rand::token();
    let kv = env.kv(names::SESSIONS)?;
    kv.put(&key(&id), session)?
        .expiration_ttl(TTL_SECONDS)
        .execute()
        .await?;
    Ok(format!(
        "{COOKIE}={id}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age={TTL_SECONDS}"
    ))
}

/// Delete the request's session, answering the cookie header value that
/// clears it.
pub async fn delete(env: &Env, req: &Request) -> worker::Result<String> {
    if let Some(cookie) = req.headers().get("cookie")? {
        if let Some(id) = cookie
            .split(';')
            .map(str::trim)
            .find_map(|pair| pair.strip_prefix(&format!("{COOKIE}=")))
        {
            let kv = env.kv(names::SESSIONS)?;
            let _ = kv.delete(&key(id)).await;
        }
    }
    Ok(format!(
        "{COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0"
    ))
}
