//! How the worker talks to its objects: one request per call, JSON in and
//! out, the caller's identity in a header the objects trust because only
//! the worker can reach them.

use serde::de::DeserializeOwned;
use worker::{Env, Headers, Method, Request, RequestInit, Response, Result, Stub};

use crate::settings::names;

/// The header naming the signed-in user.
pub const USER_HEADER: &str = "x-deployer-user";
/// The header carrying an account authorization for one operation.
pub const TOKEN_HEADER: &str = "x-deployer-token";
/// The header carrying an account's display name.
pub const ACCOUNT_NAME_HEADER: &str = "x-deployer-account-name";

/// The user object for a Cloudflare user id.
pub fn user_stub(env: &Env, user_id: &str) -> Result<Stub> {
    env.durable_object(names::USERS)?
        .id_from_name(user_id)?
        .get_stub()
}

/// The instance object for an instance id.
pub fn instance_stub(env: &Env, instance_id: &str) -> Result<Stub> {
    env.durable_object(names::INSTANCES)?
        .id_from_name(instance_id)?
        .get_stub()
}

/// The release index for a product.
pub fn release_index_stub(env: &Env, product: &str) -> Result<Stub> {
    env.durable_object(names::RELEASE_INDEX)?
        .id_from_name(product)?
        .get_stub()
}

/// One call into an object.
pub async fn call(
    stub: &Stub,
    method: Method,
    path: &str,
    headers: &[(&str, &str)],
    body: Option<String>,
) -> Result<Response> {
    let mut init = RequestInit::new();
    init.with_method(method);
    let request_headers = Headers::new();
    for (name, value) in headers {
        request_headers.set(name, value)?;
    }
    if let Some(text) = body {
        request_headers.set("content-type", "application/json")?;
        init.with_body(Some(worker::wasm_bindgen::JsValue::from_str(&text)));
    }
    init.with_headers(request_headers);
    let request = Request::new_with_init(&format!("https://object.invalid{path}"), &init)?;
    stub.fetch_with_request(request).await
}

/// Read a JSON body off an object's answer, when it answered 2xx.
pub async fn json<T: DeserializeOwned>(mut response: Response) -> Result<Option<T>> {
    if !(200..300).contains(&response.status_code()) {
        return Ok(None);
    }
    response.json::<T>().await.map(Some)
}

/// The header value a request carries, when it does.
pub fn header(req: &Request, name: &str) -> Option<String> {
    req.headers().get(name).ok().flatten()
}
