/// The signature's key.
pub fn signature_key(product: &str, version: &str) -> String {
    format!("releases/{product}/{version}/manifest.sig")
}

/// The promotion marker's key.
pub fn promoted_key(product: &str) -> String {
    format!("releases/{product}/promoted")
}

/// A blob's key.
pub fn blob_key(hash: &str) -> String {
    format!("blobs/{hash}")
}

/// The bucket.
pub fn bucket(env: &Env) -> worker::Result<Bucket> {
    env.bucket(names::RELEASES)
}

/// One object's bytes, when it exists.
pub async fn read_bytes(bucket: &Bucket, key: &str) -> worker::Result<Option<Vec<u8>>> {
    let Some(object) = bucket.get(key).execute().await? else {
        return Ok(None);
    };
    let Some(body) = object.body() else {
        return Ok(None);
    };
    body.bytes().await.map(Some)
}

/// One object's text, when it exists.
pub async fn read_text(bucket: &Bucket, key: &str) -> worker::Result<Option<String>> {
    Ok(read_bytes(bucket, key)
        .await?
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned()))
}

/// The manifest of one release, verified under the product's keys.
///
/// # Errors
/// `ReleaseUnknown` when the product has no keys or the release is not
/// there; `UpstreamUnavailable` when the store cannot be read or the
/// signature is refused, which is logged as the incident it is.
pub async fn manifest(
    env: &Env,
    settings: &Settings,
    product: &str,
    version: &str,
) -> Result<Manifest, ErrorCode> {
    let Some(keys) = settings.release_keys.get(product) else {
        return Err(ErrorCode::ReleaseUnknown);
    };
    let bucket = bucket(env).map_err(|_| ErrorCode::UpstreamUnavailable)?;
    let text = read_text(&bucket, &manifest_key(product, version))
        .await
        .map_err(|_| ErrorCode::UpstreamUnavailable)?
        .ok_or(ErrorCode::ReleaseUnknown)?;
    let signature_text = read_text(&bucket, &signature_key(product, version))
        .await
        .map_err(|_| ErrorCode::UpstreamUnavailable)?
        .ok_or(ErrorCode::ReleaseUnknown)?;
    if let Err(refusal) = signature::verify(keys, text.as_bytes(), &signature_text) {
        crate::log::event(
            "alert",
            "releases.signature_refused",
            &[
                ("product", product.to_owned()),
                ("version", version.to_owned()),
                ("reason", refusal.to_string()),
            ],
        );
        return Err(ErrorCode::UpstreamUnavailable);
    }
    let manifest = Manifest::from_json(&text).map_err(|refusal| {
        crate::log::event(
            "alert",
            "releases.manifest_refused",
            &[("product", product.to_owned()), ("reason", refusal.to_string())],
        );
        ErrorCode::UpstreamUnavailable
    })?;
    if manifest.artifacts.is_none() {
        crate::log::event("alert", "releases.manifest_unmeasured", &[("product", product.to_owned())]);
        return Err(ErrorCode::UpstreamUnavailable);
    }
    Ok(manifest)
}

/// Blobs straight from the bucket, for the control plane's own installs.
pub struct BucketBlobs {
    /// The bucket.
    pub bucket: Bucket,
}

impl BlobSource for BucketBlobs {
    async fn fetch(&self, sha256: &str) -> Result<Vec<u8>, ApiError> {
        read_bytes(&self.bucket, &blob_key(sha256))
            .await
            .map_err(|_| ApiError::transport("the release store could not be read"))?
            .ok_or_else(|| ApiError::transport(format!("no blob {sha256}")))
    }
}
