//! The release index, and the public release store routes.
//!
//! One index object per product reads the bucket's layout into a list,
//! caches it for a minute, and answers which release is promoted. The
//! store routes serve manifests, signatures, and blobs as immutable
//! bytes, because their names are hashes or versions that never change
//! what they point at.

use deployer_api::{ErrorCode, ReleaseList, ReleaseView};
use serde::{Deserialize, Serialize};
use worker::{durable_object, DurableObject, Env, Headers, Request, Response, Result, State};

use crate::internal;
use crate::problem;
use crate::store;

// why: the durable_object attribute generates the runtime's entry methods
// without doc comments, and there is no place to document a macro's output.
#[allow(missing_docs)]
mod object {
    use super::*;

    /// The per-product index.
    #[durable_object]
    pub struct ReleaseIndex {
        state: State,
        env: Env,
    }

    impl DurableObject for ReleaseIndex {
        fn new(state: State, env: Env) -> Self {
            Self { state, env }
        }

        async fn fetch(&self, req: Request) -> Result<Response> {
            let url = req.url()?;
            let product = url
                .query_pairs()
                .find(|(key, _)| key == "product")
                .map(|(_, value)| value.into_owned())
                .unwrap_or_default();
            if product.is_empty() || req.path() != "/index" {
                return problem::response(ErrorCode::NotFound);
            }
            let list = self.index(&product).await?;
            problem::json(200, &list)
        }
    }

    impl ReleaseIndex {
        async fn index(&self, product: &str) -> Result<ReleaseList> {
            let now = worker::Date::now().as_millis();
            let cached: Option<Cached> = self.state.storage().get("index").await?;
            if let Some(cached) = cached {
                if cached.product == product && now.saturating_sub(cached.at_ms) < CACHE_MS {
                    return Ok(cached.list);
                }
            }
            let list = read_index(&self.env, product).await?;
            self.state
                .storage()
                .put(
                    "index",
                    &Cached {
                        product: product.to_owned(),
                        at_ms: now,
                        list: list.clone(),
                    },
                )
                .await?;
            Ok(list)
        }
    }
}

pub use object::ReleaseIndex;

/// How long an index answer stands before the bucket is read again.
const CACHE_MS: u64 = 60_000;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Cached {
    product: String,
    at_ms: u64,
    list: ReleaseList,
}

/// Read the index off the bucket.
async fn read_index(env: &Env, product: &str) -> Result<ReleaseList> {
    let bucket = store::bucket(env)?;
    let prefix = format!("releases/{product}/");
    let mut versions: Vec<String> = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let mut listing = bucket.list().prefix(prefix.clone()).delimiter("/");
        if let Some(next) = cursor.take() {
            listing = listing.cursor(next);
        }
        let page = listing.execute().await?;
        for delimited in page.delimited_prefixes() {
            if let Some(version) = delimited
                .strip_prefix(&prefix)
                .and_then(|rest| rest.strip_suffix('/'))
            {
                versions.push(version.to_owned());
            }
        }
        if page.truncated() {
            cursor = page.cursor();
        } else {
            break;
        }
    }
    let promoted = store::read_text(&bucket, &store::promoted_key(product))
        .await?
        .map(|text| text.trim().to_owned());
    let mut releases = Vec::new();
    for version in versions {
        let Some(head) = bucket.head(store::manifest_key(product, &version)).await? else {
            continue;
        };
        releases.push(ReleaseView {
            published_at_ms: head.uploaded().as_millis(),
            promoted: promoted.as_deref() == Some(version.as_str()),
            version,
        });
    }
    releases.sort_by(|a, b| {
        b.published_at_ms
            .cmp(&a.published_at_ms)
            .then_with(|| b.version.cmp(&a.version))
    });
    Ok(ReleaseList {
        product: product.to_owned(),
        releases,
    })
}

/// The index for a product, through its object.
pub async fn index(env: &Env, product: &str) -> Result<Option<ReleaseList>> {
    let stub = internal::release_index_stub(env, product)?;
    let response = internal::call(
        &stub,
        worker::Method::Get,
        &format!("/index?product={}", deployer_cloudflare::segment(product)),
        &[],
        None,
    )
    .await?;
    internal::json(response).await
}

/// The promoted release of a product, when one is.
pub async fn promoted(env: &Env, product: &str) -> Result<Option<ReleaseView>> {
    Ok(index(env, product)
        .await?
        .and_then(|list| list.releases.into_iter().find(|release| release.promoted)))
}

/// Serve a store path.
pub async fn serve(env: &Env, path: &str) -> Result<Response> {
    if let Some(hash) = path.strip_prefix("/blobs/") {
        if hash.is_empty() || hash.contains('/') {
            return problem::response(ErrorCode::NotFound);
        }
        return serve_object(env, &store::blob_key(hash), "application/octet-stream", true).await;
    }
    let Some(rest) = path.strip_prefix("/releases/") else {
        return problem::response(ErrorCode::NotFound);
    };
    let parts: Vec<&str> = rest.split('/').collect();
    match parts.as_slice() {
        [product, "index.json"] => match index(env, product).await? {
            Some(list) => problem::json(200, &list),
            None => problem::response(ErrorCode::NotFound),
        },
        [product, version, "manifest.json"] => {
            serve_object(env, &store::manifest_key(product, version), "application/json", true).await
        }
        [product, version, "manifest.sig"] => {
            serve_object(env, &store::signature_key(product, version), "text/plain", true).await
        }
        _ => problem::response(ErrorCode::NotFound),
    }
}

async fn serve_object(env: &Env, key: &str, content_type: &str, immutable: bool) -> Result<Response> {
    let bucket = store::bucket(env)?;
    let Some(bytes) = store::read_bytes(&bucket, key).await? else {
        return problem::response(ErrorCode::NotFound);
    };
    let headers = Headers::new();
    headers.set("content-type", content_type)?;
    headers.set(
        "cache-control",
        if immutable {
            "public, max-age=31536000, immutable"
        } else {
            "no-store"
        },
    )?;
    Ok(Response::from_bytes(bytes)?.with_headers(headers))
}
