//! Cloudflare sign-in and per-operation authorization, both authorization
//! code with PKCE.
//!
//! A sign-in asks for the identity scopes and yields a session. An
//! authorization asks for the write scopes on behalf of one account and
//! yields an access token the user's object holds until it expires or an
//! operation ends. Neither asks for `offline_access`, so nothing here can
//! be refreshed later.

use base64ct::{Base64UrlUnpadded, Encoding};
use deployer_api::ErrorCode;
use deployer_cloudflare::account;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use worker::{Env, Headers, Method, Request, Response, Result};

use crate::internal::{self, user_stub};
use crate::settings::{names, Settings};
use crate::{log, problem, rand, session};

/// How long a consent may take.
const STATE_TTL_SECONDS: u64 = 600;

/// What a consent is for.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
enum Pending {
    /// A sign-in.
    SignIn { verifier: String, return_to: String },
    /// An account authorization for a signed-in user.
    Authorize {
        verifier: String,
        return_to: String,
        user_id: String,
        account_id: String,
    },
}

fn state_key(state: &str) -> String {
    format!("oauth/{state}")
}

fn challenge(verifier: &str) -> String {
    Base64UrlUnpadded::encode_string(&Sha256::digest(verifier.as_bytes()))
}

fn return_path(req: &Request) -> String {
    let url = req.url().ok();
    let wanted = url
        .as_ref()
        .and_then(|url| {
            url.query_pairs()
                .find(|(key, _)| key == "return")
                .map(|(_, value)| value.into_owned())
        })
        .unwrap_or_default();
    // why: only a path on this origin, so a consent can never land a
    // person somewhere else.
    if wanted.starts_with('/') && !wanted.starts_with("//") {
        wanted
    } else {
        "/".to_owned()
    }
}

fn consent_url(settings: &Settings, scopes: &str, state: &str, verifier: &str) -> String {
    let encode = deployer_cloudflare::segment;
    format!(
        "{}/auth?response_type=code&client_id={}&redirect_uri={}&scope={}&state={}&code_challenge={}&code_challenge_method=S256",
        settings.oauth_base,
        encode(&settings.oauth_client_id),
        encode(&format!("{}/v1/auth/callback", settings.public_url)),
        encode(scopes),
        encode(state),
        encode(&challenge(verifier)),
    )
}

async fn remember(env: &Env, state: &str, pending: &Pending) -> Result<()> {
    env.kv(names::SESSIONS)?
        .put(&state_key(state), pending)?
        .expiration_ttl(STATE_TTL_SECONDS)
        .execute()
        .await?;
    Ok(())
}

/// Begin a sign-in: redirect to the consent page.
pub async fn start(env: &Env, req: &Request) -> Result<Response> {
    let settings = Settings::read(env)?;
    let state = rand::token();
    let verifier = rand::token();
    remember(
        env,
        &state,
        &Pending::SignIn {
            verifier: verifier.clone(),
            return_to: return_path(req),
        },
    )
    .await?;
    problem::redirect(&consent_url(
        &settings,
        &settings.identity_scopes,
        &state,
        &verifier,
    ))
}

/// Begin an account authorization for a signed-in user, answering the
/// consent URL for the client to send the browser to.
pub async fn authorize(
    env: &Env,
    settings: &Settings,
    user_id: &str,
    account_id: &str,
    return_to: String,
) -> Result<String> {
    let state = rand::token();
    let verifier = rand::token();
    remember(
        env,
        &state,
        &Pending::Authorize {
            verifier: verifier.clone(),
            return_to,
            user_id: user_id.to_owned(),
            account_id: account_id.to_owned(),
        },
    )
    .await?;
    Ok(consent_url(settings, &settings.write_scopes, &state, &verifier))
}

/// The consent's return.
pub async fn callback(env: &Env, req: &Request) -> Result<Response> {
    let settings = Settings::read(env)?;
    let url = req.url()?;
    let mut code = None;
    let mut state = None;
    for (key, value) in url.query_pairs() {
        match key.as_ref() {
            "code" => code = Some(value.into_owned()),
            "state" => state = Some(value.into_owned()),
            _ => {}
        }
    }
    let (Some(code), Some(state)) = (code, state) else {
        return problem::response(ErrorCode::MalformedBody);
    };
    // The state is consumed before the exchange: a replay finds nothing.
    let kv = env.kv(names::SESSIONS)?;
    let pending: Option<Pending> = kv.get(&state_key(&state)).json().await?;
    let Some(pending) = pending else {
        return problem::response(ErrorCode::MalformedBody);
    };
    kv.delete(&state_key(&state)).await?;
    let (verifier, return_to) = match &pending {
        Pending::SignIn {
            verifier,
            return_to,
        }
        | Pending::Authorize {
            verifier,
            return_to,
            ..
        } => (verifier.clone(), return_to.clone()),
    };
    let redirect_uri = format!("{}/v1/auth/callback", settings.public_url);
    let token = match account::exchange_code(
        &settings.oauth_base,
        &settings.oauth_client_id,
        &settings.oauth_client_secret,
        &code,
        &verifier,
        &redirect_uri,
    )
    .await
    {
        Ok(token) => token,
        Err(failure) => {
            log::event("warn", "oauth.exchange_failed", &[("status", failure.status.to_string())]);
            return problem::response(ErrorCode::UpstreamUnavailable);
        }
    };
    match pending {
        Pending::SignIn { .. } => sign_in(env, &settings, &token.access_token, &return_to).await,
        Pending::Authorize {
            user_id,
            account_id,
            ..
        } => {
            let expires_at_ms = worker::Date::now().as_millis()
                + token.expires_in.unwrap_or(3600).saturating_mul(1000);
            let body = serde_json::json!({
                "accountId": account_id,
                "token": token.access_token,
                "expiresAtMs": expires_at_ms,
            });
            internal::call(
                &user_stub(env, &user_id)?,
                Method::Put,
                "/authorizations",
                &[],
                Some(body.to_string()),
            )
            .await?;
            log::event("info", "oauth.authorized", &[("account", account_id)]);
            problem::redirect(&format!("{}{return_to}", settings.public_url))
        }
    }
}

/// Finish a sign-in: learn who this is, record their accounts, mint the
/// session.
async fn sign_in(env: &Env, settings: &Settings, access_token: &str, return_to: &str) -> Result<Response> {
    let user = match account::user(&settings.api_base, access_token).await {
        Ok(user) => user,
        Err(failure) => {
            log::event("warn", "oauth.user_unreadable", &[("status", failure.status.to_string())]);
            return problem::response(ErrorCode::UpstreamUnavailable);
        }
    };
    let accounts = account::accounts(&settings.api_base, access_token)
        .await
        .unwrap_or_default();
    let connected: Vec<serde_json::Value> = accounts
        .iter()
        .map(|account| serde_json::json!({ "id": account.id, "name": account.name }))
        .collect();
    let body = serde_json::json!({
        "userId": user.id,
        "email": user.email,
        "accounts": connected,
        "atMs": worker::Date::now().as_millis(),
    });
    internal::call(
        &user_stub(env, &user.id)?,
        Method::Post,
        "/connect",
        &[],
        Some(body.to_string()),
    )
    .await?;
    let cookie = session::create(
        env,
        &session::Session {
            user_id: user.id.clone(),
            email: user.email,
            created_at_ms: worker::Date::now().as_millis(),
        },
    )
    .await?;
    // The identity token is not kept: the session is the credential from
    // here on, and there is nothing to refresh it with.
    let _ = account::revoke_token(
        &settings.oauth_base,
        &settings.oauth_client_id,
        &settings.oauth_client_secret,
        access_token,
    )
    .await;
    log::event("info", "oauth.signed_in", &[("user", user.id)]);
    let headers = Headers::new();
    headers.set("location", &format!("{}{return_to}", settings.public_url))?;
    headers.set("set-cookie", &cookie)?;
    headers.set("cache-control", "no-store")?;
    Ok(Response::empty()?.with_status(302).with_headers(headers))
}
