//! One object per Cloudflare user: who they are, which accounts they
//! connected, which instances they own, and the account authorizations
//! they hold for operations in progress.
//!
//! An authorization is an access token with the write scopes for one
//! account. It lives here from the consent until it expires or the
//! operation that needed it ends, whichever is first, and an alarm purges
//! what expired. Nothing refreshes it.

use std::collections::BTreeMap;

use deployer_api::{AccountView, ErrorCode, Me};
use serde::{Deserialize, Serialize};
use worker::{durable_object, DurableObject, Env, Request, Response, Result, State};

use crate::problem;

/// An instance the user owns.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct InstanceRef {
    /// The instance id.
    pub id: String,
    /// The account it lives in.
    pub account_id: String,
}

/// A held authorization.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Authorization {
    /// The access token.
    pub token: String,
    /// When it expires, epoch milliseconds.
    pub expires_at_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Profile {
    user_id: String,
    email: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ConnectBody {
    user_id: String,
    email: String,
    accounts: Vec<AccountName>,
    at_ms: u64,
}

#[derive(Debug, Deserialize)]
struct AccountName {
    id: String,
    name: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct AuthorizationBody {
    account_id: String,
    token: String,
    expires_at_ms: u64,
}

const KEY_PROFILE: &str = "profile";
const KEY_ACCOUNTS: &str = "accounts";
const KEY_INSTANCES: &str = "instances";
const KEY_AUTHORIZATIONS: &str = "authorizations";

// why: the durable_object attribute generates the runtime's entry methods
// without doc comments, and there is no place to document a macro's output.
#[allow(missing_docs)]
mod object {
    use super::*;

    /// The object.
    #[durable_object]
    pub struct UserObject {
        state: State,
        #[allow(dead_code)]
        env: Env,
    }

    impl DurableObject for UserObject {
        fn new(state: State, env: Env) -> Self {
            Self { state, env }
        }

        async fn fetch(&self, mut req: Request) -> Result<Response> {
            let path = req.path();
            let method = req.method();
            match (method, path.as_str()) {
                (worker::Method::Post, "/connect") => {
                    let Ok(body) = req.json::<ConnectBody>().await else {
                        return problem::response(ErrorCode::MalformedBody);
                    };
                    self.connect(body).await
                }
                (worker::Method::Get, "/me") => self.me().await,
                (worker::Method::Get, "/instances") => {
                    problem::json(200, &self.instances().await?)
                }
                (worker::Method::Post, "/instances") => {
                    let Ok(body) = req.json::<InstanceRef>().await else {
                        return problem::response(ErrorCode::MalformedBody);
                    };
                    let mut list = self.instances().await?;
                    if !list.iter().any(|entry| entry.id == body.id) {
                        list.push(body);
                    }
                    self.state.storage().put(KEY_INSTANCES, &list).await?;
                    Response::empty().map(|response| response.with_status(204))
                }
                (worker::Method::Delete, path) if path.starts_with("/instances/") => {
                    let id = path.trim_start_matches("/instances/");
                    let mut list = self.instances().await?;
                    list.retain(|entry| entry.id != id);
                    self.state.storage().put(KEY_INSTANCES, &list).await?;
                    Response::empty().map(|response| response.with_status(204))
                }
                (worker::Method::Put, "/authorizations") => {
                    let Ok(body) = req.json::<AuthorizationBody>().await else {
                        return problem::response(ErrorCode::MalformedBody);
                    };
                    self.hold(body).await
                }
                (worker::Method::Get, path) if path.starts_with("/authorizations/") => {
                    let account = path.trim_start_matches("/authorizations/");
                    match self.authorization(account).await? {
                        Some(held) => problem::json(200, &held),
                        None => problem::response(ErrorCode::AuthorizationRequired),
                    }
                }
                (worker::Method::Delete, path) if path.starts_with("/authorizations/") => {
                    let account = path.trim_start_matches("/authorizations/");
                    let mut held = self.authorizations().await?;
                    held.remove(account);
                    self.state.storage().put(KEY_AUTHORIZATIONS, &held).await?;
                    Response::empty().map(|response| response.with_status(204))
                }
                _ => problem::response(ErrorCode::NotFound),
            }
        }

        async fn alarm(&self) -> Result<Response> {
            self.purge().await?;
            Response::empty()
        }
    }

    impl UserObject {
        async fn connect(&self, body: ConnectBody) -> Result<Response> {
            let storage = self.state.storage();
            storage
                .put(
                    KEY_PROFILE,
                    &Profile {
                        user_id: body.user_id,
                        email: body.email,
                    },
                )
                .await?;
            let mut accounts: Vec<AccountView> = storage.get(KEY_ACCOUNTS).await?.unwrap_or_default();
            for account in body.accounts {
                match accounts.iter_mut().find(|known| known.id == account.id) {
                    Some(known) => known.name = account.name,
                    None => accounts.push(AccountView {
                        id: account.id,
                        name: account.name,
                        connected_at_ms: body.at_ms,
                    }),
                }
            }
            storage.put(KEY_ACCOUNTS, &accounts).await?;
            Response::empty().map(|response| response.with_status(204))
        }

        async fn me(&self) -> Result<Response> {
            let storage = self.state.storage();
            let Some(profile) = storage.get::<Profile>(KEY_PROFILE).await? else {
                return problem::response(ErrorCode::Unauthorized);
            };
            let accounts: Vec<AccountView> = storage.get(KEY_ACCOUNTS).await?.unwrap_or_default();
            problem::json(
                200,
                &Me {
                    user_id: profile.user_id,
                    email: profile.email,
                    accounts,
                },
            )
        }

        pub(super) async fn instances(&self) -> Result<Vec<InstanceRef>> {
            Ok(self
                .state
                .storage()
                .get(KEY_INSTANCES)
                .await?
                .unwrap_or_default())
        }

        async fn authorizations(&self) -> Result<BTreeMap<String, Authorization>> {
            Ok(self
                .state
                .storage()
                .get(KEY_AUTHORIZATIONS)
                .await?
                .unwrap_or_default())
        }

        async fn authorization(&self, account: &str) -> Result<Option<Authorization>> {
            let now = worker::Date::now().as_millis();
            Ok(self
                .authorizations()
                .await?
                .remove(account)
                .filter(|held| held.expires_at_ms > now))
        }

        async fn hold(&self, body: AuthorizationBody) -> Result<Response> {
            let mut held = self.authorizations().await?;
            held.insert(
                body.account_id,
                Authorization {
                    token: body.token,
                    expires_at_ms: body.expires_at_ms,
                },
            );
            let storage = self.state.storage();
            storage.put(KEY_AUTHORIZATIONS, &held).await?;
            // The alarm purges what expired, so a token never outlives its
            // own lifetime here even if no operation ever ends.
            let now = worker::Date::now().as_millis();
            let soonest = held
                .values()
                .map(|held| held.expires_at_ms)
                .min()
                .unwrap_or(now);
            storage
                .set_alarm(std::time::Duration::from_millis(
                    soonest.saturating_sub(now).max(1_000),
                ))
                .await?;
            Response::empty().map(|response| response.with_status(204))
        }

        async fn purge(&self) -> Result<()> {
            let now = worker::Date::now().as_millis();
            let mut held = self.authorizations().await?;
            held.retain(|_, authorization| authorization.expires_at_ms > now);
            self.state.storage().put(KEY_AUTHORIZATIONS, &held).await?;
            Ok(())
        }
    }
}

