//! One object per instance: its record, its desired state, what the agent
//! last said, the operation log, and the browsers watching it.
//!
//! The object is also where the control plane acts inside a customer's
//! account, twice in an instance's life: installing the agent, and
//! removing it. Both run under an access token the person authorized
//! minutes before. For provisioning the token arrives with the request and
//! leaves with it. For a teardown the token is held here until the agent
//! reports the worker gone, because removing the agent before that would
//! strand the teardown; an alarm drops it at its expiry either way.

use std::cell::RefCell;
use std::collections::BTreeMap;

use deployer_api::agent::{self as agent_product, names as agent_names};
use deployer_api::{
    AgentDesired, AgentEvents, AgentRelease, AgentStatus, AutoUpdate, CreateInstance,
    DesiredPatch, DesiredState, DesiredUpdated, ErrorCode, EventPage, GrantIssued, GrantPurpose,
    GrantRequest, InstanceCreated, InstanceDetail, InstanceStatus, InstanceSummary, LoggedEvent,
    OperationList, OperationOutcome, OperationSummary, PatchPreview, PlanTier, Provisioned,
    RouteRequest, UninstallBody, UninstallRequest, UninstallStarted,
};
use deployer_cloudflare::account;
use deployer_cloudflare::CloudflareClient;
use deployer_engine::api::CloudflareApi as _;
use deployer_engine::apply::{self, Failure, Step, Target};
use deployer_engine::diff::diff;
use deployer_engine::grant::{self, Grant, Purpose};
use deployer_engine::plan::{plan, PlanError};
use deployer_engine::render::Secrets;
use deployer_engine::spec::{resource_name, InstanceSpec, Route};
use deployer_engine::{Event, EventKind, Operation};
use deployer_manifest::Manifest;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use worker::{
    durable_object, DurableObject, Env, Method, Request, Response, Result, State,
    WebSocketPair,
};

use crate::internal::{header, TOKEN_HEADER, USER_HEADER};
use crate::settings::Settings;
use crate::{log, problem, rand, releases, store};

/// The record.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Record {
    id: String,
    owner_user_id: String,
    product: String,
    name: String,
    account_id: String,
    account_name: String,
    host: String,
    agent_resource_name: String,
    agent_url: Option<String>,
    agent_key_hash: Option<String>,
    agent_token_id: Option<String>,
    status: InstanceStatus,
    created_at_ms: u64,
    updated_at_ms: u64,
    held_token: Option<HeldToken>,
    cleanup_pending: bool,
}

/// An access token held for a teardown.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct HeldToken {
    token: String,
    expires_at_ms: u64,
}

/// What the worker sends to make the record.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CreateBody {
    /// The new id.
    pub id: String,
    /// The owner.
    pub owner_user_id: String,
    /// The account's name.
    pub account_name: String,
    /// The release, resolved.
    pub version: String,
    /// The client's request.
    pub request: CreateInstance,
}

const KEY_RECORD: &str = "record";
const KEY_DESIRED: &str = "desired";
const KEY_AGENT_STATUS: &str = "agent_status";
const KEY_OPERATIONS: &str = "operations";
const KEY_EVENTS: &str = "events";
const KEY_SEQ: &str = "seq";

/// How many events the log keeps.
const EVENT_CAP: usize = 5_000;
/// How long a grant lives.
const GRANT_MS: u64 = 10 * 60_000;
/// How long a teardown may hold its token.
const HELD_TOKEN_MS: u64 = 50 * 60_000;
/// How often an instance with auto-update on looks at the index.
const AUTO_UPDATE_TICK_MS: u64 = 3_600_000;

fn now_ms() -> u64 {
    worker::Date::now().as_millis()
}

fn sha256_hex(text: &str) -> String {
    deployer_engine::apply::sha256_hex(text.as_bytes())
}

// why: the durable_object attribute generates the runtime's entry methods
// without doc comments, and there is no place to document a macro's output.
#[allow(missing_docs)]
mod object {
    use super::*;

    /// The object.
    #[durable_object]
    pub struct InstanceObject {
        state: State,
        env: Env,
    }

    impl DurableObject for InstanceObject {
        fn new(state: State, env: Env) -> Self {
            Self { state, env }
        }

        async fn fetch(&self, mut req: Request) -> Result<Response> {
            let path = req.path();
            let method = req.method();
            if path.starts_with("/agent/") {
                return self.agent_route(req).await;
            }
            if path == "/create" && method == Method::Post {
                let Ok(body) = req.json::<CreateBody>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                return self.create(body).await;
            }
            let Some(record) = self.record().await? else {
                return problem::response(ErrorCode::NotFound);
            };
            if header(&req, USER_HEADER).as_deref() != Some(record.owner_user_id.as_str()) {
                return problem::response(ErrorCode::Forbidden);
            }
            match (method, path.as_str()) {
                (Method::Get, "/summary") => problem::json(200, &self.summary(&record).await?),
                (Method::Get, "/detail") => self.detail(record).await,
                (Method::Post, "/provision") => self.provision(record, &req).await,
                (Method::Post, "/desired") => self.desired_patch(record, req).await,
                (Method::Post, "/grants") => self.grants(record, req).await,
                (Method::Post, "/uninstall") => self.uninstall(record, req).await,
                (Method::Get, "/operations") => problem::json(
                    200,
                    &OperationList {
                        operations: self.operations().await?.into_iter().rev().collect(),
                    },
                ),
                (Method::Get, "/events") => self.events(&req).await,
                _ => problem::response(ErrorCode::NotFound),
            }
        }

        async fn alarm(&self) -> Result<Response> {
            self.tick().await?;
            Response::empty()
        }

        async fn websocket_message(
            &self,
            _ws: worker::WebSocket,
            _message: worker::WebSocketIncomingMessage,
        ) -> Result<()> {
            // The stream is one way; a client that speaks is ignored.
            Ok(())
        }

        async fn websocket_close(
            &self,
            _ws: worker::WebSocket,
            _code: usize,
            _reason: String,
            _was_clean: bool,
        ) -> Result<()> {
            Ok(())
        }

        async fn websocket_error(&self, _ws: worker::WebSocket, _error: worker::Error) -> Result<()> {
            Ok(())
        }
    }
}

pub use object::InstanceObject;

impl InstanceObject {
    async fn record(&self) -> Result<Option<Record>> {
        self.state.storage().get(KEY_RECORD).await
    }

    async fn save_record(&self, record: &mut Record) -> Result<()> {
        record.updated_at_ms = now_ms();
        self.state.storage().put(KEY_RECORD, &*record).await
    }

    async fn desired(&self) -> Result<Option<DesiredState>> {
        self.state.storage().get(KEY_DESIRED).await
    }

    async fn agent_status(&self) -> Result<Option<AgentStatus>> {
        self.state.storage().get(KEY_AGENT_STATUS).await
    }

    async fn operations(&self) -> Result<Vec<OperationSummary>> {
        Ok(self
            .state
            .storage()
            .get(KEY_OPERATIONS)
            .await?
            .unwrap_or_default())
    }

    async fn begin_operation(&self, operation: Operation, revision: u64) -> Result<String> {
        let mut operations = self.operations().await?;
        let id = format!("op-{}", operations.len() + 1);
        operations.push(OperationSummary {
            id: id.clone(),
            operation,
            revision,
            started_at_ms: now_ms(),
            finished_at_ms: None,
            outcome: OperationOutcome::Running,
        });
        self.state.storage().put(KEY_OPERATIONS, &operations).await?;
        Ok(id)
    }

    async fn finish_operation(&self, id: &str, outcome: OperationOutcome) -> Result<Option<Operation>> {
        let mut operations = self.operations().await?;
        let mut kind = None;
        if let Some(entry) = operations.iter_mut().find(|entry| entry.id == id) {
            entry.finished_at_ms = Some(now_ms());
            entry.outcome = outcome;
            kind = Some(entry.operation);
        }
        self.state.storage().put(KEY_OPERATIONS, &operations).await?;
        Ok(kind)
    }

    /// Record events and send each to every watching browser.
    async fn append_events(&self, operation_id: &str, events: Vec<Event>) -> Result<()> {
        if events.is_empty() {
            return Ok(());
        }
        let storage = self.state.storage();
        let mut seq: u64 = storage.get(KEY_SEQ).await?.unwrap_or(0);
        let mut log: Vec<LoggedEvent> = storage.get(KEY_EVENTS).await?.unwrap_or_default();
        let sockets = self.state.get_websockets();
        for event in events {
            seq += 1;
            let logged = LoggedEvent {
                operation_id: operation_id.to_owned(),
                seq,
                at_ms: now_ms(),
                event,
            };
            for socket in &sockets {
                let _ = socket.send(&logged);
            }
            log.push(logged);
        }
        if log.len() > EVENT_CAP {
            let excess = log.len() - EVENT_CAP;
            log.drain(..excess);
        }
        storage.put(KEY_EVENTS, &log).await?;
        storage.put(KEY_SEQ, seq).await
    }

    fn product_spec(record: &Record, desired: &DesiredState) -> InstanceSpec {
        InstanceSpec {
            id: record.id.clone(),
            name: record.name.clone(),
            account_id: record.account_id.clone(),
            resource_name: None,
            host: record.host.clone(),
            route: desired.route.clone(),
            vars: desired.vars.clone(),
        }
    }

    /// The agent's own instance: named for what it deploys, tagged as its
    /// own product.
    fn agent_spec(settings: &Settings, record: &Record, host: &str) -> InstanceSpec {
        let mut keys: Vec<String> = settings
            .release_keys
            .get(&record.product)
            .cloned()
            .unwrap_or_default();
        keys.extend(
            settings
                .release_keys
                .get(agent_product::PRODUCT)
                .cloned()
                .unwrap_or_default(),
        );
        keys.dedup();
        let mut vars = BTreeMap::from([
            (
                agent_names::CONTROL_PLANE_URL.to_owned(),
                settings.public_url.clone(),
            ),
            (agent_names::INSTANCE_ID.to_owned(), record.id.clone()),
            (
                agent_names::CONTROL_PLANE_PUBLIC_KEY.to_owned(),
                settings.public_key(),
            ),
            (agent_names::RELEASE_PUBLIC_KEYS.to_owned(), keys.join(",")),
        ]);
        if let Some(base) = settings.api_base_override() {
            vars.insert(agent_names::CF_API_BASE_URL.to_owned(), base);
        }
        InstanceSpec {
            id: format!("{}-agent", record.id),
            name: record.name.clone(),
            account_id: record.account_id.clone(),
            resource_name: Some(record.agent_resource_name.clone()),
            host: host.to_owned(),
            route: Route::WorkersDev,
            vars,
        }
    }

    async fn summary(&self, record: &Record) -> Result<InstanceSummary> {
        let desired = self.desired().await?;
        let agent = self.agent_status().await?;
        Ok(InstanceSummary {
            id: record.id.clone(),
            product: record.product.clone(),
            name: record.name.clone(),
            host: record.host.clone(),
            account_id: record.account_id.clone(),
            account_name: record.account_name.clone(),
            installed_version: agent.and_then(|status| status.installed_version),
            desired_version: desired.map(|desired| desired.version).unwrap_or_default(),
            status: record.status,
            plan: PlanTier::Free,
            updated_at_ms: record.updated_at_ms,
        })
    }

    async fn detail(&self, record: Record) -> Result<Response> {
        let summary = self.summary(&record).await?;
        let Some(desired) = self.desired().await? else {
            return problem::response(ErrorCode::NotFound);
        };
        let promoted = releases::promoted(&self.env, &record.product)
            .await
            .ok()
            .flatten();
        let update_available = promoted
            .filter(|release| release.version != desired.version)
            .map(|release| release.version);
        let detail = InstanceDetail {
            summary,
            desired,
            agent: self.agent_status().await?,
            agent_url: record.agent_url.clone(),
            operations: self.operations().await?.into_iter().rev().collect(),
            authorization_required: record.cleanup_pending && record.held_token.is_none(),
            update_available,
        };
        problem::json(200, &detail)
    }

    async fn create(&self, body: CreateBody) -> Result<Response> {
        if self.record().await?.is_some() {
            return problem::response(ErrorCode::Conflict);
        }
        let settings = Settings::read(&self.env)?;
        let request = body.request;
        let (route, host) = match request.route {
            RouteRequest::CustomDomain { hostname, zone_id } => (
                Route::CustomDomain {
                    hostname: hostname.clone(),
                    zone_id,
                },
                hostname,
            ),
            // The workers.dev host is known once the account's subdomain
            // is read, which takes the authorization provisioning has.
            RouteRequest::WorkersDev => (Route::WorkersDev, String::new()),
        };
        let now = now_ms();
        let mut record = Record {
            id: body.id.clone(),
            owner_user_id: body.owner_user_id,
            product: request.product.clone(),
            name: request.name.clone(),
            account_id: request.account_id,
            account_name: body.account_name,
            host,
            agent_resource_name: format!("{}-deployment-{}", request.product, request.name),
            agent_url: None,
            agent_key_hash: None,
            agent_token_id: None,
            status: InstanceStatus::Created,
            created_at_ms: now,
            updated_at_ms: now,
            held_token: None,
            cleanup_pending: false,
        };
        let desired = DesiredState {
            revision: 1,
            product: request.product.clone(),
            version: body.version.clone(),
            vars: request.vars,
            route,
            generated_public: request.generated_public,
            auto_update: request.auto_update,
            uninstall: None,
        };
        let manifest = match store::manifest(&self.env, &settings, &request.product, &body.version).await {
            Ok(manifest) => manifest,
            Err(code) => return problem::response(code),
        };
        let spec = Self::product_spec(&record, &desired);
        let built = match plan(&manifest, &spec, &desired.generated_public) {
            Ok(built) => built,
            Err(PlanError::BadName) => return problem::response(ErrorCode::BadName),
            Err(failure) => {
                log::event("info", "instance.plan_refused", &[("reason", failure.to_string())]);
                return problem::response(ErrorCode::MalformedBody);
            }
        };
        self.save_record(&mut record).await?;
        self.state.storage().put(KEY_DESIRED, &desired).await?;
        if desired.auto_update.enabled {
            self.schedule_tick().await?;
        }
        log::event(
            "info",
            "instance.created",
            &[("instance", record.id.clone()), ("product", record.product.clone())],
        );
        problem::json(
            201,
            &InstanceCreated {
                id: body.id,
                plan: built,
            },
        )
    }

    fn issue_grant(
        settings: &Settings,
        record: &Record,
        purpose: Purpose,
        secret_names: Vec<String>,
    ) -> GrantIssued {
        let now = now_ms();
        let grant = Grant {
            instance_id: record.id.clone(),
            purpose,
            secret_names,
            issued_at_ms: now,
            expires_at_ms: now + GRANT_MS,
            nonce: rand::id(),
        };
        GrantIssued {
            grant: grant::issue(&settings.signing_seed, &grant),
            agent_url: record.agent_url.clone().unwrap_or_default(),
            expires_at_ms: now + GRANT_MS,
        }
    }

    /// Ask the agent to reconcile now rather than at its next tick.
    async fn nudge(&self, settings: &Settings, record: &Record) {
        let Some(agent_url) = &record.agent_url else {
            return;
        };
        let issued = Self::issue_grant(settings, record, Purpose::Reconcile, Vec::new());
        let body = serde_json::json!({ "grant": issued.grant }).to_string();
        if let Err(failure) = deployer_cloudflare::send(
            None,
            Method::Post,
            &format!("{agent_url}/reconcile"),
            Some(deployer_cloudflare::Body::Json(body)),
        )
        .await
        {
            log::event("warn", "instance.nudge_failed", &[("reason", failure.message)]);
        }
    }

    async fn schedule_tick(&self) -> Result<()> {
        self.state
            .storage()
            .set_alarm(std::time::Duration::from_millis(AUTO_UPDATE_TICK_MS))
            .await
    }
}

/// Provisioning: everything the control plane does inside the account
/// under the person's authorization.
struct Provisioning<'a> {
    settings: &'a Settings,
    client: &'a CloudflareClient,
    token: &'a str,
    desired: &'a DesiredState,
    product_manifest: &'a Manifest,
    agent_manifest: &'a Manifest,
    operation_id: &'a str,
}

impl InstanceObject {
    async fn provision(&self, mut record: Record, req: &Request) -> Result<Response> {
        let Some(token) = header(req, TOKEN_HEADER) else {
            return problem::response(ErrorCode::AuthorizationRequired);
        };
        match record.status {
            InstanceStatus::Provisioning | InstanceStatus::Applying | InstanceStatus::Uninstalling => {
                return problem::response(ErrorCode::OperationRunning)
            }
            InstanceStatus::Uninstalled | InstanceStatus::Ready => {
                return problem::response(ErrorCode::Conflict)
            }
            _ => {}
        }
        let settings = Settings::read(&self.env)?;
        let Some(desired) = self.desired().await? else {
            return problem::response(ErrorCode::Conflict);
        };
        let product_manifest =
            match store::manifest(&self.env, &settings, &record.product, &desired.version).await {
                Ok(manifest) => manifest,
                Err(code) => return problem::response(code),
            };
        let Some(agent_release) = releases::promoted(&self.env, agent_product::PRODUCT).await? else {
            log::event("alert", "instance.no_agent_release", &[]);
            return problem::response(ErrorCode::UpstreamUnavailable);
        };
        let agent_manifest = match store::manifest(
            &self.env,
            &settings,
            agent_product::PRODUCT,
            &agent_release.version,
        )
        .await
        {
            Ok(manifest) => manifest,
            Err(code) => return problem::response(code),
        };
        record.status = InstanceStatus::Provisioning;
        self.save_record(&mut record).await?;
        let operation_id = self.begin_operation(Operation::Install, desired.revision).await?;
        let client = CloudflareClient::new(&settings.api_base, &token);
        let job = Provisioning {
            settings: &settings,
            client: &client,
            token: &token,
            desired: &desired,
            product_manifest: &product_manifest,
            agent_manifest: &agent_manifest,
            operation_id: &operation_id,
        };
        match self.install_agent(&job, &mut record).await {
            Ok(agent_host) => {
                record.agent_url = Some(format!("https://{agent_host}"));
                record.status = InstanceStatus::Applying;
                self.save_record(&mut record).await?;
                self.finish_operation(&operation_id, OperationOutcome::Succeeded).await?;
                let names = product_manifest
                    .secrets
                    .iter()
                    .map(|secret| secret.name.clone())
                    .collect();
                let secrets_grant = Self::issue_grant(&settings, &record, Purpose::Secrets, names);
                log::event("info", "instance.provisioned", &[("instance", record.id.clone())]);
                problem::json(
                    202,
                    &Provisioned {
                        operation_id,
                        agent_url: record.agent_url.clone().unwrap_or_default(),
                        secrets_grant,
                    },
                )
            }
            Err(event) => {
                record.status = InstanceStatus::Failed;
                self.save_record(&mut record).await?;
                self.append_events(&operation_id, vec![event]).await?;
                self.finish_operation(&operation_id, OperationOutcome::Failed).await?;
                problem::response(ErrorCode::UpstreamUnavailable)
            }
        }
    }

    /// Read the subdomain, mint the token, install the agent. Answers the
    /// agent's host, or the event that says which step failed and why.
    async fn install_agent(&self, job: &Provisioning<'_>, record: &mut Record) -> std::result::Result<String, Event> {
        let failed = |step: Step, failure: Failure| Event {
            seq: 0,
            operation: Operation::Install,
            step,
            kind: EventKind::Failed {
                remedy: failure.remedy(),
            },
            detail: failure.to_string(),
        };
        let subdomain = match job.client.get_subdomain(&record.account_id).await {
            Ok(Some(subdomain)) => subdomain,
            Ok(None) => return Err(failed(Step::Preflight, Failure::NoSubdomain)),
            Err(error) => return Err(failed(Step::Preflight, Failure::Api(error))),
        };
        if record.host.is_empty() {
            record.host = format!(
                "{}.{subdomain}.workers.dev",
                resource_name(&record.product, &record.name)
            );
        }
        let agent_host = format!("{}.{subdomain}.workers.dev", record.agent_resource_name);
        let minted = self
            .mint_agent_token(job, record)
            .await
            .map_err(|failure| failed(Step::Preflight, failure))?;
        record.agent_token_id = Some(minted.id);
        let agent_key = rand::token();
        record.agent_key_hash = Some(sha256_hex(&agent_key));
        let _ = self.save_record(record).await;
        let spec = Self::agent_spec(job.settings, record, &agent_host);
        let built = plan(job.agent_manifest, &spec, &BTreeMap::new())
            .map_err(|failure| failed(Step::Worker, Failure::Render(failure.to_string())))?;
        let secrets = BTreeMap::from([
            (agent_names::AGENT_TOKEN.to_owned(), minted.value),
            (agent_names::AGENT_KEY.to_owned(), agent_key),
        ]);
        let blobs = store::BucketBlobs {
            bucket: store::bucket(&self.env).map_err(|_| {
                failed(
                    Step::Worker,
                    Failure::Render("the release store is unbound".to_owned()),
                )
            })?,
        };
        let collected: RefCell<Vec<Event>> = RefCell::new(Vec::new());
        let result = {
            let mut sink = |event: Event| collected.borrow_mut().push(event);
            apply::converge(
                job.client,
                &blobs,
                Operation::Install,
                Target {
                    manifest: job.agent_manifest,
                    spec: &spec,
                    plan: &built,
                },
                Secrets::Values(&secrets),
                &mut sink,
            )
            .await
        };
        let _ = self
            .append_events(job.operation_id, collected.into_inner())
            .await;
        // The product manifest is what the person's secrets are for; the
        // agent's install is done, so the grant can name them.
        let _ = job.product_manifest;
        match result {
            Ok(()) => Ok(agent_host),
            // The failed step's event is already in the log; a second copy
            // would double it.
            Err(error) => Err(Event {
                seq: 0,
                operation: Operation::Install,
                step: error.step,
                kind: EventKind::Unchanged,
                detail: "see the step above".to_owned(),
            }),
        }
    }

    /// Mint the account-owned token the agent runs under.
    async fn mint_agent_token(
        &self,
        job: &Provisioning<'_>,
        record: &Record,
    ) -> std::result::Result<account::MintedToken, Failure> {
        let groups = account::permission_groups(&job.settings.api_base, job.token, &record.account_id)
            .await
            .map_err(Failure::Api)?;
        let find = |wanted: &str| {
            groups
                .iter()
                .find(|group| group.name.eq_ignore_ascii_case(wanted))
                .map(|group| group.id.clone())
                .ok_or_else(|| {
                    Failure::Render(format!(
                        "the Cloudflare API offers no permission group named {wanted}"
                    ))
                })
        };
        let account_groups = job
            .settings
            .token_permissions
            .account
            .iter()
            .map(|name| find(name))
            .collect::<std::result::Result<Vec<_>, _>>()?;
        let zone = match &job.desired.route {
            Route::CustomDomain { zone_id, .. } => {
                let ids = job
                    .settings
                    .token_permissions
                    .zone
                    .iter()
                    .map(|name| find(name))
                    .collect::<std::result::Result<Vec<_>, _>>()?;
                Some((zone_id.clone(), ids))
            }
            Route::WorkersDev => None,
        };
        account::mint_account_token(
            &job.settings.api_base,
            job.token,
            &record.account_id,
            &format!("deployer agent {}", record.agent_resource_name),
            &account_groups,
            zone.as_ref().map(|(id, ids)| (id.as_str(), ids.as_slice())),
        )
        .await
        .map_err(Failure::Api)
    }
}

impl InstanceObject {
    async fn desired_patch(&self, mut record: Record, mut req: Request) -> Result<Response> {
        let dry_run = req
            .url()?
            .query_pairs()
            .any(|(key, value)| key == "dryRun" && value == "true");
        let Ok(patch) = req.json::<DesiredPatch>().await else {
            return problem::response(ErrorCode::MalformedBody);
        };
        let settings = Settings::read(&self.env)?;
        let Some(mut desired) = self.desired().await? else {
            return problem::response(ErrorCode::Conflict);
        };
        if !dry_run {
            match record.status {
                InstanceStatus::Provisioning | InstanceStatus::Uninstalling => {
                    return problem::response(ErrorCode::OperationRunning)
                }
                InstanceStatus::Uninstalled => return problem::response(ErrorCode::Conflict),
                _ => {}
            }
        }
        let installed = match store::manifest(&self.env, &settings, &record.product, &desired.version).await {
            Ok(manifest) => manifest,
            Err(code) => return problem::response(code),
        };
        if let Some(version) = patch.version {
            desired.version = version;
        }
        if let Some(vars) = patch.vars {
            for (name, value) in vars {
                if value.is_empty() {
                    desired.vars.remove(&name);
                } else {
                    desired.vars.insert(name, value);
                }
            }
        }
        if let Some(auto_update) = patch.auto_update {
            desired.auto_update = auto_update;
        }
        let target = if desired.version == installed.version {
            installed.clone()
        } else {
            match store::manifest(&self.env, &settings, &record.product, &desired.version).await {
                Ok(manifest) => manifest,
                Err(code) => return problem::response(code),
            }
        };
        let spec = Self::product_spec(&record, &desired);
        let built = match plan(&target, &spec, &desired.generated_public) {
            Ok(built) => built,
            Err(failure) => {
                log::event("info", "instance.plan_refused", &[("reason", failure.to_string())]);
                return problem::response(ErrorCode::MalformedBody);
            }
        };
        let changes = diff(&installed, &target);
        if dry_run {
            return problem::json(
                200,
                &PatchPreview {
                    secrets_needed: changes.secrets_added.clone(),
                    desired,
                    diff: changes,
                    plan: built,
                },
            );
        }
        desired.revision += 1;
        self.state.storage().put(KEY_DESIRED, &desired).await?;
        let operation = if target.version == installed.version {
            Operation::Configure
        } else {
            Operation::Update
        };
        let operation_id = self.begin_operation(operation, desired.revision).await?;
        record.status = InstanceStatus::Applying;
        self.save_record(&mut record).await?;
        self.nudge(&settings, &record).await;
        if desired.auto_update.enabled {
            self.schedule_tick().await?;
        }
        problem::json(
            202,
            &DesiredUpdated {
                desired,
                operation_id,
            },
        )
    }

    async fn grants(&self, record: Record, mut req: Request) -> Result<Response> {
        let Ok(body) = req.json::<GrantRequest>().await else {
            return problem::response(ErrorCode::MalformedBody);
        };
        if record.agent_url.is_none() {
            return problem::response(ErrorCode::Conflict);
        }
        let settings = Settings::read(&self.env)?;
        let purpose = match body.purpose {
            GrantPurpose::Secrets => {
                let Some(desired) = self.desired().await? else {
                    return problem::response(ErrorCode::Conflict);
                };
                let manifest =
                    match store::manifest(&self.env, &settings, &record.product, &desired.version).await {
                        Ok(manifest) => manifest,
                        Err(code) => return problem::response(code),
                    };
                if body
                    .secret_names
                    .iter()
                    .any(|name| !manifest.secrets.iter().any(|secret| &secret.name == name))
                {
                    return problem::response(ErrorCode::MalformedBody);
                }
                Purpose::Secrets
            }
            GrantPurpose::DeleteBucket => Purpose::DeleteBucket,
        };
        problem::json(
            200,
            &Self::issue_grant(&settings, &record, purpose, body.secret_names),
        )
    }

    async fn uninstall(&self, mut record: Record, mut req: Request) -> Result<Response> {
        let Some(token) = header(&req, TOKEN_HEADER) else {
            return problem::response(ErrorCode::AuthorizationRequired);
        };
        let Ok(body) = req.json::<UninstallBody>().await else {
            return problem::response(ErrorCode::MalformedBody);
        };
        if record.status == InstanceStatus::Uninstalled {
            return problem::response(ErrorCode::Conflict);
        }
        let settings = Settings::read(&self.env)?;
        let Some(mut desired) = self.desired().await? else {
            return problem::response(ErrorCode::Conflict);
        };
        let now = now_ms();
        record.held_token = Some(HeldToken {
            token,
            expires_at_ms: now + HELD_TOKEN_MS,
        });
        // The agent already tore the worker down and only the cleanup this
        // token allows is left.
        let agent_done = self
            .agent_status()
            .await?
            .is_some_and(|status| status.revision_applied == Some(desired.revision));
        if record.cleanup_pending && desired.uninstall.is_some() && agent_done {
            self.cleanup(&settings, &mut record).await;
            self.save_record(&mut record).await?;
            let last = self.operations().await?.last().map(|op| op.id.clone());
            return problem::json(
                202,
                &UninstallStarted {
                    operation_id: last.unwrap_or_default(),
                    delete_bucket_grant: None,
                },
            );
        }
        desired.uninstall = Some(UninstallRequest {
            delete_bucket: body.delete_bucket,
        });
        desired.revision += 1;
        self.state.storage().put(KEY_DESIRED, &desired).await?;
        let operation_id = self.begin_operation(Operation::Uninstall, desired.revision).await?;
        record.status = InstanceStatus::Uninstalling;
        record.cleanup_pending = true;
        self.save_record(&mut record).await?;
        self.state
            .storage()
            .set_alarm(std::time::Duration::from_millis(HELD_TOKEN_MS))
            .await?;
        self.nudge(&settings, &record).await;
        let delete_bucket_grant = body
            .delete_bucket
            .then(|| Self::issue_grant(&settings, &record, Purpose::DeleteBucket, Vec::new()));
        problem::json(
            202,
            &UninstallStarted {
                operation_id,
                delete_bucket_grant,
            },
        )
    }

    /// Remove the agent and its token, under the held authorization.
    async fn cleanup(&self, settings: &Settings, record: &mut Record) {
        let Some(held) = record.held_token.take() else {
            record.cleanup_pending = true;
            return;
        };
        if held.expires_at_ms <= now_ms() {
            record.cleanup_pending = true;
            return;
        }
        let client = CloudflareClient::new(&settings.api_base, &held.token);
        let _ = client
            .set_workers_dev(&record.account_id, &record.agent_resource_name, false)
            .await;
        if let Err(error) = client
            .delete_script(&record.account_id, &record.agent_resource_name)
            .await
        {
            if !error.is_not_found() {
                log::event("warn", "instance.agent_delete_failed", &[("reason", error.message)]);
            }
        }
        if let Some(token_id) = record.agent_token_id.take() {
            if let Err(error) = account::delete_account_token(
                &settings.api_base,
                &held.token,
                &record.account_id,
                &token_id,
            )
            .await
            {
                log::event("warn", "instance.token_delete_failed", &[("reason", error.message)]);
            }
        }
        let _ = account::revoke_token(
            &settings.oauth_base,
            &settings.oauth_client_id,
            &settings.oauth_client_secret,
            &held.token,
        )
        .await;
        record.cleanup_pending = false;
        record.status = InstanceStatus::Uninstalled;
        record.agent_url = None;
        record.agent_key_hash = None;
        log::event("info", "instance.uninstalled", &[("instance", record.id.clone())]);
    }

    async fn events(&self, req: &Request) -> Result<Response> {
        let since: u64 = req
            .url()?
            .query_pairs()
            .find(|(key, _)| key == "since")
            .and_then(|(_, value)| value.parse().ok())
            .unwrap_or(0);
        let storage = self.state.storage();
        let log: Vec<LoggedEvent> = storage.get(KEY_EVENTS).await?.unwrap_or_default();
        let latest_seq: u64 = storage.get(KEY_SEQ).await?.unwrap_or(0);
        let events: Vec<LoggedEvent> = log.into_iter().filter(|event| event.seq > since).collect();
        let wants_socket = header(req, "upgrade")
            .is_some_and(|value| value.eq_ignore_ascii_case("websocket"));
        if wants_socket {
            let pair = WebSocketPair::new()?;
            // why hibernation: a browser may watch for an hour while nothing
            // happens; accepting through the state lets the object sleep and
            // still deliver the next event.
            self.state.accept_web_socket(&pair.server);
            for event in &events {
                pair.server.send(event)?;
            }
            return Response::from_websocket(pair.client);
        }
        problem::json(200, &EventPage { events, latest_seq })
    }

    /// The alarm: drop an expired held token, and apply a promoted release
    /// to an instance that asked for updates on its own.
    async fn tick(&self) -> Result<()> {
        let Some(mut record) = self.record().await? else {
            return Ok(());
        };
        let now = now_ms();
        if record
            .held_token
            .as_ref()
            .is_some_and(|held| held.expires_at_ms <= now)
        {
            record.held_token = None;
            self.save_record(&mut record).await?;
        }
        let Some(mut desired) = self.desired().await? else {
            return Ok(());
        };
        let policy: &AutoUpdate = &desired.auto_update;
        if !policy.enabled || policy.hold || desired.uninstall.is_some() {
            return Ok(());
        }
        if record.status == InstanceStatus::Ready {
            if let Some(promoted) = releases::promoted(&self.env, &record.product).await? {
                let aged = promoted.published_at_ms + u64::from(policy.delay_hours) * 3_600_000 <= now;
                if promoted.version != desired.version && aged {
                    let settings = Settings::read(&self.env)?;
                    if store::manifest(&self.env, &settings, &record.product, &promoted.version)
                        .await
                        .is_ok()
                    {
                        desired.version = promoted.version.clone();
                        desired.revision += 1;
                        self.state.storage().put(KEY_DESIRED, &desired).await?;
                        self.begin_operation(Operation::Update, desired.revision).await?;
                        record.status = InstanceStatus::Applying;
                        self.save_record(&mut record).await?;
                        self.nudge(&settings, &record).await;
                        log::event(
                            "info",
                            "instance.auto_update",
                            &[("instance", record.id.clone()), ("version", promoted.version)],
                        );
                    }
                }
            }
        }
        self.schedule_tick().await
    }
}

impl InstanceObject {
    /// The agent's routes, behind its key.
    async fn agent_route(&self, mut req: Request) -> Result<Response> {
        let Some(mut record) = self.record().await? else {
            return problem::response(ErrorCode::Unauthorized);
        };
        let presented = header(&req, "authorization")
            .and_then(|value| value.strip_prefix("Bearer ").map(str::to_owned))
            .map(|key| sha256_hex(&key));
        if presented.is_none() || presented != record.agent_key_hash {
            return problem::response(ErrorCode::Unauthorized);
        }
        match (req.method(), req.path().as_str()) {
            (Method::Get, "/agent/desired") => self.agent_desired(&record).await,
            (Method::Post, "/agent/events") => {
                let Ok(body) = req.json::<AgentEvents>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                self.append_events(&body.operation_id, body.events).await?;
                if let Some(outcome) = body.outcome {
                    self.operation_ended(&mut record, &body.operation_id, outcome).await?;
                }
                Response::empty().map(|response| response.with_status(204))
            }
            (Method::Post, "/agent/status") => {
                let Ok(status) = req.json::<AgentStatus>().await else {
                    return problem::response(ErrorCode::MalformedBody);
                };
                self.state.storage().put(KEY_AGENT_STATUS, &status).await?;
                let desired = self.desired().await?;
                let teardown_done = desired.as_ref().is_some_and(|desired| {
                    desired.uninstall.is_some() && status.revision_applied == Some(desired.revision)
                });
                if record.cleanup_pending && teardown_done {
                    let settings = Settings::read(&self.env)?;
                    self.cleanup(&settings, &mut record).await;
                    self.save_record(&mut record).await?;
                }
                Response::empty().map(|response| response.with_status(204))
            }
            _ => problem::response(ErrorCode::NotFound),
        }
    }

    async fn operation_ended(
        &self,
        record: &mut Record,
        operation_id: &str,
        outcome: OperationOutcome,
    ) -> Result<()> {
        let kind = self.finish_operation(operation_id, outcome).await?;
        match (outcome, kind) {
            (OperationOutcome::Succeeded, Some(Operation::Uninstall)) => {
                let settings = Settings::read(&self.env)?;
                self.cleanup(&settings, record).await;
            }
            (OperationOutcome::Succeeded, _) => record.status = InstanceStatus::Ready,
            (OperationOutcome::Failed, _) => record.status = InstanceStatus::Failed,
            (OperationOutcome::Running, _) => {}
        }
        self.save_record(record).await
    }

    async fn agent_desired(&self, record: &Record) -> Result<Response> {
        let settings = Settings::read(&self.env)?;
        let Some(desired) = self.desired().await? else {
            return problem::response(ErrorCode::NotFound);
        };
        let Some(agent_release) = releases::promoted(&self.env, agent_product::PRODUCT).await? else {
            return problem::response(ErrorCode::UpstreamUnavailable);
        };
        let operation_id = self
            .operations()
            .await?
            .last()
            .map(|op| op.id.clone())
            .unwrap_or_else(|| "op-0".to_owned());
        let agent_host = record
            .agent_url
            .as_deref()
            .and_then(|url| url.strip_prefix("https://"))
            .unwrap_or_default()
            .to_owned();
        let release_url = |product: &str, version: &str, file: &str| {
            format!("{}/releases/{product}/{version}/{file}", settings.public_url)
        };
        let body = AgentDesired {
            spec: Self::product_spec(record, &desired),
            operation_id,
            manifest_url: release_url(&record.product, &desired.version, "manifest.json"),
            signature_url: release_url(&record.product, &desired.version, "manifest.sig"),
            blob_base_url: format!("{}/blobs", settings.public_url),
            delete_bucket_confirmed: false,
            agent: AgentRelease {
                manifest_url: release_url(agent_product::PRODUCT, &agent_release.version, "manifest.json"),
                signature_url: release_url(agent_product::PRODUCT, &agent_release.version, "manifest.sig"),
                version: agent_release.version,
                spec: Self::agent_spec(&settings, record, &agent_host),
            },
            desired,
        };
        problem::json(200, &body)
    }
}
