//! The worker's routes: authenticate, resolve, forward.

use deployer_api::{
    AuthorizeStarted, CheckNames, CreateInstance, ErrorCode, InstanceList, InstanceSummary, Me,
    NamesChecked, ZoneList, ZoneView,
};
use deployer_cloudflare::{account, CloudflareClient};
use deployer_engine::api::CloudflareApi as _;
use deployer_engine::apply::{classify, Classification};
use deployer_engine::spec::{name_is_valid, resource_name};
use worker::{Env, Headers, Method, Request, Response, Result};

use crate::internal::{self, instance_stub, user_stub, TOKEN_HEADER, USER_HEADER};
use crate::session::{self, Session};
use crate::settings::{names, Settings};
use crate::user::{Authorization, InstanceRef};
use crate::{oauth, problem, rand, releases};

/// The committed OpenAPI document, served byte for byte.
const OPENAPI_YAML: &str = include_str!("../../../docs/openapi.yaml");

/// The client's API.
pub async fn client(mut req: Request, env: &Env) -> Result<Response> {
    let path = req.path();
    let method = req.method();
    let rest = path.trim_start_matches("/v1/").to_owned();
    let segments: Vec<&str> = rest.split('/').collect();
    match (method, segments.as_slice()) {
        (Method::Get, ["auth", "start"]) => oauth::start(env, &req).await,
        (Method::Get, ["auth", "callback"]) => oauth::callback(env, &req).await,
        (Method::Post, ["auth", "logout"]) => {
            let cookie = session::delete(env, &req).await?;
            let headers = Headers::new();
            headers.set("set-cookie", &cookie)?;
            Ok(Response::empty()?.with_status(204).with_headers(headers))
        }
        (Method::Get, ["openapi.yaml"]) => {
            let headers = Headers::new();
            headers.set("content-type", "application/yaml")?;
            Ok(Response::ok(OPENAPI_YAML)?.with_headers(headers))
        }
        (Method::Get, ["releases", product]) => match releases::index(env, product).await? {
            Some(list) => problem::json(200, &list),
            None => problem::response(ErrorCode::NotFound),
        },
        _ => {
            let Some(session) = session::current(env, &req).await else {
                return problem::response(ErrorCode::Unauthorized);
            };
            match (method, segments.as_slice()) {
                (Method::Get, ["me"]) => {
                    internal::call(&user_stub(env, &session.user_id)?, Method::Get, "/me", &[], None).await
                }
                (Method::Post, ["accounts", account, "authorize"]) => {
                    account_authorize(env, &req, &session, account).await
                }
                (Method::Get, ["accounts", account, "zones"]) => zones(env, &session, account).await,
                (Method::Post, ["instances", "check-names"]) => check_names(env, &mut req, &session).await,
                (Method::Get, ["instances"]) => list(env, &session).await,
                (Method::Post, ["instances"]) => create(env, &mut req, &session).await,
                (_, ["instances", id]) => instance(env, req, &session, id, None).await,
                (_, ["instances", id, tail]) => {
                    let tail = (*tail).to_owned();
                    instance(env, req, &session, id, Some(&tail)).await
                }
                _ => problem::response(ErrorCode::NotFound),
            }
        }
    }
}

/// The user's connected accounts.
async fn me(env: &Env, session: &Session) -> Result<Option<Me>> {
    let response = internal::call(&user_stub(env, &session.user_id)?, Method::Get, "/me", &[], None).await?;
    internal::json(response).await
}

/// The user's live authorization for an account, when they hold one.
async fn authorization(env: &Env, session: &Session, account: &str) -> Result<Option<String>> {
    let response = internal::call(
        &user_stub(env, &session.user_id)?,
        Method::Get,
        &format!("/authorizations/{account}"),
        &[],
        None,
    )
    .await?;
    Ok(internal::json::<Authorization>(response)
        .await?
        .map(|held| held.token))
}

async fn account_authorize(env: &Env, req: &Request, session: &Session, account: &str) -> Result<Response> {
    let settings = Settings::read(env)?;
    let Some(me) = me(env, session).await? else {
        return problem::response(ErrorCode::Unauthorized);
    };
    if !me.accounts.iter().any(|known| known.id == account) {
        return problem::response(ErrorCode::NotFound);
    }
    let return_to = req
        .url()?
        .query_pairs()
        .find(|(key, _)| key == "return")
        .map(|(_, value)| value.into_owned())
        .filter(|path| path.starts_with('/') && !path.starts_with("//"))
        .unwrap_or_else(|| "/".to_owned());
    let url = oauth::authorize(env, &settings, &session.user_id, account, return_to).await?;
    problem::json(200, &AuthorizeStarted { url })
}

async fn zones(env: &Env, session: &Session, account: &str) -> Result<Response> {
    let settings = Settings::read(env)?;
    let Some(token) = authorization(env, session, account).await? else {
        return problem::response(ErrorCode::AuthorizationRequired);
    };
    match account::zones(&settings.api_base, &token, account).await {
        Ok(zones) => problem::json(
            200,
            &ZoneList {
                zones: zones
                    .into_iter()
                    .map(|zone| ZoneView {
                        id: zone.id,
                        name: zone.name,
                    })
                    .collect(),
            },
        ),
        Err(error) => {
            crate::log::event("warn", "routes.zones_failed", &[("status", error.status.to_string())]);
            problem::response(ErrorCode::UpstreamUnavailable)
        }
    }
}

async fn check_names(env: &Env, req: &mut Request, session: &Session) -> Result<Response> {
    let Ok(body) = req.json::<CheckNames>().await else {
        return problem::response(ErrorCode::MalformedBody);
    };
    let settings = Settings::read(env)?;
    let valid = name_is_valid(&body.name) && settings.release_keys.contains_key(&body.product);
    let resource = resource_name(&body.product, &body.name);
    let worker = match (valid, authorization(env, session, &body.account_id).await?) {
        (true, Some(token)) => {
            let client = CloudflareClient::new(&settings.api_base, &token);
            match client.get_script(&body.account_id, &resource).await {
                Ok(Some(info)) => Some(classify(&info.tags, "")),
                Ok(None) => Some(Classification::Absent),
                Err(_) => None,
            }
        }
        _ => None,
    };
    problem::json(
        200,
        &NamesChecked {
            resource_name: resource,
            valid,
            worker,
        },
    )
}

async fn list(env: &Env, session: &Session) -> Result<Response> {
    let response = internal::call(
        &user_stub(env, &session.user_id)?,
        Method::Get,
        "/instances",
        &[],
        None,
    )
    .await?;
    let refs: Vec<InstanceRef> = internal::json(response).await?.unwrap_or_default();
    let mut instances = Vec::new();
    for entry in refs {
        let response = internal::call(
            &instance_stub(env, &entry.id)?,
            Method::Get,
            "/summary",
            &[(USER_HEADER, &session.user_id)],
            None,
        )
        .await?;
        if let Some(summary) = internal::json::<InstanceSummary>(response).await? {
            instances.push(summary);
        }
    }
    instances.sort_by(|a, b| b.updated_at_ms.cmp(&a.updated_at_ms));
    problem::json(200, &InstanceList { instances })
}

async fn create(env: &Env, req: &mut Request, session: &Session) -> Result<Response> {
    let Ok(request) = req.json::<CreateInstance>().await else {
        return problem::response(ErrorCode::MalformedBody);
    };
    let settings = Settings::read(env)?;
    if !settings.release_keys.contains_key(&request.product) {
        return problem::response(ErrorCode::ReleaseUnknown);
    }
    if !name_is_valid(&request.name) {
        return problem::response(ErrorCode::BadName);
    }
    let Some(me) = me(env, session).await? else {
        return problem::response(ErrorCode::Unauthorized);
    };
    let Some(account) = me.accounts.iter().find(|known| known.id == request.account_id) else {
        return problem::response(ErrorCode::Forbidden);
    };
    let Some(index) = releases::index(env, &request.product).await? else {
        return problem::response(ErrorCode::ReleaseUnknown);
    };
    let version = match &request.version {
        Some(wanted) if index.releases.iter().any(|release| &release.version == wanted) => {
            wanted.clone()
        }
        Some(_) => return problem::response(ErrorCode::ReleaseUnknown),
        None => match index.releases.iter().find(|release| release.promoted) {
            Some(promoted) => promoted.version.clone(),
            None => return problem::response(ErrorCode::ReleaseUnknown),
        },
    };
    let id = rand::id();
    let body = serde_json::json!({
        "id": id,
        "ownerUserId": session.user_id,
        "accountName": account.name,
        "version": version,
        "request": request,
    });
    let account_id = request.account_id.clone();
    let response = internal::call(
        &instance_stub(env, &id)?,
        Method::Post,
        "/create",
        &[],
        Some(body.to_string()),
    )
    .await?;
    if response.status_code() == 201 {
        internal::call(
            &user_stub(env, &session.user_id)?,
            Method::Post,
            "/instances",
            &[],
            Some(serde_json::json!({ "id": id, "accountId": account_id }).to_string()),
        )
        .await?;
    }
    Ok(response)
}

/// The account an instance lives in, read off its summary; or the
/// refusal the object answered.
async fn instance_account(env: &Env, session: &Session, id: &str) -> Result<std::result::Result<String, Response>> {
    let response = internal::call(
        &instance_stub(env, id)?,
        Method::Get,
        "/summary",
        &[(USER_HEADER, &session.user_id)],
        None,
    )
    .await?;
    if !(200..300).contains(&response.status_code()) {
        return Ok(Err(response));
    }
    match internal::json::<InstanceSummary>(response).await? {
        Some(summary) => Ok(Ok(summary.account_id)),
        None => Ok(Err(problem::response(ErrorCode::NotFound)?)),
    }
}

async fn instance(env: &Env, mut req: Request, session: &Session, id: &str, tail: Option<&str>) -> Result<Response> {
    let stub = instance_stub(env, id)?;
    let user = [(USER_HEADER, session.user_id.as_str())];
    match (req.method(), tail) {
        (Method::Get, None) => internal::call(&stub, Method::Get, "/detail", &user, None).await,
        (Method::Get, Some("operations")) => {
            internal::call(&stub, Method::Get, "/operations", &user, None).await
        }
        (Method::Get, Some("events")) => {
            let since = req
                .url()?
                .query_pairs()
                .find(|(key, _)| key == "since")
                .map(|(_, value)| value.into_owned())
                .unwrap_or_else(|| "0".to_owned());
            let upgrade = internal::header(&req, "upgrade").unwrap_or_default();
            let mut headers = vec![(USER_HEADER, session.user_id.as_str())];
            if upgrade.eq_ignore_ascii_case("websocket") {
                headers.push(("upgrade", "websocket"));
            }
            internal::call(
                &stub,
                Method::Get,
                &format!("/events?since={since}"),
                &headers,
                None,
            )
            .await
        }
        (Method::Post, Some("authorize")) => {
            let account = match instance_account(env, session, id).await? {
                Ok(account) => account,
                Err(response) => return Ok(response),
            };
            let settings = Settings::read(env)?;
            let url = oauth::authorize(
                env,
                &settings,
                &session.user_id,
                &account,
                format!("/instances/{id}"),
            )
            .await?;
            problem::json(200, &AuthorizeStarted { url })
        }
        (Method::Post, Some("provision")) => {
            let account = match instance_account(env, session, id).await? {
                Ok(account) => account,
                Err(response) => return Ok(response),
            };
            let Some(token) = authorization(env, session, &account).await? else {
                return problem::response(ErrorCode::AuthorizationRequired);
            };
            let response = internal::call(
                &stub,
                Method::Post,
                "/provision",
                &[(USER_HEADER, &session.user_id), (TOKEN_HEADER, &token)],
                None,
            )
            .await?;
            // The authorization was for this operation; it ends with it.
            if response.status_code() == 202 {
                let _ = internal::call(
                    &user_stub(env, &session.user_id)?,
                    Method::Delete,
                    &format!("/authorizations/{account}"),
                    &[],
                    None,
                )
                .await;
            }
            Ok(response)
        }
        (Method::Post, Some("uninstall")) => {
            let account = match instance_account(env, session, id).await? {
                Ok(account) => account,
                Err(response) => return Ok(response),
            };
            let Some(token) = authorization(env, session, &account).await? else {
                return problem::response(ErrorCode::AuthorizationRequired);
            };
            let body = req.text().await?;
            internal::call(
                &stub,
                Method::Post,
                "/uninstall",
                &[(USER_HEADER, &session.user_id), (TOKEN_HEADER, &token)],
                Some(body),
            )
            .await
        }
        (Method::Post, Some("desired")) => {
            let dry_run = req
                .url()?
                .query_pairs()
                .any(|(key, value)| key == "dryRun" && value == "true");
            let body = req.text().await?;
            internal::call(
                &stub,
                Method::Post,
                &format!("/desired?dryRun={dry_run}"),
                &user,
                Some(body),
            )
            .await
        }
        (Method::Post, Some("grants")) => {
            let body = req.text().await?;
            internal::call(&stub, Method::Post, "/grants", &user, Some(body)).await
        }
        _ => problem::response(ErrorCode::NotFound),
    }
}

/// The agent API: forward to the instance with the agent's bearer.
pub async fn agent(mut req: Request, env: &Env) -> Result<Response> {
    let path = req.path();
    let rest = path.trim_start_matches("/agent/v1/instances/").to_owned();
    let Some((id, tail)) = rest.split_once('/') else {
        return problem::response(ErrorCode::NotFound);
    };
    if !matches!(tail, "desired" | "events" | "status") {
        return problem::response(ErrorCode::NotFound);
    }
    let bearer = internal::header(&req, "authorization").unwrap_or_default();
    let body = if req.method() == Method::Post {
        Some(req.text().await?)
    } else {
        None
    };
    internal::call(
        &instance_stub(env, id)?,
        req.method(),
        &format!("/agent/{tail}"),
        &[("authorization", &bearer)],
        body,
    )
    .await
}

/// The client's files, with the shell for every path that names no file.
pub async fn assets(env: &Env, req: &Request) -> Result<Response> {
    let Ok(assets) = env.assets(names::ASSETS) else {
        return problem::response(ErrorCode::NotFound);
    };
    let mut url = req.url()?;
    let names_a_file = url
        .path()
        .rsplit('/')
        .next()
        .is_some_and(|last| last.contains('.'));
    if !names_a_file {
        url.set_path("/index.html");
    }
    url.set_query(None);
    assets.fetch(url.to_string(), None).await
}
