/// The three calls that act inside the customer's account, and so need
/// the account resolved and, for two of them, its authorization.
async fn instance_operation(
    env: &Env,
    mut req: Request,
    session: &Session,
    id: &str,
    operation: &str,
) -> Result<Response> {
    let stub = instance_stub(env, id)?;
    let account = match instance_account(env, session, id).await? {
        Ok(account) => account,
        Err(response) => return Ok(response),
    };
    if operation == "authorize" {
        let settings = Settings::read(env)?;
        let url = oauth::authorize(
            env,
            &settings,
            &session.user_id,
            &account,
            format!("/instances/{id}"),
        )
        .await?;
        return problem::json(200, &AuthorizeStarted { url });
    }
    let Some(token) = authorization(env, session, &account).await? else {
        return problem::response(ErrorCode::AuthorizationRequired);
    };
    let headers = [(USER_HEADER, session.user_id.as_str()), (TOKEN_HEADER, token.as_str())];
    if operation == "uninstall" {
        let body = req.text().await?;
        return internal::call(&stub, Method::Post, "/uninstall", &headers, Some(body)).await;
    }
    let response = internal::call(&stub, Method::Post, "/provision", &headers, None).await?;
    // The authorization was for this operation; it ends with it.
    if response.status_code() == 202 {
        let _ = internal::call(
            &user_stub(env, &session.user_id)?,
            Method::Delete,
            &format!("/authorizations/{account}"),
            &[],
            None,
        )
        .await;
    }
    Ok(response)
}

