// The workerd lane's driver (docs/testing/workerd.md). One scenario, two
// workers: the control plane and an agent, both under `wrangler dev
// --local`, against a stub that plays Cloudflare's API, Cloudflare's OAuth
// server, and the customer's product host. The driver is the browser: it
// signs in, creates an instance, authorizes, provisions, posts secrets to
// the agent under a grant, watches the event relay over a WebSocket, and
// asserts what the stub account ends up holding at every step.
//
// No npm dependencies: node 22's fetch, child_process, crypto, and http
// cover everything. Usage: node workerd/check.mjs

import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import crypto from "node:crypto";
import { readFileSync } from "node:fs";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import http from "node:http";
import net from "node:net";
import os from "node:os";
import path from "node:path";

const repoRoot = path.resolve(import.meta.dirname, "..");
const controlConfig = path.join(repoRoot, "workerd", "control.wrangler.toml");
const agentConfig = path.join(repoRoot, "workerd", "agent.wrangler.toml");
const agentBuild = path.join(repoRoot, "crates", "deployer-agent", "build");

// ---------------------------------------------------------------------
// Keys. One release key signs every manifest the lane publishes; one
// control seed is what the control plane signs grants with; a stranger's
// key exists so a forged grant can be refused on the record.
// ---------------------------------------------------------------------

const releaseKey = crypto.generateKeyPairSync("ed25519");
const strangerKey = crypto.generateKeyPairSync("ed25519");
const rawPublic = (publicKey) =>
  Buffer.from(publicKey.export({ format: "jwk" }).x, "base64url").toString(
    "base64",
  );
const sign = (privateKey, bytes) =>
  crypto.sign(null, Buffer.from(bytes), privateKey).toString("base64");

const controlSeed = crypto.randomBytes(32);
const controlPrivate = crypto.createPrivateKey({
  key: Buffer.concat([
    Buffer.from("302e020100300506032b657004220420", "hex"),
    controlSeed,
  ]),
  format: "der",
  type: "pkcs8",
});
const controlPublic = rawPublic(crypto.createPublicKey(controlPrivate));

// ---------------------------------------------------------------------
// The stub: Cloudflare's API, Cloudflare's OAuth, and the product host.
// ---------------------------------------------------------------------

const ACCOUNT = "0123456789abcdef0123456789abcdef";
const stub = {
  scripts: new Map(),
  secretsByScript: new Map(),
  schedules: new Map(),
  subdomainEnabled: new Map(),
  namespaces: [],
  buckets: new Map(),
  domains: [],
  tokens: [],
  deletedTokens: [],
  assetUploads: [],
  pkce: new Map(),
  exchanges: [],
  revoked: 0,
  probes: { cacheInfo: 0, config: 0 },
  publicKey: "cache.lane.invalid-1:AAAA",
};
let nextId = 1;

const envelope = (res, status, result, info) => {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(
    JSON.stringify({
      success: status < 400,
      errors: status < 400 ? [] : [{ code: status * 10, message: "lane" }],
      messages: [],
      result,
      result_info: info ?? { total_pages: 1 },
    }),
  );
};

const readBody = (req) =>
  new Promise((resolve) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks)));
  });

// Split a multipart body into its parts. The boundary comes from the
// content type; every part has headers, a blank line, then bytes.
function parseMultipart(body, contentType) {
  const boundary = contentType.match(/boundary=([^;]+)/)?.[1];
  assert.ok(boundary, "a multipart upload names its boundary");
  const marker = Buffer.from(`--${boundary}`);
  const parts = [];
  let at = body.indexOf(marker);
  while (at !== -1) {
    const start = at + marker.length;
    if (body.slice(start, start + 2).toString() === "--") break;
    const headerEnd = body.indexOf("\r\n\r\n", start);
    const next = body.indexOf(marker, headerEnd);
    const headers = body.slice(start + 2, headerEnd).toString();
    const bytes = body.slice(headerEnd + 4, next - 2);
    const name = headers.match(/name="([^"]+)"/)?.[1];
    const type = headers.match(/Content-Type: ([^\r\n]+)/)?.[1];
    parts.push({ name, type, bytes });
    at = next;
  }
  return parts;
}

async function cloudflareApi(req, res, url) {
  const p = url.pathname.replace(/^\/client\/v4/, "");
  const method = req.method;
  const body = await readBody(req);
  const json = () => (body.length ? JSON.parse(body.toString()) : {});
  let m;
  if (p === "/user") return envelope(res, 200, { id: "user-lane", email: "lane@example.invalid" });
  if (p === "/accounts") return envelope(res, 200, [{ id: ACCOUNT, name: "Lane Account" }]);
  if (p === "/zones") {
    const name = url.searchParams.get("name");
    const accountFilter = url.searchParams.get("account.id");
    const zones = [{ id: "zone-lane", name: "lane.invalid" }];
    return envelope(
      res,
      200,
      zones.filter((zone) => (name ? zone.name === name : true) && (accountFilter ? accountFilter === ACCOUNT : true)),
    );
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/tokens\/permission_groups$/))) {
    const names = [
      "Workers Scripts Write", "Workers KV Storage Write", "Workers R2 Storage Write",
      "Hyperdrive Write", "Zone Read", "DNS Write", "Workers Routes Write",
    ];
    return envelope(res, 200, names.map((name, index) => ({ id: `pg-${index}`, name })));
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/tokens$/)) && method === "POST") {
    const request = json();
    const token = { id: `tok-${nextId++}`, value: `cfat_lane_${crypto.randomBytes(8).toString("hex")}`, request };
    stub.tokens.push(token);
    return envelope(res, 200, { id: token.id, value: token.value });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/tokens\/([^/]+)$/)) && method === "DELETE") {
    stub.deletedTokens.push(m[2]);
    return envelope(res, 200, { id: m[2] });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/subdomain$/))) {
    return envelope(res, 200, { subdomain: "lane" });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)\/settings$/))) {
    const script = stub.scripts.get(m[2]);
    return script ? envelope(res, 200, { tags: script.metadata.tags ?? [] }) : envelope(res, 404, null);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)\/secrets$/)) && method === "PUT") {
    const secret = json();
    if (!stub.secretsByScript.has(m[2])) stub.secretsByScript.set(m[2], new Map());
    stub.secretsByScript.get(m[2]).set(secret.name, secret.text);
    return envelope(res, 200, { name: secret.name, type: "secret_text" });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)\/schedules$/)) && method === "PUT") {
    stub.schedules.set(m[2], json().map((entry) => entry.cron));
    return envelope(res, 200, { schedules: json() });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)\/subdomain$/)) && method === "POST") {
    stub.subdomainEnabled.set(m[2], json().enabled);
    return envelope(res, 200, { enabled: json().enabled });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)\/assets-upload-session$/)) && method === "POST") {
    const manifest = json().manifest ?? {};
    const hashes = Object.values(manifest).map((entry) => entry.hash);
    return envelope(res, 200, { jwt: "session-jwt", buckets: hashes.length ? [hashes] : [] });
  }
  if (p === "/workers/assets/upload" && method === "POST") {
    assert.equal(req.headers.authorization, "Bearer session-jwt", "assets upload carries the session token");
    const parts = parseMultipart(body, req.headers["content-type"]);
    stub.assetUploads.push(parts.map((part) => ({ name: part.name, type: part.type, text: part.bytes.toString() })));
    return envelope(res, 200, { jwt: "completion-jwt" });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/scripts\/([^/]+)$/))) {
    if (method === "PUT") {
      const parts = parseMultipart(body, req.headers["content-type"]);
      const metadataPart = parts.find((part) => part.name === "metadata");
      assert.ok(metadataPart, "a script upload carries metadata");
      const metadata = JSON.parse(metadataPart.bytes.toString());
      const previous = stub.scripts.get(m[2]);
      const kept = new Map(previous?.secrets ?? []);
      if (!(metadata.keep_bindings ?? []).includes("secret_text")) kept.clear();
      for (const binding of metadata.bindings ?? []) {
        if (binding.type === "secret_text") kept.set(binding.name, binding.text);
      }
      stub.scripts.set(m[2], {
        metadata,
        modules: parts.filter((part) => part.name !== "metadata").map((part) => ({ name: part.name, type: part.type, size: part.bytes.length })),
        secrets: kept,
        uploads: (previous?.uploads ?? 0) + 1,
      });
      return envelope(res, 200, { id: m[2] });
    }
    if (method === "DELETE") {
      const existed = stub.scripts.delete(m[2]);
      return existed ? envelope(res, 200, null) : envelope(res, 404, null);
    }
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/domains$/))) {
    if (method === "GET") {
      const service = url.searchParams.get("service");
      return envelope(res, 200, stub.domains.filter((domain) => !service || domain.service === service));
    }
    const request = json();
    const domain = { id: `domain-${nextId++}`, hostname: request.hostname, service: request.service, zone_id: request.zone_id };
    stub.domains.push(domain);
    return envelope(res, 200, domain);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/workers\/domains\/([^/]+)$/)) && method === "DELETE") {
    stub.domains = stub.domains.filter((domain) => domain.id !== m[2]);
    return envelope(res, 200, null);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/storage\/kv\/namespaces$/))) {
    if (method === "GET") return envelope(res, 200, stub.namespaces);
    const namespace = { id: `kv-${nextId++}`, title: json().title };
    stub.namespaces.push(namespace);
    return envelope(res, 200, namespace);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/storage\/kv\/namespaces\/([^/]+)$/)) && method === "DELETE") {
    stub.namespaces = stub.namespaces.filter((namespace) => namespace.id !== m[2]);
    return envelope(res, 200, null);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/r2\/buckets$/))) {
    if (method === "GET") return envelope(res, 200, { buckets: [...stub.buckets.keys()].map((name) => ({ name })) });
    const name = json().name;
    if (stub.buckets.has(name)) return envelope(res, 409, null);
    stub.buckets.set(name, new Set());
    return envelope(res, 200, { name });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/r2\/buckets\/([^/]+)$/)) && method === "DELETE") {
    const objects = stub.buckets.get(m[2]);
    if (!objects) return envelope(res, 404, null);
    if (objects.size) return envelope(res, 409, null);
    stub.buckets.delete(m[2]);
    return envelope(res, 200, null);
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/r2\/buckets\/([^/]+)\/objects$/)) && method === "GET") {
    const objects = stub.buckets.get(m[2]);
    if (!objects) return envelope(res, 404, null);
    return envelope(res, 200, [...objects].map((key) => ({ key })), { is_truncated: false });
  }
  if ((m = p.match(/^\/accounts\/([^/]+)\/r2\/buckets\/([^/]+)\/objects\/(.+)$/)) && method === "DELETE") {
    const objects = stub.buckets.get(m[2]);
    if (!objects) return envelope(res, 404, null);
    objects.delete(decodeURIComponent(m[3]));
    return envelope(res, 200, null);
  }
  envelope(res, 404, null);
}

function oauth(req, res, url) {
  if (url.pathname === "/oauth2/auth") {
    const redirect = url.searchParams.get("redirect_uri");
    const state = url.searchParams.get("state");
    assert.equal(url.searchParams.get("code_challenge_method"), "S256");
    const code = `lane-code-${nextId++}`;
    stub.pkce.set(code, { challenge: url.searchParams.get("code_challenge"), scope: url.searchParams.get("scope") });
    res.writeHead(302, { location: `${redirect}?code=${code}&state=${encodeURIComponent(state)}` });
    return res.end();
  }
  if (url.pathname === "/oauth2/token") {
    return readBody(req).then((body) => {
      const form = new URLSearchParams(body.toString());
      const pending = stub.pkce.get(form.get("code"));
      const expected = crypto.createHash("sha256").update(form.get("code_verifier") ?? "").digest("base64url");
      const ok = pending && pending.challenge === expected && form.get("client_id") === "lane-oauth-client" && form.get("client_secret") === "lane-oauth-secret";
      stub.exchanges.push({ ok, scope: pending?.scope });
      res.writeHead(ok ? 200 : 400, { "content-type": "application/json" });
      res.end(JSON.stringify(ok ? { access_token: `lane-access-${nextId++}`, token_type: "bearer", expires_in: 3600, scope: pending.scope } : { error: "invalid_grant" }));
    });
  }
  if (url.pathname === "/oauth2/revoke") {
    stub.revoked += 1;
    res.writeHead(200);
    return res.end();
  }
  res.writeHead(404);
  res.end();
}

