const agentUrl = `http://127.0.0.1:${agentPort}`;

async function bootWorkerd(config, port, persist, vars) {
  const proc = spawn(
    "wrangler",
    [
      "dev", "--local", "--port", String(port), "--persist-to", persist, "--config", config,
      ...Object.entries(vars).flatMap(([name, value]) => ["--var", `${name}:${value}`]),
    ],
    { detached: true, stdio: ["ignore", "pipe", "pipe"] },
  );
  let captured = "";
  proc.stdout.on("data", (chunk) => (captured += chunk));
  proc.stderr.on("data", (chunk) => (captured += chunk));
  const deadline = Date.now() + 90_000;
  let ready = false;
  while (Date.now() < deadline) {
    if (/Ready on http:\/\//.test(captured)) {
      ready = true;
      break;
    }
    if (captured.includes("ERROR")) break;
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  if (!ready) {
    kill(proc);
    throw new Error(`workerd never came up for ${path.basename(config)}:\n${captured.slice(-3000)}`);
  }
  return { proc, log: () => captured };
}

function kill(proc) {
  try {
    process.kill(-proc.pid, "SIGKILL");
  } catch {
    proc.kill("SIGKILL");
  }
}

