const sha256 = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const controlPersist = await mkdtemp(path.join(os.tmpdir(), "deployer-lane-control-"));
const agentPersist = await mkdtemp(path.join(os.tmpdir(), "deployer-lane-agent-"));

function seed(key, content) {
  const seedFile = path.join(controlPersist, "seed-input");
  const written = writeFile(seedFile, content);
  return written.then(() => {
    const put = spawnSync(
      "wrangler",
      ["r2", "object", "put", `deployer-lane-releases/${key}`, "--file", seedFile, "--local", "--persist-to", controlPersist, "--config", controlConfig],
      { encoding: "utf8" },
    );
    if (put.status !== 0) throw new Error(`seeding ${key} failed: ${put.stderr}${put.stdout}`);
  });
}

async function publish(product, manifest, moduleBytes, assetFiles) {
  const modules = [];
  for (const module of manifest.worker.modules) {
    const bytes = moduleBytes(module.name);
    modules.push({ name: module.name, sha256: sha256(bytes), size: bytes.length });
    await seed(`blobs/${sha256(bytes)}`, bytes);
  }
  const assets = {};
  for (const [servedPath, bytes] of Object.entries(assetFiles)) {
    const hash = sha256(bytes).slice(0, 32);
    assets[servedPath] = { hash, size: bytes.length };
    await seed(`blobs/${hash}`, bytes);
  }
  const measured = { ...manifest, artifacts: { modules, assets } };
  const text = `${JSON.stringify(measured, null, 2)}\n`;
  await seed(`releases/${product}/${manifest.version}/manifest.json`, text);
  await seed(`releases/${product}/${manifest.version}/manifest.sig`, sign(releaseKey.privateKey, text));
  await seed(`releases/${product}/promoted`, manifest.version);
  return text;
}

