const results = [];
async function check(name, fn) {
  try {
    await fn();
    results.push(["ok", name]);
    process.stdout.write(`ok ${name}\n`);
  } catch (failure) {
    const detail = failure.actual !== undefined ? ` (actual ${JSON.stringify(failure.actual)}, expected ${JSON.stringify(failure.expected)})` : "";
    results.push(["FAIL", `${name}: ${failure.message}${detail}`]);
    process.stdout.write(`FAIL ${name}: ${failure.message}${detail}\n`);
  }
}

let cookie = "";
const api = async (method, route, body, extra = {}) => {
  const response = await fetch(`${controlUrl}${route}`, {
    method,
    headers: { cookie, ...(body !== undefined ? { "content-type": "application/json" } : {}), ...extra },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    redirect: "manual",
  });
  const text = await response.text();
  let json;
