  }
  return { status: response.status, headers: response.headers, text, json };
};

// Walk a consent: the control plane's redirect to the stub, the stub's
// redirect back, the callback's answer.
async function consent(startUrl) {
  const start = await fetch(startUrl, { redirect: "manual", headers: { cookie } });
  assert.equal(start.status, 302, "the start redirects");
  const stubAuth = start.headers.get("location");
  assert.ok(stubAuth.startsWith(`${stubUrl}/oauth2/auth?`), `consent goes to the stub: ${stubAuth}`);
  const back = await fetch(stubAuth, { redirect: "manual" });
  assert.equal(back.status, 302);
  const callback = back.headers.get("location");
  assert.ok(callback.startsWith(`${controlUrl}/v1/auth/callback?`));
  return fetch(callback, { redirect: "manual", headers: { cookie } });
}

async function until(description, fn, deadlineMs = 60_000) {
  const deadline = Date.now() + deadlineMs;
  let last;
  while (Date.now() < deadline) {
    last = await fn();
    if (last) return last;
    await new Promise((resolve) => setTimeout(resolve, 300));
  }
  throw new Error(`never happened: ${description} (last: ${JSON.stringify(last)})`);
}

// A raw WebSocket client for the event relay: enough of RFC 6455 to open
// the socket with the session cookie and read the server's text frames.
function watchEvents(instanceId, since) {
  const messages = [];
  const request = http.request(`${controlUrl}/v1/instances/${instanceId}/events?since=${since}`, {
    headers: {
      cookie,
      connection: "Upgrade",
      upgrade: "websocket",
      "sec-websocket-version": "13",
      "sec-websocket-key": crypto.randomBytes(16).toString("base64"),
    },
  });
  const opened = new Promise((resolve, reject) => {
    request.on("upgrade", (response, socket) => {
      let buffer = Buffer.alloc(0);
      socket.on("data", (chunk) => {
        buffer = Buffer.concat([buffer, chunk]);
        for (;;) {
          if (buffer.length < 2) return;
          const opcode = buffer[0] & 0x0f;
          let length = buffer[1] & 0x7f;
          let offset = 2;
          if (length === 126) {
            if (buffer.length < 4) return;
            length = buffer.readUInt16BE(2);
            offset = 4;
          } else if (length === 127) {
            if (buffer.length < 10) return;
            length = Number(buffer.readBigUInt64BE(2));
            offset = 10;
          }
          if (buffer.length < offset + length) return;
          const payload = buffer.slice(offset, offset + length);
          buffer = buffer.slice(offset + length);
          if (opcode === 1) messages.push(JSON.parse(payload.toString()));
        }
      });
      resolve(response.statusCode);
    });
    request.on("response", (response) => resolve(response.statusCode));
    request.on("error", reject);
    request.end();
  });
  return { opened, messages, close: () => request.destroy() };
}

