  await check("creating an instance records it and answers the plan", async () => {
    const refused = await api("POST", "/v1/instances", {
      product: "cachet", name: "prod", accountId: ACCOUNT, route: { kind: "workersDev" }, vars: {}, autoUpdate: { enabled: false, delayHours: 24, hold: false },
    });
    assert.equal(refused.status, 400, "a required var missing refuses before anything is recorded");
    const created = await api("POST", "/v1/instances", {
      product: "cachet",
      name: "prod",
      accountId: ACCOUNT,
      route: { kind: "customDomain", hostname: "cache.lane.invalid", zoneId: "zone-lane" },
      vars: { CACHET_HOST: "cache.lane.invalid", CACHET_ORGS: "lane-org", CACHET_ADMINS: "lane-dev", CACHET_OAUTH_CLIENT_ID: "Iv1.lane" },
      generatedPublic: { CACHET_SIGNING_KEY: stub.publicKey },
      autoUpdate: { enabled: false, delayHours: 24, hold: false },
    });
    assert.equal(created.status, 201, created.text);
    instanceId = created.json.id;
    assert.equal(created.json.plan.resourceName, "cachet-prod");
    assert.equal(created.json.plan.probes[2].equals, stub.publicKey);
    assert.ok(!JSON.stringify(created.json).includes("secret"), "the plan names no secret value");
    const list = await api("GET", "/v1/instances");
    assert.equal(list.json.instances.length, 1);
    assert.equal(list.json.instances[0].status, "created");
    assert.equal(list.json.instances[0].host, "cache.lane.invalid");
    const detail = await api("GET", `/v1/instances/${instanceId}`);
    assert.equal(detail.json.desired.revision, 1);
    assert.equal(detail.json.desired.version, "0.1.2");
    assert.equal(detail.json.agentUrl, undefined);
  });

  await check("provisioning needs an authorization, then installs the agent into the account", async () => {
    const early = await api("POST", `/v1/instances/${instanceId}/provision`);
    assert.equal(early.status, 428);
    const started = await api("POST", `/v1/instances/${instanceId}/authorize`);
    assert.equal(started.status, 200);
    const landed = await consent(started.json.url);
    assert.equal(landed.status, 302);
    assert.equal(landed.headers.get("location"), `${controlUrl}/instances/${instanceId}`);
    assert.equal(stub.exchanges.at(-1).scope, "workers-scripts.write workers-kv-storage.write workers-r2-storage.write zone.read dns.write account-api-tokens.write");
    const zones = await api("GET", `/v1/accounts/${ACCOUNT}/zones`);
    assert.deepEqual(zones.json.zones, [{ id: "zone-lane", name: "lane.invalid" }]);
    const names = await api("POST", "/v1/instances/check-names", { accountId: ACCOUNT, product: "cachet", name: "prod" });
    assert.deepEqual(names.json.worker, { kind: "absent" });

    const provisioned = await api("POST", `/v1/instances/${instanceId}/provision`);
    assert.equal(provisioned.status, 202, provisioned.text);
    assert.equal(provisioned.json.agentUrl, agentUrl);
    secretsGrant = provisioned.json.secretsGrant;
    assert.ok(secretsGrant.grant.includes("."));
    const agentScript = stub.scripts.get("cachet-deployment-prod");
    assert.ok(agentScript, "the agent worker was uploaded under its deployment name");
    assert.deepEqual(agentScript.modules.map((module) => module.name), ["index.js", "index_bg.wasm", "worker/shim.mjs"]);
    assert.deepEqual(agentScript.metadata.migrations, { new_sqlite_classes: ["Agent"], new_tag: "v1" });
    assert.ok(agentScript.metadata.bindings.some((binding) => binding.type === "durable_object_namespace" && binding.class_name === "Agent"));
    assert.ok(agentScript.metadata.tags.includes(`deployer:instance=${instanceId}-agent`));
    assert.ok(agentScript.metadata.tags.includes("deployer:product=deployer-agent"));
    assert.ok(agentScript.secrets.get("AGENT_TOKEN").startsWith("cfat_lane_"), "the minted token went into the agent");
    assert.equal(stub.tokens.length, 1);
    assert.equal(stub.tokens[0].request.name, "deployer agent cachet-deployment-prod");
    assert.equal(stub.tokens[0].request.policies.length, 2, "an account policy and a zone policy for the custom domain");
    assert.equal(stub.subdomainEnabled.get("cachet-deployment-prod"), true);
    const detail = await api("GET", `/v1/instances/${instanceId}`);
    assert.equal(detail.json.summary.status, "applying");
    assert.equal(detail.json.operations[0].outcome, "succeeded");
    assert.equal(detail.json.operations[0].operation, "install");
    const afterwards = await api("GET", `/v1/accounts/${ACCOUNT}/zones`);
    assert.equal(afterwards.status, 428, "the authorization ended with the operation");
    assert.ok(!control.log().includes(agentScript.secrets.get("AGENT_TOKEN")), "the control plane never logged the token");
  });

  const agentScript = stub.scripts.get("cachet-deployment-prod");
  const agentVars = {
    CONTROL_PLANE_URL: controlUrl,
    INSTANCE_ID: instanceId,
    CONTROL_PLANE_PUBLIC_KEY: controlPublic,
    RELEASE_PUBLIC_KEYS: rawPublic(releaseKey.publicKey),
    CF_API_BASE_URL: `${stubUrl}/client/v4`,
    AGENT_TOKEN: agentScript?.secrets.get("AGENT_TOKEN") ?? "missing",
    AGENT_KEY: agentScript?.secrets.get("AGENT_KEY") ?? "missing",
  };
  agent = await bootWorkerd(agentConfig, agentPort, agentPersist, agentVars);

  await check("the agent answers its health and refuses what its key does not cover", async () => {
    const health = await fetch(`${agentUrl}/health`);
    assert.equal(health.status, 200);
    const body = await health.json();
    assert.equal(body.instanceId, instanceId);
    assert.equal(body.revisionApplied, undefined);
    assert.equal(body.secretsPending, false);
    const preflight = await fetch(`${agentUrl}/secrets`, { method: "OPTIONS", headers: { origin: controlUrl, "access-control-request-method": "POST" } });
    assert.equal(preflight.status, 204);
    assert.equal(preflight.headers.get("access-control-allow-origin"), controlUrl);
    const anonymous = await api("GET", `/agent/v1/instances/${instanceId}/desired`, undefined, { cookie: "" });
    assert.equal(anonymous.status, 401);
    const wrong = await api("GET", `/agent/v1/instances/${instanceId}/desired`, undefined, { cookie: "", authorization: "Bearer nope" });
    assert.equal(wrong.status, 401);
    const right = await api("GET", `/agent/v1/instances/${instanceId}/desired`, undefined, { cookie: "", authorization: `Bearer ${agentVars.AGENT_KEY}` });
    assert.equal(right.status, 200);
    assert.equal(right.json.manifestUrl, `${controlUrl}/releases/cachet/0.1.2/manifest.json`);
    assert.equal(right.json.spec.probeBase, stubUrl);
    assert.equal(right.json.agent.spec.resourceName, "cachet-deployment-prod");
  });

  const watcher = watchEvents(instanceId, 0);
  await check("the event stream opens as a WebSocket and replays the install", async () => {
    assert.equal(await watcher.opened, 101);
    await until("the replay", () => watcher.messages.length >= 3);
    assert.equal(watcher.messages[0].seq, 1);
    assert.equal(watcher.messages[0].event.step.kind, "preflight");
  });

  await check("secrets reach the agent only under a grant that names them", async () => {
    const forgedGrant = `${Buffer.from(JSON.stringify({ instanceId, purpose: "secrets", secretNames: ["CACHET_SIGNING_KEY"], issuedAtMs: 0, expiresAtMs: 9e15, nonce: "x" })).toString("base64")}.${sign(strangerKey.privateKey, "x")}`;
    const forged = await fetch(`${agentUrl}/secrets`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ grant: forgedGrant, secrets: { CACHET_SIGNING_KEY: "x" } }) });
    assert.equal(forged.status, 403);
    assert.equal((await forged.json()).code, "grant_refused");
    const outside = await fetch(`${agentUrl}/secrets`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ grant: secretsGrant.grant, secrets: { NOT_IN_GRANT: "x" } }) });
    assert.equal(outside.status, 403);
    const accepted = await fetch(`${agentUrl}/secrets`, {
      method: "POST",
      headers: { "content-type": "application/json", origin: controlUrl },
      body: JSON.stringify({ grant: secretsGrant.grant, secrets: { CACHET_SIGNING_KEY: SIGNING_KEY, CACHET_OAUTH_CLIENT_SECRET: OAUTH_SECRET } }),
    });
    assert.equal(accepted.status, 200, await accepted.text());
    assert.equal(accepted.headers.get("access-control-allow-origin"), controlUrl);
    assert.equal((await accepted.json()).secretsPending, true);
  });

  await check("the agent converges the account and the instance becomes ready", async () => {
    const detail = await until("ready", async () => {
      const answer = await api("GET", `/v1/instances/${instanceId}`);
      return answer.json.summary.status === "ready" || answer.json.summary.status === "failed" ? answer.json : null;
    });
    assert.equal(detail.summary.status, "ready", JSON.stringify(detail.operations));
    const product = stub.scripts.get("cachet-prod");
    assert.ok(product, "the product worker was uploaded");
    const types = product.metadata.bindings.map((binding) => binding.type);
    assert.deepEqual(types.slice(0, 4), ["r2_bucket", "kv_namespace", "analytics_engine", "assets"]);
    assert.equal(product.metadata.bindings.find((binding) => binding.name === "CACHET_EVENTS").dataset, "cachet_prod");
    assert.equal(product.metadata.assets.jwt, "completion-jwt");
    assert.equal(product.metadata.compatibility_flags[0], "nodejs_compat");
    assert.equal(product.metadata.migrations, undefined);
    assert.equal(product.secrets.get("CACHET_SIGNING_KEY"), SIGNING_KEY, "the signing key reached the account");
    assert.equal(product.secrets.get("CACHET_OAUTH_CLIENT_SECRET"), OAUTH_SECRET);
    assert.deepEqual(stub.schedules.get("cachet-prod"), ["0 * * * *"]);
    assert.ok(stub.buckets.has("cachet-prod"));
    assert.ok(stub.namespaces.some((namespace) => namespace.title === "cachet-prod"));
    assert.deepEqual(stub.domains.map((domain) => [domain.hostname, domain.service, domain.zone_id]), [["cache.lane.invalid", "cachet-prod", "zone-lane"]]);
    assert.equal(stub.assetUploads.length, 1);
    assert.equal(stub.assetUploads[0][0].type, "text/html; charset=utf-8");
    assert.ok(stub.probes.config >= 3, "the config probes ran");
    const health = await (await fetch(`${agentUrl}/health`)).json();
    assert.equal(health.revisionApplied, 1);
    assert.equal(health.secretsPending, false, "the agent forgot the secrets once the upload carried them");
    const events = await api("GET", `/v1/instances/${instanceId}/events?since=0`);
    const labels = events.json.events.filter((entry) => entry.event.kind.kind === "done" || entry.event.kind.kind === "unchanged").map((entry) => entry.event.step.kind);
    assert.ok(labels.includes("bucket") && labels.includes("worker") && labels.includes("route") && labels.includes("verify"), labels.join(","));
    assert.ok(!events.text.includes(SIGNING_KEY) && !events.text.includes(OAUTH_SECRET), "no event carries a secret");
    assert.ok(!control.log().includes(SIGNING_KEY), "the control plane never saw the signing key");
    await until("the relay caught up", () => watcher.messages.some((message) => message.event.step.kind === "verify" && message.event.kind.kind === "done"));
  });

  await check("a configuration change previews, then applies with the secrets kept", async () => {
    const preview = await api("POST", `/v1/instances/${instanceId}/desired?dryRun=true`, { vars: { CACHET_FONT_CSS: "https://fonts.lane.invalid/x.css" } });
    assert.equal(preview.status, 200, preview.text);
    assert.deepEqual(preview.json.secretsNeeded, []);
    assert.ok(preview.json.plan.vars.some(([name, value]) => name === "CACHET_FONT_CSS" && value.endsWith("x.css")));
    assert.equal(preview.json.desired.revision, 1, "a dry run records nothing");
    const applied = await api("POST", `/v1/instances/${instanceId}/desired`, { vars: { CACHET_FONT_CSS: "https://fonts.lane.invalid/x.css" } });
    assert.equal(applied.status, 202, applied.text);
    assert.equal(applied.json.desired.revision, 2);
    assert.equal(applied.json.operationId, "op-2");
    await until("revision 2 applied", async () => (await (await fetch(`${agentUrl}/health`)).json()).revisionApplied === 2);
    const product = stub.scripts.get("cachet-prod");
    assert.equal(product.uploads, 2);
    assert.deepEqual(product.metadata.keep_bindings, ["secret_text"]);
    assert.equal(product.secrets.get("CACHET_SIGNING_KEY"), SIGNING_KEY, "kept across the upload");
    assert.ok(product.metadata.bindings.some((binding) => binding.name === "CACHET_FONT_CSS"));
    assert.ok(!product.metadata.bindings.some((binding) => binding.type === "secret_text"), "an update carries no secret values");
    const detail = await until("ready again", async () => {
      const answer = await api("GET", `/v1/instances/${instanceId}`);
      return answer.json.summary.status === "ready" ? answer.json : null;
    });
    assert.equal(detail.operations[0].operation, "configure");
  });

  await check("a rotation sets one secret without an upload", async () => {
    const issued = await api("POST", `/v1/instances/${instanceId}/grants`, { purpose: "secrets", secretNames: ["CACHET_OAUTH_CLIENT_SECRET"] });
    assert.equal(issued.status, 200, issued.text);
    const unknown = await api("POST", `/v1/instances/${instanceId}/grants`, { purpose: "secrets", secretNames: ["NOT_A_SECRET"] });
    assert.equal(unknown.status, 400);
    const posted = await fetch(`${agentUrl}/secrets`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ grant: issued.json.grant, secrets: { CACHET_OAUTH_CLIENT_SECRET: ROTATED_SECRET } }) });
    assert.equal(posted.status, 200);
    await until("the rotation landed", () => stub.secretsByScript.get("cachet-prod")?.get("CACHET_OAUTH_CLIENT_SECRET") === ROTATED_SECRET);
    assert.equal(stub.scripts.get("cachet-prod").uploads, 2, "no code was uploaded");
    await until("the agent forgot it", async () => (await (await fetch(`${agentUrl}/health`)).json()).secretsPending === false);
  });

  await check("uninstalling tears the worker down, keeps the bucket until the name is typed, then removes the agent", async () => {
    stub.buckets.get("cachet-prod").add("abc.narinfo").add("nar/def.nar.zst");
    const early = await api("POST", `/v1/instances/${instanceId}/uninstall`, { deleteBucket: true });
    assert.equal(early.status, 428, "a teardown is the control plane's own work in the account");
    const started = await api("POST", `/v1/instances/${instanceId}/authorize`);
    await consent(started.json.url);
    const begun = await api("POST", `/v1/instances/${instanceId}/uninstall`, { deleteBucket: true });
    assert.equal(begun.status, 202, begun.text);
    assert.ok(begun.json.deleteBucketGrant, "a deletion needs the typed name at the agent");
    await until("the worker is gone", () => !stub.scripts.has("cachet-prod"));
    await until("the namespace is gone", () => !stub.namespaces.some((namespace) => namespace.title === "cachet-prod"));
    assert.equal(stub.domains.length, 0);
    assert.ok(stub.buckets.has("cachet-prod"), "the bucket waits for the name");
    assert.equal(stub.buckets.get("cachet-prod").size, 2);
    const wrong = await fetch(`${agentUrl}/delete-bucket`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ grant: begun.json.deleteBucketGrant.grant, name: "production" }) });
    assert.equal(wrong.status, 403);
    assert.equal((await wrong.json()).code, "name_mismatch");
    const right = await fetch(`${agentUrl}/delete-bucket`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ grant: begun.json.deleteBucketGrant.grant, name: "prod" }) });
    assert.equal(right.status, 200);
    await until("the bucket is gone", () => !stub.buckets.has("cachet-prod"));
    const detail = await until("uninstalled", async () => {
      const answer = await api("GET", `/v1/instances/${instanceId}`);
      return answer.json.summary.status === "uninstalled" ? answer.json : null;
    });
    assert.equal(detail.summary.status, "uninstalled");
    assert.ok(!stub.scripts.has("cachet-deployment-prod"), "the agent worker was removed");
    assert.deepEqual(stub.deletedTokens, [stub.tokens[0].id], "the agent's token was revoked");
    assert.equal(stub.revoked >= 2, true, "the operation's token was revoked");
  });

  watcher.close();
} finally {
  if (agent) kill(agent.proc);
  kill(control.proc);
  stubServer.close();
  await rm(controlPersist, { recursive: true, force: true });
  await rm(agentPersist, { recursive: true, force: true });
}

const failed = results.filter(([state]) => state === "FAIL");
if (failed.length) {
  process.stdout.write(`\n--- control plane log tail ---\n${control.log().split("\n").filter((line) => line.includes('"event"')).slice(-40).join("\n")}\n`);
  if (agent) process.stdout.write(`--- agent log tail ---\n${agent.log().split("\n").filter((line) => line.includes('"event"')).slice(-40).join("\n")}\n`);
  process.stdout.write(`\n${failed.length} of ${results.length} checks failed\n`);
  process.exit(1);
}
process.stdout.write(`\nall ${results.length} checks passed\n`);
EOF
cargo fmt --all && cargo clippy -p deployer-agent --target wasm32-unknown-unknown --all-features -- --deny warnings 2>&1 | grep -E '^(warning|error)' -A 14 | head -60; echo "agent relint done"; cat .wasm-build.log 2>/dev/null | tail -20

