import "@fontsource-variable/geist";
import "@fontsource-variable/geist-mono";
import "./styles/global.css";

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { RouterProvider } from "@tanstack/react-router";
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { router } from "./router.tsx";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // why: an instance's record moves when an operation runs, and the
      // event stream says when; between events a fresh answer every half
      // minute is plenty, and a refetch on focus is what a person expects
      // when they come back to a tab.
      staleTime: 30_000,
      refetchOnWindowFocus: true,
      retry: false,
    },
  },
});

const root = document.getElementById("root");
if (root === null) throw new Error("the client's root element is missing");

createRoot(root).render(
  <StrictMode>
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  </StrictMode>,
);
