import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
} from "@tanstack/react-router";

import { Gate } from "./gate.tsx";
import { Account } from "./screens/account.tsx";
import { Instance, readTab } from "./screens/instance.tsx";
import { Instances } from "./screens/instances.tsx";
import { NewInstance } from "./screens/new-instance.tsx";

// Four screens, declared rather than generated. A file-based tree would
// bring a codegen step and a committed artifact to keep in step with the
// files, which is a drift surface this many routes does not earn.

const rootRoute = createRootRoute({
  component: () => (
    <Gate>
      <Outlet />
    </Gate>
  ),
});

const routes = [
  createRoute({
    getParentRoute: () => rootRoute,
    path: "/",
    component: Instances,
  }),
  createRoute({
    getParentRoute: () => rootRoute,
    path: "/instances",
    component: Instances,
  }),
  createRoute({
    getParentRoute: () => rootRoute,
    path: "/instances/new",
    component: NewInstance,
  }),
  createRoute({
    getParentRoute: () => rootRoute,
    path: "/instances/$id",
    component: Instance,
    // why: the tab lives in the URL, so a view is a link, and it is
    // validated against the closed set so a hand-edited URL lands on a
    // real tab.
    validateSearch: (search: Record<string, unknown>) => ({
      tab: readTab(search["tab"]),
    }),
  }),
  createRoute({
    getParentRoute: () => rootRoute,
    path: "/account",
    component: Account,
  }),
];

export const router = createRouter({
  routeTree: rootRoute.addChildren(routes),
  defaultPreload: "intent",
  scrollRestoration: true,
});

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}
