import { Schema } from "effect";

// The wire, decoded. Every answer the client reads passes through one of
// these before a screen sees it, so a control plane that answers a shape
// this client does not understand fails at the boundary with the field
// named rather than three components later with `undefined`. The shapes
// are deployer-api's, and where a body carries an engine type the
// engine's own serde form is written out here.

export const Problem = Schema.Struct({
  type: Schema.String,
  title: Schema.String,
  status: Schema.Number,
  code: Schema.String,
});
export type Problem = typeof Problem.Type;

export const InstanceStatus = Schema.Literals([
  "created",
  "provisioning",
  "applying",
  "ready",
  "failed",
  "unreachable",
  "uninstalling",
  "uninstalled",
]);
export type InstanceStatus = typeof InstanceStatus.Type;

export const AutoUpdate = Schema.Struct({
  enabled: Schema.Boolean,
  delayHours: Schema.Number,
  hold: Schema.Boolean,
});
export type AutoUpdate = typeof AutoUpdate.Type;

export const Route = Schema.Union([
  Schema.Struct({
    kind: Schema.Literal("customDomain"),
    hostname: Schema.String,
    zoneId: Schema.String,
  }),
  Schema.Struct({ kind: Schema.Literal("workersDev") }),
]);
export type Route = typeof Route.Type;

export const DesiredState = Schema.Struct({
  revision: Schema.Number,
  product: Schema.String,
  version: Schema.String,
  vars: Schema.Record(Schema.String, Schema.String),
  route: Route,
  generatedPublic: Schema.optional(Schema.Record(Schema.String, Schema.String)),
  autoUpdate: AutoUpdate,
  uninstall: Schema.optional(Schema.Struct({ deleteBucket: Schema.Boolean })),
});
export type DesiredState = typeof DesiredState.Type;

export const AgentStatus = Schema.Struct({
  agentVersion: Schema.String,
  revisionApplied: Schema.optional(Schema.Number),
  installedVersion: Schema.optional(Schema.String),
  servedVersion: Schema.optional(Schema.String),
  publicKey: Schema.optional(Schema.String),
  reachable: Schema.Boolean,
  lastReconcileAtMs: Schema.Number,
  lastError: Schema.optional(Schema.String),
});
export type AgentStatus = typeof AgentStatus.Type;

export const InstanceSummary = Schema.Struct({
  id: Schema.String,
  product: Schema.String,
  name: Schema.String,
  host: Schema.String,
  accountId: Schema.String,
  accountName: Schema.String,
  installedVersion: Schema.optional(Schema.String),
  desiredVersion: Schema.String,
  status: InstanceStatus,
  plan: Schema.Literals(["free"]),
  updatedAtMs: Schema.Number,
});
export type InstanceSummary = typeof InstanceSummary.Type;

export const InstanceList = Schema.Struct({
  instances: Schema.Array(InstanceSummary),
});
export type InstanceList = typeof InstanceList.Type;

export const OperationOutcome = Schema.Literals(["running", "succeeded", "failed"]);
export type OperationOutcome = typeof OperationOutcome.Type;

export const Operation = Schema.Literals([
  "install",
  "update",
  "configure",
  "rotate",
  "uninstall",
]);
export type Operation = typeof Operation.Type;

export const OperationSummary = Schema.Struct({
  id: Schema.String,
  operation: Operation,
  revision: Schema.Number,
  startedAtMs: Schema.Number,
  finishedAtMs: Schema.optional(Schema.Number),
  outcome: OperationOutcome,
});
export type OperationSummary = typeof OperationSummary.Type;

export const InstanceDetail = Schema.Struct({
  summary: InstanceSummary,
  desired: DesiredState,
  agent: Schema.optional(AgentStatus),
  agentUrl: Schema.optional(Schema.String),
  operations: Schema.Array(OperationSummary),
  authorizationRequired: Schema.Boolean,
  updateAvailable: Schema.optional(Schema.String),
});
export type InstanceDetail = typeof InstanceDetail.Type;

export const AccountView = Schema.Struct({
