import { Schema } from "effect";

import * as wire from "./schema.ts";

// The client's one door to the control plane, and its one door to an
// agent. Every network detail stops here: below this module the client
// speaks in decoded values, and a refusal is an ApiError carrying the
// code the server chose.

/** A refusal the server named, or a shape it answered that this client
 *  could not read. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }

  /** Nobody is signed in: the ordinary state of a first visit. */
  get unauthenticated(): boolean {
    return this.status === 401;
  }

  /** The operation needs a fresh Cloudflare authorization first. */
  get authorizationRequired(): boolean {
    return this.code === "authorization_required";
  }
}

const decodeAnswer = async <A>(
  response: Response,
  path: string,
  schema: Schema.Codec<A, unknown, never, never> | undefined,
): Promise<A> => {
  const body: unknown = await response.json().catch(() => undefined);
  if (!response.ok) {
    const problem = Schema.decodeUnknownOption(wire.Problem)(body);
    throw new ApiError(
      response.status,
      problem._tag === "Some" ? problem.value.code : "unknown",
      problem._tag === "Some"
        ? problem.value.title
        : `${path} answered ${response.status}`,
    );
  }
  if (schema === undefined) return undefined as A;
  try {
    return Schema.decodeUnknownSync(schema)(body);
  } catch (failure) {
    // A 200 this client cannot read is worth naming as loudly as a
    // refusal: it means the server is newer or older than the client
    // served beside it.
    throw new ApiError(
      response.status,
      "unreadable_answer",
      `${path} answered a shape this client does not understand: ${String(failure)}`,
    );
  }
};

const read = <A>(
  path: string,
  schema: Schema.Codec<A, unknown, never, never>,
): Promise<A> =>
  fetch(path, {
    // why: the session cookie is HttpOnly and SameSite=Lax on this
    // origin, so it rides along without the client ever seeing it.
    credentials: "same-origin",
    headers: { accept: "application/json" },
  }).then((response) => decodeAnswer(response, path, schema));

const send = <A>(
  method: "POST" | "DELETE",
  path: string,
  body: unknown,
  schema: Schema.Codec<A, unknown, never, never> | undefined,
): Promise<A> =>
  fetch(path, {
    method,
    credentials: "same-origin",
    headers: {
      accept: "application/json",
      ...(body === undefined ? {} : { "content-type": "application/json" }),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  }).then((response) => decodeAnswer(response, path, schema));

