// The agent, reached directly. These bodies are the only ones that ever
// carry a secret, and they go from this browser to the customer's own
// account over TLS, under a grant the control plane signed. The control
// plane sees neither the request nor the value.

const agentPost = async <A>(
  agentUrl: string,
  path: string,
  body: unknown,
  schema: Schema.Codec<A, unknown, never, never>,
