import { Schema } from "effect";
import { useEffect, useRef, useState } from "react";

import * as api from "./client.ts";
import * as wire from "./schema.ts";

// The event stream: one WebSocket per instance, resumed by sequence
// number. The control plane replays what a reconnecting client missed,
// so a refresh mid-operation shows the same step list a patient tab shows.

export type Stream = {
  readonly events: readonly wire.LoggedEvent[];
  readonly connected: boolean;
};

const socketUrl = (id: string, since: number): string => {
  const scheme = window.location.protocol === "https:" ? "wss" : "ws";
  return `${scheme}://${window.location.host}/v1/instances/${encodeURIComponent(id)}/events?since=${since}`;
};

/** Every event the instance has logged, kept live. */
export const useEvents = (id: string | undefined): Stream => {
  const [events, setEvents] = useState<readonly wire.LoggedEvent[]>([]);
  const [connected, setConnected] = useState(false);
  const latest = useRef(0);

  useEffect(() => {
    if (id === undefined) return;
    let socket: WebSocket | undefined;
    let closed = false;
    let retry: number | undefined;

    const absorb = (incoming: readonly wire.LoggedEvent[]) => {
      if (incoming.length === 0) return;
      setEvents((known) => {
        const seen = new Set(known.map((event) => event.seq));
        const fresh = incoming.filter((event) => !seen.has(event.seq));
        const merged = [...known, ...fresh].sort((a, b) => a.seq - b.seq);
        latest.current = merged.at(-1)?.seq ?? latest.current;
        return merged;
      });
    };

    const open = () => {
      if (closed) return;
      socket = new WebSocket(socketUrl(id, latest.current));
      socket.onopen = () => setConnected(true);
      socket.onmessage = (message) => {
        const decoded = Schema.decodeUnknownOption(wire.LoggedEvent)(
          JSON.parse(String(message.data)),
        );
        if (decoded._tag === "Some") absorb([decoded.value]);
      };
      socket.onclose = () => {
        setConnected(false);
        // why: a socket drops when the object hibernates or the network
        // blinks; resuming from the last sequence loses nothing.
        if (!closed) retry = window.setTimeout(open, 2_000);
      };
    };

    // The page first, so a browser whose WebSocket is blocked still reads
    // the log.
    void api.getEvents(id, 0).then((page) => absorb(page.events));
    open();

    return () => {
      closed = true;
      if (retry !== undefined) window.clearTimeout(retry);
      socket?.close();
    };
  }, [id]);

  return { events, connected };
};
