// The signing key is made here, in the browser, and goes to the agent and
// nowhere else. The service never holds it (docs/security/threat-model.md).
//
// The text is nix's own: `<name>:<base64(seed ‖ public)>`, 88 characters of
// standard padded base64, which is what `nix-store --generate-binary-cache-key`
// writes and what cachet's keygen writes. WebCrypto exports an Ed25519
// private key as PKCS#8, whose last 32 bytes are the seed.

const base64 = (bytes: Uint8Array): string => {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
};

export type NixKeyPair = {
  /** `<name>:<base64(seed ‖ public)>`, shown once and downloaded. */
  readonly secret: string;
  /** `<name>:<base64(public)>`, what laptops trust. */
  readonly publicKey: string;
};

/** Generate a nix-format Ed25519 key with the given name. */
export const generateNixKey = async (name: string): Promise<NixKeyPair> => {
  const pair = (await crypto.subtle.generateKey("Ed25519", true, [
    "sign",
    "verify",
  ])) as CryptoKeyPair;
  const pkcs8 = new Uint8Array(
    await crypto.subtle.exportKey("pkcs8", pair.privateKey),
  );
  const seed = pkcs8.slice(pkcs8.length - 32);
  const publicBytes = new Uint8Array(
    await crypto.subtle.exportKey("raw", pair.publicKey),
  );
  const both = new Uint8Array(64);
  both.set(seed, 0);
  both.set(publicBytes, 32);
  return {
    secret: `${name}:${base64(both)}`,
    publicKey: `${name}:${base64(publicBytes)}`,
  };
};

/** The name a rotated key takes: the host with the next number.
 *  `cache.example.com-1` becomes `cache.example.com-2`; a key with no
 *  number, or none at all, starts at 1. */
export const nextKeyName = (
  current: string | undefined,
  host: string,
): string => {
  const name = current?.split(":")[0];
  const match = name?.match(/^(.*)-(\d+)$/);
  if (match?.[1] !== undefined && match[2] !== undefined && match[1] === host) {
    return `${host}-${Number(match[2]) + 1}`;
  }
  return `${host}-1`;
};

/** Render a `$HOST-1` style key name for a host. */
export const keyNameFor = (template: string, host: string): string =>
  template.replaceAll("$HOST", host);

/** Hand the person a file. The secret is what lets them reinstall or
 *  self-host later; once this page is gone it is nowhere else. */
export const downloadText = (filename: string, text: string): void => {
  const blob = new Blob([text], { type: "text/plain" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
};
