import type * as wire from "../api/schema.ts";

// The wizard's pure derivations: which questions a manifest asks, in what
// order, what is still missing, and what the rail shows. Nothing here
// touches the network or the DOM, so the client lane can pin all of it.

/** An instance name: a lowercase word of 2 to 32 characters, a letter
 *  first, then letters, digits, and dashes. The same grammar the engine
 *  enforces. */
export const NAME = /^[a-z][a-z0-9-]{1,31}$/;

export const nameIsValid = (name: string): boolean => NAME.test(name);

/** The name every resource is created under. */
export const resourceName = (product: string, name: string): string =>
  name.startsWith(`${product}-`) ? name : `${product}-${name}`;

/** Fill `$HOST` and `$NAME` in a wizard template. */
export const renderTemplate = (
  template: string,
  values: { host: string; name: string },
): string =>
  template.replaceAll("$HOST", values.host).replaceAll("$NAME", values.name);

/** The vars a person answers: everything the deployer does not derive,
 *  required ones first. A var with a default is asked under "advanced". */
export const askedVars = (
  manifest: wire.Manifest,
): { required: wire.VarSpec[]; advanced: wire.VarSpec[] } => {
  const required: wire.VarSpec[] = [];
  const advanced: wire.VarSpec[] = [];
  for (const spec of manifest.vars) {
    if (spec.requirement === "derived") continue;
    // The host is the address step's answer, never a field of its own.
    if (spec.value === "$HOST") continue;
    if (spec.requirement === "required" && spec.default === undefined) {
      required.push(spec);
    } else {
      advanced.push(spec);
    }
  }
  return { required, advanced };
};

/** The var whose value is the host, when the manifest has one, so the
 *  address step fills it. */
export const hostVar = (manifest: wire.Manifest): string | undefined =>
  manifest.vars.find((spec) => spec.value === "$HOST")?.name;

/** The secrets a person supplies or the browser generates. */
export const askedSecrets = (
  manifest: wire.Manifest,
): { generated: wire.SecretSpec[]; typed: wire.SecretSpec[] } => ({
  generated: manifest.secrets.filter((spec) => spec.generated !== undefined),
  typed: manifest.secrets.filter((spec) => spec.generated === undefined),
});

/** Required vars with no value yet. */
export const missingVars = (
  manifest: wire.Manifest,
  values: Record<string, string>,
): string[] =>
  askedVars(manifest)
    .required.filter((spec) => (values[spec.name] ?? "").trim() === "")
    .map((spec) => spec.name);

/** Required secrets with no value yet. */
export const missingSecrets = (
  manifest: wire.Manifest,
  values: Record<string, string>,
): string[] =>
  manifest.secrets
    .filter((spec) => spec.requirement === "required")
    .filter((spec) => (values[spec.name] ?? "") === "")
    .map((spec) => spec.name);

/** The vars to send: what was typed, minus blanks. */
export const varsToSend = (
  values: Record<string, string>,
): Record<string, string> =>
  Object.fromEntries(
    Object.entries(values)
      .map(([name, value]) => [name, value.trim()] as const)
      .filter(([, value]) => value !== ""),
  );

export type RailRow = { readonly label: string; readonly value: string };

/** What will be created, as the rail lists it. */
export const railRows = (plan: wire.Plan): RailRow[] => {
  const rows: RailRow[] = [{ label: "worker", value: plan.resourceName }];
  for (const resource of plan.resources) {
    const value = resource.name ?? resource.title ?? resource.dataset ?? resource.key;
    rows.push({ label: resource.kind.replaceAll("_", " "), value });
  }
  if (plan.route.kind === "customDomain") {
    rows.push({ label: "address", value: plan.route.hostname });
  } else {
    rows.push({ label: "address", value: "workers.dev, assigned at deploy" });
  }
  for (const cron of plan.crons) rows.push({ label: "schedule", value: cron });
  rows.push({ label: "secrets", value: `${plan.secrets.length} in the account` });
  return rows;
};

/** The wizard's steps, in order. */
