import type * as wire from "../api/schema.ts";

// From a flat event log to the step list a person watches: one row per
// step, carrying its latest state, in the order steps first appeared.

export type StepRow = {
  readonly key: string;
  readonly label: string;
  readonly state: "pending" | "running" | "done" | "unchanged" | "failed";
  readonly detail: string;
  readonly remedy?: string;
  readonly elapsedMs?: number;
};

/** What a step is called on screen. */
export const stepLabel = (step: wire.Step): string => {
  switch (step.kind) {
    case "preflight":
      return "Checking the account";
    case "bucket":
      return `Creating bucket ${step.name ?? ""}`;
    case "namespace":
      return `Creating namespace ${step.title ?? ""}`;
    case "hyperdrive":
      return `Creating Hyperdrive ${step.name ?? ""}`;
    case "assets":
      return "Uploading the console";
    case "worker":
      return "Uploading the worker";
    case "secret":
      return `Setting ${step.name ?? "a secret"}`;
    case "schedules":
      return "Setting the schedule";
    case "route":
      return "Attaching the address";
    case "verify":
      return `Verifying ${step.url ?? ""}`;
    case "detachRoute":
      return "Detaching the address";
    case "deleteWorker":
      return "Deleting the worker";
    case "deleteNamespace":
      return `Deleting namespace ${step.title ?? ""}`;
    case "deleteHyperdrive":
      return `Deleting Hyperdrive ${step.name ?? ""}`;
    case "emptyBucket":
      return `Emptying bucket ${step.name ?? ""}`;
    case "deleteBucket":
      return `Deleting bucket ${step.name ?? ""}`;
    default:
      return step.kind;
  }
};

const stepKey = (step: wire.Step): string =>
  [step.kind, step.name, step.title, step.url].filter(Boolean).join(":");

/** The rows for one operation. */
export const stepRows = (
  events: readonly wire.LoggedEvent[],
  operationId: string,
): StepRow[] => {
  const rows = new Map<string, StepRow & { startedAtMs?: number }>();
  for (const logged of events) {
    if (logged.operationId !== operationId) continue;
    const key = stepKey(logged.event.step);
    const previous = rows.get(key);
    const kind = logged.event.kind.kind;
    const state =
      kind === "started"
        ? "running"
        : kind === "done"
          ? "done"
          : kind === "unchanged"
            ? "unchanged"
            : "failed";
    const startedAtMs =
      kind === "started" ? logged.atMs : previous?.startedAtMs;
    rows.set(key, {
      key,
      label: stepLabel(logged.event.step),
      state,
      detail: logged.event.detail,
      ...(logged.event.kind.remedy === undefined
        ? {}
        : { remedy: logged.event.kind.remedy }),
      ...(startedAtMs === undefined
        ? {}
        : {
            startedAtMs,
            ...(kind === "started"
              ? {}
              : { elapsedMs: Math.max(0, logged.atMs - startedAtMs) }),
          }),
    });
  }
  return [...rows.values()].map(({ startedAtMs: _started, ...row }) => row);
};

/** The newest operation an event log names, when any. */
export const latestOperation = (
  events: readonly wire.LoggedEvent[],
): string | undefined => events.at(-1)?.operationId;
