  label: string;
  help?: string;
  configured: boolean;
  onSave: (value: string) => void;
  saving?: boolean;
}) => {
  const [editing, setEditing] = useState(!configured);
  const [draft, setDraft] = useState("");
  if (!editing) {
    return (
      <div {...stylex.props(styles.field)}>
        <Label>{label}</Label>
        <div {...stylex.props(styles.resting)}>
          <span {...stylex.props(styles.restingText)}>Configured</span>
