          >
            Save
          </Button>
          <Button
            onClick={() => {
              setDraft("");
              setEditing(false);
            }}
          >
            Cancel
          </Button>
        </div>
      ) : (
        <SecretCommit value={draft} onSave={onSave} />
      )}
    </div>
  );
