/** A first entry commits on every keystroke, because the wizard collects
 *  it into its own state and sends it once, at deploy. */
const SecretCommit = ({
  value,
  onSave,
}: {
  value: string;
  onSave: (value: string) => void;
}) => {
  const [last, setLast] = useState("");
  if (value !== last) {
    setLast(value);
    onSave(value);
  }
  return null;
};
