    borderStyle: "solid",
    borderColor: color.line,
    paddingBlock: space.s3,
    paddingInline: space.s4,
    fontFamily: font.mono,
    fontSize: text.spec,
    lineHeight: leading.spec,
    color: color.text,
    overflowWrap: "anywhere",
  },
  button: {
    backgroundColor: "transparent",
    borderWidth: 0,
    padding: 0,
    cursor: "pointer",
    color: { default: color.muted, ":hover": color.text },
    display: "inline-flex",
    flexShrink: 0,
  },
  labeled: { display: "flex", flexDirection: "column", gap: space.s2 },
});

export const useCopy = (value: string): [boolean, () => void] => {
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1_400);
    return () => window.clearTimeout(timer);
  }, [copied]);
  return [
    copied,
    () => {
      void navigator.clipboard?.writeText(value);
      setCopied(true);
    },
  ];
};

/** A line of text a person pastes elsewhere. */
export const Command = ({ children }: { children: string }) => {
  const [copied, copy] = useCopy(children);
  return (
    <div {...stylex.props(styles.command)}>
      <code>{children}</code>
      <button
        type="button"
        onClick={copy}
        aria-label={copied ? "Copied" : "Copy"}
        {...stylex.props(styles.button)}
      >
        {copied ? <CheckIcon /> : <CopyIcon />}
      </button>
    </div>
  );
};

/** A labeled value that copies. */
export const Copy = ({ label, value }: { label: string; value: string }) => (
  <div {...stylex.props(styles.labeled)}>
    <Label>{label}</Label>
    <Command>{value}</Command>
  </div>
);
