import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useState, type ReactNode } from "react";

import * as api from "./api/client.ts";
import { Shell } from "./components/shell.tsx";
import { SignIn } from "./screens/sign-in.tsx";

// The one place that decides whether there is a client to show: not
// signed in, or the shell. Everything below it can assume a session.

export const Gate = ({ children }: { children: ReactNode }) => {
  const queryClient = useQueryClient();
  const nowMs = useClock();
  const me = useQuery({
    queryKey: ["me"],
    queryFn: api.getMe,
    // why: a 401 is the ordinary state of a first visit, not a failure
    // to retry.
    retry: false,
  });

  if (me.isPending) return null;
  if (me.error instanceof api.ApiError && me.error.unauthenticated) {
    return <SignIn />;
  }
  if (me.error !== null) {
    return <SignIn refused={String(me.error)} />;
  }

  const signOut = () => {
    void api.signOut().then(() => {
      queryClient.clear();
      window.location.assign("/");
    });
  };

  return (
    <Shell {...(me.data ? { me: me.data } : {})} nowMs={nowMs} onSignOut={signOut}>
      {children}
    </Shell>
  );
};

/** A UTC clock ticking once a second. */
const useClock = (): number => {
  const [nowMs, setNowMs] = useState(() => Date.now());
  useEffect(() => {
    const tick = window.setInterval(() => setNowMs(Date.now()), 1_000);
    return () => window.clearInterval(tick);
  }, []);
  return nowMs;
};
