import * as stylex from "@stylexjs/stylex";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { useEffect, useMemo, useState } from "react";

import * as api from "../api/client.ts";
import type { Manifest, Plan, Route } from "../api/schema.ts";
import { Button } from "../components/ui/button.tsx";
import { Command } from "../components/ui/copy.tsx";
import { Choice, Field, Secret, SetupSteps, type Verdict } from "../components/ui/field.tsx";
import { KeyPair } from "../components/ui/keypair.tsx";
import { Intro, Label, Panel, Prose } from "../components/ui/primitives.tsx";
import { Segmented } from "../components/ui/segmented.tsx";
import { Failed, LoadingScreen, Mono, Note } from "../components/ui/states.tsx";
import { generateNixKey, keyNameFor, type NixKeyPair } from "../lib/keys.ts";
import * as wizard from "../lib/wizard.ts";
import { color, font, leading, space, text } from "../styles/tokens.stylex.ts";

// One question per screen, and a rail that fills in as answers arrive.
// The authorization is the second step, before any secret is typed,
// because it is a full-page redirect through Cloudflare's consent and a
// secret must never have to survive one: the draft that does survive it
// holds names, addresses, and vars, and nothing else.

const styles = stylex.create({
  layout: {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 360px)",
    gap: space.s8,
    "@media (max-width: 1000px)": { gridTemplateColumns: "minmax(0, 1fr)" },
  },
  column: { display: "flex", flexDirection: "column", gap: space.s6 },
  steps: {
    display: "flex",
    gap: space.s4,
    fontFamily: font.ui,
    fontSize: text.label,
    lineHeight: leading.label,
    textTransform: "uppercase",
    letterSpacing: "0.08em",
    color: color.lineStrong,
    flexWrap: "wrap",
  },
  stepDone: { color: color.muted },
  stepHere: { color: color.text },
  actions: { display: "flex", gap: space.s3 },
  rail: { display: "flex", flexDirection: "column", gap: space.s3 },
  railRow: {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 2fr)",
    gap: space.s3,
    fontFamily: font.mono,
    fontSize: text.spec,
    lineHeight: leading.spec,
    color: color.text,
    overflowWrap: "anywhere",
  },
  railLabel: { color: color.muted, fontFamily: font.ui },
  group: { display: "flex", flexDirection: "column", gap: space.s5 },
});

const loadDraft = (): wizard.Draft => {
  try {
    const stored = window.sessionStorage.getItem(wizard.DRAFT_KEY);
    return stored === null ? wizard.emptyDraft() : (JSON.parse(stored) as wizard.Draft);
  } catch {
    return wizard.emptyDraft();
  }
};

const saveDraft = (draft: wizard.Draft) => {
  try {
    window.sessionStorage.setItem(wizard.DRAFT_KEY, JSON.stringify(draft));
  } catch {
    // A browser that refuses storage still runs the wizard; the draft
    // just does not survive the authorization's redirect.
  }
};

const clearDraft = () => {
  try {
    window.sessionStorage.removeItem(wizard.DRAFT_KEY);
  } catch {
    // Nothing to clear.
  }
};

export const NewInstance = () => {
  const navigate = useNavigate();
  const [draft, setDraft] = useState<wizard.Draft>(loadDraft);
  const update = (patch: Partial<wizard.Draft>) =>
    setDraft((current) => {
      const next = { ...current, ...patch };
      saveDraft(next);
      return next;
    });
  const go = (step: wizard.StepName) => update({ step });
  // Secrets live here and nowhere else: not in the draft, not in storage.
  const [secrets, setSecrets] = useState<Record<string, string>>({});
  const [generated, setGenerated] = useState<Record<string, NixKeyPair>>({});
  const [downloaded, setDownloaded] = useState<Record<string, boolean>>({});
  const [plan, setPlan] = useState<Plan | undefined>(undefined);

  const products = useQuery({ queryKey: ["products"], queryFn: api.getProducts });
  const me = useQuery({ queryKey: ["me"], queryFn: api.getMe });
  const manifest = useQuery({
    queryKey: ["manifest", draft.product, draft.version],
    queryFn: () => api.getManifest(draft.product, draft.version),
    enabled: draft.product !== "" && draft.version !== "",
    staleTime: Number.POSITIVE_INFINITY,
  });
  const authorization = useQuery({
    queryKey: ["authorization", draft.accountId],
    queryFn: () => api.getAuthorization(draft.accountId),
    enabled: draft.accountId !== "",
    refetchInterval: 30_000,
  });
  const authorized = authorization.data?.authorized === true;

  const resource = wizard.resourceName(draft.product, draft.name);
  const host = wizard.draftHost(draft, resource);

  const deploy = useMutation({
    mutationFn: async () => {
      const created = await api.createInstance({
        product: draft.product,
        version: draft.version,
        name: draft.name,
        accountId: draft.accountId,
        route: draft.route,
        vars: wizard.varsToSend(draft.vars),
        generatedPublic: Object.fromEntries(
          Object.entries(generated).map(([name, pair]) => [name, pair.publicKey]),
        ),
        autoUpdate: draft.autoUpdate,
      });
      setPlan(created.plan);
      const provisioned = await api.provision(created.id);
      const values: Record<string, string> = { ...wizard.varsToSend(secrets) };
      for (const [name, pair] of Object.entries(generated)) values[name] = pair.secret;
      await api.postSecrets(provisioned.agentUrl, provisioned.secretsGrant.grant, values);
      return created.id;
    },
    onSuccess: (id) => {
      clearDraft();
      void navigate({ to: "/instances/$id", params: { id }, search: { tab: "overview" } });
    },
  });

  const stepIndex = wizard.STEPS.indexOf(draft.step);

  return (
    <div {...stylex.props(styles.layout)}>
      <div {...stylex.props(styles.column)}>
        <Intro>
          <Label>New instance</Label>
          <ol {...stylex.props(styles.steps)}>
            {wizard.STEPS.map((step, index) => (
              <li
                key={step}
                {...stylex.props(
                  index < stepIndex && styles.stepDone,
                  index === stepIndex && styles.stepHere,
                )}
              >
                {index + 1} {wizard.stepTitle(step)}
              </li>
            ))}
          </ol>
        </Intro>

        {draft.step === "product" && (
          <div {...stylex.props(styles.group)}>
            {products.isPending || me.isPending ? <LoadingScreen /> : null}
            {products.error ? <Failed message={String(products.error)} /> : null}
            {products.data && me.data ? (
              <>
                <div>
                  <Label>Product</Label>
                  <Segmented
                    label="Product"
                    options={products.data.products
                      .filter((product) => product.promoted !== undefined)
                      .map((product) => ({ value: product.name, label: `${product.name} ${product.promoted ?? ""}` }))}
                    value={draft.product}
                    onChange={(name) =>
                      update({
                        product: name,
                        version: products.data.products.find((product) => product.name === name)?.promoted ?? "",
                      })
                    }
                  />
                </div>
                <div>
                  <Label>Cloudflare account</Label>
                  <Segmented
                    label="Account"
                    options={me.data.accounts.map((account) => ({ value: account.id, label: account.name }))}
                    value={draft.accountId}
                    onChange={(accountId) => update({ accountId })}
                  />
                </div>
                <div {...stylex.props(styles.actions)}>
                  <Button
                    kind="primary"
                    disabled={draft.product === "" || draft.accountId === ""}
                    onClick={() => go("authorize")}
                  >
                    Continue
                  </Button>
                </div>
              </>
            ) : null}
          </div>
        )}

        {draft.step === "authorize" && (
          <div {...stylex.props(styles.group)}>
            <Prose>
              Deploying creates resources in your account and mints the token
              the agent will run under. Cloudflare asks you to allow that for
              this account, once, for this operation: the permission lasts an
              hour, is never refreshed, and is dropped when the deploy ends.
            </Prose>
            {authorized ? (
              <>
                <Note title="Authorized">
                  This account is authorized until the token expires. Continue to
                  choose a name and address.
                </Note>
                <div {...stylex.props(styles.actions)}>
                  <Button onClick={() => go("product")}>Back</Button>
                  <Button kind="primary" onClick={() => go("address")}>
                    Continue
                  </Button>
                </div>
              </>
            ) : (
              <div {...stylex.props(styles.actions)}>
                <Button onClick={() => go("product")}>Back</Button>
                <Button
                  kind="primary"
                  onClick={() => {
                    void api
                      .startAccountAuthorization(draft.accountId, "/instances/new")
                      .then((started) => window.location.assign(started.url));
                  }}
                >
                  Authorize with Cloudflare
                </Button>
              </div>
            )}
          </div>
        )}

        {draft.step === "address" && manifest.data && (
          <AddressStep
            draft={draft}
            manifest={manifest.data}
            authorized={authorized}
            update={update}
            onBack={() => go("authorize")}
            onNext={() => go("configuration")}
          />
        )}

        {draft.step === "configuration" && manifest.data && (
          <ConfigurationStep
            draft={draft}
            manifest={manifest.data}
            host={host}
            update={update}
            onBack={() => go("address")}
            onNext={() => go("secrets")}
          />
        )}

        {draft.step === "secrets" && manifest.data && (
          <SecretsStep
            manifest={manifest.data}
            host={host}
            secrets={secrets}
            setSecrets={setSecrets}
            generated={generated}
            setGenerated={setGenerated}
            downloaded={downloaded}
            setDownloaded={setDownloaded}
            onBack={() => go("configuration")}
            onNext={() => go("options")}
          />
        )}

        {draft.step === "options" && manifest.data && (
          <OptionsStep
            draft={draft}
            manifest={manifest.data}
            update={update}
            onBack={() => go("secrets")}
            onNext={() => go("deploy")}
          />
        )}

        {draft.step === "deploy" && (
          <div {...stylex.props(styles.group)}>
            <Prose>
              The record is created, the agent is installed in your account
              under the authorization you gave, and the secrets go from this
              browser to the agent. Then the agent installs {draft.product}{" "}
              and you watch each step.
            </Prose>
            {!authorized ? (
              <Note title="The authorization expired">
                Go back to the authorize step and allow the operation again;
                everything you typed is kept.
              </Note>
            ) : null}
            {deploy.error ? <Failed message={String(deploy.error)} /> : null}
            <div {...stylex.props(styles.actions)}>
              <Button onClick={() => go("options")} disabled={deploy.isPending}>
                Back
              </Button>
              <Button
                kind="primary"
                disabled={!authorized || deploy.isPending}
                onClick={() => deploy.mutate()}
              >
                {deploy.isPending ? "Deploying" : "Deploy"}
              </Button>
            </div>
          </div>
        )}
        {(draft.step === "address" || draft.step === "configuration" || draft.step === "secrets" || draft.step === "options") &&
        manifest.isPending ? (
          <LoadingScreen />
        ) : null}
        {manifest.error ? <Failed message={String(manifest.error)} /> : null}
      </div>

      <Panel title="What will be created">
        <div {...stylex.props(styles.rail)}>
          {(plan
            ? wizard.railRows(plan)
            : [
                { label: "product", value: draft.product || "—" },
                { label: "worker", value: draft.name === "" ? "—" : resource },
                { label: "address", value: draft.name === "" ? "—" : host },
              ]
          ).map((row) => (
            <div key={`${row.label}:${row.value}`} {...stylex.props(styles.railRow)}>
              <span {...stylex.props(styles.railLabel)}>{row.label}</span>
              <span>{row.value}</span>
            </div>
          ))}
        </div>
      </Panel>
    </div>
  );
};

const AddressStep = ({
  draft,
  manifest,
  authorized,
  update,
  onBack,
  onNext,
}: {
  draft: wizard.Draft;
  manifest: Manifest;
  authorized: boolean;
  update: (patch: Partial<wizard.Draft>) => void;
  onBack: () => void;
  onNext: () => void;
}) => {
  const zones = useQuery({
    queryKey: ["zones", draft.accountId],
    queryFn: () => api.getZones(draft.accountId),
    enabled: authorized && manifest.route.customDomain !== "none",
  });
  const [checked, setChecked] = useState<Verdict | undefined>(undefined);
  useEffect(() => {
    if (draft.name === "") {
      setChecked(undefined);
      return;
    }
    if (!wizard.nameIsValid(draft.name)) {
      setChecked({ tone: "refused", text: "A lowercase word of 2 to 32 characters: a letter, then letters, digits, and dashes." });
      return;
    }
    setChecked({ tone: "checking", text: "Checking the account" });
    const timer = window.setTimeout(() => {
      void api
        .checkNames({ accountId: draft.accountId, product: draft.product, name: draft.name })
        .then((answer) => {
          if (!answer.valid) {
            setChecked({ tone: "refused", text: "This name is outside the grammar." });
          } else if (answer.worker === undefined || answer.worker.kind === "absent") {
            setChecked({ tone: "ok", text: `Resources will be named ${answer.resourceName}.` });
          } else if (answer.worker.kind === "otherInstance") {
            setChecked({ tone: "refused", text: "This name belongs to another instance of yours." });
          } else {
            setChecked({ tone: "refused", text: `The account already holds a worker named ${answer.resourceName} that was not deployed here.` });
          }
        })
        .catch((failure: unknown) => setChecked({ tone: "refused", text: String(failure) }));
    }, 400);
    return () => window.clearTimeout(timer);
  }, [draft.name, draft.accountId, draft.product]);

  const routeOptions = [
    ...(manifest.route.customDomain === "none"
      ? []
      : [{ value: "customDomain" as const, label: "custom domain", description: "A hostname in a zone this account holds. The deployer attaches it and Cloudflare issues the certificate." }]),
    ...(manifest.route.workersDev
      ? [{ value: "workersDev" as const, label: "workers.dev", description: "The account's workers.dev subdomain. Assigned when the deploy runs." }]
      : []),
  ];
  const route: Route = draft.route;
  const hostnameOk =
    route.kind !== "customDomain" ||
    (route.hostname !== "" && (zones.data?.zones.some((zone) => route.hostname === zone.name || route.hostname.endsWith(`.${zone.name}`)) ?? true));

  return (
    <div {...stylex.props(styles.group)}>
      <Field
        label="Name"
        help="Names the instance here and every resource in your account. Two instances in one account cannot share it."
        value={draft.name}
        onChange={(name) => update({ name })}
        placeholder="production"
        {...(checked === undefined ? {} : { verdict: checked })}
        autoFocus
      />
      {routeOptions.length > 1 ? (
        <Choice
          label="Address"
          options={routeOptions}
          value={route.kind}
          onChange={(kind) =>
            update({ route: kind === "customDomain" ? { kind, hostname: "", zoneId: "" } : { kind } })
          }
        />
      ) : null}
      {route.kind === "customDomain" ? (
        <>
          {zones.data && zones.data.zones.length > 0 ? (
            <div>
              <Label>Zone</Label>
              <Segmented
                label="Zone"
                options={zones.data.zones.map((zone) => ({ value: zone.id, label: zone.name }))}
                value={route.zoneId}
                onChange={(zoneId) => {
                  const zone = zones.data.zones.find((candidate) => candidate.id === zoneId);
                  update({
                    route: {
                      kind: "customDomain",
                      zoneId,
                      hostname: zone === undefined ? route.hostname : `${draft.name === "" ? "cache" : draft.name}.${zone.name}`,
                    },
                  });
                }}
              />
            </div>
          ) : null}
          {zones.data && zones.data.zones.length === 0 ? (
            <Note title="No zones in this account">
              A custom domain needs a zone here. Add one in the Cloudflare
              dashboard, or choose workers.dev.
            </Note>
          ) : null}
          <Field
            label="Hostname"
            help={
              manifest.route.hostIsIdentity
                ? "This address names the signing key and appears in every signature. Moving it later is a key rotation, so choose it once."
                : "The hostname the product answers on, inside the chosen zone."
            }
            value={route.hostname}
            onChange={(hostname) => update({ route: { ...route, hostname } })}
            placeholder="cache.example.com"
            {...(route.hostname !== "" && !hostnameOk
              ? { verdict: { tone: "refused" as const, text: "The hostname must be inside the chosen zone." } }
              : {})}
          />
        </>
      ) : null}
      <div {...stylex.props(styles.actions)}>
        <Button onClick={onBack}>Back</Button>
        <Button
          kind="primary"
          disabled={
            checked?.tone !== "ok" ||
            !hostnameOk ||
            (route.kind === "customDomain" && route.zoneId === "")
          }
          onClick={onNext}
        >
          Continue
        </Button>
      </div>
    </div>
  );
};

const VarField = ({
  spec,
  value,
  host,
  name,
  onChange,
}: {
  spec: Manifest["vars"][number];
  value: string;
  host: string;
  name: string;
  onChange: (next: string) => void;
}) => {
  const wizardHints = spec.wizard;
  return (
    <Field
      label={wizardHints?.label ?? spec.name}
      help={wizardHints?.help ?? spec.summary}
      value={value}
      onChange={onChange}
      {...(spec.default === undefined ? {} : { placeholder: spec.default })}
    >
      {wizardHints?.setupSteps !== undefined && wizardHints.setupSteps.length > 0 ? (
        <SetupSteps
          steps={wizardHints.setupSteps}
          {...(wizardHints.consoleUrl === undefined ? {} : { consoleUrl: wizardHints.consoleUrl })}
        />
      ) : null}
      {wizardHints?.redirectUriTemplate === undefined ? null : (
        <Command>{wizard.renderTemplate(wizardHints.redirectUriTemplate, { host, name })}</Command>
      )}
    </Field>
  );
};

const ConfigurationStep = ({
  draft,
  manifest,
  host,
  update,
  onBack,
  onNext,
}: {
  draft: wizard.Draft;
  manifest: Manifest;
  host: string;
  update: (patch: Partial<wizard.Draft>) => void;
  onBack: () => void;
  onNext: () => void;
}) => {
  const asked = useMemo(() => wizard.askedVars(manifest), [manifest]);
  // The host var is the address step's answer.
  const hostName = wizard.hostVar(manifest);
  useEffect(() => {
    if (hostName !== undefined && draft.route.kind === "customDomain" && draft.vars[hostName] !== draft.route.hostname) {
      update({ vars: { ...draft.vars, [hostName]: draft.route.hostname } });
    }
  }, [hostName, draft.route, draft.vars, update]);
  const missing = wizard.missingVars(manifest, draft.vars);
  return (
    <div {...stylex.props(styles.group)}>
      {asked.required.map((spec) => (
        <VarField
          key={spec.name}
          spec={spec}
          value={draft.vars[spec.name] ?? ""}
          host={host}
          name={draft.name}
          onChange={(value) => update({ vars: { ...draft.vars, [spec.name]: value } })}
        />
      ))}
      <div {...stylex.props(styles.actions)}>
        <Button onClick={onBack}>Back</Button>
        <Button kind="primary" disabled={missing.length > 0} onClick={onNext}>
          Continue
        </Button>
      </div>
    </div>
  );
};

const SecretsStep = ({
  manifest,
  host,
  secrets,
  setSecrets,
  generated,
  setGenerated,
  downloaded,
  setDownloaded,
  onBack,
  onNext,
}: {
  manifest: Manifest;
  host: string;
  secrets: Record<string, string>;
  setSecrets: (next: Record<string, string>) => void;
  generated: Record<string, NixKeyPair>;
  setGenerated: (next: Record<string, NixKeyPair>) => void;
  downloaded: Record<string, boolean>;
  setDownloaded: (next: Record<string, boolean>) => void;
  onBack: () => void;
  onNext: () => void;
}) => {
  const asked = useMemo(() => wizard.askedSecrets(manifest), [manifest]);
  useEffect(() => {
    for (const spec of asked.generated) {
      if (generated[spec.name] !== undefined || spec.generated?.kind !== "ed25519NixKey") continue;
      void generateNixKey(keyNameFor(spec.generated.keyName, host)).then((pair) =>
        setGenerated({ ...generated, [spec.name]: pair }),
      );
    }
  }, [asked.generated, generated, host, setGenerated]);
  const allValues = { ...secrets, ...Object.fromEntries(Object.entries(generated).map(([name, pair]) => [name, pair.secret])) };
  const missing = wizard.missingSecrets(manifest, allValues);
  const undownloaded = asked.generated.some((spec) => downloaded[spec.name] !== true);
  return (
    <div {...stylex.props(styles.group)}>
      {asked.generated.map((spec) => {
        const pair = generated[spec.name];
        return (
          <div key={spec.name} {...stylex.props(styles.group)}>
            <Label>{spec.wizard?.label ?? spec.name}</Label>
            <Prose>{spec.wizard?.help ?? spec.summary}</Prose>
            {pair === undefined ? (
              <Prose>Generating</Prose>
            ) : (
              <KeyPair
                publicKey={pair.publicKey}
                secret={pair.secret}
                filename={`${pair.publicKey.split(":")[0] ?? spec.name}.secret`}
                downloaded={downloaded[spec.name] === true}
                onDownloaded={() => setDownloaded({ ...downloaded, [spec.name]: true })}
              />
            )}
          </div>
        );
      })}
      {asked.typed.map((spec) => (
        <div key={spec.name}>
          {spec.wizard?.setupSteps !== undefined && spec.wizard.setupSteps.length > 0 ? (
            <SetupSteps
              steps={spec.wizard.setupSteps}
              {...(spec.wizard.consoleUrl === undefined ? {} : { consoleUrl: spec.wizard.consoleUrl })}
            />
          ) : null}
          <Secret
            label={`${spec.wizard?.label ?? spec.name}${spec.requirement === "optional" ? " (optional)" : ""}`}
            help={spec.wizard?.help ?? spec.summary}
            configured={false}
            onSave={(value) => setSecrets({ ...secrets, [spec.name]: value })}
          />
        </div>
      ))}
      <Prose>
        These values go from this browser to the agent in your account, under a
        grant the deployer signs, and the deployer never sees them.
      </Prose>
      <div {...stylex.props(styles.actions)}>
        <Button onClick={onBack}>Back</Button>
        <Button kind="primary" disabled={missing.length > 0 || undownloaded} onClick={onNext}>
          {undownloaded && missing.length === 0 ? "Download the key to continue" : "Continue"}
        </Button>
      </div>
    </div>
  );
};

const OptionsStep = ({
