import { latestOperation, stepRows } from "../lib/steps.ts";
import * as wizard from "../lib/wizard.ts";
import { color, font, leading, space, text } from "../styles/tokens.stylex.ts";

// One instance: its facts, and five tabs that change it. Every change is
// a request to the control plane, which the agent then applies, and the
// steps that follow arrive over the event stream.

const TABS = ["overview", "configuration", "secrets", "updates", "uninstall"] as const;
export type Tab = (typeof TABS)[number];
export const readTab = (value: unknown): Tab =>
  TABS.includes(value as Tab) ? (value as Tab) : "overview";

const styles = stylex.create({
  head: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: space.s6 },
  title: {
    fontFamily: font.mono,
    fontSize: text.h3,
    lineHeight: leading.h3,
    color: color.text,
    margin: 0,
  },
  facts: {
    display: "flex",
    gap: space.s4,
    fontFamily: font.ui,
    fontSize: text.spec,
    lineHeight: leading.spec,
    color: color.muted,
    flexWrap: "wrap",
  },
  group: { display: "flex", flexDirection: "column", gap: space.s5 },
  actions: { display: "flex", gap: space.s3 },
  rows: { display: "flex", flexDirection: "column" },
  row: {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) minmax(0, 2fr)",
    gap: space.s4,
    paddingBlock: space.s3,
    borderBottomWidth: "1px",
    borderBottomStyle: "solid",
    borderBottomColor: color.line,
    fontFamily: font.mono,
    fontSize: text.spec,
