    margin: 0,
    paddingLeft: space.s5,
  },
});

const statusTone = (status: InstanceDetail["summary"]["status"]) =>
  status === "failed" ? "signal" : status === "ready" ? "text" : status === "unreachable" ? "amber" : "muted";

export const Instance = () => {
  const { id } = useParams({ from: "/instances/$id" });
  const { tab } = useSearch({ from: "/instances/$id" });
  const navigate = useNavigate();
  const detail = useQuery({
    queryKey: ["instance", id],
    queryFn: () => api.getInstance(id),
    refetchInterval: (query) => {
      const status = query.state.data?.summary.status;
      return status === "applying" || status === "provisioning" || status === "uninstalling" ? 3_000 : 30_000;
    },
  });
  const manifest = useQuery({
    queryKey: ["manifest", detail.data?.desired.product, detail.data?.desired.version],
    queryFn: () => api.getManifest(detail.data?.desired.product ?? "", detail.data?.desired.version ?? ""),
    enabled: detail.data !== undefined,
    staleTime: Number.POSITIVE_INFINITY,
  });
  const stream = useEvents(id);

  if (detail.isPending) return <LoadingScreen />;
  if (detail.error) return <Failed message={String(detail.error)} />;
  const summary = detail.data.summary;

  return (
    <>
      <div {...stylex.props(styles.head)}>
        <Intro>
          <Label>{summary.product}</Label>
          <h1 {...stylex.props(styles.title)}>{summary.name}</h1>
          <div {...stylex.props(styles.facts)}>
            <span>{summary.host === "" ? "workers.dev, assigned at deploy" : summary.host}</span>
            <span>{summary.accountName}</span>
            <span>
              {summary.installedVersion ?? "not installed"}
              {summary.installedVersion !== undefined && summary.installedVersion !== summary.desiredVersion
                ? ` → ${summary.desiredVersion}`
                : ""}
            </span>
            <Pill tone={statusTone(summary.status)}>{summary.status}</Pill>
            {detail.data.updateAvailable === undefined || summary.status === "uninstalled" ? null : (
              <Pill tone="text">update available</Pill>
            )}
            {stream.connected ? null : <Pill>reconnecting</Pill>}
          </div>
        </Intro>
        <Segmented
          label="Tab"
          options={TABS.map((name) => ({ value: name, label: name }))}
          value={tab}
          onChange={(next) => void navigate({ to: "/instances/$id", params: { id }, search: { tab: next } })}
        />
      </div>
      {tab === "overview" && <Overview detail={detail.data} events={stream.events} />}
      {tab === "configuration" && manifest.data && (
        <Configuration id={id} detail={detail.data} manifest={manifest.data} />
      )}
      {tab === "secrets" && manifest.data && <Secrets id={id} detail={detail.data} manifest={manifest.data} />}
      {tab === "updates" && <Updates id={id} detail={detail.data} />}
      {tab === "uninstall" && manifest.data && (
        <Uninstall id={id} detail={detail.data} manifest={manifest.data} events={stream.events} />
      )}
      {tab !== "overview" && tab !== "updates" && manifest.isPending ? <LoadingScreen /> : null}
    </>
  );
};

const Overview = ({ detail, events }: { detail: InstanceDetail; events: ReturnType<typeof useEvents>["events"] }) => {
  const latest = latestOperation(events) ?? detail.operations[0]?.id;
  const rows = latest === undefined ? [] : stepRows(events, latest);
  const agent = detail.agent;
  return (
    <>
      <Tiles
        tiles={[
          { label: "Status", value: detail.summary.status, ...(detail.summary.status === "failed" ? { tone: "signal" as const } : {}) },
          { label: "Installed", value: agent?.installedVersion ?? "—" },
          { label: "Desired", value: `${detail.desired.version} · rev ${detail.desired.revision}` },
          { label: "Agent last seen", value: agent === undefined ? "—" : format.stamp(agent.lastReconcileAtMs), ...(agent === undefined ? { tone: "muted" as const } : {}) },
        ]}
      />
      {agent?.lastError === undefined ? null : (
        <Note title="The agent reported a problem">{agent.lastError}</Note>
      )}
      {latest === undefined ? (
        <Note title="Nothing has run yet">
          The agent has not started an operation for this instance. If the
          deploy just began, the first steps arrive here as they happen.
        </Note>
      ) : (
        <Panel title={`Operation ${latest}`}>
          <Steps rows={rows} />
        </Panel>
      )}
      <Panel title="Operations">
        <div {...stylex.props(styles.rows)}>
          {detail.operations.map((operation) => (
            <div key={operation.id} {...stylex.props(styles.row)}>
              <span {...stylex.props(styles.rowLabel)}>
                {operation.id} · {operation.operation}
              </span>
              <span>
                {operation.outcome} · started {format.stamp(operation.startedAtMs)}
                {operation.finishedAtMs === undefined ? "" : `, ${format.duration(operation.finishedAtMs - operation.startedAtMs)}`}
              </span>
            </div>
          ))}
        </div>
      </Panel>
    </>
  );
};

const Configuration = ({ id, detail, manifest }: { id: string; detail: InstanceDetail; manifest: Manifest }) => {
  const queryClient = useQueryClient();
  const asked = useMemo(() => wizard.askedVars(manifest), [manifest]);
  const [values, setValues] = useState<Record<string, string>>({ ...detail.desired.vars });
  const [preview, setPreview] = useState<PatchPreview | undefined>(undefined);
  const changed = Object.fromEntries(
    [...asked.required, ...asked.advanced]
      .map((spec) => spec.name)
      .filter((name) => (values[name] ?? "") !== (detail.desired.vars[name] ?? ""))
      .map((name) => [name, values[name] ?? ""]),
  );
  const previewChange = useMutation({
    mutationFn: () => api.previewDesired(id, { vars: changed }),
    onSuccess: setPreview,
  });
  const apply = useMutation({
    mutationFn: () => api.patchDesired(id, { vars: changed }),
    onSuccess: () => {
      setPreview(undefined);
      void queryClient.invalidateQueries({ queryKey: ["instance", id] });
    },
  });
  const hostName = wizard.hostVar(manifest);
  return (
    <div {...stylex.props(styles.group)}>
      <Panel title="Fixed" aside="changing these is a new instance">
        <div {...stylex.props(styles.rows)}>
          <div {...stylex.props(styles.row)}>
            <span {...stylex.props(styles.rowLabel)}>name</span>
            <span>{detail.summary.name}</span>
          </div>
          <div {...stylex.props(styles.row)}>
            <span {...stylex.props(styles.rowLabel)}>host</span>
            <span>{detail.summary.host}</span>
          </div>
        </div>
      </Panel>
      {[...asked.required, ...asked.advanced]
        .filter((spec) => spec.name !== hostName)
        .map((spec) => (
          <Field
            key={spec.name}
            label={spec.wizard?.label ?? spec.name}
            help={spec.wizard?.help ?? spec.summary}
            value={values[spec.name] ?? ""}
            onChange={(value) => setValues({ ...values, [spec.name]: value })}
            {...(spec.default === undefined ? {} : { placeholder: spec.default })}
          />
        ))}
      {previewChange.error ? <Failed message={String(previewChange.error)} /> : null}
      {apply.error ? <Failed message={String(apply.error)} /> : null}
      <div {...stylex.props(styles.actions)}>
        <Button
          kind="primary"
          disabled={Object.keys(changed).length === 0 || previewChange.isPending}
          onClick={() => previewChange.mutate()}
        >
          Review changes
        </Button>
        <Button onClick={() => setValues({ ...detail.desired.vars })}>Reset</Button>
      </div>
      <Confirm
        open={preview !== undefined}
        onClose={() => setPreview(undefined)}
        title="Apply this configuration"
        confirmLabel="Apply"
        busy={apply.isPending}
        onConfirm={() => apply.mutate()}
      >
        <Prose>
          The agent uploads the worker again with these values; the release,
          the secrets, and everything in the account stay as they are.
        </Prose>
        <ul {...stylex.props(styles.list)}>
          {Object.entries(changed).map(([name, value]) => (
            <li key={name}>
              <Mono>{name}</Mono> {value === "" ? "removed" : `= ${value}`}
            </li>
          ))}
        </ul>
      </Confirm>
    </div>
  );
};

const Secrets = ({ id, detail, manifest }: { id: string; detail: InstanceDetail; manifest: Manifest }) => {
  const queryClient = useQueryClient();
  const asked = useMemo(() => wizard.askedSecrets(manifest), [manifest]);
  const agentUrl = detail.agentUrl;
  const [rotation, setRotation] = useState<{ name: string; pair: NixKeyPair; downloaded: boolean } | undefined>(undefined);
  const replace = useMutation({
    mutationFn: async ({ name, value }: { name: string; value: string }) => {
      if (agentUrl === undefined) throw new Error("the agent is not installed yet");
      const grant = await api.issueGrant(id, { purpose: "secrets", secretNames: [name] });
      await api.postSecrets(agentUrl, grant.grant, { [name]: value });
    },
  });
  const rotate = useMutation({
    mutationFn: async () => {
      if (rotation === undefined || agentUrl === undefined) return;
      const spec = manifest.secrets.find((candidate) => candidate.name === rotation.name);
      const grant = await api.issueGrant(id, { purpose: "secrets", secretNames: [rotation.name] });
      await api.postSecrets(agentUrl, grant.grant, { [rotation.name]: rotation.pair.secret });
      const previous = detail.desired.generatedPublic?.[rotation.name];
      const previousVar = spec?.generated?.kind === "ed25519NixKey" ? spec.generated.previousKeysVar : undefined;
      const vars: Record<string, string> = {};
      if (previousVar !== undefined && previous !== undefined) {
        const listed = (detail.desired.vars[previousVar] ?? "").split(",").map((key) => key.trim()).filter(Boolean);
        vars[previousVar] = [...listed, previous].join(",");
      }
      await api.patchDesired(id, {
        generatedPublic: { [rotation.name]: rotation.pair.publicKey },
        ...(Object.keys(vars).length > 0 ? { vars } : {}),
      });
    },
    onSuccess: () => {
      setRotation(undefined);
      void queryClient.invalidateQueries({ queryKey: ["instance", id] });
    },
  });
  if (agentUrl === undefined) {
    return <Note title="Not installed yet">Secrets can be set once the agent is in the account.</Note>;
  }
  return (
    <div {...stylex.props(styles.group)}>
      <Prose>
        A secret goes from this browser to the agent in your account, under a
        grant the deployer signs for that one name. The deployer never sees the
        value, and the agent forgets it once it is set.
      </Prose>
      {asked.generated.map((spec) => {
        const current = detail.desired.generatedPublic?.[spec.name];
        return (
          <Panel key={spec.name} title={spec.wizard?.label ?? spec.name}>
            {current === undefined ? null : (
              <KeyPair publicKey={current} filename="" {...(detail.agent?.publicKey === undefined ? {} : { servedKey: detail.agent.publicKey })} />
            )}
            {rotation?.name === spec.name ? (
              <>
                <Prose>
                  The new key. Download it, then apply: the agent sets it, and
                  laptops re-run setup to trust it.
                </Prose>
                <KeyPair
                  publicKey={rotation.pair.publicKey}
                  secret={rotation.pair.secret}
                  filename={`${rotation.pair.publicKey.split(":")[0] ?? spec.name}.secret`}
                  downloaded={rotation.downloaded}
                  onDownloaded={() => setRotation({ ...rotation, downloaded: true })}
                />
                <div {...stylex.props(styles.actions)}>
                  <Button kind="primary" disabled={!rotation.downloaded || rotate.isPending} onClick={() => rotate.mutate()}>
                    Apply rotation
                  </Button>
                  <Button onClick={() => setRotation(undefined)}>Cancel</Button>
                </div>
              </>
            ) : (
              <div>
                <Button
                  onClick={() => {
                    void generateNixKey(nextKeyName(current, detail.summary.host)).then((pair) =>
                      setRotation({ name: spec.name, pair, downloaded: false }),
                    );
                  }}
                >
                  Rotate
                </Button>
              </div>
            )}
          </Panel>
        );
      })}
      {asked.typed.map((spec) => (
        <Secret
          key={spec.name}
          label={spec.wizard?.label ?? spec.name}
          help={spec.wizard?.help ?? spec.summary}
          configured
          saving={replace.isPending}
          onSave={(value) => replace.mutate({ name: spec.name, value })}
        />
      ))}
      {replace.error ? <Failed message={String(replace.error)} /> : null}
      {rotate.error ? <Failed message={String(rotate.error)} /> : null}
    </div>
  );
};

const Updates = ({ id, detail }: { id: string; detail: InstanceDetail }) => {
  const queryClient = useQueryClient();
  const releases = useQuery({
    queryKey: ["releases", detail.desired.product],
    queryFn: () => api.getReleases(detail.desired.product),
  });
  const [preview, setPreview] = useState<PatchPreview | undefined>(undefined);
  const [neededSecrets, setNeededSecrets] = useState<Record<string, string>>({});
  const previewUpdate = useMutation({
    mutationFn: (version: string) => api.previewDesired(id, { version }),
