  });
  const applyUpdate = useMutation({
    mutationFn: async () => {
      if (preview === undefined) return;
      const updated = await api.patchDesired(id, { version: preview.desired.version });
      if (preview.secretsNeeded.length > 0 && detail.agentUrl !== undefined) {
        const grant = await api.issueGrant(id, { purpose: "secrets", secretNames: preview.secretsNeeded });
        await api.postSecrets(detail.agentUrl, grant.grant, neededSecrets);
      }
      return updated;
    },
    onSuccess: () => {
      setPreview(undefined);
      void queryClient.invalidateQueries({ queryKey: ["instance", id] });
    },
  });
  const policy = useMutation({
    mutationFn: (autoUpdate: InstanceDetail["desired"]["autoUpdate"]) => api.patchDesired(id, { autoUpdate }),
    onSuccess: () => void queryClient.invalidateQueries({ queryKey: ["instance", id] }),
  });
  const auto = detail.desired.autoUpdate;
  return (
    <div {...stylex.props(styles.group)}>
      <Tiles
        tiles={[
          { label: "Installed", value: detail.agent?.installedVersion ?? "—" },
          { label: "Desired", value: detail.desired.version },
          { label: "Promoted", value: releases.data?.releases.find((release) => release.promoted)?.version ?? "—" },
          { label: "Policy", value: auto.hold ? "held" : auto.enabled ? `automatic, ${auto.delayHours}h` : "manual" },
        ]}
      />
      <Choice
        label="Updates"
