const Uninstall = ({
  id,
  detail,
  manifest,
  events,
}: {
  id: string;
  detail: InstanceDetail;
  manifest: Manifest;
  events: ReturnType<typeof useEvents>["events"];
}) => {
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [deleteBucket, setDeleteBucket] = useState<"keep" | "delete">("keep");
  const authorization = useQuery({
    queryKey: ["authorization", detail.summary.accountId],
    queryFn: () => api.getAuthorization(detail.summary.accountId),
    refetchInterval: 30_000,
  });
  const authorized = authorization.data?.authorized === true;
  const begin = useMutation({
    mutationFn: async () => {
      const started = await api.uninstall(id, { deleteBucket: deleteBucket === "delete" });
      if (started.deleteBucketGrant !== undefined && detail.agentUrl !== undefined) {
        await api.confirmDeleteBucket(detail.agentUrl, started.deleteBucketGrant.grant, detail.summary.name);
      }
    },
    onSuccess: () => {
      setOpen(false);
      void queryClient.invalidateQueries({ queryKey: ["instance", id] });
    },
  });
  const teardown = detail.operations.find((operation) => operation.operation === "uninstall");
  const bucketNames = manifest.vars.length > 0 ? ["every object it holds"] : [];
  if (detail.summary.status === "uninstalled") {
    return <Note title="Uninstalled">The worker, its namespace, its schedule, its address, the agent, and the agent's token are gone from the account.</Note>;
  }
  return (
    <div {...stylex.props(styles.group)}>
      <Prose>
        Uninstalling removes what the deployer created in your account. The
        agent tears the product down first, then the deployer removes the agent
        and revokes its token, which is why this asks for a fresh Cloudflare
        authorization.
      </Prose>
      {teardown === undefined ? null : (
        <Panel title={`Operation ${teardown.id}`}>
          <Steps rows={stepRows(events, teardown.id)} />
        </Panel>
      )}
      {detail.authorizationRequired ? (
        <Note title="Authorize to finish">
          The agent has finished. Removing the agent and its token needs one
          more authorization; then press Uninstall again.
        </Note>
      ) : null}
      <div {...stylex.props(styles.actions)}>
        {authorized ? (
          <Button kind="destructive" onClick={() => setOpen(true)}>
            Uninstall {detail.summary.name}
          </Button>
        ) : (
          <Button
            kind="primary"
            onClick={() => {
              void api
                .startInstanceAuthorization(id)
                .then((started) => window.location.assign(started.url));
            }}
          >
            Authorize with Cloudflare
          </Button>
        )}
      </div>
      {begin.error ? <Failed message={String(begin.error)} /> : null}
      <Confirm
        open={open}
        onClose={() => setOpen(false)}
        title={`Uninstall ${detail.summary.name}`}
        confirmLabel="Uninstall"
        destructive
        busy={begin.isPending}
        typed={{ expected: detail.summary.name, label: "Type the instance name" }}
        onConfirm={() => begin.mutate()}
      >
        <Prose>This removes, by name:</Prose>
        <ul {...stylex.props(styles.list)}>
          <li>the worker <Mono>{wizard.resourceName(detail.summary.product, detail.summary.name)}</Mono>, its schedule, and its address</li>
          <li>the KV namespace <Mono>{wizard.resourceName(detail.summary.product, detail.summary.name)}</Mono> and everything in it</li>
          <li>the agent <Mono>{`${detail.summary.product}-deployment-${detail.summary.name}`}</Mono> and the token it ran under</li>
        </ul>
        <Choice
          label="The bucket"
          options={[
            { value: "keep", label: "keep", description: "The bucket stays with its data. A later install with the same name and the saved key picks it up." },
            { value: "delete", label: "delete", description: `The bucket and ${bucketNames.join(", ")} are deleted. Nothing brings them back.` },
          ]}
          value={deleteBucket}
          onChange={setDeleteBucket}
        />
        <Prose>
          Laptops keep their configuration until they run the product's own
          forget command. Analytics data stays in the account.
        </Prose>
      </Confirm>
      <Command>{detail.summary.host}</Command>
    </div>
  );
};
