// @vitest-environment node
import { describe, expect, it } from "vitest";

import { generateNixKey, keyNameFor, nextKeyName } from "../src/lib/keys.ts";

// The key the browser makes is nix's format exactly, because it is what
// cachet's worker parses and what a laptop's nix trusts.

describe("generateNixKey", () => {
  it("writes name:base64(seed ‖ public), 64 bytes, and the matching public half", async () => {
    const pair = await generateNixKey("cache.acme.example-1");
    const [name, secretBase64] = pair.secret.split(":");
    expect(name).toBe("cache.acme.example-1");
    expect(secretBase64).toHaveLength(88);
    const bytes = Buffer.from(secretBase64 ?? "", "base64");
    expect(bytes).toHaveLength(64);
    const [publicName, publicBase64] = pair.publicKey.split(":");
    expect(publicName).toBe("cache.acme.example-1");
    expect(Buffer.from(publicBase64 ?? "", "base64")).toEqual(bytes.subarray(32));
  });

  it("makes a different key every time", async () => {
    const first = await generateNixKey("k");
    const second = await generateNixKey("k");
    expect(first.secret).not.toBe(second.secret);
  });
});

describe("key names", () => {
  it("increments the host's suffix and starts at one otherwise", () => {
    expect(nextKeyName("cache.acme.example-1:AAAA", "cache.acme.example")).toBe("cache.acme.example-2");
