'''/// Decode an envelope for a call whose result the caller does not read: a
/// success with a null or absent result is a success, which is what the
/// platform answers for most deletes.
///
/// # Errors
/// [`ApiError`].
pub fn decode_ok(status: u16, text: &str) -> Result<(), ApiError> {
    if (200..300).contains(&status) && text.trim().is_empty() {
        return Ok(());
    }
    let envelope: Envelope<serde_json::Value> = serde_json::from_str(text).map_err(|_| ApiError {
        status,
        code: None,
        message: format!("Cloudflare answered {status}"),
    })?;
    if (200..300).contains(&status) && envelope.success {
        return Ok(());
    }
    let first = envelope.errors.first();
    Err(ApiError {
        status,
        code: first.and_then(|error| error.code),
        message: first.map_or_else(
            || format!("Cloudflare answered {status}"),
            |error| error.message.clone(),
        ),
    })
}

/// Send one request and decode it with [`decode_ok`].
///
/// # Errors
/// [`ApiError`].
pub async fn call_ok(
    bearer: &str,
    method: Method,
    url: &str,
    body: Option<Body>,
) -> Result<(), ApiError> {
    let (status, text) = send(Some(bearer), method, url, body).await?;
    decode_ok(status, &text)
}

/// Percent-encode a path segment.'''),
